```python
"""
Recommendation: the Anthropic Claude Messages API with native PDF input.

Why it fits your pilot:
  * One HTTPS POST per invoice. You send the PDF as base64, and the fields come back.
    There are no queues, templates, model training, or extra infrastructure.
  * It handles both digital PDFs and clean 300 dpi scans. Each page is read as
    text plus image, so scans need no separate OCR step.
  * You get JSON that follows your schema. The code forces a "tool call", so the
    model must answer with arguments that match the JSON schema below.
  * 300 invoices a week is far below the default rate limits, so plain
    synchronous calls are enough.
  * The same call works from your TypeScript app, either with the official
    SDK (`npm i @anthropic-ai/sdk`) or with raw `fetch` to
    POST https://api.anthropic.com/v1/messages and these headers:
    x-api-key, anthropic-version: 2023-06-01, content-type: application/json.
  * Limits per request: 32 MB and up to 100 pages. Invoices fit easily.

Setup:  pip install anthropic   and   export ANTHROPIC_API_KEY=...
Usage:  python extract_invoice.py invoice.pdf
"""

import base64
import json
import sys

import anthropic

MODEL = "claude-sonnet-4-5"  # good accuracy/cost balance for document extraction

INVOICE_TOOL = {
    "name": "record_invoice",
    "description": "Record the key fields extracted from an invoice document.",
    "input_schema": {
        "type": "object",
        "properties": {
            "invoice_number": {
                "type": ["string", "null"],
                "description": "Invoice number/ID exactly as printed; null if absent.",
            },
            "supplier": {
                "type": ["string", "null"],
                "description": "Legal or trading name of the company issuing the invoice (the seller, not the customer).",
            },
            "date": {
                "type": ["string", "null"],
                "description": "Invoice issue date in ISO 8601 format (YYYY-MM-DD).",
            },
            "total": {
                "type": ["number", "null"],
                "description": "Final amount due including tax, as a number without currency symbols or thousands separators.",
            },
            "currency": {
                "type": ["string", "null"],
                "description": "ISO 4217 currency code if identifiable (e.g. USD, GBP, EUR).",
            },
        },
        "required": ["invoice_number", "supplier", "date", "total", "currency"],
        "additionalProperties": False,
    },
}

client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY from the environment


def extract_invoice(pdf_bytes: bytes) -> dict:
    """Send one PDF to Claude and return the extracted fields as a dict."""
    response = client.messages.create(
        model=MODEL,
        max_tokens=1024,
        temperature=0,
        tools=[INVOICE_TOOL],
        tool_choice={"type": "tool", "name": "record_invoice"},  # force structured output
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": "document",
                        "source": {
                            "type": "base64",
                            "media_type": "application/pdf",
                            "data": base64.standard_b64encode(pdf_bytes).decode("ascii"),
                        },
                    },
                    {
                        "type": "text",
                        "text": (
                            "Extract the invoice number, supplier (the issuer/seller), "
                            "invoice date, and grand total from this invoice. "
                            "Use null for any field that is not present. Do not guess."
                        ),
                    },
                ],
            }
        ],
    )

    for block in response.content:
        if block.type == "tool_use" and block.name == "record_invoice":
            return block.input

    raise RuntimeError(f"No structured result returned (stop_reason={response.stop_reason})")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: python extract_invoice.py <invoice.pdf>")

    with open(sys.argv[1], "rb") as f:
        result = extract_invoice(f.read())

    print(json.dumps(result, indent=2))
    # Example output:
    # {
    #   "invoice_number": "INV-2024-0412",
    #   "supplier": "Acme Supplies Ltd",
    #   "date": "2024-04-12",
    #   "total": 1284.5,
    #   "currency": "GBP"
    # }
```

