**Recommendation: AWS Textract `AnalyzeDocument` (synchronous) with the `TABLES` feature.**

Why: it's a single synchronous call per page (typically 1–3 s for a clean digital page, well under your 5 s abandonment threshold), it returns cells with row/column indices plus `COLUMN_HEADER` flags so headers and row labels fall out directly, it handles both digital PDFs and good scans with the same code path, and at ~$15 per 1,000 pages the 20k/day volume is affordable. Since analysts verify before export, Textract's occasional merged-cell quirks are acceptable. Azure Document Intelligence and Google Document AI are comparable in quality but require async submit-then-poll for PDFs, which adds latency; LLM-based parsers (Reducto, LlamaParse) are more accurate on messy layouts but routinely take 10–30 s per page.

```python
import io
import json
import sys
from concurrent.futures import ThreadPoolExecutor

import boto3
from pypdf import PdfReader, PdfWriter

textract = boto3.client("textract", region_name="us-east-1")


def split_pages(pdf_bytes: bytes) -> list[bytes]:
    """Textract sync API accepts single-page PDFs only, so split first."""
    reader = PdfReader(io.BytesIO(pdf_bytes))
    pages = []
    for page in reader.pages:
        writer = PdfWriter()
        writer.add_page(page)
        buf = io.BytesIO()
        writer.write(buf)
        pages.append(buf.getvalue())
    return pages


def _cell_text(cell: dict, blocks: dict) -> str:
    words = []
    for rel in cell.get("Relationships", []):
        if rel["Type"] == "CHILD":
            for cid in rel["Ids"]:
                b = blocks[cid]
                if b["BlockType"] == "WORD":
                    words.append(b["Text"])
                elif b["BlockType"] == "SELECTION_ELEMENT":
                    words.append("[x]" if b["SelectionStatus"] == "SELECTED" else "[ ]")
    return " ".join(words).strip()


def parse_tables(resp: dict) -> list[dict]:
    blocks = {b["Id"]: b for b in resp["Blocks"]}
    tables = []

    for tb in resp["Blocks"]:
        if tb["BlockType"] != "TABLE":
            continue

        cells = []
        for rel in tb.get("Relationships", []):
            if rel["Type"] == "CHILD":
                cells += [blocks[cid] for cid in rel["Ids"] if blocks[cid]["BlockType"] == "CELL"]

        n_rows = max(c["RowIndex"] for c in cells)
        n_cols = max(c["ColumnIndex"] for c in cells)
        grid = [["" for _ in range(n_cols)] for _ in range(n_rows)]
        header_rows = set()

        for c in cells:
            r, col = c["RowIndex"] - 1, c["ColumnIndex"] - 1
            text = _cell_text(c, blocks)
            # Fill spanned cells so the grid is rectangular for the frontend.
            for dr in range(c.get("RowSpan", 1)):
                for dc in range(c.get("ColumnSpan", 1)):
                    if r + dr < n_rows and col + dc < n_cols:
                        grid[r + dr][col + dc] = text
            if "COLUMN_HEADER" in c.get("EntityTypes", []):
                header_rows.add(r)

        # Fall back to treating the first row as header when Textract doesn't flag one.
        if not header_rows:
            header_rows = {0}
        last_header = max(header_rows)

        headers = grid[last_header]
        rows = []
        for r in range(last_header + 1, n_rows):
            label = grid[r][0]
            rows.append({
                "label": label,
                "values": grid[r][1:],
                "cells": {headers[c] or f"col_{c}": grid[r][c] for c in range(n_cols)},
            })

        tables.append({
            "confidence": tb.get("Confidence"),
            "bbox": tb["Geometry"]["BoundingBox"],
            "headers": headers,
            "header_rows": [grid[r] for r in sorted(header_rows)],
            "rows": rows,
        })

    return tables


def process_page(page_bytes: bytes, page_number: int) -> dict:
    resp = textract.analyze_document(
        Document={"Bytes": page_bytes},
        FeatureTypes=["TABLES"],
    )
    return {"page": page_number, "tables": parse_tables(resp)}


def process_pdf(pdf_bytes: bytes, max_workers: int = 8) -> list[dict]:
    pages = split_pages(pdf_bytes)
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        results = list(pool.map(lambda p: process_page(p[1], p[0] + 1), enumerate(pages)))
    return results


if __name__ == "__main__":
    with open(sys.argv[1], "rb") as f:
        output = process_pdf(f.read())
    print(json.dumps(output, indent=2))
```

Operational notes: call `process_page` directly from your upload handler (one page at a time) so the preview renders as soon as each page returns, rather than waiting for the whole document. Request a Textract TPS limit increase for `AnalyzeDocument` in your region before launch — 20k pages/day with bursty uploads will exceed the default quota.

