```python
"""
Hosted API choice: Amazon Textract AnalyzeExpense.

It is receipt-specific and synchronous; use AnalyzeExpense rather than the
batch-oriented StartExpenseAnalysis API.

Setup:
    pip install boto3
    export AWS_REGION=us-east-1
    # Authenticate with an IAM role or standard AWS credential variables.

Usage:
    python extract_receipt.py receipt.jpg
"""

import json
import os
import sys
import unicodedata
from pathlib import Path
from typing import Any, Optional

import boto3
from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError

MAX_IMAGE_BYTES = 10 * 1024 * 1024

textract = boto3.client(
    "textract",
    region_name=os.getenv("AWS_REGION", "us-east-1"),
    config=Config(
        connect_timeout=0.3,
        read_timeout=2.5,
        retries={"mode": "standard", "total_max_attempts": 1},
    ),
)

FIELD_TYPES = {
    "merchant": ("VENDOR_NAME",),
    "date": ("INVOICE_RECEIPT_DATE",),
    "tax": ("TAX",),
    "total": ("TOTAL",),
}

LABEL_ALIASES = {
    "merchant": {
        "merchant",
        "vendor",
        "store",
        "supplier",
        "comerciante",
        "estabelecimento",
        "fornecedor",
        "loja",
    },
    "date": {"date", "transaction date", "data", "data da compra"},
    "tax": {"tax", "vat", "iva", "imposto", "icms"},
    "total": {"total", "grand total", "amount due", "valor total", "total a pagar"},
}


def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKD", text.casefold())
    return " ".join(
        "".join(character for character in text if not unicodedata.combining(character)).split()
    )


def field_value(field: dict[str, Any]) -> tuple[Optional[str], float]:
    detection = field.get("ValueDetection") or {}
    value = detection.get("Text")
    confidence = float(detection.get("Confidence") or 0.0)
    return value, confidence


def extract_fields(response: dict[str, Any]) -> dict[str, Optional[str]]:
    candidates: dict[str, tuple[Optional[str], float]] = {
        name: (None, -1.0) for name in FIELD_TYPES
    }

    for document in response.get("ExpenseDocuments", []):
        for field in document.get("SummaryFields", []):
            field_type = (field.get("Type") or {}).get("Text", "").upper()
            label = normalize((field.get("LabelDetection") or {}).get("Text", ""))
            value, confidence = field_value(field)

            if not value:
                continue

            for output_name, accepted_types in FIELD_TYPES.items():
                type_match = field_type in accepted_types
                label_match = any(
                    alias == label or alias in label
                    for alias in LABEL_ALIASES[output_name]
                )

                if (type_match or label_match) and confidence > candidates[output_name][1]:
                    candidates[output_name] = (value.strip(), confidence)

    return {name: value for name, (value, _) in candidates.items()}


def analyze_receipt(image_path: str) -> dict[str, Optional[str]]:
    path = Path(image_path)
    image = path.read_bytes()

    if len(image) > MAX_IMAGE_BYTES:
        raise ValueError("JPEG exceeds Textract's 10 MB synchronous request limit")

    if not image.startswith(b"\xff\xd8\xff"):
        raise ValueError("Input must be a JPEG image")

    response = textract.analyze_expense(Document={"Bytes": image})
    return extract_fields(response)


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python extract_receipt.py RECEIPT.jpg")

    try:
        result = analyze_receipt(sys.argv[1])
        print(json.dumps(result, ensure_ascii=False))
    except (ValueError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        raise SystemExit(2)
    except (ClientError, BotoCoreError) as error:
        print(
            json.dumps({"error": "Receipt processing failed", "detail": str(error)}),
            file=sys.stderr,
        )
        raise SystemExit(3)


if __name__ == "__main__":
    main()
```

