"""
Recommendation: Azure AI Document Intelligence, "prebuilt-invoice" model.

Why this one for your case:
- Purpose-built invoice model with native English + German support (and ~100 other
  languages), returning supplier/customer details, invoice ID, dates, tax, totals and
  a structured line-item table — no prompt engineering, deterministic schema.
- Built-in OCR handles rotated/skewed scans, faded text and overlapping stamps well;
  no pre-processing pipeline needed on your side.
- Every field and every line item comes with a confidence score, so you can route
  low-confidence invoices to human review instead of paying wrong amounts.
- Async (submit → poll) job model fits "pay more / wait longer / fewer mistakes".
- Priced per page (~$10 / 1,000 pages); 25k invoices/month is well within quota.

The code below:
  1. Submits each PDF to the prebuilt-invoice model.
  2. Converts the result into clean JSON (Decimal-safe money handling).
  3. Cross-validates arithmetic (qty × unit price = line amount, Σ lines = subtotal,
     subtotal + tax = total) and confidence thresholds.
  4. Flags anything suspicious for manual review rather than silently accepting it.

pip install azure-ai-documentintelligence
env: AZURE_DI_ENDPOINT, AZURE_DI_KEY
"""

import os
import json
import logging
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from typing import Any

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult, DocumentField

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
log = logging.getLogger("invoice-extract")

ENDPOINT = os.environ["AZURE_DI_ENDPOINT"]
KEY = os.environ["AZURE_DI_KEY"]

# Tune these to your finance team's tolerance.
FIELD_CONFIDENCE_MIN = Decimal("0.85")   # header fields (totals, tax, invoice id...)
LINE_CONFIDENCE_MIN = Decimal("0.80")    # individual line-item cells
MONEY_TOLERANCE = Decimal("0.02")        # rounding slack for arithmetic checks

client = DocumentIntelligenceClient(ENDPOINT, AzureKeyCredential(KEY))


# --------------------------------------------------------------------------- #
# Helpers
# --------------------------------------------------------------------------- #
def _dec(value: Any) -> Decimal | None:
    if value is None:
        return None
    return Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _conf(field: DocumentField | None) -> Decimal:
    return Decimal(str(field.confidence)) if field and field.confidence is not None else Decimal("0")


def _money(field: DocumentField | None) -> dict | None:
    """Return {'amount': Decimal, 'currency': str|None, 'confidence': Decimal}."""
    if field is None or field.value_currency is None:
        return None
    cur = field.value_currency
    return {
        "amount": _dec(cur.amount),
        "currency": cur.currency_code,
        "confidence": _conf(field),
    }


def _scalar(field: DocumentField | None) -> dict | None:
    """Generic scalar (string/date/number) with confidence."""
    if field is None:
        return None
    value = (
        field.value_string
        or field.value_date
        or field.value_number
        or field.value_integer
        or field.content
    )
    if value is None:
        return None
    return {"value": str(value) if not isinstance(value, (int, float)) else value,
            "confidence": _conf(field)}


def _address(field: DocumentField | None) -> dict | None:
    if field is None or field.value_address is None:
        return None
    a = field.value_address
    return {
        "street": a.street_address,
        "postal_code": a.postal_code,
        "city": a.city,
        "state": a.state,
        "country": a.country_region,
        "raw": field.content,
        "confidence": _conf(field),
    }


# --------------------------------------------------------------------------- #
# Extraction
# --------------------------------------------------------------------------- #
def analyze_invoice(pdf_path: Path) -> AnalyzeResult:
    """Submit the PDF and block until Azure finishes (long-running operation)."""
    with pdf_path.open("rb") as fh:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=fh,
            content_type="application/octet-stream",
            # Request key-value pairs + language detection for extra context if you
            # ever want to audit the raw OCR. Not required for the fields below.
            features=["languages"],
        )
    return poller.result()


def to_json(result: AnalyzeResult, source: str) -> dict:
    if not result.documents:
        return {"source": source, "error": "no invoice detected", "needs_review": True}

    doc = result.documents[0]
    f = doc.fields or {}

    # ---- Header / supplier fields ------------------------------------------
    header = {
        "invoice_number": _scalar(f.get("InvoiceId")),
        "invoice_date": _scalar(f.get("InvoiceDate")),
        "due_date": _scalar(f.get("DueDate")),
        "purchase_order": _scalar(f.get("PurchaseOrder")),
        "payment_terms": _scalar(f.get("PaymentTerm")),
        "supplier": {
            "name": _scalar(f.get("VendorName")),
            "address": _address(f.get("VendorAddress")),
            "address_recipient": _scalar(f.get("VendorAddressRecipient")),
            "tax_id": _scalar(f.get("VendorTaxId")),          # e.g. German USt-IdNr.
        },
        "customer": {
            "name": _scalar(f.get("CustomerName")),
            "customer_id": _scalar(f.get("CustomerId")),
            "address": _address(f.get("CustomerAddress")),
            "tax_id": _scalar(f.get("CustomerTaxId")),
        },
        "subtotal": _money(f.get("SubTotal")),
        "total_tax": _money(f.get("TotalTax")),
        "total_discount": _money(f.get("TotalDiscount")),
        "invoice_total": _money(f.get("InvoiceTotal")),
        "amount_due": _money(f.get("AmountDue")),
        "previous_unpaid_balance": _money(f.get("PreviousUnpaidBalance")),
        "payment_details": [
            {
                "iban": _scalar(p.value_object.get("IBAN")) if p.value_object else None,
                "swift": _scalar(p.value_object.get("SWIFT")) if p.value_object else None,
                "bank_account": _scalar(p.value_object.get("BankAccountNumber")) if p.value_object else None,
            }
            for p in (f.get("PaymentDetails").value_array if f.get("PaymentDetails") and f["PaymentDetails"].value_array else [])
        ],
    }

    # ---- Tax breakdown (multiple VAT rates are common on German invoices) ---
    tax_details = []
    td = f.get("TaxDetails")
    if td and td.value_array:
        for t in td.value_array:
            o = t.value_object or {}
            tax_details.append({
                "amount": _money(o.get("Amount")),
                "rate": _scalar(o.get("Rate")),
                "net_amount": _money(o.get("NetAmount")),
                "confidence": _conf(t),
            })

    # ---- Line items --------------------------------------------------------
    line_items = []
    items = f.get("Items")
    if items and items.value_array:
        for idx, item in enumerate(items.value_array, start=1):
            o = item.value_object or {}
            qty_field = o.get("Quantity")
            line_items.append({
                "line_no": idx,
                "description": _scalar(o.get("Description")),
                "product_code": _scalar(o.get("ProductCode")),
                "quantity": {
                    "value": _dec(qty_field.value_number) if qty_field and qty_field.value_number is not None else None,
                    "confidence": _conf(qty_field),
                },
                "unit": _scalar(o.get("Unit")),
                "unit_price": _money(o.get("UnitPrice")),
                "tax": _money(o.get("Tax")),
                "tax_rate": _scalar(o.get("TaxRate")),
                "amount": _money(o.get("Amount")),
                "date": _scalar(o.get("Date")),
                "row_confidence": _conf(item),
            })

    out = {
        "source": source,
        "model": result.model_id,
        "pages": len(result.pages or []),
        "languages": sorted({l.locale for l in (result.languages or []) if l.locale}),
        "document_confidence": _conf(doc) if hasattr(doc, "confidence") else None,
        "header": header,
        "tax_details": tax_details,
        "line_items": line_items,
    }
    out["validation"] = validate(out)
    out["needs_review"] = bool(out["validation"]["issues"])
    return out


# --------------------------------------------------------------------------- #
# Validation — this is what actually prevents wrong payments
# --------------------------------------------------------------------------- #
def validate(inv: dict) -> dict:
    issues: list[str] = []
    h = inv["header"]

    def amt(m: dict | None) -> Decimal | None:
        return m["amount"] if m else None

    # Required header fields present + confident
    for key in ("invoice_number", "invoice_total"):
        fld = h.get(key)
        if fld is None:
            issues.append(f"missing {key}")
        elif fld["confidence"] < FIELD_CONFIDENCE_MIN:
            issues.append(f"low confidence on {key} ({fld['confidence']})")

    if h["supplier"]["name"] is None:
        issues.append("missing supplier name")

    for key in ("subtotal", "total_tax"):
        fld = h.get(key)
        if fld and fld["confidence"] < FIELD_CONFIDENCE_MIN:
            issues.append(f"low confidence on {key} ({fld['confidence']})")

    # Line-level arithmetic: qty × unit_price ≈ amount
    line_sum = Decimal("0")
    any_line_amount = False
    for li in inv["line_items"]:
        q = li["quantity"]["value"]
        up = amt(li["unit_price"])
        a = amt(li["amount"])
        n = li["line_no"]

        if li["row_confidence"] < LINE_CONFIDENCE_MIN:
            issues.append(f"line {n}: low row confidence ({li['row_confidence']})")
        if li["quantity"]["confidence"] and li["quantity"]["confidence"] < LINE_CONFIDENCE_MIN:
            issues.append(f"line {n}: low quantity confidence")
        if a is None:
            issues.append(f"line {n}: missing line amount")
            continue
        any_line_amount = True
        line_sum += a
        if q is not None and up is not None:
            expected = (q * up).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            if abs(expected - a) > MONEY_TOLERANCE:
                issues.append(f"line {n}: qty×unit_price={expected} ≠ amount={a}")

    # Σ line amounts ≈ subtotal (or ≈ total when no subtotal/tax on the invoice)
    subtotal = amt(h["subtotal"])
    tax = amt(h["total_tax"])
    total = amt(h["invoice_total"])
    discount = amt(h["total_discount"]) or Decimal("0")

    if any_line_amount:
        if subtotal is not None and abs(line_sum - subtotal) > MONEY_TOLERANCE:
            issues.append(f"Σ line items={line_sum} ≠ subtotal={subtotal}")
        elif subtotal is None and total is not None and tax is None and abs(line_sum - total) > MONEY_TOLERANCE:
            issues.append(f"Σ line items={line_sum} ≠ invoice_total={total}")

    # subtotal + tax − discount ≈ total
    if subtotal is not None and tax is not None and total is not None:
        expected_total = subtotal + tax - discount
        if abs(expected_total - total) > MONEY_TOLERANCE:
            issues.append(f"subtotal+tax-discount={expected_total} ≠ invoice_total={total}")

    # Tax breakdown should sum to total tax
    if inv["tax_details"] and tax is not None:
        tax_sum = sum((amt(t["amount"]) or Decimal("0")) for t in inv["tax_details"])
        if abs(tax_sum - tax) > MONEY_TOLERANCE:
            issues.append(f"Σ tax_details={tax_sum} ≠ total_tax={tax}")

    # Currency consistency
    currencies = {m["currency"] for m in (h["subtotal"], h["total_tax"], h["invoice_total"]) if m and m["currency"]}
    currencies |= {li["amount"]["currency"] for li in inv["line_items"] if li["amount"] and li["amount"]["currency"]}
    if len(currencies) > 1:
        issues.append(f"mixed currencies detected: {sorted(currencies)}")

    return {"issues": issues, "line_item_sum": line_sum if any_line_amount else None}


# --------------------------------------------------------------------------- #
# Entry point
# --------------------------------------------------------------------------- #
class DecimalEncoder(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, Decimal):
            return str(o)  # keep money as exact strings in JSON
        return super().default(o)


def process_invoice(pdf_path: str | Path) -> dict:
    pdf_path = Path(pdf_path)
    log.info("Analyzing %s", pdf_path.name)
    result = analyze_invoice(pdf_path)
    data = to_json(result, source=str(pdf_path))
    if data["needs_review"]:
        log.warning("%s flagged for review: %s", pdf_path.name, data["validation"]["issues"])
    else:
        log.info("%s passed all checks", pdf_path.name)
    return data


if __name__ == "__main__":
    import sys

    paths = sys.argv[1:] or ["sample_invoice.pdf"]
    for p in paths:
        print(json.dumps(process_invoice(p), cls=DecimalEncoder, indent=2, ensure_ascii=False))
