"""

import argparse
import json
import os
import re
from pathlib import Path
from typing import Any

from google.api_core.client_options import ClientOptions
from google.cloud import documentai


def clean_text(value: str) -> str:
    return re.sub(r"\s+", " ", value).strip()


def semantic_key(label: str, fallback: str) -> str:
    key = re.sub(r"[^a-z0-9]+", "_", label.lower()).strip("_")
    return key or fallback


class FormParser:
    def __init__(self, project_id: str, location: str, processor_id: str):
        options = ClientOptions(
            api_endpoint=f"{location}-documentai.googleapis.com"
        )
        self.client = documentai.DocumentProcessorServiceClient(
            client_options=options
        )
        self.processor_name = self.client.processor_path(
            project_id, location, processor_id
        )

    @staticmethod
    def _layout_text(document: documentai.Document, layout: Any) -> str:
        parts: list[str] = []

        for segment in layout.text_anchor.text_segments:
            start = int(segment.start_index or 0)
            end = int(segment.end_index)
            parts.append(document.text[start:end])

        return clean_text("".join(parts))

    @staticmethod
    def _checkbox_state(value_type: str, value: str) -> bool | None:
        normalized_type = value_type.lower().strip()
        normalized_value = value.lower().strip()

        if normalized_type in {
            "filled_checkbox",
            "checked",
            "selected",
        }:
            return True

        if normalized_type in {
            "unfilled_checkbox",
            "unchecked",
            "unselected",
        }:
            return False

        if normalized_value in {"☒", "☑", "✓", "✔", "checked", "selected"}:
            return True

        if normalized_value in {"☐", "unchecked", "unselected"}:
            return False

        return None

    def process_pdf(self, pdf_path: Path) -> dict[str, Any]:
        request = documentai.ProcessRequest(
            name=self.processor_name,
            raw_document=documentai.RawDocument(
                content=pdf_path.read_bytes(),
                mime_type="application/pdf",
            ),
        )

        document = self.client.process_document(request=request).document
        fields: list[dict[str, Any]] = []

        for page_number, page in enumerate(document.pages, start=1):
            for field_number, field in enumerate(page.form_fields, start=1):
                label = self._layout_text(document, field.field_name)
                raw_value = self._layout_text(document, field.field_value)
                raw_value_type = getattr(field, "value_type", "") or ""

                checked = self._checkbox_state(raw_value_type, raw_value)
                is_checkbox = (
                    "checkbox" in raw_value_type.lower() or checked is not None
                )

                fields.append(
                    {
                        "page": page_number,
                        "key": semantic_key(
                            label, f"page_{page_number}_field_{field_number}"
                        ),
                        "label": label,
                        "type": "checkbox" if is_checkbox else "text",
                        "value": None if is_checkbox else (raw_value or None),
                        "checked": checked if is_checkbox else None,
                        "confidence": {
                            "label": round(
                                float(field.field_name.confidence), 4
                            ),
                            "value": round(
                                float(field.field_value.confidence), 4
                            ),
                        },
                    }
                )

        return {
            "source_file": pdf_path.name,
            "page_count": len(document.pages),
            "fields": fields,
        }


def pdf_files(path: Path) -> list[Path]:
    if path.is_file():
        if path.suffix.lower() != ".pdf":
            raise ValueError("Input file must be a PDF")
        return [path]

    if path.is_dir():
        return sorted(
            item for item in path.iterdir()
            if item.is_file() and item.suffix.lower() == ".pdf"
        )

    raise FileNotFoundError(path)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=Path, help="PDF file or directory of PDFs")
    parser.add_argument("-o", "--output", type=Path)
    args = parser.parse_args()

