        "GCP_PROJECT_ID": os.getenv("GCP_PROJECT_ID"),
        "GCP_LOCATION": os.getenv("GCP_LOCATION", "us"),
        "GCP_FORM_PARSER_PROCESSOR_ID": os.getenv(
            "GCP_FORM_PARSER_PROCESSOR_ID"
        ),
    }
    missing = [name for name, value in required.items() if not value]
    if missing:
        raise RuntimeError(
            f"Missing environment variables: {', '.join(missing)}"
        )

    form_parser = FormParser(
        project_id=required["GCP_PROJECT_ID"],
        location=required["GCP_LOCATION"],
        processor_id=required["GCP_FORM_PARSER_PROCESSOR_ID"],
    )

    result = {
        "provider": "google-cloud-document-ai",
        "processor": "form-parser",
        "documents": [
            form_parser.process_pdf(path) for path in pdf_files(args.input)
        ],
    }

    output = json.dumps(result, indent=2, ensure_ascii=False)

    if args.output:
        args.output.write_text(output + "\n", encoding="utf-8")
    else:
        print(output)


if __name__ == "__main__":
    main()
