from typing import Any

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest

ENDPOINT = os.environ["AZURE_DI_ENDPOINT"]
KEY = os.environ["AZURE_DI_KEY"]

# Anything below this confidence on a money/quantity field -> human review.
# Tune upward if finance wants to be stricter; 0.90 is a sensible start.
MIN_CONFIDENCE = 0.90
# Allowed rounding slack when cross-checking totals (per-line rounding adds up).
TOLERANCE = Decimal("0.02")

client = DocumentIntelligenceClient(ENDPOINT, AzureKeyCredential(KEY))


# ---------- helpers ----------

def _dec(x: Any) -> Decimal | None:
    if x is None:
        return None
    return Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _field(fields: dict, name: str):
    """Return (value, confidence) for a prebuilt-invoice field, or (None, None)."""
    f = fields.get(name)
    if f is None:
        return None, None
    # Currency fields carry amount+currencyCode; others carry a typed value
    if f.type == "currency" and f.value_currency is not None:
        return {"amount": float(f.value_currency.amount),
                "currency": f.value_currency.currency_code}, f.confidence
    if f.type == "date":
        return (str(f.value_date) if f.value_date else f.content), f.confidence
    if f.type == "number":
        return f.value_number, f.confidence
    if f.type == "address" and f.value_address is not None:
        a = f.value_address
        return {
            "street": a.street_address, "postal_code": a.postal_code,
            "city": a.city, "country": a.country_region,
            "raw": f.content,
        }, f.confidence
    return (f.value_string if f.value_string is not None else f.content), f.confidence


def _money(v):
    return _dec(v["amount"]) if isinstance(v, dict) else _dec(v)


# ---------- core ----------

def extract_invoice(pdf_path: str) -> dict:
    with open(pdf_path, "rb") as fh:
        poller = client.begin_analyze_document(
            "prebuilt-invoice",
            AnalyzeDocumentRequest(bytes_source=fh.read()),
            # Request high-res OCR: slower and costs more, materially better on faded/
            # skewed scans and small-font line items.
            features=["ocrHighResolution"],
            locale=None,  # let the service auto-detect EN/DE
        )
    result = poller.result()

    if not result.documents:
        return {"file": pdf_path, "status": "no_invoice_detected", "needs_review": True}

    doc = result.documents[0]
    f = doc.fields or {}

    issues: list[str] = []

    def take(name: str, critical: bool = False):
        val, conf = _field(f, name)
        if critical and val is not None and conf is not None and conf < MIN_CONFIDENCE:
            issues.append(f"low confidence on {name}: {conf:.2f}")
        return {"value": val, "confidence": conf}

    # Header fields
    out = {
        "file": pdf_path,
        "supplier": {
            "name": take("VendorName", critical=True),
            "address": take("VendorAddress"),
            "address_recipient": take("VendorAddressRecipient"),
            "tax_id": take("VendorTaxId", critical=True),  # USt-IdNr. / VAT ID
        },
        "customer": {
            "name": take("CustomerName"),
            "address": take("CustomerAddress"),
            "tax_id": take("CustomerTaxId"),
        },
        "invoice_id": take("InvoiceId", critical=True),
        "invoice_date": take("InvoiceDate", critical=True),
        "due_date": take("DueDate"),
        "purchase_order": take("PurchaseOrder"),
        "payment_terms": take("PaymentTerm"),
        "bank": {
            # Populated on most German invoices
            "iban": take("PaymentDetails"),  # list of {IBAN, SWIFT, ...}; raw passthrough
        },
        "subtotal": take("SubTotal", critical=True),
        "total_tax": take("TotalTax", critical=True),
        "invoice_total": take("InvoiceTotal", critical=True),
        "amount_due": take("AmountDue"),
        "currency": None,
        "line_items": [],
        "tax_details": [],
    }

    # Currency comes with any currency field
    for key in ("invoice_total", "subtotal", "total_tax"):
        v = out[key]["value"]
        if isinstance(v, dict) and v.get("currency"):
            out["currency"] = v["currency"]
            break

    # Line items
    items_field = f.get("Items")
    if items_field and items_field.value_array:
        for idx, item in enumerate(items_field.value_array, start=1):
            sub = item.value_object or {}

            def li(name: str, critical: bool = False):
                val, conf = _field(sub, name)
                if critical and val is not None and conf is not None and conf < MIN_CONFIDENCE:
                    issues.append(f"line {idx}: low confidence on {name}: {conf:.2f}")
                return {"value": val, "confidence": conf}

            line = {
                "line_no": idx,
                "description": li("Description"),
                "product_code": li("ProductCode"),
                "quantity": li("Quantity", critical=True),
                "unit": li("Unit"),
                "unit_price": li("UnitPrice", critical=True),
                "tax_rate": li("TaxRate"),
                "tax": li("Tax"),
                "amount": li("Amount", critical=True),
                "date": li("Date"),
            }

            # Per-line arithmetic check: qty * unit_price ≈ amount
            q, up, amt = line["quantity"]["value"], _money(line["unit_price"]["value"]), _money(line["amount"]["value"])
            if q is not None and up is not None and amt is not None:
                expected = _dec(Decimal(str(q)) * up)
                if abs(expected - amt) > TOLERANCE:
                    issues.append(f"line {idx}: qty*unit_price={expected} != amount={amt}")

            out["line_items"].append(line)

    # Tax breakdown (multiple VAT rates are common on German invoices)
    tax_field = f.get("TaxDetails")
    if tax_field and tax_field.value_array:
        for t in tax_field.value_array:
            sub = t.value_object or {}
            amt, c1 = _field(sub, "Amount")
            rate, c2 = _field(sub, "Rate")
            out["tax_details"].append({"amount": amt, "rate": rate,
                                       "confidence": min(x for x in (c1, c2) if x is not None) if (c1 or c2) else None})

    # ---------- document-level arithmetic checks ----------
    subtotal = _money(out["subtotal"]["value"])
    tax = _money(out["total_tax"]["value"])
    total = _money(out["invoice_total"]["value"])

    line_sum = sum((_money(l["amount"]["value"]) or Decimal(0)) for l in out["line_items"]) if out["line_items"] else None
    if line_sum is not None and subtotal is not None and abs(line_sum - subtotal) > TOLERANCE:
        # Some invoices list line amounts gross; try against total before flagging.
        if total is None or abs(line_sum - total) > TOLERANCE:
            issues.append(f"sum of line items {line_sum} != subtotal {subtotal}")

    if subtotal is not None and tax is not None and total is not None:
        if abs((subtotal + tax) - total) > TOLERANCE:
            issues.append(f"subtotal {subtotal} + tax {tax} != total {total}")

    if out["tax_details"] and tax is not None:
        td_sum = sum((_money(t["amount"]) or Decimal(0)) for t in out["tax_details"])
        if abs(td_sum - tax) > TOLERANCE:
            issues.append(f"sum of tax details {td_sum} != total tax {tax}")

    if total is None:
        issues.append("invoice total missing")
    if not out["line_items"]:
        issues.append("no line items extracted")

    out["issues"] = issues
    out["needs_review"] = bool(issues)
    out["status"] = "review" if issues else "ok"
    return out


if __name__ == "__main__":
    paths = sys.argv[1:] or ["invoice.pdf"]
    for p in paths:
        print(json.dumps(extract_invoice(p), indent=2, ensure_ascii=False, default=str))
