```python
"""
Invoice extraction API: Azure AI Document Intelligence (prebuilt-invoice)
+ confidence gating + arithmetic validation.

pip install fastapi uvicorn azure-ai-documentintelligence python-multipart

Env vars:
  AZURE_DI_ENDPOINT = https://<your-resource>.cognitiveservices.azure.com/
  AZURE_DI_KEY      = <your key>

Run: uvicorn invoice_api:app --host 0.0.0.0 --port 8000
POST /extract  (multipart form field "file" = the PDF)
"""

import os
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Optional

from fastapi import FastAPI, File, HTTPException, UploadFile
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential
from azure.core.exceptions import HttpResponseError

ENDPOINT = os.environ["AZURE_DI_ENDPOINT"]
KEY = os.environ["AZURE_DI_KEY"]

# Tune these to your tolerance. Anything below -> needs_review = True
FIELD_CONF_THRESHOLD = 0.85      # per-field confidence
MONEY_TOLERANCE = Decimal("0.02")  # rounding slack for arithmetic checks

client = DocumentIntelligenceClient(ENDPOINT, AzureKeyCredential(KEY))
app = FastAPI(title="Invoice Extraction API")


# ---------------------------------------------------------------------------
# Helpers: turn Azure DocumentField objects into plain, typed JSON
# ---------------------------------------------------------------------------
def _dec(x) -> Optional[Decimal]:
    if x is None:
        return None
    return Decimal(str(x)).quantize(Decimal("0.0001"))


def field_value(f) -> Any:
    """Extract the typed value from a DocumentField regardless of its type."""
    if f is None:
        return None
    t = f.type
    if t == "currency" and f.value_currency is not None:
        return {
            "amount": _dec(f.value_currency.amount),
            "currency": f.value_currency.currency_code,
        }
    if t == "number":
        return _dec(f.value_number)
    if t == "integer":
        return f.value_integer
    if t == "date":
        return f.value_date.isoformat() if f.value_date else None
    if t == "string":
        return f.value_string
    if t == "address" and f.value_address is not None:
        a = f.value_address
        return {
            "street": a.street_address,
            "house": a.house_number,
            "road": a.road,
            "postal_code": a.postal_code,
            "city": a.city,
            "state": a.state,
            "country": a.country_region,
            "raw": f.content,
        }
    # Fallback: raw OCR text
    return f.content


def pack(fields: dict, name: str, review: list) -> dict:
    """Return {value, confidence, raw} and record low-confidence fields."""
    f = fields.get(name)
    if f is None:
        return {"value": None, "confidence": None, "raw": None}
    conf = f.confidence
    if conf is not None and conf < FIELD_CONF_THRESHOLD:
        review.append(f"low confidence on {name} ({conf:.2f})")
    return {"value": field_value(f), "confidence": conf, "raw": f.content}


def money(packed: dict) -> Optional[Decimal]:
    v = packed.get("value")
    if isinstance(v, dict):
        return v.get("amount")
    if isinstance(v, Decimal):
        return v
    return None


def close(a: Optional[Decimal], b: Optional[Decimal]) -> bool:
    if a is None or b is None:
        return True  # can't check -> don't flag here (missing data is flagged elsewhere)
    return abs(a - b) <= MONEY_TOLERANCE


# ---------------------------------------------------------------------------
# Core extraction
# ---------------------------------------------------------------------------
def extract_invoice(pdf_bytes: bytes) -> dict:
    try:
        poller = client.begin_analyze_document(
            "prebuilt-invoice",
            body=pdf_bytes,
            content_type="application/pdf",
        )
        result = poller.result()
    except HttpResponseError as e:
        raise HTTPException(status_code=502, detail=f"Document Intelligence error: {e.message}")

    if not result.documents:
        raise HTTPException(status_code=422, detail="No invoice detected in document")

    doc = result.documents[0]
    fields = doc.fields or {}
    review: list[str] = []

    supplier = {
        "name": pack(fields, "VendorName", review),
        "address": pack(fields, "VendorAddress", review),
        "tax_id": pack(fields, "VendorTaxId", review),
    }
    customer = {
        "name": pack(fields, "CustomerName", review),
        "id": pack(fields, "CustomerId", review),
        "tax_id": pack(fields, "CustomerTaxId", review),
        "address": pack(fields, "CustomerAddress", review),
    }
    header = {
        "invoice_number": pack(fields, "InvoiceId", review),
        "invoice_date": pack(fields, "InvoiceDate", review),
        "due_date": pack(fields, "DueDate", review),
        "purchase_order": pack(fields, "PurchaseOrder", review),
        "payment_terms": pack(fields, "PaymentTerm", review),
    }
    totals = {
        "subtotal": pack(fields, "SubTotal", review),
        "total_tax": pack(fields, "TotalTax", review),
        "invoice_total": pack(fields, "InvoiceTotal", review),
        "amount_due": pack(fields, "AmountDue", review),
    }

    # --- Tax breakdown (e.g. 7% / 19% MwSt lines on German invoices) ---
    taxes = []
    tax_field = fields.get("TaxDetails")
    if tax_field is not None and tax_field.value_array:
        for i, t in enumerate(tax_field.value_array):
            sub = t.value_object or {}
            taxes.append({
                "amount": pack(sub, "Amount", review),
                "rate": pack(sub, "Rate", review),
            })

    # --- Line items ---
    line_items = []
    items_field = fields.get("Items")
    if items_field is not None and items_field.value_array:
        for i, item in enumerate(items_field.value_array, start=1):
            sub = item.value_object or {}
            li = {
                "line_no": i,
                "description": pack(sub, "Description", review),
                "product_code": pack(sub, "ProductCode", review),
                "quantity": pack(sub, "Quantity", review),
                "unit": pack(sub, "Unit", review),
                "unit_price": pack(sub, "UnitPrice", review),
                "tax": pack(sub, "Tax", review),
                "tax_rate": pack(sub, "TaxRate", review),
                "amount": pack(sub, "Amount", review),
            }
            # Arithmetic check: qty * unit_price ≈ amount
            qty = li["quantity"]["value"]
            up = money(li["unit_price"])
            amt = money(li["amount"])
