                        f"line {i}: qty×unit_price={expected} but amount={amt}"
                    )
            line_items.append(li)

    # --- Document-level arithmetic checks ---
    subtotal = money(totals["subtotal"])
    total_tax = money(totals["total_tax"])
    inv_total = money(totals["invoice_total"])

    if line_items:
        line_sum = sum(
            (money(li["amount"]) or Decimal(0)) for li in line_items
        )
        if subtotal is not None and not close(line_sum, subtotal):
            review.append(f"sum of line amounts {line_sum} ≠ subtotal {subtotal}")

    if subtotal is not None and total_tax is not None and inv_total is not None:
        if not close(subtotal + total_tax, inv_total):
