    ]:
        if header[key]["value"] is None:
            review.append(f"missing {label}")
    if supplier["name"]["value"] is None:
        review.append("missing VendorName")
    if inv_total is None:
        review.append("missing InvoiceTotal")

    return {
        "needs_review": bool(review),
        "review_reasons": review,
        "document_confidence": doc.confidence,
        "pages": len(result.pages or []),
        "language": _guess_language(result),
        "supplier": supplier,
        "customer": customer,
        "header": header,
        "totals": totals,
        "taxes": taxes,
        "line_items": line_items,
    }


def _guess_language(result) -> Optional[str]:
    langs = getattr(result, "languages", None) or []
    if not langs:
        return None
    best = max(langs, key=lambda l: l.confidence or 0)
    return best.locale


