```python
"""
Recommendation: AWS Textract, synchronous AnalyzeDocument with FeatureTypes=["TABLES"].

Why this fits your constraints:
  - Sync call returns in ~1–3 s for a single page (no job polling like Azure/Google async),
    so you stay comfortably under the 5-second abandonment threshold.
  - Native table output: cells with row/column indices, COLUMN_HEADER tags, and
    merged-cell handling — no LLM prompting, no hallucinated numbers.
  - Handles both digital PDFs and good-quality scans; 20k pages/day is well within quota.
  - Accuracy is "very good, not perfect", which is fine since analysts review before export.

Usage:  POST /extract  (multipart file = one page as PDF/PNG/JPEG)
Your TypeScript backend calls this and gets JSON back:
  { "tables": [ { "headers": [...], "rows": [ { "label": "...", "cells": [...] } ] } ] }
"""

import io
import os
from collections import defaultdict
from typing import Any

import boto3
from botocore.config import Config
from fastapi import FastAPI, File, HTTPException, UploadFile

app = FastAPI(title="Financial table extraction")

textract = boto3.client(
    "textract",
    region_name=os.getenv("AWS_REGION", "us-east-1"),
    config=Config(
        read_timeout=4,          # fail fast rather than make the analyst wait
        connect_timeout=1,
        retries={"max_attempts": 1},
    ),
)


def _cell_text(cell: dict, blocks_by_id: dict[str, dict]) -> str:
    words = []
    for rel in cell.get("Relationships", []):
        if rel["Type"] != "CHILD":
            continue
        for cid in rel["Ids"]:
            child = blocks_by_id.get(cid)
            if not child:
                continue
            if child["BlockType"] == "WORD":
                words.append(child["Text"])
            elif child["BlockType"] == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                words.append("X")
    return " ".join(words).strip()


def _parse_tables(blocks: list[dict]) -> list[dict[str, Any]]:
    blocks_by_id = {b["Id"]: b for b in blocks}
    tables = []

    for table in (b for b in blocks if b["BlockType"] == "TABLE"):
        grid: dict[int, dict[int, dict]] = defaultdict(dict)
        header_rows: set[int] = set()

        for rel in table.get("Relationships", []):
            if rel["Type"] != "CHILD":
                continue
            for cid in rel["Ids"]:
                cell = blocks_by_id.get(cid)
                if not cell or cell["BlockType"] != "CELL":
                    continue
                r, c = cell["RowIndex"], cell["ColumnIndex"]
                text = _cell_text(cell, blocks_by_id)
                grid[r][c] = {
                    "text": text,
                    "confidence": round(cell.get("Confidence", 0.0), 2),
                    "rowSpan": cell.get("RowSpan", 1),
                    "columnSpan": cell.get("ColumnSpan", 1),
                }
                if "COLUMN_HEADER" in cell.get("EntityTypes", []):
                    header_rows.add(r)

        if not grid:
            continue

        n_rows = max(grid)
        n_cols = max(max(cols) for cols in grid.values())

        # Fallback: if Textract didn't tag headers, treat the first row as the header.
        if not header_rows:
            header_rows = {1}

        headers: list[str] = []
        for c in range(1, n_cols + 1):
            parts = [grid[r].get(c, {}).get("text", "") for r in sorted(header_rows)]
            headers.append(" ".join(p for p in parts if p).strip())

        rows = []
        for r in range(1, n_rows + 1):
            if r in header_rows:
                continue
            cells = [grid[r].get(c, {"text": "", "confidence": 0.0}) for c in range(1, n_cols + 1)]
            rows.append(
                {
                    "label": cells[0]["text"],          # first column = row label (line item)
                    "cells": [c["text"] for c in cells[1:]],
                    "confidence": [c["confidence"] for c in cells],
                }
            )

        tables.append(
            {
                "confidence": round(table.get("Confidence", 0.0), 2),
                "boundingBox": table["Geometry"]["BoundingBox"],
                "headers": headers,
                "rows": rows,
            }
        )

    return tables


@app.post("/extract")
async def extract(file: UploadFile = File(...)) -> dict[str, Any]:
    """Accepts ONE page (single-page PDF, PNG, or JPEG, <= 10 MB) and returns tables as JSON.
    Split multi-page PDFs into pages upstream so each preview request stays fast."""
    data = await file.read()
    if len(data) > 10 * 1024 * 1024:
        raise HTTPException(413, "Page must be under 10 MB for synchronous Textract")

    try:
        resp = textract.analyze_document(
            Document={"Bytes": data},
            FeatureTypes=["TABLES"],
        )
    except textract.exceptions.UnsupportedDocumentException:
        raise HTTPException(400, "Unsupported file type; send a single-page PDF, PNG or JPEG")
    except Exception as exc:  # timeouts, throttling, etc.
        raise HTTPException(502, f"Textract error: {exc}")

    return {
        "page": {"width": 1.0, "height": 1.0},  # Textract geometry is normalized 0–1
        "tables": _parse_tables(resp["Blocks"]),
    }


if __name__ == "__main__":
    # Quick local test:  python extract.py path/to/page.pdf
    import json
    import sys

    with open(sys.argv[1], "rb") as f:
        result = textract.analyze_document(Document={"Bytes": f.read()}, FeatureTypes=["TABLES"])
    print(json.dumps(_parse_tables(result["Blocks"]), indent=2))
