            .get("BoundingBox", {})
            .get("Top", 0),
            block.get("Geometry", {})
            .get("BoundingBox", {})
            .get("Left", 0),
        )
    )

    page_block = next(
        (block for block in blocks if block.get("BlockType") == "PAGE"),
        None,
    )

    return {
        "provider": "aws-textract",
        "model": "AnalyzeDocument/TABLES",
        "pageNumber": source_page_number,
        "elapsedMs": elapsed_ms,
        "pageGeometry": _geometry(page_block) if page_block else None,
        "tableCount": len(table_blocks),
        "tables": [
            _serialize_table(table, blocks_by_id, index)
            for index, table in enumerate(table_blocks, start=1)
        ],
    }


async def _analyze_page(
    page_bytes: bytes,
    source_page_number: int,
) -> dict[str, Any]:
    if not page_bytes:
        raise ValueError("The page is empty.")
    if len(page_bytes) > MAX_PAGE_BYTES:
        raise ValueError(
            f"Page {source_page_number} exceeds Textract's "
            f"{MAX_PAGE_BYTES}-byte synchronous request limit."
        )

    async with textract_slots:
        started = time.perf_counter()

        try:
            response = await asyncio.wait_for(
                asyncio.to_thread(
                    textract.analyze_document,
                    Document={"Bytes": page_bytes},
                    FeatureTypes=["TABLES"],
                ),
                timeout=PAGE_TIMEOUT_SECONDS,
            )
        except TimeoutError as exc:
            raise TimeoutError(
                f"Page {source_page_number} exceeded "
                f"{PAGE_TIMEOUT_SECONDS:.1f} seconds."
            ) from exc

        elapsed_ms = round((time.perf_counter() - started) * 1000)
        return _parse_textract_response(
            response=response,
            source_page_number=source_page_number,
            elapsed_ms=elapsed_ms,
        )


def _split_pdf(pdf_bytes: bytes) -> list[bytes]:
    reader = PdfReader(io.BytesIO(pdf_bytes))

    if reader.is_encrypted:
        try:
            reader.decrypt("")
        except Exception as exc:
            raise ValueError("Encrypted PDFs are not supported.") from exc

    if len(reader.pages) > MAX_DOCUMENT_PAGES:
        raise ValueError(
            f"The document contains {len(reader.pages)} pages; "
            f"the configured maximum is {MAX_DOCUMENT_PAGES}."
        )

    pages: list[bytes] = []
    for page in reader.pages:
        writer = PdfWriter()
        writer.add_page(page)
        output = io.BytesIO()
        writer.write(output)
        pages.append(output.getvalue())

    return pages


async def _read_limited(upload: UploadFile, limit: int) -> bytes:
    data = await upload.read(limit + 1)
    if len(data) > limit:
        raise HTTPException(
            status_code=413,
            detail=f"Upload exceeds the {limit}-byte limit.",
        )
    return data


def _client_error_detail(exc: Exception) -> str:
    if isinstance(exc, ClientError):
        error = exc.response.get("Error", {})
        return f"{error.get('Code', 'TextractError')}: {error.get('Message', str(exc))}"
    return str(exc)


