@app.post("/v1/extract-page")
async def extract_page(
    page_number: int = 1,
    file: UploadFile = File(...),
) -> dict[str, Any]:
    """
    Low-latency endpoint for one PDF/image page.

    The TypeScript backend should call this endpoint as soon as each page is
    available, allowing the browser to render tables page by page.
    """
    page_bytes = await _read_limited(file, MAX_PAGE_BYTES)

    try:
        return await _analyze_page(page_bytes, page_number)
    except TimeoutError as exc:
        raise HTTPException(status_code=504, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except (ClientError, BotoCoreError) as exc:
        raise HTTPException(
            status_code=502,
            detail=_client_error_detail(exc),
        ) from exc


@app.post("/v1/extract-document")
async def extract_document(
    file: UploadFile = File(...),
) -> StreamingResponse:
    """
    Accepts a complete PDF and streams one NDJSON object per completed page.
    Pages may arrive out of order; use pageNumber when updating the preview.
    """
    if file.content_type not in {
        "application/pdf",
        "application/octet-stream",
    }:
        raise HTTPException(
            status_code=415,
            detail="The document endpoint accepts PDF files only.",
        )

    pdf_bytes = await _read_limited(file, MAX_DOCUMENT_BYTES)

    try:
        pages = await asyncio.to_thread(_split_pdf, pdf_bytes)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

    async def stream_results():
        async def process(page_number: int, page_bytes: bytes):
            try:
                return await _analyze_page(page_bytes, page_number)
            except Exception as exc:
                return {
                    "pageNumber": page_number,
                    "error": {
                        "type": type(exc).__name__,
                        "message": _client_error_detail(exc),
                    },
                }

        tasks = [
            asyncio.create_task(process(index, page_bytes))
            for index, page_bytes in enumerate(pages, start=1)
        ]

        try:
            for completed in asyncio.as_completed(tasks):
                result = await completed
                yield json.dumps(result, separators=(",", ":")) + "\n"
        finally:
            for task in tasks:
                if not task.done():
                    task.cancel()

    return StreamingResponse(
        stream_results(),
        media_type="application/x-ndjson",
        headers={
            "Cache-Control": "no-store",
            "X-Extraction-Provider": "aws-textract",
        },
    )
