Invoices with quality.needs_review=true should not be paid automatically.
"""

from __future__ import annotations

import json
import os
import sys
import time
import uuid
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any
from urllib.parse import quote

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry


API_VERSION = "2024-11-30"
DEFAULT_MODEL_ID = "prebuilt-invoice"
DEFAULT_CONFIDENCE_THRESHOLD = Decimal("0.90")
POLL_INTERVAL_SECONDS = 2.0
ANALYSIS_TIMEOUT_SECONDS = 300.0


class DocumentIntelligenceError(RuntimeError):
    pass


def decimal_string(value: Any) -> str | None:
    if value is None:
        return None
    try:
        return format(Decimal(str(value)), "f")
    except (InvalidOperation, ValueError, TypeError):
        return None


def field_value(field: dict[str, Any] | None) -> Any:
    """Return a JSON-safe normalized value while preserving decimals as strings."""
    if not field:
        return None

    if "valueCurrency" in field:
        currency = field["valueCurrency"] or {}
        value = {
            "amount": decimal_string(currency.get("amount")),
            "currency_code": currency.get("currencyCode"),
            "currency_symbol": currency.get("currencySymbol"),
        }
        return {key: val for key, val in value.items() if val is not None}

    if "valueNumber" in field:
        return decimal_string(field["valueNumber"])

    if "valueInteger" in field:
        return str(field["valueInteger"])

    for key in (
        "valueString",
        "valueDate",
        "valueTime",
        "valuePhoneNumber",
        "valueCountryRegion",
        "valueSelectionMark",
        "valueSignature",
        "valueBoolean",
    ):
        if key in field:
            return field[key]

    if "valueAddress" in field:
        return field["valueAddress"]

    if "valueArray" in field:
        return [normalize_field(item) for item in field["valueArray"] or []]

    if "valueObject" in field:
        return {
            name: normalize_field(value)
            for name, value in (field["valueObject"] or {}).items()
        }

    return field.get("content")


def normalize_field(field: dict[str, Any] | None) -> dict[str, Any] | None:
    if not field:
        return None

    return {
        "value": field_value(field),
        "raw": field.get("content"),
        "confidence": field.get("confidence"),
    }


def first_field(
    fields: dict[str, dict[str, Any]], *names: str
) -> dict[str, Any] | None:
    for name in names:
        if fields.get(name):
            return fields[name]
    return None


def decimal_from_field(field: dict[str, Any] | None) -> Decimal | None:
    if not field:
        return None

    value: Any = None
    if "valueCurrency" in field:
        value = (field.get("valueCurrency") or {}).get("amount")
    elif "valueNumber" in field:
        value = field.get("valueNumber")
    elif "valueInteger" in field:
        value = field.get("valueInteger")

    if value is None:
        return None

    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None


def currency_from_field(field: dict[str, Any] | None) -> str | None:
    if not field:
        return None
    currency = field.get("valueCurrency") or {}
    return currency.get("currencyCode") or currency.get("currencySymbol")


def approximately_equal(
    left: Decimal,
    right: Decimal,
    absolute_tolerance: Decimal = Decimal("0.02"),
    relative_tolerance: Decimal = Decimal("0.005"),
) -> bool:
    difference = abs(left - right)
    scale = max(abs(left), abs(right), Decimal("1"))
    return difference <= max(absolute_tolerance, scale * relative_tolerance)


class AzureInvoiceExtractor:
    def __init__(
        self,
        endpoint: str,
        key: str,
        model_id: str = DEFAULT_MODEL_ID,
        confidence_threshold: Decimal = DEFAULT_CONFIDENCE_THRESHOLD,
    ) -> None:
        self.endpoint = endpoint.rstrip("/")
        self.key = key
        self.model_id = model_id
        self.confidence_threshold = confidence_threshold

        retry_policy = Retry(
            total=5,
            backoff_factor=1.0,
            status_forcelist=(429, 500, 502, 503, 504),
            allowed_methods=frozenset({"GET"}),
            respect_retry_after_header=True,
        )
        self.session = requests.Session()
        self.session.mount("https://", HTTPAdapter(max_retries=retry_policy))

    def analyze(
        self,
        pdf_bytes: bytes,
        *,
        filename: str | None = None,
    ) -> dict[str, Any]:
        result = self._submit_and_poll(pdf_bytes)

        documents = [
            self._normalize_document(document, index)
            for index, document in enumerate(result.get("documents") or [])
        ]

        if not documents:
            raise DocumentIntelligenceError(
                "The API completed successfully but found no invoice documents."
            )

        return {
            "api": {
                "provider": "Azure AI Document Intelligence",
                "model_id": self.model_id,
                "api_version": API_VERSION,
                "features": ["ocrHighResolution"],
            },
            "source": {
                "filename": filename,
                "page_count": len(result.get("pages") or []),
            },
            "documents": documents,
        }

    def _submit_and_poll(self, document: bytes) -> dict[str, Any]:
        model_id = quote(self.model_id, safe="")
        url = (
            f"{self.endpoint}/documentintelligence/"
            f"documentModels/{model_id}:analyze"
        )
        params = [
            ("api-version", API_VERSION),
            ("_overload", "analyzeDocument"),
            ("features", "ocrHighResolution"),
        ]
        request_id = str(uuid.uuid4())
        headers = {
            "Ocp-Apim-Subscription-Key": self.key,
            "Content-Type": "application/octet-stream",
            "Accept": "application/json",
            "x-ms-client-request-id": request_id,
        }

        response = None
        for attempt in range(5):
            response = self.session.post(
                url,
                params=params,
                headers=headers,
                data=document,
                timeout=(15, 120),
            )
            if response.status_code not in {429, 500, 502, 503, 504}:
                break

            retry_after = response.headers.get("Retry-After")
            delay = float(retry_after) if retry_after and retry_after.isdigit() else 2**attempt
            time.sleep(min(delay, 30))

        assert response is not None

        if response.status_code != 202:
            raise DocumentIntelligenceError(
                f"Analyze request failed with HTTP {response.status_code}: "
                f"{response.text[:1000]}"
            )

        operation_url = response.headers.get("Operation-Location")
        if not operation_url:
            raise DocumentIntelligenceError(
                "Azure did not return an Operation-Location header."
            )

        poll_headers = {
            "Ocp-Apim-Subscription-Key": self.key,
            "Accept": "application/json",
        }
        deadline = time.monotonic() + ANALYSIS_TIMEOUT_SECONDS

        while time.monotonic() < deadline:
            poll_response = self.session.get(
                operation_url,
                headers=poll_headers,
                timeout=(15, 60),
            )
            if poll_response.status_code != 200:
                raise DocumentIntelligenceError(
                    f"Polling failed with HTTP {poll_response.status_code}: "
                    f"{poll_response.text[:1000]}"
                )

            operation = poll_response.json()
            status = str(operation.get("status", "")).lower()

            if status == "succeeded":
                return operation["analyzeResult"]

            if status in {"failed", "canceled"}:
                error = operation.get("error") or {}
                raise DocumentIntelligenceError(
                    f"Invoice analysis {status}: "
                    f"{error.get('code', 'UnknownError')} - "
                    f"{error.get('message', 'No error message')}"
                )

            retry_after = poll_response.headers.get("Retry-After")
            delay = (
                float(retry_after)
                if retry_after and retry_after.isdigit()
                else POLL_INTERVAL_SECONDS
            )
            time.sleep(delay)

        raise TimeoutError(
            f"Invoice analysis exceeded {ANALYSIS_TIMEOUT_SECONDS} seconds."
        )

    def _normalize_document(
        self,
        document: dict[str, Any],
        document_index: int,
    ) -> dict[str, Any]:
        fields = document.get("fields") or {}
        items_field = first_field(fields, "Items")
        item_wrappers = (items_field or {}).get("valueArray") or []
        raw_items = [
            item.get("valueObject") or {}
            for item in item_wrappers
            if isinstance(item, dict)
        ]

        line_items = [
            self._normalize_line_item(item_fields, index)
            for index, item_fields in enumerate(raw_items, start=1)
        ]

        quality = self._validate(fields, raw_items, document.get("confidence"))

        return {
            "document_index": document_index,
            "document_type": document.get("docType"),
            "document_confidence": document.get("confidence"),
            "supplier": {
                "name": normalize_field(first_field(fields, "VendorName")),
                "tax_id": normalize_field(first_field(fields, "VendorTaxId")),
                "address": normalize_field(first_field(fields, "VendorAddress")),
                "address_recipient": normalize_field(
                    first_field(fields, "VendorAddressRecipient")
                ),
            },
            "customer": {
                "name": normalize_field(first_field(fields, "CustomerName")),
                "customer_id": normalize_field(first_field(fields, "CustomerId")),
                "tax_id": normalize_field(first_field(fields, "CustomerTaxId")),
                "billing_address": normalize_field(
                    first_field(fields, "BillingAddress")
                ),
                "shipping_address": normalize_field(
                    first_field(fields, "ShippingAddress")
                ),
            },
            "invoice": {
                "invoice_number": normalize_field(first_field(fields, "InvoiceId")),
                "invoice_date": normalize_field(first_field(fields, "InvoiceDate")),
                "due_date": normalize_field(first_field(fields, "DueDate")),
                "purchase_order": normalize_field(
                    first_field(fields, "PurchaseOrder")
                ),
                "payment_terms": normalize_field(
                    first_field(fields, "PaymentTerm", "PaymentTerms")
                ),
                "service_start_date": normalize_field(
                    first_field(fields, "ServiceStartDate")
                ),
                "service_end_date": normalize_field(
                    first_field(fields, "ServiceEndDate")
                ),
            },
            "taxes": {
                "supplier_tax_id": normalize_field(
                    first_field(fields, "VendorTaxId")
                ),
                "customer_tax_id": normalize_field(
                    first_field(fields, "CustomerTaxId")
                ),
                "total_tax": normalize_field(first_field(fields, "TotalTax")),
                "tax_details": normalize_field(first_field(fields, "TaxDetails")),
            },
            "totals": {
                "subtotal": normalize_field(first_field(fields, "SubTotal")),
                "total_tax": normalize_field(first_field(fields, "TotalTax")),
                "invoice_total": normalize_field(
                    first_field(fields, "InvoiceTotal")
                ),
                "amount_due": normalize_field(first_field(fields, "AmountDue")),
                "previous_unpaid_balance": normalize_field(
                    first_field(fields, "PreviousUnpaidBalance")
                ),
            },
            "line_items": line_items,
            "quality": quality,
            # Retain every model field so newly supported fields are never discarded.
            "all_extracted_fields": {
                name: normalize_field(field) for name, field in fields.items()
            },
        }

    @staticmethod
    def _normalize_line_item(
        fields: dict[str, dict[str, Any]],
        index: int,
    ) -> dict[str, Any]:
        mapped_names = {
            "Description",
            "ProductCode",
            "Quantity",
            "Unit",
            "UnitPrice",
            "Tax",
            "TaxRate",
            "Amount",
            "Date",
        }

        return {
            "index": index,
            "description": normalize_field(first_field(fields, "Description")),
            "product_code": normalize_field(first_field(fields, "ProductCode")),
            "quantity": normalize_field(first_field(fields, "Quantity")),
            "unit": normalize_field(first_field(fields, "Unit")),
            "unit_price": normalize_field(first_field(fields, "UnitPrice")),
            "tax": normalize_field(first_field(fields, "Tax")),
            "tax_rate": normalize_field(first_field(fields, "TaxRate")),
            "amount": normalize_field(first_field(fields, "Amount")),
            "date": normalize_field(first_field(fields, "Date")),
            "additional_fields": {
                name: normalize_field(field)
                for name, field in fields.items()
                if name not in mapped_names
            },
        }

    def _validate(
        self,
        fields: dict[str, dict[str, Any]],
        line_items: list[dict[str, dict[str, Any]]],
        document_confidence: float | None,
    ) -> dict[str, Any]:
        issues: list[dict[str, Any]] = []

        def add_issue(
            code: str,
            path: str,
            message: str,
            *,
            expected: str | None = None,
            actual: str | None = None,
        ) -> None:
            issue = {
                "code": code,
                "path": path,
                "message": message,
            }
            if expected is not None:
                issue["expected"] = expected
            if actual is not None:
                issue["actual"] = actual
            issues.append(issue)

        def check_confidence(
            path: str,
            field: dict[str, Any] | None,
            *,
            required: bool,
        ) -> None:
            if not field:
                if required:
                    add_issue(
                        "missing_critical_field",
                        path,
                        "A payment-critical field was not extracted.",
                    )
                return

            confidence = field.get("confidence")
            if confidence is None:
                add_issue(
                    "missing_confidence",
                    path,
                    "The API did not provide a confidence score.",
                )
            elif Decimal(str(confidence)) < self.confidence_threshold:
                add_issue(
                    "low_confidence",
                    path,
                    "Field confidence is below the automatic-processing threshold.",
                    expected=f">={self.confidence_threshold}",
                    actual=str(confidence),
                )

        check_confidence(
            "supplier.name",
            first_field(fields, "VendorName"),
            required=True,
        )
        check_confidence(
            "invoice.invoice_number",
            first_field(fields, "InvoiceId"),
            required=True,
        )
        check_confidence(
            "totals.invoice_total",
            first_field(fields, "InvoiceTotal"),
            required=True,
        )

        for name, output_name in (
            ("SubTotal", "totals.subtotal"),
            ("TotalTax", "totals.total_tax"),
            ("AmountDue", "totals.amount_due"),
        ):
            field = first_field(fields, name)
            if field:
                check_confidence(output_name, field, required=False)

        if not line_items:
            add_issue(
                "missing_line_items",
                "line_items",
                "No line items were extracted.",
            )

        line_amounts: list[Decimal] = []
        currencies: set[str] = set()

        for index, item in enumerate(line_items, start=1):
            prefix = f"line_items[{index - 1}]"
            description = first_field(item, "Description")
            quantity = first_field(item, "Quantity")
            unit_price = first_field(item, "UnitPrice")
            amount = first_field(item, "Amount")

            check_confidence(
                f"{prefix}.description",
                description,
                required=True,
            )
            check_confidence(
                f"{prefix}.amount",
                amount,
                required=True,
            )

            if quantity:
                check_confidence(f"{prefix}.quantity", quantity, required=False)

            if unit_price:
                check_confidence(f"{prefix}.unit_price", unit_price, required=False)

            if unit_price and not quantity:
                add_issue(
                    "missing_quantity",
                    f"{prefix}.quantity",
                    "A unit price was extracted but its quantity was not.",
                )

            quantity_value = decimal_from_field(quantity)
            unit_price_value = decimal_from_field(unit_price)
            amount_value = decimal_from_field(amount)

            if amount_value is not None:
                line_amounts.append(amount_value)

            if (
                quantity_value is not None
                and unit_price_value is not None
                and amount_value is not None
            ):
                calculated = quantity_value * unit_price_value
                if not approximately_equal(calculated, amount_value):
                    add_issue(
                        "line_arithmetic_mismatch",
                        f"{prefix}.amount",
                        "Quantity × unit price does not match the extracted line amount. "
                        "This may indicate a discount, surcharge, or OCR error.",
                        expected=decimal_string(calculated),
                        actual=decimal_string(amount_value),
                    )

            for money_field in (unit_price, amount, first_field(item, "Tax")):
                currency = currency_from_field(money_field)
                if currency:
                    currencies.add(currency)

        subtotal_field = first_field(fields, "SubTotal")
        tax_field = first_field(fields, "TotalTax")
        invoice_total_field = first_field(fields, "InvoiceTotal")

        subtotal = decimal_from_field(subtotal_field)
        total_tax = decimal_from_field(tax_field)
        invoice_total = decimal_from_field(invoice_total_field)

        for money_field in (
            subtotal_field,
            tax_field,
            invoice_total_field,
            first_field(fields, "AmountDue"),
        ):
            currency = currency_from_field(money_field)
            if currency:
                currencies.add(currency)

        if subtotal is not None and line_amounts:
            line_sum = sum(line_amounts, Decimal("0"))
            if not approximately_equal(line_sum, subtotal):
                add_issue(
                    "subtotal_mismatch",
                    "totals.subtotal",
                    "The sum of extracted line amounts does not match the subtotal. "
                    "Check for discounts, shipping charges, or OCR errors.",
                    expected=decimal_string(line_sum),
                    actual=decimal_string(subtotal),
                )

        if (
            subtotal is not None
            and total_tax is not None
            and invoice_total is not None
        ):
            calculated_total = subtotal + total_tax
            if not approximately_equal(calculated_total, invoice_total):
                add_issue(
                    "invoice_total_mismatch",
                    "totals.invoice_total",
                    "Subtotal + tax does not match the invoice total. "
                    "Check for discounts, fees, rounding, or OCR errors.",
                    expected=decimal_string(calculated_total),
                    actual=decimal_string(invoice_total),
                )

        if len(currencies) > 1:
            add_issue(
                "currency_mismatch",
                "totals",
                "Multiple currencies were extracted from one invoice.",
                actual=", ".join(sorted(currencies)),
            )

        if (
            document_confidence is not None
            and Decimal(str(document_confidence)) < self.confidence_threshold
        ):
            add_issue(
                "low_document_confidence",
                "document_confidence",
                "Overall document confidence is below the threshold.",
                expected=f">={self.confidence_threshold}",
                actual=str(document_confidence),
            )

        return {
            "confidence_threshold": str(self.confidence_threshold),
            "needs_review": bool(issues),
            "auto_pay_eligible": not issues,
            "issues": issues,
        }


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python extract_invoice.py <invoice.pdf>")

    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    model_id = os.environ.get("AZURE_DI_MODEL_ID", DEFAULT_MODEL_ID)

    try:
        threshold = Decimal(
            os.environ.get(
                "INVOICE_CONFIDENCE_THRESHOLD",
                str(DEFAULT_CONFIDENCE_THRESHOLD),
            )
        )
    except InvalidOperation as exc:
        raise SystemExit("INVOICE_CONFIDENCE_THRESHOLD must be a decimal.") from exc

    if not endpoint or not key:
        raise SystemExit(
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and "
            "AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    path = Path(sys.argv[1])
    if not path.is_file():
        raise SystemExit(f"File not found: {path}")

    extractor = AzureInvoiceExtractor(
        endpoint=endpoint,
        key=key,
        model_id=model_id,
        confidence_threshold=threshold,
    )
    output = extractor.analyze(path.read_bytes(), filename=path.name)
    print(json.dumps(output, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
