"""
Invoice header extraction pipeline (supplier_id, invoice_date, currency, total)
using OpenAI gpt-4o-mini through the Batch API.

pip install openai pdfplumber pymupdf

Env: OPENAI_API_KEY
"""

import base64
import io
import json
import os
import time
from pathlib import Path

import fitz  # pymupdf
import pdfplumber
from openai import OpenAI

client = OpenAI()

INPUT_DIR = Path("invoices_in")      # PDFs to process (one invoice per file)
OUTPUT_DIR = Path("invoices_out")    # JSON results
WORK_DIR = Path("batch_work")
MODEL = "gpt-4o-mini"
MAX_REQUESTS_PER_BATCH = 20_000      # stay well under 50k / 200MB limits
MIN_TEXT_CHARS = 200                 # below this, treat page as a scan
SCAN_DPI = 150
MAX_RETRY_ROUNDS = 3

SYSTEM_PROMPT = (
    "You extract header fields from supplier invoices written in English or Italian. "
    "Return only the requested fields. Use null if a field is not present."
)

INVOICE_SCHEMA = {
    "name": "invoice_header",
    "strict": True,
    "schema": {
        "type": "object",
        "properties": {
            "supplier_id": {
                "type": ["string", "null"],
                "description": "Supplier identifier: VAT number / Partita IVA / Codice Fiscale / supplier code as printed.",
            },
            "invoice_date": {
                "type": ["string", "null"],
                "description": "Invoice date (Data fattura) in ISO format YYYY-MM-DD.",
            },
            "currency": {
                "type": ["string", "null"],
                "description": "ISO 4217 currency code, e.g. EUR, USD, GBP.",
            },
            "total": {
                "type": ["number", "null"],
                "description": "Grand total including tax (Totale fattura / Totale documento). Plain number, no thousands separators.",
            },
        },
        "required": ["supplier_id", "invoice_date", "currency", "total"],
        "additionalProperties": False,
    },
}


# ---------------------------------------------------------------------------
# Document preparation: text for digital PDFs, image for scans
# ---------------------------------------------------------------------------
def extract_text(pdf_path: Path) -> str:
    text_parts = []
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages[:3]:  # header fields are on the first pages
            text_parts.append(page.extract_text() or "")
    return "\n\n".join(text_parts).strip()


def render_first_pages_as_images(pdf_path: Path, max_pages: int = 2) -> list[str]:
    images = []
    with fitz.open(pdf_path) as doc:
        for page in doc.pages(0, min(max_pages, doc.page_count)):
            pix = page.get_pixmap(dpi=SCAN_DPI)
            img_bytes = pix.tobytes("jpeg")
            images.append(base64.b64encode(img_bytes).decode("ascii"))
    return images


def build_user_content(pdf_path: Path):
    text = extract_text(pdf_path)
    if len(text) >= MIN_TEXT_CHARS:
        return [{"type": "text", "text": f"Invoice text:\n\n{text}"}]
    # Scanned PDF -> send page images
    content = [{"type": "text", "text": "Extract the fields from this scanned invoice."}]
    for b64 in render_first_pages_as_images(pdf_path):
        content.append(
            {
                "type": "image_url",
                "image_url": {"url": f"data:image/jpeg;base64,{b64}", "detail": "low"},
            }
        )
    return content


def make_request(custom_id: str, pdf_path: Path) -> dict:
    return {
        "custom_id": custom_id,
        "method": "POST",
        "url": "/v1/chat/completions",
        "body": {
            "model": MODEL,
            "temperature": 0,
            "max_tokens": 150,
            "messages": [
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": build_user_content(pdf_path)},
            ],
            "response_format": {"type": "json_schema", "json_schema": INVOICE_SCHEMA},
        },
    }


# ---------------------------------------------------------------------------
# Batch submission / polling
# ---------------------------------------------------------------------------
def write_batch_files(pdf_paths: list[Path]) -> list[Path]:
    WORK_DIR.mkdir(exist_ok=True)
    files, current, idx = [], [], 0
    for pdf_path in pdf_paths:
        custom_id = pdf_path.stem
        try:
            current.append(make_request(custom_id, pdf_path))
        except Exception as e:
            print(f"[prep-error] {pdf_path}: {e}")
            continue
        if len(current) >= MAX_REQUESTS_PER_BATCH:
            files.append(_flush(current, idx)); current, idx = [], idx + 1
    if current:
        files.append(_flush(current, idx))
    return files


def _flush(requests: list[dict], idx: int) -> Path:
    path = WORK_DIR / f"batch_{int(time.time())}_{idx}.jsonl"
    with path.open("w", encoding="utf-8") as f:
        for r in requests:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    return path


def submit_batch(jsonl_path: Path) -> str:
    with jsonl_path.open("rb") as f:
        uploaded = client.files.create(file=f, purpose="batch")
    batch = client.batches.create(
        input_file_id=uploaded.id,
        endpoint="/v1/chat/completions",
        completion_window="24h",
        metadata={"source": jsonl_path.name},
    )
    print(f"[submitted] {jsonl_path.name} -> {batch.id}")
    return batch.id


def wait_for_batches(batch_ids: list[str], poll_seconds: int = 300) -> dict:
    pending = set(batch_ids)
    finished = {}
    while pending:
        for bid in list(pending):
            b = client.batches.retrieve(bid)
            if b.status in ("completed", "failed", "expired", "cancelled"):
                print(f"[{b.status}] {bid} "
                      f"ok={b.request_counts.completed} failed={b.request_counts.failed}")
                finished[bid] = b
                pending.discard(bid)
        if pending:
            time.sleep(poll_seconds)
    return finished


def collect_results(batches: dict) -> tuple[dict, set]:
    """Returns ({custom_id: fields}, {custom_ids that failed})."""
    results, failed = {}, set()
    for bid, b in batches.items():
        if b.output_file_id:
            for line in client.files.content(b.output_file_id).text.splitlines():
                rec = json.loads(line)
                cid = rec["custom_id"]
                resp = rec.get("response") or {}
                if resp.get("status_code") == 200:
                    try:
                        content = resp["body"]["choices"][0]["message"]["content"]
                        results[cid] = json.loads(content)
                    except Exception:
                        failed.add(cid)
                else:
                    failed.add(cid)
        if b.error_file_id:
            for line in client.files.content(b.error_file_id).text.splitlines():
                failed.add(json.loads(line)["custom_id"])
    return results, failed


# ---------------------------------------------------------------------------
# Main pipeline with retry of failed items
# ---------------------------------------------------------------------------
def run():
    OUTPUT_DIR.mkdir(exist_ok=True)
    pdfs = {p.stem: p for p in sorted(INPUT_DIR.glob("*.pdf"))
            if not (OUTPUT_DIR / f"{p.stem}.json").exists()}
    to_process = list(pdfs.values())
    print(f"{len(to_process)} invoices to process")

    for attempt in range(1, MAX_RETRY_ROUNDS + 1):
        if not to_process:
            break
        print(f"--- round {attempt}: {len(to_process)} documents ---")
        batch_files = write_batch_files(to_process)
        batch_ids = [submit_batch(p) for p in batch_files]
        finished = wait_for_batches(batch_ids)
        results, failed = collect_results(finished)

        for cid, fields in results.items():
            out = {"file": pdfs[cid].name, **fields}
            (OUTPUT_DIR / f"{cid}.json").write_text(
                json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8"
            )

        # Anything submitted but neither in results nor explicitly failed is retried too
        submitted = {p.stem for p in to_process}
        unresolved = (submitted - set(results)) | failed
        to_process = [pdfs[c] for c in unresolved]
        print(f"round {attempt}: {len(results)} ok, {len(to_process)} to retry")

    if to_process:
        (WORK_DIR / "unprocessed.txt").write_text("\n".join(p.name for p in to_process))
        print(f"{len(to_process)} documents still unprocessed, listed in batch_work/unprocessed.txt")


if __name__ == "__main__":
    run()
```

How it keeps cost down:
- **Digital PDFs (95%)**: text pulled locally with `pdfplumber`, only the first 3 pages sent → ~1k input tokens per invoice.
- **Scans (5%)**: first 2 pages rendered at 150 DPI and sent with `detail: "low"` (fixed 85 tokens per image) — no separate OCR service needed.
- **Batch API**: 50% off list price, 24h window matches overnight processing; failed items are automatically resubmitted in a new batch (up to 3 rounds).
- **Structured output** (`json_schema`, `strict: true`) guarantees exactly your four fields, so your downstream reconciliation against accounting records works without parsing surprises.

Ballpark: ~1.2M × ~1.2k tokens × $0.075/M ≈ **$110–200/month**, leaving ample headroom in the $4,800 budget even if you later move the scanned subset to `detail: "high"` for tricky layouts.

