    BotoCoreError,
    ClientError,
    ConnectTimeoutError,
    ReadTimeoutError,
)
from fastapi import FastAPI, File, Form, HTTPException, UploadFile

app = FastAPI()
MAX_UPLOAD_BYTES = 50 * 1024 * 1024

textract = boto3.client(
    "textract",
    region_name=os.getenv("AWS_REGION", "us-east-1"),
    config=Config(
        connect_timeout=0.5,
        read_timeout=4.0,
        retries={"total_max_attempts": 1},  # No hidden retries in the preview path.
        max_pool_connections=32,
    ),
)
# Socket timeouts are NOT an end-to-end five-second guarantee.


def render_pdf_page(pdf: bytes, page_number: int) -> bytes:
    """Render only the requested page; also works for scanned PDFs."""
    with pymupdf.open(stream=pdf, filetype="pdf") as document:
        if document.needs_pass:
            raise ValueError("Password-protected PDFs are not supported.")
        if not 1 <= page_number <= len(document):
            raise ValueError(f"page must be between 1 and {len(document)}.")

        page = document[page_number - 1]
        # Start at 180 DPI; cap dimensions to bound payload size.
        scale = min(180 / 72, 5000 / max(page.rect.width, page.rect.height))
        image = page.get_pixmap(
            matrix=pymupdf.Matrix(scale, scale),
            colorspace=pymupdf.csRGB,
            alpha=False,
        ).tobytes("jpeg", jpg_quality=90)

    if len(image) > 10 * 1024 * 1024:
        raise ValueError("Rendered page exceeds Textract's synchronous size limit.")
    return image


def normalize_tables(response: dict) -> list[dict]:
    blocks = {block["Id"]: block for block in response.get("Blocks", [])}

    def related(block: dict, relationship_type: str = "CHILD") -> list[dict]:
        return [
            blocks[block_id]
            for relationship in block.get("Relationships", [])
            if relationship["Type"] == relationship_type
            for block_id in relationship["Ids"]
            if block_id in blocks
        ]

    def text(block: dict) -> str:
        if block["BlockType"] == "WORD":
            return block.get("Text", "")
        if block["BlockType"] == "SELECTION_ELEMENT":
            return (
                "[x]" if block.get("SelectionStatus") == "SELECTED" else "[ ]"
            )
        return " ".join(filter(None, (text(child) for child in related(block))))

    def cell_json(block: dict) -> dict:
        return {
            "row": block["RowIndex"],          # One-based indices.
            "column": block["ColumnIndex"],
            "row_span": block.get("RowSpan", 1),
            "column_span": block.get("ColumnSpan", 1),
            "value": text(block),             # Preserve currency/precision.
            "roles": block.get("EntityTypes", []),
            "confidence": block.get("Confidence"),  # 0–100.
            "bounding_box": block.get("Geometry", {}).get("BoundingBox"),
        }

    tables = []
    for block in blocks.values():
        if block["BlockType"] != "TABLE":
            continue

        cells = sorted(
            [
                cell_json(child)
                for child in related(block)
                if child["BlockType"] == "CELL"
            ],
            key=lambda cell: (cell["row"], cell["column"]),
        )
        merged_cells = [
            cell_json(child)
            for child in related(block, "MERGED_CELL")
            if child["BlockType"] == "MERGED_CELL"
        ]
        headers = [
            cell
            for cell in cells + merged_cells
            if "COLUMN_HEADER" in cell["roles"] and cell["value"]
        ]
        header_rows = {
            row
            for header in headers
            for row in range(header["row"], header["row"] + header["row_span"])
        }

        tables.append(
            {
                "table_index": len(tables) + 1,
                "cells": cells,
                # Separate to preserve merged-cell structure without replacing
                # constituent cells. Headers can include both representations.
                "merged_cells": merged_cells,
                "headers": headers,
                "row_labels": [
                    {
                        "row": cell["row"],
                        "value": cell["value"],
                        "inferred": True,
                        "method": "nonempty_first_column_excluding_header_rows",
                    }
                    for cell in cells
                    if cell["column"] == 1
                    and cell["row"] not in header_rows
                    and cell["value"]
                ],
                "bounding_box": block.get("Geometry", {}).get("BoundingBox"),
            }
        )
    return tables


@app.post("/preview")
def preview(
    file: UploadFile = File(...),
    page: int = Form(1, ge=1),
) -> dict:
    # A synchronous route runs in FastAPI's thread pool, keeping boto3 and PDF
    # rendering off the event loop. Bound deployment concurrency to AWS quotas.
    started = time.perf_counter()
    pdf = file.file.read(MAX_UPLOAD_BYTES + 1)
    if len(pdf) > MAX_UPLOAD_BYTES:
        raise HTTPException(413, "PDF exceeds the 50 MiB upload limit.")

    try:
        image = render_pdf_page(pdf, page)
        response = textract.analyze_document(
            Document={"Bytes": image},
            FeatureTypes=["TABLES"],  # Avoid unnecessary FORMS/QUERIES work.
        )
        tables = normalize_tables(response)
    except (ValueError, RuntimeError, pymupdf.FileDataError) as exc:
        raise HTTPException(422, "Invalid, protected, or unsupported PDF/page.") from exc
    except (ConnectTimeoutError, ReadTimeoutError) as exc:
        raise HTTPException(504, "Table extraction timed out.") from exc
    except ClientError as exc:
        code = exc.response.get("Error", {}).get("Code", "")
        throttled = code in {
            "ThrottlingException",
            "ProvisionedThroughputExceededException",
            "LimitExceededException",
        }
        raise HTTPException(
            429 if throttled else 502,
            "Extraction capacity exceeded." if throttled else "Extraction failed.",
        ) from exc
    except BotoCoreError as exc:
        raise HTTPException(502, "Extraction service unavailable.") from exc

    elapsed_ms = round((time.perf_counter() - started) * 1000)
    return {
        "page": page,
        "tables": tables,
        "processing_ms": elapsed_ms,  # Excludes upload and request queue time.
        "requires_analyst_verification": True,
    }


