def normalize_invoice(document: dict[str, Any], document_index: int) -> dict[str, Any]:
    fields: dict[str, Any] = document.get("fields") or {}
    reasons: list[str] = []

    def require_confident(
        field: dict[str, Any] | None,
        path: str,
        *,
        required: bool = True,
    ) -> None:
        if not field:
            if required:
                reasons.append(f"{path}: missing")
            return

        confidence = confidence_of(field)
        if confidence is None:
            reasons.append(f"{path}: confidence unavailable")
        elif confidence < MIN_CONFIDENCE:
            reasons.append(
                f"{path}: confidence {confidence} is below {MIN_CONFIDENCE}"
            )

    supplier = {
        output_name: field_value(fields.get(azure_name))
        for output_name, azure_name in SUPPLIER_FIELDS.items()
    }
    supplier_evidence = {
        output_name: field_evidence(fields.get(azure_name))
        for output_name, azure_name in SUPPLIER_FIELDS.items()
    }

    invoice_header = {
        output_name: field_value(fields.get(azure_name))
        for output_name, azure_name in INVOICE_FIELDS.items()
    }
    invoice_evidence = {
        output_name: field_evidence(fields.get(azure_name))
        for output_name, azure_name in INVOICE_FIELDS.items()
    }

    totals = {
        output_name: field_value(fields.get(azure_name))
        for output_name, azure_name in TOTAL_FIELDS.items()
    }
    totals_evidence = {
        output_name: field_evidence(fields.get(azure_name))
        for output_name, azure_name in TOTAL_FIELDS.items()
    }

    tax_details_field = fields.get("TaxDetails")
    taxes = {
        "total": field_value(fields.get("TotalTax")),
        "details": field_value(tax_details_field) or [],
    }
    taxes_evidence = {
        "total": field_evidence(fields.get("TotalTax")),
        "details": field_evidence(tax_details_field),
    }

    items_field = fields.get("Items")
    item_fields = (items_field or {}).get("valueArray", [])
    line_items: list[dict[str, Any]] = []
    line_item_evidence: list[dict[str, Any]] = []

    for item in item_fields:
        item_object: dict[str, Any] = item.get("valueObject") or {}

        normalized = {
            output_name: field_value(item_object.get(azure_name))
            for output_name, azure_name in LINE_ITEM_FIELDS.items()
        }
        evidence = {
            output_name: field_evidence(item_object.get(azure_name))
            for output_name, azure_name in LINE_ITEM_FIELDS.items()
        }

        known_names = set(LINE_ITEM_FIELDS.values())
        extra = {
            snake_case(name): field_value(value)
            for name, value in item_object.items()
            if name not in known_names
        }
        extra_evidence = {
            snake_case(name): field_evidence(value)
            for name, value in item_object.items()
            if name not in known_names
        }

        if extra:
            normalized["extra"] = extra
            evidence["extra"] = extra_evidence

        line_items.append(normalized)
        line_item_evidence.append(evidence)

    require_confident(fields.get("VendorName"), "supplier.name")
    require_confident(fields.get("InvoiceId"), "invoice_number")
    require_confident(fields.get("SubTotal"), "totals.subtotal")
    require_confident(fields.get("InvoiceTotal"), "totals.invoice_total")

    if not fields.get("TotalTax") and not tax_details_field:
        reasons.append("taxes: total tax and tax details are both missing")
    else:
        require_confident(fields.get("TotalTax"), "taxes.total", required=False)
        require_confident(tax_details_field, "taxes.details", required=False)

    if not item_fields:
        reasons.append("line_items: no line items extracted")
    else:
        require_confident(items_field, "line_items")

    for index, item in enumerate(item_fields):
        obj = item.get("valueObject") or {}
        prefix = f"line_items[{index}]"

        require_confident(obj.get("Description"), f"{prefix}.description")
        require_confident(obj.get("Quantity"), f"{prefix}.quantity")
        require_confident(obj.get("UnitPrice"), f"{prefix}.unit_price")
        require_confident(obj.get("Amount"), f"{prefix}.amount")

        quantity = field_decimal(obj.get("Quantity"))
        unit_price = field_decimal(obj.get("UnitPrice"))
        amount = field_decimal(obj.get("Amount"))

        has_discount = bool(obj.get("Discount") or obj.get("DiscountRate"))
        if (
            quantity is not None
            and unit_price is not None
            and amount is not None
            and not has_discount
        ):
            calculated_amount = quantity * unit_price
            if not within_tolerance(amount, calculated_amount):
                reasons.append(
                    f"{prefix}: quantity × unit_price is "
                    f"{format(calculated_amount, 'f')}, but amount is "
                    f"{format(amount, 'f')}"
                )

        line_currency = field_currency(obj.get("Amount"))
        unit_currency = field_currency(obj.get("UnitPrice"))
        if line_currency and unit_currency and line_currency != unit_currency:
            reasons.append(
                f"{prefix}: unit price currency {unit_currency} differs from "
                f"amount currency {line_currency}"
            )

    subtotal = field_decimal(fields.get("SubTotal"))
    total_tax = field_decimal(fields.get("TotalTax"))
    total_discount = field_decimal(fields.get("TotalDiscount")) or Decimal("0")
    invoice_total = field_decimal(fields.get("InvoiceTotal"))

    item_amounts = [
        field_decimal((item.get("valueObject") or {}).get("Amount"))
        for item in item_fields
    ]
    if subtotal is not None and item_amounts and all(v is not None for v in item_amounts):
        calculated_subtotal = sum(item_amounts, Decimal("0"))  # type: ignore[arg-type]
        if not within_tolerance(subtotal, calculated_subtotal):
            reasons.append(
                "totals.subtotal: extracted line amounts sum to "
                f"{format(calculated_subtotal, 'f')}, but subtotal is "
                f"{format(subtotal, 'f')}"
            )

    if subtotal is not None and total_tax is not None and invoice_total is not None:
        calculated_total = subtotal - total_discount + total_tax
        if not within_tolerance(invoice_total, calculated_total):
            reasons.append(
                "totals.invoice_total: subtotal - discount + tax equals "
                f"{format(calculated_total, 'f')}, but invoice total is "
                f"{format(invoice_total, 'f')}"
            )

    invoice_currency = field_currency(fields.get("InvoiceTotal"))
    currency_fields = {
        "subtotal": fields.get("SubTotal"),
        "total_tax": fields.get("TotalTax"),
        "amount_due": fields.get("AmountDue"),
    }
    for name, field in currency_fields.items():
        currency = field_currency(field)
        if invoice_currency and currency and currency != invoice_currency:
            reasons.append(
                f"totals.{name}: currency {currency} differs from invoice "
                f"currency {invoice_currency}"
            )

    reasons = list(dict.fromkeys(reasons))

    result = {
        "document_index": document_index,
        "document_type": document.get("docType"),
        "document_confidence": json_safe(document.get("confidence")),
        "supplier": supplier,
        **invoice_header,
        "currency": invoice_currency,
        "taxes": taxes,
        "totals": totals,
        "line_items": line_items,
        "quality": {
            "review_required": bool(reasons),
            "auto_post_eligible": not reasons,
            "minimum_confidence": format(MIN_CONFIDENCE, "f"),
            "reasons": reasons,
            "evidence": {
                "supplier": supplier_evidence,
                **invoice_evidence,
                "taxes": taxes_evidence,
                "totals": totals_evidence,
                "line_items": line_item_evidence,
            },
        },
    }

    return result


async def read_upload(file: UploadFile) -> bytes:
    chunks: list[bytes] = []
    size = 0

    while chunk := await file.read(1024 * 1024):
        size += len(chunk)
        if size > MAX_PDF_BYTES:
            raise HTTPException(
                status_code=413,
                detail=f"PDF exceeds the {MAX_PDF_BYTES}-byte limit",
            )
        chunks.append(chunk)

    pdf = b"".join(chunks)
    if not pdf:
        raise HTTPException(status_code=400, detail="Uploaded PDF is empty")

