```python
"""
Recommendation: Azure AI Document Intelligence's prebuilt-invoice API.

It supports English/German invoices, OCR for degraded scans, supplier/tax/total
fields, and line-item extraction. High-resolution OCR is enabled below. Because
invoice payments are high risk, low-confidence or arithmetically inconsistent
results are explicitly marked for human review.

Install:
    pip install fastapi uvicorn httpx python-multipart

Environment:
    AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT=https://<resource>.cognitiveservices.azure.com
    AZURE_DOCUMENT_INTELLIGENCE_KEY=<key>

Optional:
    AZURE_MODEL_ID=prebuilt-invoice
    MIN_CONFIDENCE=0.95
    MAX_PDF_BYTES=52428800
    ANALYSIS_TIMEOUT_SECONDS=300
    INCLUDE_RAW_RESULT=false

Run:
    uvicorn invoice_api:app --host 0.0.0.0 --port 8000
"""

from __future__ import annotations

import asyncio
import hashlib
import json
import os
import re
import time
from contextlib import asynccontextmanager
from decimal import Decimal, InvalidOperation
from typing import Any
from urllib.parse import quote

import httpx
from fastapi import FastAPI, File, HTTPException, UploadFile


AZURE_ENDPOINT = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT", "").rstrip("/")
AZURE_KEY = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY", "")
AZURE_MODEL_ID = os.getenv("AZURE_MODEL_ID", "prebuilt-invoice")
AZURE_API_VERSION = os.getenv("AZURE_API_VERSION", "2024-11-30")

MIN_CONFIDENCE = Decimal(os.getenv("MIN_CONFIDENCE", "0.95"))
MONEY_TOLERANCE = Decimal(os.getenv("MONEY_TOLERANCE", "0.02"))
MAX_PDF_BYTES = int(os.getenv("MAX_PDF_BYTES", str(50 * 1024 * 1024)))
ANALYSIS_TIMEOUT_SECONDS = int(os.getenv("ANALYSIS_TIMEOUT_SECONDS", "300"))
INCLUDE_RAW_RESULT = os.getenv("INCLUDE_RAW_RESULT", "false").lower() == "true"
USE_HIGH_RES_OCR = os.getenv("USE_HIGH_RES_OCR", "true").lower() == "true"


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.http = httpx.AsyncClient(
        timeout=httpx.Timeout(connect=20, read=120, write=120, pool=20),
        limits=httpx.Limits(max_connections=100, max_keepalive_connections=30),
    )
    yield
    await app.state.http.aclose()


app = FastAPI(
    title="Supplier Invoice Extraction API",
    version="1.0.0",
    lifespan=lifespan,
)


def parse_json(response: httpx.Response) -> dict[str, Any]:
    return json.loads(response.text, parse_float=Decimal)


def json_safe(value: Any) -> Any:
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, dict):
        return {str(k): json_safe(v) for k, v in value.items()}
    if isinstance(value, list):
        return [json_safe(v) for v in value]
    return value


def snake_case(name: str) -> str:
    name = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", name)
    name = re.sub(r"([a-z\d])([A-Z])", r"\1_\2", name)
    return name.replace("-", "_").replace(" ", "_").lower()


def field_value(field: dict[str, Any] | None) -> Any:
    if not field:
        return None

    if "valueCurrency" in field:
        currency = field["valueCurrency"] or {}
        return {
            "amount": json_safe(currency.get("amount")),
            "currency": currency.get("currencyCode"),
        }

    if "valueArray" in field:
        return [field_value(item) for item in field.get("valueArray", [])]

    if "valueObject" in field:
        return {
            snake_case(key): field_value(value)
            for key, value in field.get("valueObject", {}).items()
        }

    if "valueAddress" in field:
        return json_safe(field["valueAddress"])

    value_keys = (
        "valueString",
        "valueDate",
        "valueTime",
        "valuePhoneNumber",
        "valueCountryRegion",
        "valueSelectionMark",
        "valueSignature",
        "valueBoolean",
        "valueInteger",
        "valueNumber",
    )
    for key in value_keys:
        if key in field:
            return json_safe(field[key])

    return field.get("content")


def field_evidence(field: dict[str, Any] | None) -> Any:
    if not field:
        return None

    confidence = field.get("confidence")
    result: dict[str, Any] = {
        "confidence": float(confidence) if confidence is not None else None,
        "source_text": field.get("content"),
        "pages": sorted(
            {
                region["pageNumber"]
                for region in field.get("boundingRegions", [])
                if "pageNumber" in region
            }
        ),
    }

    if "valueArray" in field:
        result["items"] = [
            field_evidence(item) for item in field.get("valueArray", [])
        ]

    if "valueObject" in field:
        result["fields"] = {
            snake_case(key): field_evidence(value)
            for key, value in field.get("valueObject", {}).items()
        }

    return result


def field_decimal(field: dict[str, Any] | None) -> Decimal | None:
    if not field:
        return None

    raw: Any = None
    if "valueCurrency" in field:
        raw = (field.get("valueCurrency") or {}).get("amount")
    elif "valueNumber" in field:
        raw = field.get("valueNumber")
    elif "valueInteger" in field:
        raw = field.get("valueInteger")

    if raw is None:
        return None

    try:
        return Decimal(str(raw))
    except (InvalidOperation, ValueError):
        return None


def field_currency(field: dict[str, Any] | None) -> str | None:
    if not field:
        return None
    return (field.get("valueCurrency") or {}).get("currencyCode")


def confidence_of(field: dict[str, Any] | None) -> Decimal | None:
    if not field or field.get("confidence") is None:
        return None
    return Decimal(str(field["confidence"]))


def within_tolerance(actual: Decimal, expected: Decimal) -> bool:
    return abs(actual - expected) <= MONEY_TOLERANCE


async def request_with_backoff(
    client: httpx.AsyncClient,
    method: str,
    url: str,
    *,
    attempts: int = 5,
    **kwargs: Any,
) -> httpx.Response:
    last_error: Exception | None = None

    for attempt in range(attempts):
        try:
            response = await client.request(method, url, **kwargs)
        except httpx.HTTPError as exc:
            last_error = exc
            if attempt == attempts - 1:
                break
            await asyncio.sleep(min(2**attempt, 15))
            continue

        if response.status_code not in {429, 500, 502, 503, 504}:
            return response

        if attempt == attempts - 1:
            return response

        try:
            delay = float(response.headers.get("Retry-After", 2**attempt))
        except ValueError:
            delay = float(2**attempt)
        await asyncio.sleep(min(delay, 30))

    raise HTTPException(
        status_code=502,
        detail=f"Could not reach Azure Document Intelligence: {last_error}",
    )


async def analyze_pdf(client: httpx.AsyncClient, pdf: bytes) -> dict[str, Any]:
    if not AZURE_ENDPOINT or not AZURE_KEY:
        raise HTTPException(
            status_code=500,
            detail=(
                "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and "
                "AZURE_DOCUMENT_INTELLIGENCE_KEY must be configured"
            ),
        )

    model_id = quote(AZURE_MODEL_ID, safe="")
    analyze_url = (
        f"{AZURE_ENDPOINT}/documentintelligence/"
        f"documentModels/{model_id}:analyze"
    )

    params: dict[str, str] = {"api-version": AZURE_API_VERSION}
    if USE_HIGH_RES_OCR:
        params["features"] = "ocrHighResolution"

    headers = {
        "Ocp-Apim-Subscription-Key": AZURE_KEY,
        "Content-Type": "application/pdf",
    }

    response = await request_with_backoff(
        client,
        "POST",
        analyze_url,
        params=params,
        headers=headers,
        content=pdf,
    )

    if response.status_code not in {200, 202}:
        raise HTTPException(
            status_code=502,
            detail=f"Azure analysis request failed: {response.text[:2000]}",
        )

    if response.status_code == 200:
        return parse_json(response)

    operation_url = response.headers.get("Operation-Location")
    if not operation_url:
        raise HTTPException(
            status_code=502,
            detail="Azure did not return an Operation-Location header",
        )

    deadline = time.monotonic() + ANALYSIS_TIMEOUT_SECONDS
    poll_headers = {"Ocp-Apim-Subscription-Key": AZURE_KEY}

    while time.monotonic() < deadline:
        poll_response = await request_with_backoff(
            client,
            "GET",
            operation_url,
            headers=poll_headers,
        )

        if poll_response.status_code != 200:
            raise HTTPException(
                status_code=502,
                detail=f"Azure analysis polling failed: {poll_response.text[:2000]}",
            )

        result = parse_json(poll_response)
        status = str(result.get("status", "")).lower()

        if status == "succeeded":
            return result

        if status in {"failed", "canceled"}:
            raise HTTPException(
                status_code=422,
                detail={
                    "message": "Azure could not analyze the invoice",
                    "errors": json_safe(result.get("error")),
                },
            )

        await asyncio.sleep(1.5)

    raise HTTPException(
        status_code=504,
        detail="Invoice analysis timed out",
    )


SUPPLIER_FIELDS = {
    "name": "VendorName",
    "address": "VendorAddress",
    "address_recipient": "VendorAddressRecipient",
    "tax_id": "VendorTaxId",
    "registration_number": "KVKNumber",
}

INVOICE_FIELDS = {
    "invoice_number": "InvoiceId",
    "invoice_date": "InvoiceDate",
    "due_date": "DueDate",
    "purchase_order": "PurchaseOrder",
    "payment_terms": "PaymentTerm",
}

TOTAL_FIELDS = {
    "subtotal": "SubTotal",
    "total_discount": "TotalDiscount",
    "total_tax": "TotalTax",
    "invoice_total": "InvoiceTotal",
    "amount_due": "AmountDue",
    "previous_unpaid_balance": "PreviousUnpaidBalance",
}

LINE_ITEM_FIELDS = {
    "product_code": "ProductCode",
    "description": "Description",
    "quantity": "Quantity",
    "unit": "Unit",
    "unit_price": "UnitPrice",
    "discount": "Discount",
    "discount_rate": "DiscountRate",
    "tax": "Tax",
    "tax_rate": "TaxRate",
    "amount": "Amount",
    "date": "Date",
}


def normalize_invoice(document: dict[str, Any], document_index: int) -> dict[str, Any]:
    fields: dict[str, Any] = document.get("fields") or {}
    reasons: list[str] = []

    def require_confident(
        field: dict[str, Any] | None,
        path: str,
        *,
        required: bool = True,
    ) -> None:
        if not field:
            if required:
                reasons.append(f"{path}: missing")
            return

        confidence = confidence_of(field)
        if confidence is None:
            reasons.append(f"{path}: confidence unavailable")
        elif confidence < MIN_CONFIDENCE:
            reasons.append(
                f"{path}: confidence {confidence} is below {MIN_CONFIDENCE}"
            )

    supplier = {
        output_name: field_value(fields.get(azure_name))
        for output_name, azure_name in SUPPLIER_FIELDS.items()
    }
    supplier_evidence = {
        output_name: field_evidence(fields.get(azure_name))
        for output_name, azure_name in SUPPLIER_FIELDS.items()
    }

    invoice_header = {
        output_name: field_value(fields.get(azure_name))
        for output_name, azure_name in INVOICE_FIELDS.items()
    }
    invoice_evidence = {
        output_name: field_evidence(fields.get(azure_name))
        for output_name, azure_name in INVOICE_FIELDS.items()
    }

    totals = {
        output_name: field_value(fields.get(azure_name))
        for output_name, azure_name in TOTAL_FIELDS.items()
    }
    totals_evidence = {
        output_name: field_evidence(fields.get(azure_name))
        for output_name, azure_name in TOTAL_FIELDS.items()
    }

    tax_details_field = fields.get("TaxDetails")
    taxes = {
        "total": field_value(fields.get("TotalTax")),
        "details": field_value(tax_details_field) or [],
    }
    taxes_evidence = {
        "total": field_evidence(fields.get("TotalTax")),
        "details": field_evidence(tax_details_field),
    }

    items_field = fields.get("Items")
    item_fields = (items_field or {}).get("valueArray", [])
    line_items: list[dict[str, Any]] = []
    line_item_evidence: list[dict[str, Any]] = []

    for item in item_fields:
        item_object: dict[str, Any] = item.get("valueObject") or {}

        normalized = {
            output_name: field_value(item_object.get(azure_name))
            for output_name, azure_name in LINE_ITEM_FIELDS.items()
        }
        evidence = {
            output_name: field_evidence(item_object.get(azure_name))
            for output_name, azure_name in LINE_ITEM_FIELDS.items()
        }

        known_names = set(LINE_ITEM_FIELDS.values())
        extra = {
            snake_case(name): field_value(value)
            for name, value in item_object.items()
            if name not in known_names
        }
        extra_evidence = {
            snake_case(name): field_evidence(value)
            for name, value in item_object.items()
            if name not in known_names
        }

        if extra:
            normalized["extra"] = extra
            evidence["extra"] = extra_evidence

        line_items.append(normalized)
        line_item_evidence.append(evidence)

    require_confident(fields.get("VendorName"), "supplier.name")
    require_confident(fields.get("InvoiceId"), "invoice_number")
    require_confident(fields.get("SubTotal"), "totals.subtotal")
    require_confident(fields.get("InvoiceTotal"), "totals.invoice_total")

    if not fields.get("TotalTax") and not tax_details_field:
        reasons.append("taxes: total tax and tax details are both missing")
    else:
        require_confident(fields.get("TotalTax"), "taxes.total", required=False)
        require_confident(tax_details_field, "taxes.details", required=False)

    if not item_fields:
        reasons.append("line_items: no line items extracted")
    else:
        require_confident(items_field, "line_items")

    for index, item in enumerate(item_fields):
        obj = item.get("valueObject") or {}
        prefix = f"line_items[{index}]"

        require_confident(obj.get("Description"), f"{prefix}.description")
        require_confident(obj.get("Quantity"), f"{prefix}.quantity")
        require_confident(obj.get("UnitPrice"), f"{prefix}.unit_price")
        require_confident(obj.get("Amount"), f"{prefix}.amount")

        quantity = field_decimal(obj.get("Quantity"))
        unit_price = field_decimal(obj.get("UnitPrice"))
        amount = field_decimal(obj.get("Amount"))

        has_discount = bool(obj.get("Discount") or obj.get("DiscountRate"))
        if (
            quantity is not None
            and unit_price is not None
            and amount is not None
            and not has_discount
        ):
            calculated_amount = quantity * unit_price
            if not within_tolerance(amount, calculated_amount):
                reasons.append(
                    f"{prefix}: quantity × unit_price is "
                    f"{format(calculated_amount, 'f')}, but amount is "
                    f"{format(amount, 'f')}"
                )

        line_currency = field_currency(obj.get("Amount"))
        unit_currency = field_currency(obj.get("UnitPrice"))
        if line_currency and unit_currency and line_currency != unit_currency:
            reasons.append(
                f"{prefix}: unit price currency {unit_currency} differs from "
                f"amount currency {line_currency}"
            )

    subtotal = field_decimal(fields.get("SubTotal"))
    total_tax = field_decimal(fields.get("TotalTax"))
    total_discount = field_decimal(fields.get("TotalDiscount")) or Decimal("0")
    invoice_total = field_decimal(fields.get("InvoiceTotal"))

    item_amounts = [
        field_decimal((item.get("valueObject") or {}).get("Amount"))
        for item in item_fields
    ]
    if subtotal is not None and item_amounts and all(v is not None for v in item_amounts):
        calculated_subtotal = sum(item_amounts, Decimal("0"))  # type: ignore[arg-type]
        if not within_tolerance(subtotal, calculated_subtotal):
            reasons.append(
                "totals.subtotal: extracted line amounts sum to "
                f"{format(calculated_subtotal, 'f')}, but subtotal is "
                f"{format(subtotal, 'f')}"
            )

    if subtotal is not None and total_tax is not None and invoice_total is not None:
        calculated_total = subtotal - total_discount + total_tax
        if not within_tolerance(invoice_total, calculated_total):
            reasons.append(
                "totals.invoice_total: subtotal - discount + tax equals "
                f"{format(calculated_total, 'f')}, but invoice total is "
                f"{format(invoice_total, 'f')}"
            )

    invoice_currency = field_currency(fields.get("InvoiceTotal"))
    currency_fields = {
        "subtotal": fields.get("SubTotal"),
        "total_tax": fields.get("TotalTax"),
        "amount_due": fields.get("AmountDue"),
    }
    for name, field in currency_fields.items():
        currency = field_currency(field)
        if invoice_currency and currency and currency != invoice_currency:
            reasons.append(
                f"totals.{name}: currency {currency} differs from invoice "
                f"currency {invoice_currency}"
            )

    reasons = list(dict.fromkeys(reasons))

    result = {
        "document_index": document_index,
        "document_type": document.get("docType"),
        "document_confidence": json_safe(document.get("confidence")),
        "supplier": supplier,
        **invoice_header,
        "currency": invoice_currency,
        "taxes": taxes,
        "totals": totals,
        "line_items": line_items,
        "quality": {
            "review_required": bool(reasons),
            "auto_post_eligible": not reasons,
            "minimum_confidence": format(MIN_CONFIDENCE, "f"),
            "reasons": reasons,
            "evidence": {
                "supplier": supplier_evidence,
                **invoice_evidence,
                "taxes": taxes_evidence,
                "totals": totals_evidence,
                "line_items": line_item_evidence,
            },
        },
    }

    return result


async def read_upload(file: UploadFile) -> bytes:
    chunks: list[bytes] = []
    size = 0

    while chunk := await file.read(1024 * 1024):
        size += len(chunk)
        if size > MAX_PDF_BYTES:
            raise HTTPException(
                status_code=413,
                detail=f"PDF exceeds the {MAX_PDF_BYTES}-byte limit",
            )
        chunks.append(chunk)

    pdf = b"".join(chunks)
    if not pdf:
        raise HTTPException(status_code=400, detail="Uploaded PDF is empty")

    if not pdf.lstrip().startswith(b"%PDF-"):
        raise HTTPException(status_code=415, detail="The uploaded file is not a PDF")

    return pdf


@app.get("/health")
async def health() -> dict[str, Any]:
    return {
        "status": "ok",
        "provider": "Azure AI Document Intelligence",
        "model": AZURE_MODEL_ID,
    }


@app.post("/v1/invoices/extract")
async def extract_invoice(file: UploadFile = File(...)) -> dict[str, Any]:
    pdf = await read_upload(file)
    sha256 = hashlib.sha256(pdf).hexdigest()

    azure_result = await analyze_pdf(app.state.http, pdf)
    analyze_result = azure_result.get("analyzeResult") or {}
    documents = analyze_result.get("documents") or []

    if not documents:
        raise HTTPException(
            status_code=422,
            detail="No invoice document was detected in the PDF",
        )

    invoices = [
        normalize_invoice(document, index)
        for index, document in enumerate(documents)
    ]

    response: dict[str, Any] = {
        "file": {
            "name": file.filename,
            "sha256": sha256,
            "bytes": len(pdf),
        },
        "provider": {
            "name": "Azure AI Document Intelligence",
            "model": AZURE_MODEL_ID,
            "api_version": AZURE_API_VERSION,
            "high_resolution_ocr": USE_HIGH_RES_OCR,
        },
        "invoice_count": len(invoices),
        "invoices": invoices,
        "review_required": any(
            invoice["quality"]["review_required"] for invoice in invoices
        ),
    }

    if INCLUDE_RAW_RESULT:
        response["raw_provider_result"] = json_safe(azure_result)

    return response
