        "date": {"type": ["string", "null"]},
        "currency": {"type": ["string", "null"]},
        "total": {"type": ["number", "null"]},
    },
    "required": ["merchant", "date", "currency", "total"],
    "additionalProperties": False,
}


def json_bytes(value: Any) -> bytes:
    return (
        json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        + b"\n"
    )


def atomic_write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    os.replace(temporary, path)


def load_state(work_dir: Path) -> dict[str, Any]:
    state_path = work_dir / "state.json"
    if not state_path.exists():
        raise FileNotFoundError(f"Missing state file: {state_path}")
    return json.loads(state_path.read_text(encoding="utf-8"))


def save_state(work_dir: Path, state: dict[str, Any]) -> None:
    atomic_write_json(work_dir / "state.json", state)


def detect_mime_type(item: dict[str, Any]) -> str:
    mime_type = str(item.get("mime_type") or "").lower().split(";", 1)[0]
    if mime_type:
        return mime_type

    suffix = Path(urlparse(str(item["url"])).path).suffix.lower()
    if suffix == ".pdf":
        return "application/pdf"
    if suffix in {".jpg", ".jpeg"}:
        return "image/jpeg"
    if suffix == ".png":
        return "image/png"
    if suffix == ".webp":
        return "image/webp"
    return "image/jpeg"


def make_request(
    item: dict[str, Any],
    sequence_number: int,
) -> tuple[str, bytes, bytes]:
    source_id = item["id"]
    url = str(item["url"])

    if not url.startswith("https://"):
        raise ValueError(
            f"Receipt {source_id!r} must use an HTTPS URL accessible by the API"
        )

    mime_type = detect_mime_type(item)
    digest = hashlib.sha256(str(source_id).encode("utf-8")).hexdigest()[:12]
    custom_id = f"r{sequence_number:010d}_{digest}"

    if mime_type == "application/pdf":
        document_content = {
            "type": "input_file",
            "file_url": url,
        }
    else:
        document_content = {
            "type": "input_image",
            "image_url": url,
            "detail": "high",
        }

    request = {
        "custom_id": custom_id,
        "method": "POST",
        "url": "/v1/responses",
        "body": {
            "model": MODEL,
            "store": False,
            "max_output_tokens": 150,
            "input": [
                {
                    "role": "system",
                    "content": [{"type": "input_text", "text": SYSTEM_PROMPT}],
                },
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": "Extract the receipt fields.",
                        },
                        document_content,
                    ],
                },
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": "receipt",
                    "strict": True,
                    "schema": RECEIPT_SCHEMA,
                }
            },
        },
    }

    mapping = {
        "custom_id": custom_id,
        "id": source_id,
        "url": url,
        "mime_type": mime_type,
    }
    return custom_id, json_bytes(request), json_bytes(mapping)


def prepare(manifest: Path, work_dir: Path) -> None:
    state_path = work_dir / "state.json"
    if state_path.exists():
        raise FileExistsError(
            f"{state_path} already exists; use another work directory"
        )

    shard_dir = work_dir / "shards"
    map_dir = work_dir / "maps"
    result_dir = work_dir / "result-shards"
    raw_dir = work_dir / "raw"

    for directory in (shard_dir, map_dir, result_dir, raw_dir):
        directory.mkdir(parents=True, exist_ok=True)

    state: dict[str, Any] = {
        "model": MODEL,
        "created_at": int(time.time()),
        "shards": [],
    }

    shard_number = -1
    request_file = None
    map_file = None
    shard_record: dict[str, Any] | None = None
    shard_bytes = 0
    shard_requests = 0
    total_requests = 0

    def close_shard() -> None:
        nonlocal request_file, map_file, shard_record
        if request_file:
            request_file.close()
        if map_file:
            map_file.close()
        if shard_record:
            shard_record["request_count"] = shard_requests
            shard_record["input_bytes"] = shard_bytes
            state["shards"].append(shard_record)
        request_file = None
        map_file = None
        shard_record = None

    def open_shard() -> None:
        nonlocal shard_number, request_file, map_file, shard_record
        nonlocal shard_bytes, shard_requests

        shard_number += 1
        shard_bytes = 0
        shard_requests = 0
        name = f"batch-{shard_number:05d}"

        request_file = (shard_dir / f"{name}.jsonl").open("wb")
        map_file = (map_dir / f"{name}.jsonl").open("wb")
        shard_record = {
            "name": name,
            "status": "pending",
            "input_file_id": None,
            "batch_id": None,
            "output_file_id": None,
            "error_file_id": None,
            "processed": False,
        }

    with manifest.open("r", encoding="utf-8") as source:
        for line_number, line in enumerate(source, start=1):
            if not line.strip():
                continue

            try:
                item = json.loads(line)
                if "id" not in item or "url" not in item:
                    raise ValueError("Each row requires id and url")
                _, request_line, map_line = make_request(item, total_requests)
            except Exception as exc:
                raise ValueError(
                    f"Invalid manifest row {line_number}: {exc}"
                ) from exc

            if request_file is None:
                open_shard()

            if shard_requests and (
                shard_requests >= MAX_REQUESTS_PER_SHARD
                or shard_bytes + len(request_line) > TARGET_SHARD_BYTES
            ):
                close_shard()
                open_shard()

            request_file.write(request_line)
            map_file.write(map_line)
            shard_bytes += len(request_line)
            shard_requests += 1
            total_requests += 1

    close_shard()

    if total_requests == 0:
        raise ValueError("Manifest contains no receipts")

    state["total_requests"] = total_requests
    save_state(work_dir, state)

    print(
        f"Prepared {total_requests:,} receipts in "
        f"{len(state['shards']):,} batch files."
    )


def fetch_api_file(client: OpenAI, file_id: str, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_suffix(destination.suffix + ".tmp")
    response = client.files.content(file_id)

    if hasattr(response, "write_to_file"):
        response.write_to_file(str(temporary))
    else:
        data = getattr(response, "content", None)
        if data is None and hasattr(response, "read"):
            data = response.read()
        if not isinstance(data, bytes):
            raise TypeError(f"Could not read API file {file_id}")
        temporary.write_bytes(data)

    os.replace(temporary, destination)


def extract_response_text(body: dict[str, Any]) -> str:
    direct_text = body.get("output_text")
    if isinstance(direct_text, str) and direct_text:
        return direct_text

    for output_item in body.get("output", []):
        if output_item.get("type") != "message":
            continue

        for content in output_item.get("content", []):
            if content.get("type") == "output_text":
                return content["text"]
            if content.get("type") == "refusal":
                raise ValueError(f"Model refusal: {content.get('refusal')}")

    raise ValueError("Response did not contain output text")


def validate_receipt(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Receipt output is not a JSON object")

    expected = {"merchant", "date", "currency", "total"}
    if set(value) != expected:
        raise ValueError(f"Unexpected output fields: {sorted(value)}")

    if value["merchant"] is not None and not isinstance(value["merchant"], str):
        raise ValueError("merchant must be a string or null")

    if value["date"] is not None:
        if not isinstance(value["date"], str):
            raise ValueError("date must be a string or null")
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value["date"]):
            raise ValueError("date is not YYYY-MM-DD")

    if value["currency"] is not None:
        if not isinstance(value["currency"], str):
            raise ValueError("currency must be a string or null")
        value["currency"] = value["currency"].upper()
        if not re.fullmatch(r"[A-Z]{3}", value["currency"]):
            raise ValueError("currency is not an ISO 4217-style code")

    if value["total"] is not None:
        if isinstance(value["total"], bool) or not isinstance(
            value["total"], (int, float)
        ):
            raise ValueError("total must be a number or null")

    return value


def process_terminal_shard(
    client: OpenAI,
    work_dir: Path,
    record: dict[str, Any],
) -> None:
    name = record["name"]
    raw_dir = work_dir / "raw"
    result_dir = work_dir / "result-shards"

    output_raw = raw_dir / f"{name}.output.jsonl"
    error_raw = raw_dir / f"{name}.api-errors.jsonl"

    if record.get("output_file_id") and not output_raw.exists():
        fetch_api_file(client, record["output_file_id"], output_raw)

    if record.get("error_file_id") and not error_raw.exists():
        fetch_api_file(client, record["error_file_id"], error_raw)

    mappings: dict[str, dict[str, Any]] = {}
    map_path = work_dir / "maps" / f"{name}.jsonl"
    with map_path.open("r", encoding="utf-8") as source:
        for line in source:
            mapping = json.loads(line)
            mappings[mapping["custom_id"]] = mapping

    result_path = result_dir / f"{name}.results.jsonl"
    error_path = result_dir / f"{name}.errors.jsonl"
    usage_path = result_dir / f"{name}.usage.json"

    result_tmp = result_path.with_suffix(".jsonl.tmp")
    error_tmp = error_path.with_suffix(".jsonl.tmp")

    seen: set[str] = set()
    input_tokens = 0
    output_tokens = 0
    total_tokens = 0

    with result_tmp.open("w", encoding="utf-8") as results, error_tmp.open(
        "w", encoding="utf-8"
    ) as errors:
        for raw_path in (output_raw, error_raw):
            if not raw_path.exists():
                continue

            with raw_path.open("r", encoding="utf-8") as source:
                for line in source:
                    if not line.strip():
                        continue

                    row = json.loads(line)
                    custom_id = row.get("custom_id")
                    if custom_id:
                        seen.add(custom_id)

                    mapping = mappings.get(
                        custom_id,
                        {
                            "id": None,
                            "url": None,
                            "mime_type": None,
                        },
                    )

                    response = row.get("response") or {}
                    body = response.get("body") or {}
                    usage = body.get("usage") or {}
                    input_tokens += int(usage.get("input_tokens") or 0)
                    output_tokens += int(usage.get("output_tokens") or 0)
                    total_tokens += int(usage.get("total_tokens") or 0)

                    try:
                        if row.get("error"):
                            raise ValueError(
                                json.dumps(row["error"], ensure_ascii=False)
                            )

                        status_code = response.get("status_code")
                        if status_code != 200:
                            raise ValueError(f"HTTP status {status_code}: {body}")

                        text = extract_response_text(body)
                        receipt = validate_receipt(json.loads(text))
                        result = {"id": mapping["id"], **receipt}
                        results.write(
                            json.dumps(result, ensure_ascii=False) + "\n"
                        )
                    except Exception as exc:
                        error = {
                            "id": mapping["id"],
                            "url": mapping["url"],
                            "mime_type": mapping["mime_type"],
                            "custom_id": custom_id,
                            "error": str(exc),
                        }
                        errors.write(json.dumps(error, ensure_ascii=False) + "\n")

        # Account for requests missing from both API output files.
        for custom_id, mapping in mappings.items():
            if custom_id not in seen:
                error = {
                    "id": mapping["id"],
                    "url": mapping["url"],
                    "mime_type": mapping["mime_type"],
                    "custom_id": custom_id,
                    "error": (
                        f"No result returned; batch ended with status "
                        f"{record.get('status')}"
                    ),
                }
                errors.write(json.dumps(error, ensure_ascii=False) + "\n")

    os.replace(result_tmp, result_path)
    os.replace(error_tmp, error_path)
    atomic_write_json(
        usage_path,
        {
            "input_tokens": input_tokens,
            "output_tokens": output_tokens,
            "total_tokens": total_tokens,
        },
    )

    record["processed"] = True
    record["processed_at"] = int(time.time())


def submit_shard(
    client: OpenAI,
    work_dir: Path,
    state: dict[str, Any],
    record: dict[str, Any],
) -> None:
    name = record["name"]

    if not record.get("input_file_id"):
        record["status"] = "uploading"
        save_state(work_dir, state)

        shard_path = work_dir / "shards" / f"{name}.jsonl"
        with shard_path.open("rb") as batch_file:
            uploaded = client.files.create(file=batch_file, purpose="batch")

        record["input_file_id"] = uploaded.id
        record["status"] = "uploaded"
        save_state(work_dir, state)

    batch = client.batches.create(
        input_file_id=record["input_file_id"],
        endpoint="/v1/responses",
        completion_window="24h",
        metadata={
            "pipeline": "receipt-extraction",
            "shard": name,
        },
    )

    record["batch_id"] = batch.id
    record["status"] = str(batch.status)
    record["submitted_at"] = int(time.time())
    record.pop("last_submit_error", None)
    save_state(work_dir, state)

    print(f"Submitted {name}: {batch.id}")


def refresh_shard(
    client: OpenAI,
    work_dir: Path,
    state: dict[str, Any],
    record: dict[str, Any],
) -> None:
    if not record.get("batch_id") or record.get("status") in TERMINAL_STATUSES:
        return

    batch = client.batches.retrieve(record["batch_id"])
    record["status"] = str(batch.status)
    record["output_file_id"] = getattr(batch, "output_file_id", None)
    record["error_file_id"] = getattr(batch, "error_file_id", None)

    request_counts = getattr(batch, "request_counts", None)
    if request_counts is not None:
        if hasattr(request_counts, "model_dump"):
            record["request_counts"] = request_counts.model_dump()
        else:
            record["request_counts"] = str(request_counts)

    save_state(work_dir, state)


def merge_results(work_dir: Path, state: dict[str, Any]) -> None:
    result_dir = work_dir / "result-shards"
    final_results = work_dir / "results.jsonl"
    final_errors = work_dir / "errors.jsonl"

    results_tmp = final_results.with_suffix(".jsonl.tmp")
    errors_tmp = final_errors.with_suffix(".jsonl.tmp")

    aggregate_usage = {
        "model": state.get("model"),
        "input_tokens": 0,
        "output_tokens": 0,
        "total_tokens": 0,
    }

    with results_tmp.open("wb") as results_out, errors_tmp.open(
        "wb"
    ) as errors_out:
        for record in state["shards"]:
            name = record["name"]

            result_path = result_dir / f"{name}.results.jsonl"
            error_path = result_dir / f"{name}.errors.jsonl"
            usage_path = result_dir / f"{name}.usage.json"

            if result_path.exists():
                with result_path.open("rb") as source:
                    while chunk := source.read(1024 * 1024):
                        results_out.write(chunk)

            if error_path.exists():
                with error_path.open("rb") as source:
                    while chunk := source.read(1024 * 1024):
                        errors_out.write(chunk)

            if usage_path.exists():
                usage = json.loads(usage_path.read_text(encoding="utf-8"))
                for key in ("input_tokens", "output_tokens", "total_tokens"):
                    aggregate_usage[key] += int(usage.get(key) or 0)

    os.replace(results_tmp, final_results)
    os.replace(errors_tmp, final_errors)

    # Set these to current discounted Batch rates if cost estimation is desired.
    input_rate = os.environ.get("BATCH_INPUT_USD_PER_MILLION")
    output_rate = os.environ.get("BATCH_OUTPUT_USD_PER_MILLION")
    if input_rate and output_rate:
        aggregate_usage["estimated_api_usd"] = round(
            aggregate_usage["input_tokens"] / 1_000_000 * float(input_rate)
            + aggregate_usage["output_tokens"] / 1_000_000 * float(output_rate),
            2,
        )

    atomic_write_json(work_dir / "usage.json", aggregate_usage)
    print(f"Results: {final_results}")
    print(f"Errors/retry manifest: {final_errors}")
    print(f"Usage: {work_dir / 'usage.json'}")


def run(
    work_dir: Path,
    max_active: int,
    poll_seconds: int,
    once: bool,
) -> None:
    client = OpenAI()

    while True:
        state = load_state(work_dir)

        for record in state["shards"]:
            try:
                refresh_shard(client, work_dir, state, record)

                if (
                    record.get("status") in TERMINAL_STATUSES
                    and not record.get("processed")
                ):
                    process_terminal_shard(client, work_dir, record)
                    save_state(work_dir, state)
                    print(
                        f"Processed {record['name']} "
                        f"({record.get('status')})"
                    )
            except Exception as exc:
                record["last_refresh_error"] = str(exc)
                save_state(work_dir, state)
                print(
                    f"Refresh error for {record['name']}: {exc}",
                    file=sys.stderr,
                )

        active = sum(
            1
            for record in state["shards"]
            if record.get("batch_id")
            and record.get("status") not in TERMINAL_STATUSES
        )

        for record in state["shards"]:
            if active >= max_active:
                break
            if record.get("batch_id"):
                continue

            try:
                submit_shard(client, work_dir, state, record)
                active += 1
            except Exception as exc:
                record["last_submit_error"] = str(exc)
                save_state(work_dir, state)
                print(
                    f"Submission paused after {record['name']}: {exc}",
                    file=sys.stderr,
                )
                break

        all_processed = all(
            record.get("processed") for record in state["shards"]
        )
        if all_processed:
            merge_results(work_dir, state)
            return

        status_counts: dict[str, int] = {}
        for record in state["shards"]:
            status = record.get("status", "unknown")
            status_counts[status] = status_counts.get(status, 0) + 1
        print(f"Batch statuses: {status_counts}")

        if once:
            return

        time.sleep(poll_seconds)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Asynchronous receipt extraction with OpenAI Batch API"
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    prepare_parser = subparsers.add_parser("prepare")
    prepare_parser.add_argument("manifest", type=Path)
    prepare_parser.add_argument("work_dir", type=Path)

    run_parser = subparsers.add_parser("run")
    run_parser.add_argument("work_dir", type=Path)
    run_parser.add_argument("--max-active", type=int, default=8)
    run_parser.add_argument("--poll-seconds", type=int, default=60)
    run_parser.add_argument(
        "--once",
        action="store_true",
        help="Perform one scheduler pass and exit; suitable for cron",
    )

    merge_parser = subparsers.add_parser("merge")
    merge_parser.add_argument("work_dir", type=Path)

    args = parser.parse_args()

    if args.command == "prepare":
        prepare(args.manifest, args.work_dir)
    elif args.command == "run":
        if args.max_active < 1:
            parser.error("--max-active must be at least 1")
        run(
            args.work_dir,
            max_active=args.max_active,
            poll_seconds=args.poll_seconds,
            once=args.once,
        )
    elif args.command == "merge":
        merge_results(args.work_dir, load_state(args.work_dir))


if __name__ == "__main__":
    main()
