                file=sys.stderr,
            )

    requests = len(pdfs)
    retry_factor = 1 + MAX_EXTRACTION_RETRIES
    input_tokens = total_pages * PDF_TOKENS_PER_PAGE
    input_tokens += requests * PROMPT_TOKEN_ALLOWANCE
    output_tokens = requests * MAX_OUTPUT_TOKENS

    estimated = retry_factor * (
        input_tokens / 1_000_000 * BATCH_INPUT_USD_PER_MILLION
        + output_tokens / 1_000_000 * BATCH_OUTPUT_USD_PER_MILLION
    )
    guarded_estimate = estimated * COST_SAFETY_FACTOR
    available = MONTHLY_BUDGET_USD - ALREADY_SPENT_USD

    print(
        json.dumps(
            {
                "model": MODEL,
                "documents": requests,
                "pages": total_pages,
                "estimated_worst_case_usd": round(estimated, 2),
                "guarded_estimate_usd": round(guarded_estimate, 2),
                "available_budget_usd": round(available, 2),
            },
            indent=2,
        ),
        file=sys.stderr,
    )

    if available <= 0 or guarded_estimate > available:
        raise RuntimeError(
            f"Budget guard stopped submission: estimated ${guarded_estimate:.2f}, "
            f"available ${available:.2f}"
        )


def shard_documents(paths: Iterable[Path]) -> Iterable[list[Path]]:
    shard: list[Path] = []
    estimated_bytes = 0

    for path in paths:
        size = path.stat().st_size
        request_size = (
            ((size + 2) // 3) * 4 + 2048
            if size <= INLINE_PDF_BYTES
            else 4096
