    deadline = time.monotonic() + 3600
    current = uploaded

    while True:
        status = state_name(getattr(current, "state", None))
        if not status or "ACTIVE" in status:
            return current
        if "FAILED" in status:
            raise RuntimeError(f"Uploaded PDF processing failed: {uploaded.name}")
        if time.monotonic() >= deadline:
            raise TimeoutError(f"Timed out processing uploaded PDF: {uploaded.name}")
        time.sleep(5)
        current = api_call(client.files.get, name=uploaded.name)


