    parts = candidates[0].get("content", {}).get("parts", [])
    text = "".join(part.get("text", "") for part in parts if part.get("text"))
    text = text.strip()

    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s*```$", "", text)

    return text or None


def normalize_result(payload: Any) -> dict[str, Any]:
    result = {field: None for field in FIELDS}
    if not isinstance(payload, dict):
        return result

    supplier = payload.get("supplier_id")
    if supplier is not None:
        supplier = str(supplier).strip()
        result["supplier_id"] = supplier or None

    date = payload.get("invoice_date")
    if date is not None:
        date = str(date).strip()
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
            result["invoice_date"] = date

    currency = payload.get("currency")
    if currency is not None:
        currency = str(currency).strip().upper()
        if re.fullmatch(r"[A-Z]{3}", currency):
            result["currency"] = currency

    total = payload.get("total")
    if total is not None:
        total = str(total).strip()
        if re.fullmatch(r"-?(?:0|[1-9]\d*)(?:\.\d+)?", total):
            try:
                Decimal(total)
                result["total"] = total
            except InvalidOperation:
                pass

    return result


def result_score(result: dict[str, Any]) -> int:
    return sum(result.get(field) is not None for field in FIELDS)


def cleanup_job_files(entry: dict[str, Any], output_file: str | None = None) -> None:
    names = [entry["source_file"], *entry["uploaded_pdfs"]]
    if output_file:
        names.append(output_file)

    for name in names:
        try:
            api_call(client.files.delete, name=name)
        except Exception:
            pass


def process_round(
    paths: list[Path],
    root: Path,
    output_root: Path,
    round_number: int,
) -> tuple[list[Path], dict[Path, dict[str, Any]]]:
    jobs: list[dict[str, Any]] = []

    for shard_number, shard in enumerate(shard_documents(paths), 1):
        print(
            f"Submitting retry round {round_number}, shard {shard_number}, "
            f"{len(shard):,} documents",
            file=sys.stderr,
        )
        jobs.append(
            submit_shard(shard, root, round_number, shard_number)
        )

    terminal = {
        "JOB_STATE_SUCCEEDED",
        "JOB_STATE_FAILED",
        "JOB_STATE_CANCELLED",
        "JOB_STATE_EXPIRED",
    }
    deadline = time.monotonic() + JOB_TIMEOUT_HOURS * 3600
    unfinished = set(range(len(jobs)))

    while unfinished:
        for index in list(unfinished):
            current = api_call(client.batches.get, name=jobs[index]["job"].name)
            jobs[index]["job"] = current
            if state_name(current.state) in terminal:
                unfinished.remove(index)

        if unfinished:
            if time.monotonic() >= deadline:
                raise TimeoutError(
                    f"{len(unfinished)} Gemini batch jobs exceeded the timeout"
                )
            print(f"Waiting for {len(unfinished)} batch jobs", file=sys.stderr)
            time.sleep(POLL_SECONDS)

    remaining = set(paths)
    partial_results: dict[Path, dict[str, Any]] = {}

    for entry in jobs:
        job = entry["job"]
        output_file: str | None = None

        try:
            if state_name(job.state) != "JOB_STATE_SUCCEEDED":
                print(
                    f"Batch job {job.name} ended as {state_name(job.state)}",
                    file=sys.stderr,
                )
                continue

            destination = getattr(job, "dest", None)
            output_file = getattr(destination, "file_name", None)
            if not output_file:
                print(f"Batch job {job.name} has no output file", file=sys.stderr)
                continue

            content = api_call(client.files.download, file=output_file)

            for raw_line in content.decode("utf-8").splitlines():
                if not raw_line.strip():
                    continue

                try:
                    record = json.loads(raw_line)
                    path = entry["mapping"].get(record.get("key"))
                    if path is None:
                        continue

                    text = extract_response_text(record)
                    if text is None:
                        continue

                    normalized = normalize_result(json.loads(text))
                    if result_score(normalized) == len(FIELDS):
                        write_result(path, root, output_root, normalized)
                        remaining.discard(path)
                    elif result_score(normalized) > result_score(
                        partial_results.get(path, {})
                    ):
                        partial_results[path] = normalized

                except (json.JSONDecodeError, UnicodeDecodeError, TypeError):
                    continue

        finally:
            cleanup_job_files(entry, output_file)

    return sorted(remaining), partial_results


def main() -> None:
    if len(sys.argv) != 3:
        raise SystemExit(
            f"Usage: {Path(sys.argv[0]).name} INPUT_PDF_DIRECTORY OUTPUT_DIRECTORY"
        )

    root = Path(sys.argv[1]).expanduser().resolve()
    output_root = Path(sys.argv[2]).expanduser().resolve()
    output_root.mkdir(parents=True, exist_ok=True)

    if not root.is_dir():
        raise SystemExit(f"Input directory does not exist: {root}")

    all_pdfs = sorted(
        path
        for path in root.rglob("*")
        if path.is_file() and path.suffix.lower() == ".pdf"
    )

    # Existing results are skipped, allowing safe continuation after interruption.
    pending = [
        path
        for path in all_pdfs
        if not result_path(path, root, output_root).exists()
    ]

    if not pending:
        print("No unprocessed PDFs found.", file=sys.stderr)
        return

    check_budget(pending)

    best_partial: dict[Path, dict[str, Any]] = {}

    for round_number in range(1, MAX_EXTRACTION_RETRIES + 2):
        pending, partial = process_round(
            pending, root, output_root, round_number
        )

        for path, result in partial.items():
            if result_score(result) > result_score(best_partial.get(path, {})):
                best_partial[path] = result

        if not pending:
            break

        print(
            f"{len(pending):,} documents require another extraction attempt",
            file=sys.stderr,
        )

    failure_log = output_root / "_extraction_failures.jsonl"
    if pending:
        with failure_log.open("a", encoding="utf-8") as log:
            for path in pending:
                result = best_partial.get(path, {field: None for field in FIELDS})
                write_result(path, root, output_root, result)
                log.write(
                    json.dumps(
                        {
                            "source": path.relative_to(root).as_posix(),
                            "missing_fields": [
                                field for field in FIELDS if result.get(field) is None
                            ],
                        },
                        ensure_ascii=False,
                    )
                    + "\n"
                )

    print(
        f"Finished: {len(all_pdfs) - len(pending):,} complete, "
        f"{len(pending):,} incomplete",
        file=sys.stderr,
    )


if __name__ == "__main__":
    main()
```

