import time
from pathlib import Path

import anthropic
from PIL import Image

MODEL = "claude-haiku-4-5"
MANIFEST = Path("batch_manifest.jsonl")      # custom_id -> source path, batch_id
RESULTS = Path("results.jsonl")
FAILURES = Path("failures.jsonl")

# Batch limits: 100k requests or 256 MB per batch. Base64 images hit the byte cap first.
MAX_REQS_PER_BATCH = 100_000
MAX_BYTES_PER_BATCH = 200 * 1024 * 1024       # headroom under 256 MB
MAX_EDGE_PX = 1568                             # Claude downsizes beyond this anyway; shrink before upload

client = anthropic.Anthropic()

SCHEMA = {
    "type": "object",
    "properties": {
        "merchant": {"anyOf": [{"type": "string"}, {"type": "null"}]},
        "date": {
            "anyOf": [{"type": "string"}, {"type": "null"}],
            "description": "ISO 8601 YYYY-MM-DD",
        },
        "currency": {
            "anyOf": [{"type": "string"}, {"type": "null"}],
            "description": "ISO 4217 code, e.g. USD, EUR, MXN",
        },
        "total": {
            "anyOf": [{"type": "number"}, {"type": "null"}],
            "description": "Final amount paid, including tax and tip",
        },
    },
    "required": ["merchant", "date", "currency", "total"],
    "additionalProperties": False,
}

SYSTEM = (
    "You extract fields from a single receipt (English or Spanish). "
    "merchant: the business name as printed. "
    "date: the transaction date as YYYY-MM-DD. Spanish receipts usually use DD/MM/YYYY. "
    "currency: ISO 4217 code, inferred from symbols, country, or text if not explicit. "
    "total: the final amount paid (TOTAL / TOTAL A PAGAR / IMPORTE), as a number. "
    "Treat a comma as the decimal separator where the locale uses it (e.g. 1.234,56 -> 1234.56). "
    "Use null for any field that is missing or illegible. Never guess."
)


def custom_id_for(path: Path) -> str:
    # custom_id must match ^[a-zA-Z0-9_-]{1,64}$
    return hashlib.sha256(str(path.resolve()).encode()).hexdigest()[:40]


def image_block(path: Path) -> dict:
    img = Image.open(path)
    img = img.convert("RGB")
    img.thumbnail((MAX_EDGE_PX, MAX_EDGE_PX))
    buf = io.BytesIO()
    img.save(buf, format="JPEG", quality=85)
    return {
        "type": "image",
        "source": {
            "type": "base64",
            "media_type": "image/jpeg",
            "data": base64.standard_b64encode(buf.getvalue()).decode(),
        },
    }


def pdf_block(path: Path) -> dict:
    return {
        "type": "document",
        "source": {
            "type": "base64",
            "media_type": "application/pdf",
            "data": base64.standard_b64encode(path.read_bytes()).decode(),
        },
    }


def build_request(path: Path) -> dict:
    suffix = path.suffix.lower()
    if suffix == ".pdf":
        block = pdf_block(path)
    elif suffix in {".jpg", ".jpeg", ".png", ".webp"}:
        block = image_block(path)
    else:
        raise ValueError(f"unsupported file type: {path}")

    return {
        "custom_id": custom_id_for(path),
        "params": {
            "model": MODEL,
            "max_tokens": 256,
            "system": SYSTEM,
            "messages": [
                {
                    "role": "user",
                    "content": [block, {"type": "text", "text": "Extract the receipt fields."}],
                }
            ],
            "output_config": {"format": {"type": "json_schema", "schema": SCHEMA}},
        },
    }


def submit(root: Path) -> None:
    files = sorted(
        p for p in root.rglob("*")
        if p.suffix.lower() in {".pdf", ".jpg", ".jpeg", ".png", ".webp"}
    )
    print(f"{len(files)} files found")

    chunk, chunk_paths, chunk_bytes = [], [], 0

    def flush():
        nonlocal chunk, chunk_paths, chunk_bytes
        if not chunk:
            return
        batch = client.messages.batches.create(requests=chunk)
        with MANIFEST.open("a") as m:
            for req, p in zip(chunk, chunk_paths):
                m.write(json.dumps({"custom_id": req["custom_id"], "path": str(p), "batch_id": batch.id}) + "\n")
        print(f"submitted {batch.id} with {len(chunk)} requests ({chunk_bytes / 1e6:.1f} MB)")
        chunk, chunk_paths, chunk_bytes = [], [], 0

    for path in files:
        try:
            req = build_request(path)
        except Exception as e:
            with FAILURES.open("a") as f:
                f.write(json.dumps({"path": str(path), "error": f"build: {e}"}) + "\n")
            continue
        size = len(json.dumps(req))
        if chunk and (len(chunk) >= MAX_REQS_PER_BATCH or chunk_bytes + size > MAX_BYTES_PER_BATCH):
            flush()
        chunk.append(req)
        chunk_paths.append(path)
        chunk_bytes += size
    flush()


def collect(poll_seconds: int = 300) -> None:
    entries = [json.loads(line) for line in MANIFEST.read_text().splitlines()]
    id_to_path = {e["custom_id"]: e["path"] for e in entries}
    pending = {e["batch_id"] for e in entries}

    done_file = Path("collected_batches.txt")
    already = set(done_file.read_text().split()) if done_file.exists() else set()
    pending -= already

    usage_in = usage_out = 0
    while pending:
        for batch_id in list(pending):
            batch = client.messages.batches.retrieve(batch_id)
            if batch.processing_status != "ended":
                continue

            with RESULTS.open("a") as out, FAILURES.open("a") as fail:
                for r in client.messages.batches.results(batch_id):
                    path = id_to_path.get(r.custom_id)
                    if r.result.type == "succeeded":
                        msg = r.result.message
                        usage_in += msg.usage.input_tokens
                        usage_out += msg.usage.output_tokens
                        text = next(b.text for b in msg.content if b.type == "text")
                        out.write(json.dumps({"path": path, **json.loads(text)}) + "\n")
                    else:
                        # errored / expired / canceled -> resubmit later (optionally with Sonnet)
                        fail.write(json.dumps({"path": path, "error": r.result.type}) + "\n")

            with done_file.open("a") as d:
                d.write(batch_id + "\n")
            pending.discard(batch_id)
            print(f"collected {batch_id}; tokens so far in={usage_in:,} out={usage_out:,}")

        if pending:
            time.sleep(poll_seconds)

    # Batch Haiku 4.5 pricing: $0.50 / MTok in, $2.50 / MTok out
    cost = usage_in / 1e6 * 0.50 + usage_out / 1e6 * 2.50
    print(f"done. this run: ${cost:,.2f}")


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "submit":
        submit(Path(sys.argv[2]))
    elif len(sys.argv) >= 2 and sys.argv[1] == "collect":
        collect()
    else:
        print(__doc__)
```

**Notes for scaling:**

- **Batch size:** Base64 images reach the 256 MB batch cap long before the 100k-request cap. You'll likely send a few thousand receipts per batch, which works fine with many workers submitting in parallel. If your receipts already live in S3 or GCS, you can use `"source": {"type": "url", "url": presigned_url}` instead. This keeps requests tiny, but make the presigned URLs last at least 24h.
- **Pre-shrinking images** to a 1568px long edge cuts upload size. It has no effect on token cost, because Claude would downscale larger images anyway.
- **Failures:** Rerun the paths in `failures.jsonl` (and any rows with all-null fields) as a separate batch. Swapping `MODEL` to `claude-sonnet-4-5` for that small set should cost little.
- **Output format:** Dates come back in ISO format and totals as numbers, so they can go straight into your existing review rules for suspicious amounts.

