pip install azure-ai-documentintelligence
env:  AZURE_DI_ENDPOINT, AZURE_DI_KEY
"""

import os
import sys
import json
from decimal import Decimal, ROUND_HALF_UP
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import Any, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult, DocumentField
from azure.core.credentials import AzureKeyCredential

ENDPOINT = os.environ["AZURE_DI_ENDPOINT"]
KEY = os.environ["AZURE_DI_KEY"]

# Any field below this confidence is flagged for human review.
CONFIDENCE_THRESHOLD = 0.90
# Tolerance for arithmetic cross-checks (rounding differences).
MONEY_TOLERANCE = Decimal("0.02")

client = DocumentIntelligenceClient(ENDPOINT, AzureKeyCredential(KEY))


# ----------------------------------------------------------------------------
# Field helpers
# ----------------------------------------------------------------------------
def money(x: Any) -> Optional[Decimal]:
    if x is None:
        return None
    return Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def field_value(f: Optional[DocumentField]) -> Any:
    """Return a JSON-friendly typed value from a DocumentField."""
    if f is None:
        return None
    t = f.type
    if t == "string":
        return f.value_string
    if t == "number":
        return f.value_number
    if t == "integer":
        return f.value_integer
    if t == "date":
        return f.value_date.isoformat() if f.value_date else None
    if t == "currency" and f.value_currency is not None:
        return {
            "amount": str(money(f.value_currency.amount)),
            "currency": f.value_currency.currency_code,
        }
    if t == "address" and f.value_address is not None:
        a = f.value_address
        return {
            "street": a.street_address,
            "postal_code": a.postal_code,
            "city": a.city,
            "country": a.country_region,
            "raw": f.content,
        }
    if t == "array":
        return [field_value(v) for v in (f.value_array or [])]
    if t == "object":
        return {k: field_value(v) for k, v in (f.value_object or {}).items()}
    # Fallback: raw OCR text
    return f.content


def field_amount(f: Optional[DocumentField]) -> Optional[Decimal]:
    if f is None:
        return None
    if f.type == "currency" and f.value_currency is not None:
        return money(f.value_currency.amount)
    if f.type == "number" and f.value_number is not None:
        return money(f.value_number)
    return None


def pick(fields: dict, name: str, review: list, path: str = "") -> Any:
    """Extract field value and record it for review if confidence is low."""
    f = fields.get(name)
    if f is None:
        return None
    if f.confidence is not None and f.confidence < CONFIDENCE_THRESHOLD:
        review.append(
            {
                "field": f"{path}{name}",
                "value": field_value(f),
                "raw_text": f.content,
                "confidence": round(f.confidence, 3),
                "reason": "low_confidence",
            }
        )
    return field_value(f)


