# Core extraction
# ----------------------------------------------------------------------------
def analyze_invoice(pdf_path: str) -> dict:
    with open(pdf_path, "rb") as fh:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=fh,
            content_type="application/octet-stream",
            # locale="de-DE",  # optionally force if you know the supplier is German
        )
    result: AnalyzeResult = poller.result()  # waits for the LRO to finish

    if not result.documents:
        return {
            "source_file": pdf_path,
            "status": "no_invoice_detected",
            "needs_review": True,
            "review_items": [{"reason": "no_invoice_detected"}],
        }

    doc = result.documents[0]
    f = doc.fields or {}
    review: list = []

    invoice = {
        "source_file": pdf_path,
        "pages": len(result.pages or []),
        "document_confidence": round(doc.confidence or 0.0, 3),
        "supplier": {
