    for i, item in enumerate((items_field.value_array if items_field else []) or []):
        sub = item.value_object or {}
        p = f"Items[{i}]."
        line = {
            "line_no": i + 1,
            "description": pick(sub, "Description", review, p),
            "product_code": pick(sub, "ProductCode", review, p),
            "quantity": pick(sub, "Quantity", review, p),
            "unit": pick(sub, "Unit", review, p),
            "unit_price": pick(sub, "UnitPrice", review, p),
            "tax": pick(sub, "Tax", review, p),
            "tax_rate": pick(sub, "TaxRate", review, p),
            "amount": pick(sub, "Amount", review, p),
            "date": pick(sub, "Date", review, p),
            "raw_text": item.content,
        }

        # Arithmetic check: quantity * unit_price ≈ amount
        qty = sub.get("Quantity")
        up = field_amount(sub.get("UnitPrice"))
        amt = field_amount(sub.get("Amount"))
        if qty is not None and qty.value_number is not None and up is not None and amt is not None:
            expected = money(Decimal(str(qty.value_number)) * up)
            if abs(expected - amt) > MONEY_TOLERANCE:
                review.append(
                    {
                        "field": f"{p}Amount",
                        "value": str(amt),
                        "expected": str(expected),
                        "reason": "quantity_x_unit_price_mismatch",
                    }
                )
        invoice["line_items"].append(line)

    # Cross-checks on totals
    subtotal = field_amount(f.get("SubTotal"))
    total_tax = field_amount(f.get("TotalTax"))
    total = field_amount(f.get("InvoiceTotal"))

    line_sum = sum(
        (field_amount((it.value_object or {}).get("Amount")) or Decimal("0"))
        for it in ((items_field.value_array if items_field else []) or [])
    )
    if subtotal is not None and invoice["line_items"] and abs(line_sum - subtotal) > MONEY_TOLERANCE:
        review.append(
            {
                "field": "SubTotal",
                "value": str(subtotal),
                "expected": str(money(line_sum)),
                "reason": "line_items_do_not_sum_to_subtotal",
            }
        )
    if subtotal is not None and total_tax is not None and total is not None:
        if abs((subtotal + total_tax) - total) > MONEY_TOLERANCE:
            review.append(
                {
                    "field": "InvoiceTotal",
                    "value": str(total),
                    "expected": str(money(subtotal + total_tax)),
                    "reason": "subtotal_plus_tax_not_equal_total",
                }
            )

    # Must-have fields missing -> review
    for required in ("invoice_number", "total"):
        if invoice[required] is None:
            review.append({"field": required, "reason": "missing"})
    if not invoice["line_items"]:
        review.append({"field": "line_items", "reason": "no_line_items_found"})

    invoice["needs_review"] = bool(review)
    invoice["review_items"] = review
    invoice["status"] = "ok"
    return invoice


# ----------------------------------------------------------------------------
# Batch runner (25k/month ≈ ~1 200/day; a handful of workers is plenty)
# ----------------------------------------------------------------------------
def process_folder(folder: str, out_folder: str, workers: int = 4) -> None:
    pdfs = sorted(Path(folder).glob("*.pdf"))
    Path(out_folder).mkdir(parents=True, exist_ok=True)

    def _one(p: Path):
        try:
            data = analyze_invoice(str(p))
        except Exception as e:  # keep the batch alive, surface the error
            data = {"source_file": str(p), "status": "error", "error": str(e), "needs_review": True}
        (Path(out_folder) / f"{p.stem}.json").write_text(json.dumps(data, ensure_ascii=False, indent=2))
        flag = "REVIEW" if data.get("needs_review") else "ok"
        print(f"[{flag}] {p.name}")
        return data

    with ThreadPoolExecutor(max_workers=workers) as ex:
        results = list(ex.map(_one, pdfs))

    n_review = sum(1 for r in results if r.get("needs_review"))
    print(f"\nDone: {len(results)} invoices, {n_review} flagged for human review.")


if __name__ == "__main__":
    if len(sys.argv) == 2:
        print(json.dumps(analyze_invoice(sys.argv[1]), ensure_ascii=False, indent=2))
    elif len(sys.argv) == 3:
        process_folder(sys.argv[1], sys.argv[2])
    else:
        print("usage: python invoices.py <invoice.pdf>  |  python invoices.py <in_dir> <out_dir>")
