**Recommendation: Amazon Textract `AnalyzeExpense`.** It's a synchronous, receipt-specific endpoint (no job polling, no batching), supports English and Portuguese, handles skewed/shadowed phone photos reasonably well, and returns normalized summary fields (`VENDOR_NAME`, `INVOICE_RECEIPT_DATE`, `TAX`, `TOTAL`) that map directly to what your Go backend needs. Typical latency is ~1–2 s for a single JPEG, which fits the 3-second abandonment window. 75k/day ≈ 0.9 req/s average, well within default quotas (request a raise for peak bursts).

Below is a small Python microservice your Go backend can call (or port the same mapping logic to the AWS Go SDK directly).

```python
import os
import re
from datetime import datetime
from typing import Optional

import boto3
from botocore.config import Config
from fastapi import FastAPI, File, HTTPException, UploadFile

# Tight timeouts so a slow call fails fast instead of eating the 3s budget.
textract = boto3.client(
    "textract",
    region_name=os.getenv("AWS_REGION", "us-east-1"),
    config=Config(connect_timeout=1, read_timeout=2.5, retries={"max_attempts": 1}),
)

app = FastAPI()

FIELD_MAP = {
    "VENDOR_NAME": "merchant",
    "INVOICE_RECEIPT_DATE": "date",
    "TAX": "tax",
    "TOTAL": "total",
}

DATE_FORMATS = (
    "%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y", "%d-%m-%Y", "%d.%m.%Y",
    "%d/%m/%y", "%m/%d/%y", "%b %d, %Y", "%d %b %Y", "%d %B %Y",
)


def parse_amount(text: str) -> Optional[float]:
    """Handles '1,234.56', '1.234,56' (pt-BR), 'R$ 45,90', '$12.00'."""
    s = re.sub(r"[^\d,.\-]", "", text)
    if not s:
        return None
    if "," in s and "." in s:
        # Last separator is the decimal mark.
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        s = s.replace(",", ".") if re.search(r",\d{2}$", s) else s.replace(",", "")
    try:
        return round(float(s), 2)
    except ValueError:
        return None


def parse_date(text: str) -> Optional[str]:
    cleaned = text.strip()
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(cleaned, fmt).date().isoformat()
        except ValueError:
            continue
    m = re.search(r"\d{1,4}[/.-]\d{1,2}[/.-]\d{2,4}", cleaned)
    if m and m.group(0) != cleaned:
        return parse_date(m.group(0))
    return None


def extract_receipt(image_bytes: bytes) -> dict:
    resp = textract.analyze_expense(Document={"Bytes": image_bytes})

    result = {
        "merchant": None,
        "date": None,
        "tax": None,
        "total": None,
        "confidence": {},
        "raw": {},
    }

    for doc in resp.get("ExpenseDocuments", []):
        for field in doc.get("SummaryFields", []):
            ftype = field.get("Type", {}).get("Text")
            key = FIELD_MAP.get(ftype)
            if not key:
                continue
            value = field.get("ValueDetection", {}) or {}
            text = (value.get("Text") or "").strip()
            conf = value.get("Confidence", 0.0)
            if not text:
                continue
            # Keep the highest-confidence candidate per field.
            if conf <= result["confidence"].get(key, -1):
                continue
            result["confidence"][key] = round(conf, 1)
            result["raw"][key] = text
            if key == "merchant":
                result[key] = text
            elif key == "date":
                result[key] = parse_date(text) or text
            else:
                result[key] = parse_amount(text)

    return result


@app.post("/extract")
async def extract(file: UploadFile = File(...)):
    data = await file.read()
    if not data:
        raise HTTPException(status_code=400, detail="empty file")
    if len(data) > 10 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="image exceeds 10 MB Textract limit")
    try:
        return extract_receipt(data)
    except textract.exceptions.UnsupportedDocumentException:
        raise HTTPException(status_code=415, detail="unsupported image")
    except textract.exceptions.ProvisionedThroughputExceededException:
        raise HTTPException(status_code=429, detail="throttled, retry")
    except Exception as e:  # surface to the app so the user can correct manually
        raise HTTPException(status_code=502, detail=f"extraction failed: {e}")


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

Notes for production:
- Downscale images client-side to ~1500 px on the long edge before upload; it cuts upload time more than it hurts accuracy.
- Run the service in the same region as your Textract endpoint to shave network latency.
- Low `confidence` values are a good trigger for your "please confirm" correction UI.

