```python
"""
Recommendation: use the Anthropic Claude API (Messages API with native PDF input).

Why it fits your pilot:
  - One HTTPS POST per invoice. You send the PDF as base64 and get JSON back.
    You don't need queues, templates, training, or OCR infrastructure.
  - Native PDF support. Claude reads both the text layer of digital PDFs and the
    rendered page images, so your 300 dpi scans work through the same call.
  - Structured output. Forcing a tool call with a JSON schema makes the model
    return arguments shaped by your schema rather than free text. Because the
    fields are generated, still check them before use (see the review flag below).
  - Volume. About 300 invoices a week (roughly 60 a day) fits easily within
    synchronous request limits.
  - Limits. PDFs must be under 32 MB and 100 pages per request. Invoices are
    usually far below both.

Your app is TypeScript, and the same request works there unchanged through
`@anthropic-ai/sdk` or plain fetch() to https://api.anthropic.com/v1/messages.
The Python below shows the exact request shape.

Before the pilot, review your data-handling obligations. Invoices contain supplier
and possibly personal data, so check your retention and processing requirements
for a third-party API.

Setup:  pip install anthropic
        export ANTHROPIC_API_KEY=sk-ant-...
"""

import base64
import json
import mimetypes
import re
import sys
from datetime import date
from pathlib import Path

import anthropic

MODEL = "claude-sonnet-4-5"  # strong accuracy/cost balance for document extraction

client = anthropic.Anthropic(max_retries=3, timeout=120.0)  # SDK retries 429/5xx with backoff

INVOICE_TOOL = {
    "name": "record_invoice",
    "description": "Record the key fields extracted from an invoice document.",
    "input_schema": {
        "type": "object",
        "properties": {
            "invoice_number": {
                "type": ["string", "null"],
                "description": "Invoice number/ID exactly as printed. Null if absent.",
            },
            "supplier": {
                "type": ["string", "null"],
                "description": "Legal or trading name of the company issuing the invoice (the seller, not the customer).",
            },
            "date": {
                "type": ["string", "null"],
                "description": "Invoice issue date in ISO 8601 format YYYY-MM-DD. Null if absent.",
            },
            "total": {
                "type": ["number", "null"],
                "description": "Final total amount due including tax, as a plain number without currency symbols or thousands separators.",
            },
            "currency": {
                "type": ["string", "null"],
                "description": "ISO 4217 currency code of the total (e.g. USD, GBP, EUR) if determinable.",
            },
        },
        "required": ["invoice_number", "supplier", "date", "total", "currency"],
    },
}

SYSTEM_PROMPT = (
    "You extract data from invoices. Read the attached invoice and call the "
    "record_invoice tool exactly once. Use values printed on the document only; "
    "never guess. If a field is missing or illegible, return null for it. "
    "The supplier is the party issuing the invoice, not the bill-to customer. "
    "The total is the grand total payable (after tax and discounts)."
)

SUPPORTED_IMAGE_TYPES = {"image/png", "image/jpeg", "image/gif", "image/webp"}


def _build_content_block(file_bytes: bytes, media_type: str) -> dict:
    data = base64.standard_b64encode(file_bytes).decode("utf-8")
    if media_type == "application/pdf":
        return {
            "type": "document",
            "source": {"type": "base64", "media_type": "application/pdf", "data": data},
        }
    if media_type in SUPPORTED_IMAGE_TYPES:
        return {
            "type": "image",
            "source": {"type": "base64", "media_type": media_type, "data": data},
        }
    raise ValueError(f"Unsupported file type: {media_type}")


def _validate(fields: dict) -> dict:
    """Light sanity checks. Flag issues for human review instead of failing hard."""
    issues = []
    if not fields.get("invoice_number"):
        issues.append("missing invoice_number")
    if not fields.get("supplier"):
        issues.append("missing supplier")
    d = fields.get("date")
    if d:
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", d):
            issues.append("date not ISO formatted")
        else:
            try:
                date.fromisoformat(d)
            except ValueError:
                issues.append("invalid calendar date")
    else:
        issues.append("missing date")
    total = fields.get("total")
    if total is None:
        issues.append("missing total")
    elif not isinstance(total, (int, float)) or total < 0:
        issues.append("suspicious total")
    fields["needs_review"] = bool(issues)
    fields["review_reasons"] = issues
    return fields


def extract_invoice(file_bytes: bytes, media_type: str = "application/pdf") -> dict:
    """Send one invoice to Claude and return the extracted fields as a dict."""
    response = client.messages.create(
        model=MODEL,
        max_tokens=1024,
        temperature=0,
        system=SYSTEM_PROMPT,
        tools=[INVOICE_TOOL],
        tool_choice={"type": "tool", "name": "record_invoice"},  # force structured output
        messages=[
            {
                "role": "user",
                "content": [
                    _build_content_block(file_bytes, media_type),
                    {"type": "text", "text": "Extract the invoice fields."},
                ],
            }
        ],
    )

    for block in response.content:
        if block.type == "tool_use" and block.name == "record_invoice":
            return _validate(dict(block.input))

    raise RuntimeError(f"No structured output returned (stop_reason={response.stop_reason})")


def extract_invoice_from_path(path: str) -> dict:
    p = Path(path)
    media_type = mimetypes.guess_type(p.name)[0] or "application/pdf"
    return extract_invoice(p.read_bytes(), media_type)


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python extract_invoice.py invoice1.pdf [invoice2.pdf ...]")
        sys.exit(1)

    results = {}
    for path in sys.argv[1:]:
        try:
            results[path] = extract_invoice_from_path(path)
        except (anthropic.APIError, ValueError, RuntimeError) as e:
            results[path] = {"error": str(e), "needs_review": True}

    print(json.dumps(results, indent=2))

    # Example output:
    # {
    #   "invoice_0412.pdf": {
    #     "invoice_number": "INV-2024-0412",
    #     "supplier": "Northwind Traders Ltd",
    #     "date": "2024-05-14",
    #     "total": 1284.5,
    #     "currency": "GBP",
    #     "needs_review": false,
    #     "review_reasons": []
    #   }
    # }
```

