"""
Recommendation: Amazon Textract (AnalyzeDocument with QUERIES + FORMS).

Why it fits your constraints:
  - Zero training / no labeled data: you just write plain-English questions
    ("What is the applicant's date of birth?") and Textract returns the answer
    with a confidence score -> stable JSON keys you control.
  - Native checkbox support (SELECTION_ELEMENT -> SELECTED / NOT_SELECTED).
  - Works well on 300 dpi English printed scans.
  - Pay-per-page, nothing to host; ~500 pages/week is a few dollars.
  - One developer, one afternoon. The Java side just reads the JSON below.

pip install boto3 pypdfium2
AWS creds via env vars / ~/.aws/credentials, region set via AWS_DEFAULT_REGION.
"""

import json
import sys
from pathlib import Path

import boto3
import pypdfium2 as pdfium

textract = boto3.client("textract")

# ---- Your fixed output schema: alias -> question. Max 15 queries per call. ----
QUERIES = {
    "first_name":   "What is the first name?",
    "last_name":    "What is the last name?",
    "date_of_birth": "What is the date of birth?",
    "signature_date": "What is the date signed?",
    "street_address": "What is the street address?",
    "city":         "What is the city?",
    "state":        "What is the state?",
    "zip_code":     "What is the ZIP code?",
    "phone":        "What is the phone number?",
    "email":        "What is the email address?",
}

MIN_CONFIDENCE = 70.0


def pdf_pages_to_png(pdf_path: Path, dpi: int = 300):
    """Rasterize each page so we can call the synchronous API (no S3 needed)."""
    doc = pdfium.PdfDocument(str(pdf_path))
    for i in range(len(doc)):
        page = doc[i]
        bitmap = page.render(scale=dpi / 72)
        img = bitmap.to_pil()
        from io import BytesIO
        buf = BytesIO()
        img.save(buf, format="PNG")
        yield i + 1, buf.getvalue()


def analyze_page(png_bytes: bytes) -> dict:
    return textract.analyze_document(
        Document={"Bytes": png_bytes},
        FeatureTypes=["QUERIES", "FORMS"],
        QueriesConfig={
            "Queries": [{"Text": q, "Alias": alias} for alias, q in QUERIES.items()]
        },
    )


def block_text(block: dict, blocks: dict) -> str:
    """Concatenate WORD children of a block."""
    words = []
    for rel in block.get("Relationships", []):
        if rel["Type"] == "CHILD":
            for cid in rel["Ids"]:
                child = blocks[cid]
                if child["BlockType"] == "WORD":
                    words.append(child["Text"])
    return " ".join(words).strip()


def parse_response(resp: dict) -> dict:
    blocks = {b["Id"]: b for b in resp["Blocks"]}

    # ---- 1. Query answers -> fixed keys ----
    fields = {alias: None for alias in QUERIES}
    for b in resp["Blocks"]:
        if b["BlockType"] != "QUERY":
            continue
        alias = b["Query"]["Alias"]
        for rel in b.get("Relationships", []):
            if rel["Type"] == "ANSWER":
                best = max(
                    (blocks[i] for i in rel["Ids"]),
                    key=lambda x: x.get("Confidence", 0),
                )
                if best.get("Confidence", 0) >= MIN_CONFIDENCE:
                    fields[alias] = {
                        "value": best["Text"],
                        "confidence": round(best["Confidence"], 1),
                    }

    # ---- 2. Checkboxes: label text -> bool ----
    checkboxes = {}
    for b in resp["Blocks"]:
        if b["BlockType"] != "KEY_VALUE_SET" or "KEY" not in b.get("EntityTypes", []):
            continue
        label = block_text(b, blocks)
        value_block = None
        for rel in b.get("Relationships", []):
            if rel["Type"] == "VALUE":
                value_block = blocks[rel["Ids"][0]]
        if not value_block:
            continue
        for rel in value_block.get("Relationships", []):
            if rel["Type"] == "CHILD":
                for cid in rel["Ids"]:
                    child = blocks[cid]
                    if child["BlockType"] == "SELECTION_ELEMENT" and label:
                        checkboxes[label] = child["SelectionStatus"] == "SELECTED"

    # Also catch orphan selection marks whose label wasn't linked by FORMS
    for b in resp["Blocks"]:
        if b["BlockType"] == "SELECTION_ELEMENT" and b["Id"] not in {
            cid for v in blocks.values() if v["BlockType"] == "KEY_VALUE_SET"
            for rel in v.get("Relationships", []) if rel["Type"] == "CHILD"
            for cid in rel["Ids"]
        }:
            checkboxes.setdefault(f"unlabeled_{b['Id'][:8]}", b["SelectionStatus"] == "SELECTED")

    return {"fields": fields, "checkboxes": checkboxes}


def merge_pages(pages: list[dict]) -> dict:
    """Most forms are 1 page; if multi-page, first non-null answer wins."""
    merged = {"fields": {k: None for k in QUERIES}, "checkboxes": {}}
    for p in pages:
        for k, v in p["fields"].items():
            if merged["fields"][k] is None and v is not None:
                merged["fields"][k] = v
        merged["checkboxes"].update(p["checkboxes"])
    return merged


def process_pdf(pdf_path: Path) -> dict:
    pages = []
    for page_no, png in pdf_pages_to_png(pdf_path):
        resp = analyze_page(png)
        parsed = parse_response(resp)
        parsed["page"] = page_no
        pages.append(parsed)
    result = merge_pages(pages)
    result["source_file"] = pdf_path.name
    result["page_count"] = len(pages)
    return result


def main(input_dir: str, output_dir: str):
    in_dir, out_dir = Path(input_dir), Path(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    for pdf in sorted(in_dir.glob("*.pdf")):
        try:
            result = process_pdf(pdf)
            out_path = out_dir / f"{pdf.stem}.json"
            out_path.write_text(json.dumps(result, indent=2))
            print(f"OK   {pdf.name} -> {out_path.name}")
        except Exception as e:  # keep the batch going; log failures for review
            print(f"FAIL {pdf.name}: {e}", file=sys.stderr)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("usage: python extract_forms.py <input_pdf_dir> <output_json_dir>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])
