```python
"""
Precision-first supplier-invoice extraction using Google Cloud Document AI.

Recommended setup:
1. Create an "Invoice Parser" processor in Google Document AI, preferably in
   the EU region if required for data residency.
2. Pin a tested processor version in production.
3. Keep the confidence and arithmetic gates below. Never silently repair or
   infer uncertain monetary values.
4. Route "needs_review" invoices to verification instead of posting them.
5. Use reviewed corrections to train a Custom Extractor for your suppliers.

Install:
    pip install google-cloud-documentai fastapi uvicorn python-multipart

Environment:
    GOOGLE_CLOUD_PROJECT=your-project
    DOCUMENT_AI_LOCATION=eu
    DOCUMENT_AI_PROCESSOR_ID=...
    DOCUMENT_AI_PROCESSOR_VERSION=...
    GOOGLE_APPLICATION_CREDENTIALS=/path/to/service-account.json

Run:
    uvicorn main:app --host 0.0.0.0 --port 8000
"""

from __future__ import annotations

import hashlib
import json
import os
import re
from collections import defaultdict
from decimal import Decimal, InvalidOperation
from typing import Any

from fastapi import FastAPI, File, HTTPException, UploadFile
from google.api_core.client_options import ClientOptions
from google.api_core.exceptions import GoogleAPICallError
from google.cloud import documentai_v1 as documentai
from starlette.concurrency import run_in_threadpool


PROJECT_ID = os.environ["GOOGLE_CLOUD_PROJECT"]
LOCATION = os.getenv("DOCUMENT_AI_LOCATION", "eu")
PROCESSOR_ID = os.environ["DOCUMENT_AI_PROCESSOR_ID"]
PROCESSOR_VERSION = os.environ["DOCUMENT_AI_PROCESSOR_VERSION"]

MAX_PDF_BYTES = int(os.getenv("MAX_PDF_BYTES", str(20 * 1024 * 1024)))
CRITICAL_CONFIDENCE = float(os.getenv("CRITICAL_CONFIDENCE", "0.97"))
TEXT_CONFIDENCE = float(os.getenv("TEXT_CONFIDENCE", "0.90"))
MIN_IMAGE_QUALITY = float(os.getenv("MIN_IMAGE_QUALITY", "0.50"))
REQUIRE_LINE_QUANTITY = os.getenv("REQUIRE_LINE_QUANTITY", "true").lower() == "true"
REQUIRE_LINE_UNIT_PRICE = os.getenv("REQUIRE_LINE_UNIT_PRICE", "true").lower() == "true"
ARITHMETIC_TOLERANCE = Decimal(os.getenv("ARITHMETIC_TOLERANCE", "0.02"))

client = documentai.DocumentProcessorServiceClient(
    client_options=ClientOptions(
        api_endpoint=f"{LOCATION}-documentai.googleapis.com"
    )
)

PROCESSOR_NAME = client.processor_version_path(
    PROJECT_ID,
    LOCATION,
    PROCESSOR_ID,
    PROCESSOR_VERSION,
)

app = FastAPI(title="Precision-first supplier invoice extraction")


def canonical_type(value: str) -> str:
    leaf = (value or "").lower().rsplit("/", 1)[-1]
    return re.sub(r"[^a-z0-9]+", "_", leaf).strip("_")


def has_proto_field(message: Any, name: str) -> bool:
    try:
        pb = getattr(message, "_pb", message)
        return pb.HasField(name)
    except (AttributeError, ValueError):
        return False


def decimal_string(value: Decimal) -> str:
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return "0" if text in {"", "-0"} else text


def normalized_value(entity: documentai.Document.Entity) -> Any:
    nv = entity.normalized_value

    if has_proto_field(nv, "money_value"):
        money = nv.money_value
        amount = Decimal(money.units) + (
            Decimal(money.nanos) / Decimal("1000000000")
        )
        result: dict[str, Any] = {"amount": decimal_string(amount)}
        if money.currency_code:
            result["currency"] = money.currency_code
        return result

    if has_proto_field(nv, "date_value"):
        date = nv.date_value
        if date.year and date.month and date.day:
            return f"{date.year:04d}-{date.month:02d}-{date.day:02d}"

    if nv.text:
        return nv.text.strip()

    return None


def entity_pages(entity: documentai.Document.Entity) -> list[int]:
    pages: set[int] = set()
    try:
        for ref in entity.page_anchor.page_refs:
            pages.add(int(ref.page) + 1)
    except (AttributeError, TypeError, ValueError):
        pass
    return sorted(pages)


def field_payload(entity: documentai.Document.Entity) -> dict[str, Any]:
    return {
        "normalized": normalized_value(entity),
        "raw": (entity.mention_text or "").strip() or None,
        "confidence": round(float(entity.confidence), 6),
        "pages": entity_pages(entity),
    }


def entity_tree(entity: documentai.Document.Entity) -> dict[str, Any]:
    result = {
        "type": entity.type_,
        **field_payload(entity),
    }
    if entity.properties:
        result["properties"] = [entity_tree(prop) for prop in entity.properties]
    return result


def scalar(entry: dict[str, Any] | None) -> Any:
    if not entry:
        return None
    value = entry.get("normalized")
    if isinstance(value, dict) and "amount" in value:
        return value["amount"]
    return value if value not in (None, "") else entry.get("raw")


def entry_decimal(entry: dict[str, Any] | None) -> Decimal | None:
    if not entry:
        return None

    value = entry.get("normalized")
    if isinstance(value, dict):
        value = value.get("amount")

    if not isinstance(value, str):
        return None

    value = value.strip()

    # Only accept unambiguous, normalized decimals. Raw values such as
    # "1.234,56" are not guessed; they are sent to review instead.
    if not re.fullmatch(r"[+-]?\d+(?:\.\d+)?", value):
        return None

    try:
        return Decimal(value)
    except InvalidOperation:
        return None


def choose_entry(
    fields: dict[str, list[dict[str, Any]]],
    *aliases: str,
) -> dict[str, Any] | None:
    candidates: list[dict[str, Any]] = []
    for alias in aliases:
        candidates.extend(fields.get(canonical_type(alias), []))
    if not candidates:
        return None
    return max(candidates, key=lambda item: float(item.get("confidence", 0)))


def candidate_values(
    fields: dict[str, list[dict[str, Any]]],
    *aliases: str,
) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for alias in aliases:
        result.extend(fields.get(canonical_type(alias), []))
    return result


def values_conflict(entries: list[dict[str, Any]]) -> bool:
    if len(entries) < 2:
        return False

    decimals = [entry_decimal(entry) for entry in entries]
    if all(value is not None for value in decimals):
        return len(set(decimals)) > 1

    identities = {
        json.dumps(scalar(entry), sort_keys=True, ensure_ascii=False)
        for entry in entries
        if scalar(entry) is not None
    }
    return len(identities) > 1


def flatten_properties(
    entity: documentai.Document.Entity,
    destination: dict[str, list[dict[str, Any]]],
) -> None:
    for prop in entity.properties:
        destination[canonical_type(prop.type_)].append(field_payload(prop))
        flatten_properties(prop, destination)


LINE_ALIASES: dict[str, tuple[str, ...]] = {
    "description": ("description", "item_description", "name"),
    "product_code": ("product_code", "item_code", "sku"),
    "quantity": ("quantity", "qty"),
    "unit": ("unit", "unit_of_measure", "uom"),
    "unit_price": ("unit_price", "price", "price_per_unit"),
    "amount": ("amount", "line_amount", "net_amount"),
    "discount_amount": ("discount_amount", "discount"),
    "tax_rate": ("tax_rate", "vat_rate", "gst_rate"),
    "tax_amount": ("tax_amount", "vat_amount", "gst_amount"),
}


def parse_line_item(entity: documentai.Document.Entity) -> dict[str, Any]:
    fields: dict[str, list[dict[str, Any]]] = defaultdict(list)
    flatten_properties(entity, fields)

    line: dict[str, Any] = {}
    evidence: dict[str, Any] = {}
    consumed: set[str] = set()

    for output_name, aliases in LINE_ALIASES.items():
        entry = choose_entry(fields, *aliases)
        line[output_name] = scalar(entry)
        if entry:
            evidence[output_name] = entry
        consumed.update(canonical_type(alias) for alias in aliases)

    extras: dict[str, Any] = {}
    for field_name, entries in fields.items():
        if field_name in consumed:
            continue
        values = [scalar(entry) for entry in entries]
        extras[field_name] = values[0] if len(values) == 1 else values

    if extras:
        line["extra"] = extras

    line["_entity_confidence"] = round(float(entity.confidence), 6)
    line["_pages"] = entity_pages(entity)
    line["_evidence"] = evidence
    return line


def document_image_quality(
    document: documentai.Document,
) -> list[dict[str, Any]]:
    results: list[dict[str, Any]] = []

    for index, page in enumerate(document.pages, start=1):
        if not has_proto_field(page, "image_quality_scores"):
            continue

        quality = page.image_quality_scores
        defects = []
        for defect in quality.detected_defects:
            defects.append(
                {
                    "type": str(defect.type_),
                    "confidence": round(float(defect.confidence), 6),
                }
            )

        results.append(
            {
                "page": index,
                "quality_score": round(float(quality.quality_score), 6),
                "detected_defects": defects,
            }
        )

    return results


def extract_invoice(pdf_bytes: bytes) -> dict[str, Any]:
    request = documentai.ProcessRequest(
        name=PROCESSOR_NAME,
        raw_document=documentai.RawDocument(
            content=pdf_bytes,
            mime_type="application/pdf",
        ),
    )

    response = client.process_document(request=request, timeout=180)
    document = response.document

    fields: dict[str, list[dict[str, Any]]] = defaultdict(list)
    line_entities: list[documentai.Document.Entity] = []

    for entity in document.entities:
        entity_type = canonical_type(entity.type_)

        if entity_type == "line_item":
            line_entities.append(entity)
            continue

        fields[entity_type].append(field_payload(entity))
        flatten_properties(entity, fields)

    supplier_entries = {
        "name": choose_entry(fields, "supplier_name", "vendor_name"),
        "address": choose_entry(fields, "supplier_address", "vendor_address"),
        "tax_id": choose_entry(
            fields,
            "supplier_tax_id",
            "vendor_tax_id",
            "supplier_vat_id",
            "vendor_vat_id",
        ),
        "registration_id": choose_entry(
            fields, "supplier_registration", "supplier_registration_id"
        ),
        "email": choose_entry(fields, "supplier_email", "vendor_email"),
        "phone": choose_entry(fields, "supplier_phone", "vendor_phone"),
        "iban": choose_entry(fields, "supplier_iban", "iban"),
        "bank_account": choose_entry(
            fields, "supplier_bank_account", "bank_account"
        ),
    }

    invoice_entries = {
        "invoice_number": choose_entry(
            fields, "invoice_id", "invoice_number", "invoice_no"
        ),
        "invoice_date": choose_entry(fields, "invoice_date"),
        "due_date": choose_entry(fields, "due_date"),
        "purchase_order": choose_entry(
            fields, "purchase_order", "purchase_order_number", "po_number"
        ),
        "payment_terms": choose_entry(fields, "payment_terms"),
        "payment_reference": choose_entry(
            fields, "payment_reference", "payment_ref"
        ),
    }

    receiver_entries = {
        "name": choose_entry(fields, "receiver_name", "customer_name"),
        "address": choose_entry(fields, "receiver_address", "customer_address"),
        "tax_id": choose_entry(
            fields, "receiver_tax_id", "customer_tax_id", "customer_vat_id"
        ),
    }

    total_entries = {
        "subtotal": choose_entry(fields, "net_amount", "subtotal"),
        "tax": choose_entry(
            fields, "total_tax_amount", "tax_amount", "total_vat_amount"
        ),
        "discount": choose_entry(
            fields, "total_discount_amount", "discount_amount"
        ),
        "shipping": choose_entry(
            fields, "freight_amount", "shipping_amount"
        ),
        "total": choose_entry(
            fields, "total_amount", "gross_amount", "invoice_total"
        ),
        "amount_due": choose_entry(
            fields, "amount_due", "total_due", "balance_due"
        ),
    }

    line_items = [parse_line_item(entity) for entity in line_entities]

    currency_entry = choose_entry(fields, "currency", "currency_code")
    currency = scalar(currency_entry)

    money_currencies: set[str] = set()
    for entries in fields.values():
        for entry in entries:
            normalized = entry.get("normalized")
            if isinstance(normalized, dict) and normalized.get("currency"):
                money_currencies.add(normalized["currency"])

    for line in line_items:
        for evidence in line["_evidence"].values():
            normalized = evidence.get("normalized")
            if isinstance(normalized, dict) and normalized.get("currency"):
                money_currencies.add(normalized["currency"])

    if not currency and len(money_currencies) == 1:
        currency = next(iter(money_currencies))

    tax_details = []
    for field_name, entries in fields.items():
        if not any(token in field_name for token in ("tax", "vat", "gst")):
            continue
        if field_name in {
            "supplier_tax_id",
            "vendor_tax_id",
            "supplier_vat_id",
            "receiver_tax_id",
            "customer_tax_id",
            "customer_vat_id",
            "total_tax_amount",
            "total_vat_amount",
        }:
            continue
        for entry in entries:
            tax_details.append(
                {
                    "type": field_name,
                    "value": scalar(entry),
                    "confidence": entry["confidence"],
                    "pages": entry["pages"],
                }
            )

    reasons: list[str] = []

    def require(
        label: str,
        entry: dict[str, Any] | None,
        threshold: float,
        decimal_required: bool = False,
    ) -> None:
        if entry is None or scalar(entry) in (None, ""):
            reasons.append(f"Missing required field: {label}")
            return
        if float(entry.get("confidence", 0)) < threshold:
            reasons.append(
                f"Low confidence for {label}: "
                f"{entry.get('confidence', 0):.3f} < {threshold:.3f}"
            )
        if decimal_required and entry_decimal(entry) is None:
            reasons.append(
                f"{label} is not an unambiguous normalized decimal"
            )

    require("supplier.name", supplier_entries["name"], TEXT_CONFIDENCE)
    require(
        "invoice.invoice_number",
        invoice_entries["invoice_number"],
        CRITICAL_CONFIDENCE,
    )
    require(
        "invoice.invoice_date",
        invoice_entries["invoice_date"],
        TEXT_CONFIDENCE,
    )
    require(
        "totals.total",
        total_entries["total"],
        CRITICAL_CONFIDENCE,
        decimal_required=True,
    )

    if not currency:
        reasons.append("Missing currency")
    elif len(money_currencies) > 1:
        reasons.append(
            "Multiple currencies detected: " + ", ".join(sorted(money_currencies))
        )

    singleton_fields = {
        "supplier.name": candidate_values(
            fields, "supplier_name", "vendor_name"
        ),
        "invoice.invoice_number": candidate_values(
            fields, "invoice_id", "invoice_number", "invoice_no"
        ),
        "totals.total": candidate_values(
            fields, "total_amount", "gross_amount", "invoice_total"
        ),
        "totals.tax": candidate_values(
            fields, "total_tax_amount", "total_vat_amount"
        ),
    }

    for label, entries in singleton_fields.items():
        if values_conflict(entries):
            reasons.append(f"Conflicting candidates detected for {label}")

    if not line_items:
        reasons.append("No line items were extracted")

    for index, line in enumerate(line_items, start=1):
        evidence = line["_evidence"]

        description = evidence.get("description")
        if description is None:
            reasons.append(f"Line {index}: missing description")
        elif float(description.get("confidence", 0)) < TEXT_CONFIDENCE:
            reasons.append(f"Line {index}: low-confidence description")

        amount_entry = evidence.get("amount")
        require(
            f"line_items[{index}].amount",
            amount_entry,
            CRITICAL_CONFIDENCE,
            decimal_required=True,
        )

        quantity_entry = evidence.get("quantity")
        unit_price_entry = evidence.get("unit_price")

        if REQUIRE_LINE_QUANTITY:
            require(
                f"line_items[{index}].quantity",
                quantity_entry,
                CRITICAL_CONFIDENCE,
                decimal_required=True,
            )
        elif quantity_entry:
            require(
                f"line_items[{index}].quantity",
                quantity_entry,
                CRITICAL_CONFIDENCE,
                decimal_required=True,
            )

        if REQUIRE_LINE_UNIT_PRICE:
            require(
                f"line_items[{index}].unit_price",
                unit_price_entry,
                CRITICAL_CONFIDENCE,
                decimal_required=True,
            )
        elif unit_price_entry:
            require(
                f"line_items[{index}].unit_price",
                unit_price_entry,
                CRITICAL_CONFIDENCE,
                decimal_required=True,
            )

        quantity = entry_decimal(quantity_entry)
        unit_price = entry_decimal(unit_price_entry)
        line_amount = entry_decimal(amount_entry)
        discount = entry_decimal(evidence.get("discount_amount")) or Decimal("0")
        line_tax = entry_decimal(evidence.get("tax_amount"))

        if quantity is not None and unit_price is not None and line_amount is not None:
            expected_net = quantity * unit_price - discount
            candidates = [expected_net]
            if line_tax is not None:
                candidates.append(expected_net + line_tax)

            if all(
                abs(line_amount - candidate) > ARITHMETIC_TOLERANCE
                for candidate in candidates
            ):
                reasons.append(
                    f"Line {index}: quantity × unit price does not reconcile "
                    f"with line amount"
                )

    subtotal = entry_decimal(total_entries["subtotal"])
    total_tax = entry_decimal(total_entries["tax"])
    discount = entry_decimal(total_entries["discount"]) or Decimal("0")
    shipping = entry_decimal(total_entries["shipping"]) or Decimal("0")
    total = entry_decimal(total_entries["total"])

    if subtotal is not None and total_tax is not None and total is not None:
        expected_total = subtotal + total_tax + shipping - discount
        if abs(total - expected_total) > ARITHMETIC_TOLERANCE:
            reasons.append(
                "Invoice arithmetic does not reconcile: "
                "subtotal + tax + shipping - discount != total"
            )

    parsed_line_amounts = [
        entry_decimal(line["_evidence"].get("amount"))
        for line in line_items
    ]
    if (
        subtotal is not None
        and parsed_line_amounts
        and all(value is not None for value in parsed_line_amounts)
    ):
        line_sum = sum(
            (value for value in parsed_line_amounts if value is not None),
            Decimal("0"),
        )
        expected_subtotal = line_sum + shipping - discount
        if abs(subtotal - expected_subtotal) > ARITHMETIC_TOLERANCE:
            reasons.append(
                "Line-item amounts do not reconcile with the invoice subtotal"
            )

    quality_results = document_image_quality(document)
    for page in quality_results:
        if page["quality_score"] < MIN_IMAGE_QUALITY:
            reasons.append(
                f"Page {page['page']} has low image quality: "
                f"{page['quality_score']:.3f}"
            )

    reasons = list(dict.fromkeys(reasons))

    return {
        "status": "needs_review" if reasons else "validated",
        "posting_decision": (
            "HOLD_FOR_REVIEW" if reasons else "READY_FOR_ERP_IMPORT"
        ),
        "document_sha256": hashlib.sha256(pdf_bytes).hexdigest(),
        "currency": currency,
        "supplier": {
            key: scalar(entry) for key, entry in supplier_entries.items()
        },
        "invoice": {
            key: scalar(entry) for key, entry in invoice_entries.items()
        },
        "receiver": {
            key: scalar(entry) for key, entry in receiver_entries.items()
        },
        "taxes": {
            "total": scalar(total_entries["tax"]),
            "details": tax_details,
        },
        "totals": {
            key: scalar(entry) for key, entry in total_entries.items()
        },
        "line_items": line_items,
        "review_reasons": reasons,
        "audit": {
            "processor": PROCESSOR_NAME,
            "page_count": len(document.pages),
            "image_quality": quality_results,
            "field_candidates": dict(fields),
            "raw_entities": [entity_tree(entity) for entity in document.entities],
        },
    }


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok"}


@app.post("/extract-invoice")
async def extract_invoice_endpoint(
    file: UploadFile = File(...),
) -> dict[str, Any]:
    content = await file.read(MAX_PDF_BYTES + 1)

    if len(content) > MAX_PDF_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"PDF exceeds the {MAX_PDF_BYTES}-byte limit",
        )

    if not content.startswith(b"%PDF-"):
        raise HTTPException(status_code=415, detail="A valid PDF is required")

    try:
        return await run_in_threadpool(extract_invoice, content)
    except GoogleAPICallError as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Document AI request failed: {exc.__class__.__name__}",
        ) from exc
