                "role": "user",
                "content": [
                    {
                        "type": "document",
                        "source": {
                            "type": "base64",
                            "media_type": "application/pdf",
                            "data": pdf_b64,
                        },
                    },
                    {
                        "type": "text",
                        "text": (
                            "Extract the invoice number, supplier (issuing company), "
                            "invoice date (YYYY-MM-DD) and grand total from this invoice. "
                            "Use null for anything not present. Do not guess."
                        ),
                    },
                ],
            }
        ],
    }

    headers = {
        "x-api-key": os.environ["ANTHROPIC_API_KEY"],
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
    }

    resp = requests.post(API_URL, headers=headers, json=payload, timeout=120)
    resp.raise_for_status()

    for block in resp.json()["content"]:
        if block["type"] == "tool_use" and block["name"] == "record_invoice":
            return block["input"]

    raise RuntimeError("No structured output returned")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: python extract_invoice.py <invoice.pdf>")
    print(json.dumps(extract_invoice(sys.argv[1]), indent=2))
