                                      "required": ["marker", "text"]},
                        },
                        "continues_from_previous_page": {"type": "boolean"},
                        "continues_on_next_page": {"type": "boolean"},
                        "legibility_issues": {"type": "string"},
                    },
                    "required": ["title", "number_format", "unit", "scale", "column_headers", "rows"],
                },
            }
        },
        "required": ["tables"],
    },
}

LOCATE_PROMPT = """This excerpt contains {n} PDF pages from a company annual report (English or French).
List every page that contains a financial or numeric table: income statement, balance sheet, cash flow,
changes in equity, segment information, notes to the accounts, KPI tables, multi-year summaries.
Ignore charts, tables of contents and narrative text.
Use the 1-based POSITION of the page inside this excerpt (1..{n}), NOT the page number printed on the page.
Call report_table_pages exactly once."""

EXTRACT_PROMPT = """Extract every financial table on this single annual-report page (PDF page {page_no}).
Accuracy of every digit matters more than anything else.

Rules:
1. column_headers: one entry per DATA column (exclude the row-label column), left to right. Each entry is the
   full header path from top level to bottom level. If a header cell is merged across several columns,
   repeat its text in every column it spans. Keep years/periods/notes columns exactly as printed.
2. rows: one entry per printed data row, top to bottom. Section headings without numbers are NOT rows:
   prepend them to label_path of the rows beneath them (e.g. ["Current assets", "Inventories"]).
3. cells: exactly one cell per entry in column_headers, same order. Empty or dash cells: copy raw as printed
   ("", "-", "—") with value null.
4. raw: copy the number exactly as printed, including parentheses, minus signs, spaces, commas, dots and %.
   Do NOT put footnote markers in raw; put them in the cell's footnotes (or label_footnotes for row labels).
5. value: the number as printed (do NOT apply the table's unit/scale). Parentheses or a minus sign mean negative.
   Respect number_format: "en" = 1,234.5 ; "fr" = 1 234,5.
6. Totals: set is_total for total/subtotal rows and, when you can tell which rows it adds up,
   list their 0-based indices in this table's rows array in sum_of_rows.
7. NEVER guess. If any character is unclear, replace it with "?" in raw, set value null, and explain in legibility_issues.
8. Record the stated unit/currency/scale (e.g. "en millions d'euros"). If some columns are % or another unit, use column_units.
9. Mark tables that are cut off at the page top/bottom with continues_from_previous_page / continues_on_next_page.
Call record_tables exactly once (empty list if there are no tables)."""

STRIPS_NOTE = ("The following images are high-resolution horizontal strips of the SAME page, top to bottom, "
               "overlapping slightly. Use them to read small digits accurately; use the full page for layout. "
               "Do not duplicate rows that appear in two overlapping strips.")


# ----------------------------------------------------------------------------- PDF helpers
def subset_pdf(reader: PdfReader, start: int, end: int) -> bytes:
    writer = PdfWriter()
    for i in range(start, end):
        writer.add_page(reader.pages[i])
    buf = io.BytesIO()
    writer.write(buf)
    return buf.getvalue()


def page_text(reader: PdfReader, idx: int) -> str:
    try:
        return reader.pages[idx].extract_text() or ""
    except Exception:
        return ""


def render_strips(pdfium_doc, page_idx: int) -> list[bytes]:
    page = pdfium_doc[page_idx]
    try:
        scale = STRIP_WIDTH / max(page.get_width(), page.get_height() * 0.5)
        img = page.render(scale=scale).to_pil().convert("L")
    finally:
        page.close()
    width, height = img.size
    strips, top = [], 0
    while True:
        bottom = min(top + STRIP_HEIGHT, height)
        buf = io.BytesIO()
        img.crop((0, top, width, bottom)).save(buf, format="PNG", optimize=True)
        strips.append(buf.getvalue())
        if bottom >= height:
            break
        top = bottom - STRIP_OVERLAP
    return strips


def b64(data: bytes) -> str:
    return base64.standard_b64encode(data).decode("ascii")


def pdf_block(data: bytes) -> dict:
    return {"type": "document", "source": {"type": "base64", "media_type": "application/pdf", "data": b64(data)}}


def png_block(data: bytes) -> dict:
    return {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": b64(data)}}


# ----------------------------------------------------------------------------- batch runner
def _pack(requests: list[dict]) -> list[list[dict]]:
    groups, cur, cur_bytes = [], [], 0
    for req in requests:
        size = len(json.dumps(req))
        if cur and (cur_bytes + size > MAX_BATCH_BYTES or len(cur) >= MAX_BATCH_REQUESTS):
            groups.append(cur)
            cur, cur_bytes = [], 0
        cur.append(req)
        cur_bytes += size
    if cur:
        groups.append(cur)
    return groups


def run_batches(requests: list[dict]) -> dict:
    """Submit requests as batches, wait, retry failures. Returns custom_id -> Message."""
    results: dict = {}
    pending = list(requests)
    for round_no in range(MAX_RETRY_ROUNDS + 1):
        if not pending:
            break
        batch_ids = [client.messages.batches.create(requests=g).id for g in _pack(pending)]
        print(f"  submitted {len(pending)} requests in {len(batch_ids)} batch(es) (round {round_no})")
        for bid in batch_ids:
            while client.messages.batches.retrieve(bid).processing_status != "ended":
                time.sleep(POLL_SECONDS)
        failed_ids = set()
        for bid in batch_ids:
            for entry in client.messages.batches.results(bid):
                if entry.result.type == "succeeded":
                    results[entry.custom_id] = entry.result.message
                else:
                    failed_ids.add(entry.custom_id)
        pending = [r for r in pending if r["custom_id"] in failed_ids]
    for r in pending:
        print(f"  WARNING: request {r['custom_id']} failed after retries")
    return results


def tool_input(message) -> dict | None:
    if message is None:
        return None
    for block in message.content:
        if block.type == "tool_use":
            return block.input
    return None


# ----------------------------------------------------------------------------- stage 1: locate
def _chunks_within_limit(reader, start, end):
    data = subset_pdf(reader, start, end)
    if len(data) <= MAX_REQUEST_BYTES or end - start == 1:
        return [(start, end, data)]
    mid = (start + end) // 2
    return _chunks_within_limit(reader, start, mid) + _chunks_within_limit(reader, mid, end)


def locate_table_pages(docs: dict[int, Path]) -> dict[int, set[int]]:
    requests, chunk_meta, found = [], {}, {}
    for d, path in docs.items():
        reader = PdfReader(str(path))
        found[d] = set()
        for i in range(len(reader.pages)):  # cheap heuristic on digital pages (union with model)
            if len(re.findall(r"\(?-?\d[\d .,\u00a0\u202f]*\)?", page_text(reader, i))) >= NUMERIC_DENSITY_THRESHOLD:
                found[d].add(i)
        for s in range(0, len(reader.pages), LOCATE_CHUNK_PAGES):
            e = min(s + LOCATE_CHUNK_PAGES, len(reader.pages))
            for cs, ce, data in _chunks_within_limit(reader, s, e):
                cid = f"loc-{d}-{cs}"
                chunk_meta[cid] = (d, cs, ce)
                requests.append({"custom_id": cid, "params": {
                    "model": LOCATOR_MODEL, "max_tokens": 2048, "temperature": 0,
                    "tools": [LOCATE_TOOL], "tool_choice": {"type": "tool", "name": LOCATE_TOOL["name"]},
                    "messages": [{"role": "user", "content": [
                        pdf_block(data), {"type": "text", "text": LOCATE_PROMPT.format(n=ce - cs)}]}],
                }})
    results = run_batches(requests)
    for cid, (d, cs, ce) in chunk_meta.items():
        out = tool_input(results.get(cid))
        if out is None:  # locator failed: be safe and extract every page in that chunk
            found[d].update(range(cs, ce))
            continue
        for p in out.get("pages", []):
            pos = p.get("position_in_excerpt")
            if isinstance(pos, int) and 1 <= pos <= ce - cs:
                found[d].add(cs + pos - 1)
    return found


# ----------------------------------------------------------------------------- stage 2: extract
def build_extract_requests(docs, table_pages):
    requests, page_info = [], {}
    for d, path in docs.items():
        reader = PdfReader(str(path))
        pdfium_doc = pdfium.PdfDocument(str(path))
        try:
            for p in sorted(table_pages[d]):
                scanned = len(page_text(reader, p).strip()) < SCANNED_TEXT_THRESHOLD
                content = [pdf_block(subset_pdf(reader, p, p + 1))]
                if scanned:
                    content.append({"type": "text", "text": STRIPS_NOTE})
                    content.extend(png_block(s) for s in render_strips(pdfium_doc, p))
                content.append({"type": "text", "text": EXTRACT_PROMPT.format(page_no=p + 1)})
                page_info[(d, p)] = {"scanned": scanned}
                for variant, model in (("a", PRIMARY_MODEL), ("b", CHECK_MODEL)):
                    requests.append({"custom_id": f"ext-{d}-{p}-{variant}", "params": {
                        "model": model, "max_tokens": 32000, "temperature": 0,
                        "tools": [EXTRACT_TOOL], "tool_choice": {"type": "tool", "name": EXTRACT_TOOL["name"]},
                        "messages": [{"role": "user", "content": content}],
                    }})
        finally:
            pdfium_doc.close()
    return requests, page_info


# ----------------------------------------------------------------------------- stage 3: verify
NULL_TOKENS = {"", "-", "–", "—", "−", "/", "n/a", "na", "n.a.", "n.a", "nm", "n.m.", "n.s.", "ns", "n.d.", "nd", "*"}


def parse_raw(raw: str, fmt: str):
    """Deterministic number parsing. Returns (Decimal|None, decimals, status)."""
    s = unicodedata.normalize("NFKC", raw or "").strip()
    if s.casefold() in NULL_TOKENS:
        return None, 0, "empty"
    if "?" in s:
        return None, 0, "illegible"
    neg = False
    if s.startswith("(") and s.endswith(")"):
        neg, s = True, s[1:-1].strip()
    s = s.replace("\u2212", "-").replace("–", "-").replace("—", "-")
    s = re.sub(r"(?i)(€|\$|£|¥|%|\bEUR\b|\bUSD\b|\bGBP\b|\bCHF\b|\bbps?\b|x$)", "", s).strip()
    if s.startswith("(") and s.endswith(")"):
        neg, s = True, s[1:-1].strip()
    if s.startswith("-"):
        neg, s = True, s[1:]
    elif s.endswith("-"):
        neg, s = True, s[:-1]
    elif s.startswith("+"):
        s = s[1:]
    s = re.sub(r"[\s']", "", s)
    if fmt == "fr":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    if not re.fullmatch(r"\d+(\.\d+)?|\.\d+", s):
        return None, 0, "unparseable"
    try:
        val = Decimal(s)
    except InvalidOperation:
        return None, 0, "unparseable"
    decimals = len(s.split(".")[1]) if "." in s else 0
    return (-val if neg else val), decimals, "ok"


def norm_raw(raw: str) -> str:
    return re.sub(r"\s+", "", unicodedata.normalize("NFKC", raw or "")).replace("\u2212", "-")


def norm_label(parts) -> str:
    return re.sub(r"[^0-9a-zà-ÿ]", "", " ".join(parts or []).casefold())


def match_tables(tables_a, tables_b):
    """Pair primary tables with check tables by order, falling back to shape."""
    shape = lambda t: (len(t.get("rows", [])), len(t.get("column_headers", [])))
    pairs, used = [], set()
    for i, ta in enumerate(tables_a):
        if i < len(tables_b) and i not in used and shape(tables_b[i]) == shape(ta):
            pairs.append(tables_b[i]); used.add(i); continue
        j = next((j for j, tb in enumerate(tables_b) if j not in used and shape(tb) == shape(ta)), None)
        if j is not None:
            used.add(j)
        pairs.append(tables_b[j] if j is not None else None)
    return pairs


def verify_table(t, check, check_available):
    fmt = t.get("number_format", "en")
    headers = t.get("column_headers", [])
    rows = t.get("rows", [])
    ncols = len(headers)
    table_flags, cell_flags, parsed = [], {}, {}

    if t.get("legibility_issues"):
        table_flags.append("model_reported_legibility_issue")

    for r, row in enumerate(rows):
        cells = row.get("cells", [])
        if len(cells) != ncols:
            cell_flags.setdefault((r, -1), []).append(f"cell_count_{len(cells)}_vs_{ncols}_columns")
        for c, cell in enumerate(cells):
            val, dec, status = parse_raw(cell.get("raw", ""), fmt)
            parsed[(r, c)] = (val, dec)
            flags = cell_flags.setdefault((r, c), [])
            if status == "illegible":
                flags.append("illegible")
            elif status == "unparseable":
                flags.append("unparseable_raw")
            model_val = cell.get("value")
            if status == "ok" and model_val is not None:
                if abs(Decimal(str(model_val)) - val) > Decimal("1e-9"):
                    flags.append(f"model_value_{model_val}_differs_from_raw")
            elif status == "ok" and model_val is None:
                flags.append("model_value_missing")

    # arithmetic: totals must equal the sum of their components (within rounding)
    for r, row in enumerate(rows):
        comps = [i for i in row.get("sum_of_rows") or [] if isinstance(i, int) and 0 <= i < len(rows) and i != r]
        if not comps:
            continue
        for c in range(ncols):
            total, tdec = parsed.get((r, c), (None, 0))
            vals = [parsed.get((i, c), (None, 0)) for i in comps]
            if total is None or any(v is None for v, _ in vals):
                continue
            dec = max([tdec] + [d for _, d in vals])
            tol = Decimal("0.5") * Decimal(10) ** -dec * (len(comps) + 1)
            diff = total - sum(v for v, _ in vals)
            if abs(diff) > tol:
                cell_flags.setdefault((r, c), []).append(f"sum_check_off_by_{diff}")

    # independent second extraction must agree cell by cell
    if not check_available:
        table_flags.append("no_independent_check")
    elif check is None:
        table_flags.append("check_model_found_different_table_shape")
    else:
        rows_b = check.get("rows", [])
        for c, (ha, hb) in enumerate(zip(headers, check.get("column_headers", []))):
            if norm_label(ha) != norm_label(hb):
                cell_flags.setdefault((-1, c), []).append(f"header_disagrees:{json.dumps(hb, ensure_ascii=False)}")
        for r, (ra, rb) in enumerate(zip(rows, rows_b)):
            if norm_label(ra.get("label_path")) != norm_label(rb.get("label_path")):
                cell_flags.setdefault((r, -1), []).append(
                    f"row_label_disagrees:{json.dumps(rb.get('label_path'), ensure_ascii=False)}")
            for c, (ca, cb) in enumerate(zip(ra.get("cells", []), rb.get("cells", []))):
                if norm_raw(ca.get("raw")) != norm_raw(cb.get("raw")):
                    cell_flags.setdefault((r, c), []).append(f"check_read:{cb.get('raw')}")
                if sorted(ca.get("footnotes") or []) != sorted(cb.get("footnotes") or []):
                    cell_flags.setdefault((r, c), []).append("footnote_disagrees")
    return table_flags, cell_flags, parsed


# ----------------------------------------------------------------------------- output
CSV_FIELDS = ["document", "page", "scanned_page", "table_index", "table_title", "number_format", "unit", "scale",
              "currency", "row_index", "row_label_path", "row_label_footnotes", "is_total", "col_index",
              "column_header_path", "column_unit", "raw", "value", "cell_footnotes", "table_footnotes",
              "continues_from_previous_page", "continues_on_next_page", "flags"]


def write_document(path: Path, d: int, pages, results, page_info, out_dir: Path, review_writer):
    out_file = out_dir / f"{path.stem}.csv"
    with out_file.open("w", newline="", encoding="utf-8") as fh:
        writer = csv.DictWriter(fh, fieldnames=CSV_FIELDS)
        writer.writeheader()
        for p in sorted(pages):
            msg_a, msg_b = results.get(f"ext-{d}-{p}-a"), results.get(f"ext-{d}-{p}-b")
            out_a, out_b = tool_input(msg_a), tool_input(msg_b)
            page_flags = []
            if out_a is None:
                review_writer.writerow({"document": path.name, "page": p + 1, "flags": "primary_extraction_failed"})
                continue
            if msg_a.stop_reason == "max_tokens":
                page_flags.append("primary_output_truncated")
            if msg_b is not None and msg_b.stop_reason == "max_tokens":
                page_flags.append("check_output_truncated")
            tables_a = out_a.get("tables", [])
            tables_b = (out_b or {}).get("tables", [])
            if out_b is not None and len(tables_a) != len(tables_b):
                page_flags.append(f"table_count_{len(tables_a)}_vs_check_{len(tables_b)}")
            checks = match_tables(tables_a, tables_b) if out_b is not None else [None] * len(tables_a)

            for ti, (t, chk) in enumerate(zip(tables_a, checks)):
                table_flags, cell_flags, parsed = verify_table(t, chk, out_b is not None)
                headers = t.get("column_headers", [])
                col_units = t.get("column_units") or []
                table_fn = json.dumps(t.get("footnotes", []), ensure_ascii=False)
                for r, row in enumerate(t.get("rows", [])):
                    for c, cell in enumerate(row.get("cells", [])):
                        flags = (page_flags + table_flags + cell_flags.get((r, c), [])
                                 + cell_flags.get((r, -1), []) + cell_flags.get((-1, c), []))
                        val = parsed.get((r, c), (None, 0))[0]
                        rec = {
                            "document": path.name, "page": p + 1,
                            "scanned_page": page_info.get((d, p), {}).get("scanned", False),
                            "table_index": ti, "table_title": t.get("title", ""),
                            "number_format": t.get("number_format", ""), "unit": t.get("unit", ""),
                            "scale": t.get("scale", ""), "currency": t.get("currency") or "",
                            "row_index": r,
                            "row_label_path": json.dumps(row.get("label_path", []), ensure_ascii=False),
                            "row_label_footnotes": json.dumps(row.get("label_footnotes", []), ensure_ascii=False),
                            "is_total": bool(row.get("is_total")), "col_index": c,
                            "column_header_path": json.dumps(headers[c] if c < len(headers) else [], ensure_ascii=False),
                            "column_unit": (col_units[c] if c < len(col_units) and col_units[c] else ""),
                            "raw": cell.get("raw", ""),
                            "value": "" if val is None else format(val, "f"),
                            "cell_footnotes": json.dumps(cell.get("footnotes", []), ensure_ascii=False),
                            "table_footnotes": table_fn,
                            "continues_from_previous_page": bool(t.get("continues_from_previous_page")),
                            "continues_on_next_page": bool(t.get("continues_on_next_page")),
                            "flags": ";".join(flags),
                        }
                        writer.writerow(rec)
                        if flags:
                            review_writer.writerow(rec)
    print(f"  wrote {out_file}")


# ----------------------------------------------------------------------------- main
def process_wave(paths: list[Path], out_dir: Path, review_writer):
    docs = dict(enumerate(paths))
    print(f"Stage 1: locating table pages in {len(docs)} documents")
    table_pages = locate_table_pages(docs)
    print(f"Stage 2: extracting {sum(len(v) for v in table_pages.values())} table pages (x2 models)")
    requests, page_info = build_extract_requests(docs, table_pages)
    results = run_batches(requests)
    del requests
    print("Stage 3: verifying and writing CSV")
    for d, path in docs.items():
        write_document(path, d, table_pages[d], results, page_info, out_dir, review_writer)


def main(in_dir: str, out_dir: str):
    in_path, out_path = Path(in_dir), Path(out_dir)
    out_path.mkdir(parents=True, exist_ok=True)
    pdfs = sorted(p for p in in_path.rglob("*.pdf") if not (out_path / f"{p.stem}.csv").exists())
    review_file = out_path / "review_queue.csv"
    new_file = not review_file.exists()
    with review_file.open("a", newline="", encoding="utf-8") as fh:
        review_writer = csv.DictWriter(fh, fieldnames=CSV_FIELDS)
        if new_file:
            review_writer.writeheader()
        for i in range(0, len(pdfs), DOCS_PER_WAVE):
            print(f"=== Wave {i // DOCS_PER_WAVE + 1}: documents {i + 1}-{min(i + DOCS_PER_WAVE, len(pdfs))} of {len(pdfs)}")
            process_wave(pdfs[i:i + DOCS_PER_WAVE], out_path, review_writer)
            fh.flush()


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: python extract_tables.py <input_pdf_dir> <output_dir>")
    main(sys.argv[1], sys.argv[2])
```

Notes for integration:

- **Java side:** read each `<report>.csv` as long-format data.
  - `row_label_path` and `column_header_path` are JSON arrays, so multi-level headers and merged cells can be pivoted back exactly.
  - `value` is an exact decimal string. Parse it with `BigDecimal`. It is not scaled; apply `scale`/`unit` in Java.
  - Tables that span pages are marked with `continues_on_next_page`, so you can stitch them by page order.
- **Review workload:** analysts only open `review_queue.csv`. A cell lands there if the two models disagree, if a sum doesn't add up, if the parsed raw text conflicts with the model's value, or if a digit was illegible. Unflagged cells were read identically by two independent models and passed arithmetic checks.
- **Tuning:**
  - Raise `DOCS_PER_WAVE` if memory allows.
  - Set `CHECK_MODEL` to `PRIMARY_MODEL` if you prefer two reads by the same model. Cross-model checks usually catch more errors.
  - Run a pilot on ~50 reports and compare against hand-checked tables to calibrate how much to trust unflagged cells.

content.text:
Use the **Anthropic Claude API** with the **Message Batches API**. It suits this job for these reasons:

- **Input handling:** Claude accepts PDFs directly. It uses the text layer on digital pages and the rendered page image on scanned pages, and it reads English and French.
- **Cost and timing:** Batches are asynchronous and cost about 50% less. Your analysts can wait, so this tradeoff works for you.
- **Structured output:** Forced tool use returns a strict JSON structure, which avoids parsing free-form text.
- **Less manual checking:** No model is perfectly accurate on dense tables. The pipeline checks the output so reviewers only look at flagged cells:
  1. It extracts every table page twice with two different models (Opus as primary, Sonnet as an independent check) and compares them cell by cell.
  2. It parses every printed number itself, using English or French number formats, and compares that to the model's value.
  3. It checks that totals and subtotals add up.
  4. It treats illegible characters as `?` instead of guessing.
- **Small text on scans:** Scanned pages also get high-resolution horizontal strips, so small digits stay readable.

The output is a tidy, long-format CSV: one row per cell, with row and header paths stored as JSON arrays. Your Java service can rebuild multi-level headers and merged cells from it without ambiguity. A separate `review_queue.csv` lists only the flagged cells.

```python
"""
Financial-table extraction for annual reports (EN/FR) -> CSV, using the Anthropic Claude API.

Pipeline (asynchronous, via the Message Batches API):
  1. LOCATE  : find pages that contain financial tables (Claude + digit-density heuristic).
  2. EXTRACT : each table page is extracted twice by two different models (independent check).
               Scanned pages also get high-resolution image strips so small text stays readable.
  3. VERIFY  : deterministic EN/FR number parsing, sum/subtotal checks, cross-model cell diff.
               Only flagged cells go to review_queue.csv.

Output per document: <stem>.csv in long format (one row per cell), easy for a Java service:
  label/header paths are JSON arrays, values are exact decimals (never floats), unit/scale kept.

Install: pip install anthropic pypdf pypdfium2 pillow
Env:     ANTHROPIC_API_KEY
Usage:   python extract_tables.py ./reports ./out
"""
import base64
import csv
import io
import json
import os
import re
import sys
import time
import unicodedata
from decimal import Decimal, InvalidOperation
from pathlib import Path

import anthropic
import pypdfium2 as pdfium
from pypdf import PdfReader, PdfWriter

client = anthropic.Anthropic()

# ----------------------------------------------------------------------------- config
PRIMARY_MODEL = os.environ.get("PRIMARY_MODEL", "claude-opus-4-5")   # authoritative extraction
CHECK_MODEL = os.environ.get("CHECK_MODEL", "claude-sonnet-4-5")     # independent second read
LOCATOR_MODEL = os.environ.get("LOCATOR_MODEL", "claude-sonnet-4-5")

DOCS_PER_WAVE = int(os.environ.get("DOCS_PER_WAVE", "20"))  # bounds memory (base64 payloads)
LOCATE_CHUNK_PAGES = 40
MAX_REQUEST_BYTES = 28 * 1024 * 1024       # API request limit is 32 MB
MAX_BATCH_BYTES = 200 * 1024 * 1024        # batch limit is 256 MB
MAX_BATCH_REQUESTS = 50_000
POLL_SECONDS = 60
MAX_RETRY_ROUNDS = 2

STRIP_WIDTH = 1568        # Claude's max useful long edge; full-width strips keep rows intact
STRIP_HEIGHT = 1000
STRIP_OVERLAP = 120
SCANNED_TEXT_THRESHOLD = 80      # chars of extractable text below which a page is "scanned"
NUMERIC_DENSITY_THRESHOLD = 30   # numeric tokens that make a digital page a table candidate

# ----------------------------------------------------------------------------- tool schemas
LOCATE_TOOL = {
    "name": "report_table_pages",
    "description": "Report which pages of the excerpt contain financial/numeric tables.",
    "input_schema": {
        "type": "object",
        "properties": {
            "pages": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "position_in_excerpt": {"type": "integer", "description": "1-based PDF position within this excerpt"},
                        "kind": {"type": "string", "description": "e.g. income statement, balance sheet, note table"},
                    },
                    "required": ["position_in_excerpt"],
                },
            }
        },
        "required": ["pages"],
    },
}

EXTRACT_TOOL = {
    "name": "record_tables",
    "description": "Record every financial table on the page with exact cell contents.",
    "input_schema": {
        "type": "object",
        "properties": {
            "tables": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "title": {"type": "string"},
                        "number_format": {"type": "string", "enum": ["en", "fr"],
                                          "description": "en: 1,234.5 | fr: 1 234,5"},
                        "unit": {"type": "string", "description": "As stated, e.g. 'in € millions', 'en milliers d'euros'"},
                        "currency": {"type": ["string", "null"]},
                        "scale": {"type": "string",
                                  "enum": ["units", "thousands", "millions", "billions", "percent", "mixed", "unknown"]},
                        "column_headers": {
                            "type": "array",
                            "description": "One entry per data column, left to right. Each entry is the full header path top->bottom.",
                            "items": {"type": "array", "items": {"type": "string"}},
                        },
                        "column_units": {
                            "type": "array",
                            "description": "Optional per-column unit override (e.g. '%'), same length as column_headers; null = table unit.",
                            "items": {"type": ["string", "null"]},
                        },
                        "rows": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "label_path": {"type": "array", "items": {"type": "string"}},
                                    "label_footnotes": {"type": "array", "items": {"type": "string"}},
                                    "is_total": {"type": "boolean"},
                                    "sum_of_rows": {"type": "array", "items": {"type": "integer"}},
                                    "cells": {
                                        "type": "array",
                                        "items": {
                                            "type": "object",
                                            "properties": {
                                                "raw": {"type": "string"},
                                                "value": {"type": ["number", "null"]},
                                                "footnotes": {"type": "array", "items": {"type": "string"}},
                                            },
                                            "required": ["raw", "value"],
                                        },
                                    },
                                },
                                "required": ["label_path", "cells"],
                            },
                        },
                        "footnotes": {
                            "type": "array",
                            "items": {"type": "object",
                                      "properties": {"marker": {"type": "string"}, "text": {"type": "string"}},
                                      "required": ["marker", "text"]},
                        },
                        "continues_from_previous_page": {"type": "boolean"},
                        "continues_on_next_page": {"type": "boolean"},
                        "legibility_issues": {"type": "string"},
                    },
                    "required": ["title", "number_format", "unit", "scale", "column_headers", "rows"],
                },
            }
        },
        "required": ["tables"],
    },
}

LOCATE_PROMPT = """This excerpt contains {n} PDF pages from a company annual report (English or French).
List every page that contains a financial or numeric table: income statement, balance sheet, cash flow,
changes in equity, segment information, notes to the accounts, KPI tables, multi-year summaries.
Ignore charts, tables of contents and narrative text.
Use the 1-based POSITION of the page inside this excerpt (1..{n}), NOT the page number printed on the page.
Call report_table_pages exactly once."""

EXTRACT_PROMPT = """Extract every financial table on this single annual-report page (PDF page {page_no}).
Accuracy of every digit matters more than anything else.

Rules:
1. column_headers: one entry per DATA column (exclude the row-label column), left to right. Each entry is the
   full header path from top level to bottom level. If a header cell is merged across several columns,
   repeat its text in every column it spans. Keep years/periods/notes columns exactly as printed.
2. rows: one entry per printed data row, top to bottom. Section headings without numbers are NOT rows:
   prepend them to label_path of the rows beneath them (e.g. ["Current assets", "Inventories"]).
3. cells: exactly one cell per entry in column_headers, same order. Empty or dash cells: copy raw as printed
   ("", "-", "—") with value null.
4. raw: copy the number exactly as printed, including parentheses, minus signs, spaces, commas, dots and %.
   Do NOT put footnote markers in raw; put them in the cell's footnotes (or label_footnotes for row labels).
5. value: the number as printed (do NOT apply the table's unit/scale). Parentheses or a minus sign mean negative.
   Respect number_format: "en" = 1,234.5 ; "fr" = 1 234,5.
6. Totals: set is_total for total/subtotal rows and, when you can tell which rows it adds up,
   list their 0-based indices in this table's rows array in sum_of_rows.
7. NEVER guess. If any character is unclear, replace it with "?" in raw, set value null, and explain in legibility_issues.
8. Record the stated unit/currency/scale (e.g. "en millions d'euros"). If some columns are % or another unit, use column_units.
9. Mark tables that are cut off at the page top/bottom with continues_from_previous_page / continues_on_next_page.
Call record_tables exactly once (empty list if there are no tables)."""

STRIPS_NOTE = ("The following images are high-resolution horizontal strips of the SAME page, top to bottom, "
               "overlapping slightly. Use them to read small digits accurately; use the full page for layout. "
               "Do not duplicate rows that appear in two overlapping strips.")


# ----------------------------------------------------------------------------- PDF helpers
def subset_pdf(reader: PdfReader, start: int, end: int) -> bytes:
    writer = PdfWriter()
    for i in range(start, end):
        writer.add_page(reader.pages[i])
    buf = io.BytesIO()
    writer.write(buf)
    return buf.getvalue()


def page_text(reader: PdfReader, idx: int) -> str:
    try:
        return reader.pages[idx].extract_text() or ""
    except Exception:
        return ""


def render_strips(pdfium_doc, page_idx: int) -> list[bytes]:
    page = pdfium_doc[page_idx]
    try:
        scale = STRIP_WIDTH / max(page.get_width(), page.get_height() * 0.5)
        img = page.render(scale=scale).to_pil().convert("L")
    finally:
        page.close()
    width, height = img.size
    strips, top = [], 0
    while True:
        bottom = min(top + STRIP_HEIGHT, height)
        buf = io.BytesIO()
        img.crop((0, top, width, bottom)).save(buf, format="PNG", optimize=True)
        strips.append(buf.getvalue())
        if bottom >= height:
            break
        top = bottom - STRIP_OVERLAP
    return strips


def b64(data: bytes) -> str:
    return base64.standard_b64encode(data).decode("ascii")


def pdf_block(data: bytes) -> dict:
    return {"type": "document", "source": {"type": "base64", "media_type": "application/pdf", "data": b64(data)}}


def png_block(data: bytes) -> dict:
    return {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": b64(data)}}


# ----------------------------------------------------------------------------- batch runner
def _pack(requests: list[dict]) -> list[list[dict]]:
    groups, cur, cur_bytes = [], [], 0
    for req in requests:
        size = len(json.dumps(req))
        if cur and (cur_bytes + size > MAX_BATCH_BYTES or len(cur) >= MAX_BATCH_REQUESTS):
            groups.append(cur)
            cur, cur_bytes = [], 0
        cur.append(req)
        cur_bytes += size
    if cur:
        groups.append(cur)
    return groups


def run_batches(requests: list[dict]) -> dict:
    """Submit requests as batches, wait, retry failures. Returns custom_id -> Message."""
    results: dict = {}
    pending = list(requests)
    for round_no in range(MAX_RETRY_ROUNDS + 1):
        if not pending:
            break
        batch_ids = [client.messages.batches.create(requests=g).id for g in _pack(pending)]
        print(f"  submitted {len(pending)} requests in {len(batch_ids)} batch(es) (round {round_no})")
        for bid in batch_ids:
            while client.messages.batches.retrieve(bid).processing_status != "ended":
                time.sleep(POLL_SECONDS)
        failed_ids = set()
        for bid in batch_ids:
            for entry in client.messages.batches.results(bid):
                if entry.result.type == "succeeded":
                    results[entry.custom_id] = entry.result.message
                else:
                    failed_ids.add(entry.custom_id)
        pending = [r for r in pending if r["custom_id"] in failed_ids]
    for r in pending:
        print(f"  WARNING: request {r['custom_id']} failed after retries")
    return results


def tool_input(message) -> dict | None:
    if message is None:
        return None
    for block in message.content:
        if block.type == "tool_use":
            return block.input
    return None


# ----------------------------------------------------------------------------- stage 1: locate
def _chunks_within_limit(reader, start, end):
    data = subset_pdf(reader, start, end)
    if len(data) <= MAX_REQUEST_BYTES or end - start == 1:
        return [(start, end, data)]
    mid = (start + end) // 2
    return _chunks_within_limit(reader, start, mid) + _chunks_within_limit(reader, mid, end)


def locate_table_pages(docs: dict[int, Path]) -> dict[int, set[int]]:
    requests, chunk_meta, found = [], {}, {}
    for d, path in docs.items():
        reader = PdfReader(str(path))
        found[d] = set()
        for i in range(len(reader.pages)):  # cheap heuristic on digital pages (union with model)
            if len(re.findall(r"\(?-?\d[\d .,\u00a0\u202f]*\)?", page_text(reader, i))) >= NUMERIC_DENSITY_THRESHOLD:
                found[d].add(i)
        for s in range(0, len(reader.pages), LOCATE_CHUNK_PAGES):
            e = min(s + LOCATE_CHUNK_PAGES, len(reader.pages))
            for cs, ce, data in _chunks_within_limit(reader, s, e):
                cid = f"loc-{d}-{cs}"
                chunk_meta[cid] = (d, cs, ce)
                requests.append({"custom_id": cid, "params": {
                    "model": LOCATOR_MODEL, "max_tokens": 2048, "temperature": 0,
                    "tools": [LOCATE_TOOL], "tool_choice": {"type": "tool", "name": LOCATE_TOOL["name"]},
                    "messages": [{"role": "user", "content": [
                        pdf_block(data), {"type": "text", "text": LOCATE_PROMPT.format(n=ce - cs)}]}],
                }})
    results = run_batches(requests)
    for cid, (d, cs, ce) in chunk_meta.items():
        out = tool_input(results.get(cid))
        if out is None:  # locator failed: be safe and extract every page in that chunk
            found[d].update(range(cs, ce))
            continue
        for p in out.get("pages", []):
            pos = p.get("position_in_excerpt")
            if isinstance(pos, int) and 1 <= pos <= ce - cs:
                found[d].add(cs + pos - 1)
    return found


# ----------------------------------------------------------------------------- stage 2: extract
def build_extract_requests(docs, table_pages):
    requests, page_info = [], {}
    for d, path in docs.items():
        reader = PdfReader(str(path))
        pdfium_doc = pdfium.PdfDocument(str(path))
        try:
            for p in sorted(table_pages[d]):
                scanned = len(page_text(reader, p).strip()) < SCANNED_TEXT_THRESHOLD
                content = [pdf_block(subset_pdf(reader, p, p + 1))]
                if scanned:
                    content.append({"type": "text", "text": STRIPS_NOTE})
                    content.extend(png_block(s) for s in render_strips(pdfium_doc, p))
                content.append({"type": "text", "text": EXTRACT_PROMPT.format(page_no=p + 1)})
                page_info[(d, p)] = {"scanned": scanned}
                for variant, model in (("a", PRIMARY_MODEL), ("b", CHECK_MODEL)):
                    requests.append({"custom_id": f"ext-{d}-{p}-{variant}", "params": {
                        "model": model, "max_tokens": 32000, "temperature": 0,
                        "tools": [EXTRACT_TOOL], "tool_choice": {"type": "tool", "name": EXTRACT_TOOL["name"]},
                        "messages": [{"role": "user", "content": content}],
                    }})
        finally:
            pdfium_doc.close()
    return requests, page_info


# ----------------------------------------------------------------------------- stage 3: verify
NULL_TOKENS = {"", "-", "–", "—", "−", "/", "n/a", "na", "n.a.", "n.a", "nm", "n.m.", "n.s.", "ns", "n.d.", "nd", "*"}


def parse_raw(raw: str, fmt: str):
    """Deterministic number parsing. Returns (Decimal|None, decimals, status)."""
    s = unicodedata.normalize("NFKC", raw or "").strip()
    if s.casefold() in NULL_TOKENS:
        return None, 0, "empty"
    if "?" in s:
        return None, 0, "illegible"
    neg = False
    if s.startswith("(") and s.endswith(")"):
        neg, s = True, s[1:-1].strip()
    s = s.replace("\u2212", "-").replace("–", "-").replace("—", "-")
    s = re.sub(r"(?i)(€|\$|£|¥|%|\bEUR\b|\bUSD\b|\bGBP\b|\bCHF\b|\bbps?\b|x$)", "", s).strip()
    if s.startswith("(") and s.endswith(")"):
        neg, s = True, s[1:-1].strip()
    if s.startswith("-"):
        neg, s = True, s[1:]
    elif s.endswith("-"):
        neg, s = True, s[:-1]
    elif s.startswith("+"):
        s = s[1:]
    s = re.sub(r"[\s']", "", s)
    if fmt == "fr":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    if not re.fullmatch(r"\d+(\.\d+)?|\.\d+", s):
        return None, 0, "unparseable"
    try:
        val = Decimal(s)
    except InvalidOperation:
        return None, 0, "unparseable"
    decimals = len(s.split(".")[1]) if "." in s else 0
    return (-val if neg else val), decimals, "ok"


def norm_raw(raw: str) -> str:
    return re.sub(r"\s+", "", unicodedata.normalize("NFKC", raw or "")).replace("\u2212", "-")


def norm_label(parts) -> str:
    return re.sub(r"[^0-9a-zà-ÿ]", "", " ".join(parts or []).casefold())


def match_tables(tables_a, tables_b):
    """Pair primary tables with check tables by order, falling back to shape."""
    shape = lambda t: (len(t.get("rows", [])), len(t.get("column_headers", [])))
    pairs, used = [], set()
    for i, ta in enumerate(tables_a):
        if i < len(tables_b) and i not in used and shape(tables_b[i]) == shape(ta):
            pairs.append(tables_b[i]); used.add(i); continue
        j = next((j for j, tb in enumerate(tables_b) if j not in used and shape(tb) == shape(ta)), None)
        if j is not None:
            used.add(j)
        pairs.append(tables_b[j] if j is not None else None)
    return pairs


def verify_table(t, check, check_available):
    fmt = t.get("number_format", "en")
    headers = t.get("column_headers", [])
    rows = t.get("rows", [])
    ncols = len(headers)
    table_flags, cell_flags, parsed = [], {}, {}

    if t.get("legibility_issues"):
        table_flags.append("model_reported_legibility_issue")

    for r, row in enumerate(rows):
        cells = row.get("cells", [])
        if len(cells) != ncols:
            cell_flags.setdefault((r, -1), []).append(f"cell_count_{len(cells)}_vs_{ncols}_columns")
        for c, cell in enumerate(cells):
            val, dec, status = parse_raw(cell.get("raw", ""), fmt)
            parsed[(r, c)] = (val, dec)
            flags = cell_flags.setdefault((r, c), [])
            if status == "illegible":
                flags.append("illegible")
            elif status == "unparseable":
                flags.append("unparseable_raw")
            model_val = cell.get("value")
            if status == "ok" and model_val is not None:
                if abs(Decimal(str(model_val)) - val) > Decimal("1e-9"):
                    flags.append(f"model_value_{model_val}_differs_from_raw")
            elif status == "ok" and model_val is None:
                flags.append("model_value_missing")

    # arithmetic: totals must equal the sum of their components (within rounding)
    for r, row in enumerate(rows):
        comps = [i for i in row.get("sum_of_rows") or [] if isinstance(i, int) and 0 <= i < len(rows) and i != r]
        if not comps:
            continue
        for c in range(ncols):
            total, tdec = parsed.get((r, c), (None, 0))
            vals = [parsed.get((i, c), (None, 0)) for i in comps]
            if total is None or any(v is None for v, _ in vals):
                continue
            dec = max([tdec] + [d for _, d in vals])
            tol = Decimal("0.5") * Decimal(10) ** -dec * (len(comps) + 1)
            diff = total - sum(v for v, _ in vals)
            if abs(diff) > tol:
                cell_flags.setdefault((r, c), []).append(f"sum_check_off_by_{diff}")

    # independent second extraction must agree cell by cell
    if not check_available:
        table_flags.append("no_independent_check")
    elif check is None:
        table_flags.append("check_model_found_different_table_shape")
    else:
        rows_b = check.get("rows", [])
        for c, (ha, hb) in enumerate(zip(headers, check.get("column_headers", []))):
            if norm_label(ha) != norm_label(hb):
                cell_flags.setdefault((-1, c), []).append(f"header_disagrees:{json.dumps(hb, ensure_ascii=False)}")
        for r, (ra, rb) in enumerate(zip(rows, rows_b)):
            if norm_label(ra.get("label_path")) != norm_label(rb.get("label_path")):
                cell_flags.setdefault((r, -1), []).append(
                    f"row_label_disagrees:{json.dumps(rb.get('label_path'), ensure_ascii=False)}")
            for c, (ca, cb) in enumerate(zip(ra.get("cells", []), rb.get("cells", []))):
                if norm_raw(ca.get("raw")) != norm_raw(cb.get("raw")):
                    cell_flags.setdefault((r, c), []).append(f"check_read:{cb.get('raw')}")
                if sorted(ca.get("footnotes") or []) != sorted(cb.get("footnotes") or []):
                    cell_flags.setdefault((r, c), []).append("footnote_disagrees")
    return table_flags, cell_flags, parsed


# ----------------------------------------------------------------------------- output
CSV_FIELDS = ["document", "page", "scanned_page", "table_index", "table_title", "number_format", "unit", "scale",
              "currency", "row_index", "row_label_path", "row_label_footnotes", "is_total", "col_index",
              "column_header_path", "column_unit", "raw", "value", "cell_footnotes", "table_footnotes",
              "continues_from_previous_page", "continues_on_next_page", "flags"]


def write_document(path: Path, d: int, pages, results, page_info, out_dir: Path, review_writer):
    out_file = out_dir / f"{path.stem}.csv"
    with out_file.open("w", newline="", encoding="utf-8") as fh:
        writer = csv.DictWriter(fh, fieldnames=CSV_FIELDS)
        writer.writeheader()
        for p in sorted(pages):
            msg_a, msg_b = results.get(f"ext-{d}-{p}-a"), results.get(f"ext-{d}-{p}-b")
            out_a, out_b = tool_input(msg_a), tool_input(msg_b)
            page_flags = []
            if out_a is None:
                review_writer.writerow({"document": path.name, "page": p + 1, "flags": "primary_extraction_failed"})
                continue
            if msg_a.stop_reason == "max_tokens":
                page_flags.append("primary_output_truncated")
            if msg_b is not None and msg_b.stop_reason == "max_tokens":
                page_flags.append("check_output_truncated")
            tables_a = out_a.get("tables", [])
            tables_b = (out_b or {}).get("tables", [])
            if out_b is not None and len(tables_a) != len(tables_b):
                page_flags.append(f"table_count_{len(tables_a)}_vs_check_{len(tables_b)}")
            checks = match_tables(tables_a, tables_b) if out_b is not None else [None] * len(tables_a)

            for ti, (t, chk) in enumerate(zip(tables_a, checks)):
                table_flags, cell_flags, parsed = verify_table(t, chk, out_b is not None)
                headers = t.get("column_headers", [])
                col_units = t.get("column_units") or []
                table_fn = json.dumps(t.get("footnotes", []), ensure_ascii=False)
                for r, row in enumerate(t.get("rows", [])):
                    for c, cell in enumerate(row.get("cells", [])):
                        flags = (page_flags + table_flags + cell_flags.get((r, c), [])
                                 + cell_flags.get((r, -1), []) + cell_flags.get((-1, c), []))
                        val = parsed.get((r, c), (None, 0))[0]
                        rec = {
                            "document": path.name, "page": p + 1,
                            "scanned_page": page_info.get((d, p), {}).get("scanned", False),
                            "table_index": ti, "table_title": t.get("title", ""),
                            "number_format": t.get("number_format", ""), "unit": t.get("unit", ""),
                            "scale": t.get("scale", ""), "currency": t.get("currency") or "",
                            "row_index": r,
                            "row_label_path": json.dumps(row.get("label_path", []), ensure_ascii=False),
                            "row_label_footnotes": json.dumps(row.get("label_footnotes", []), ensure_ascii=False),
                            "is_total": bool(row.get("is_total")), "col_index": c,
                            "column_header_path": json.dumps(headers[c] if c < len(headers) else [], ensure_ascii=False),
                            "column_unit": (col_units[c] if c < len(col_units) and col_units[c] else ""),
                            "raw": cell.get("raw", ""),
                            "value": "" if val is None else format(val, "f"),
                            "cell_footnotes": json.dumps(cell.get("footnotes", []), ensure_ascii=False),
                            "table_footnotes": table_fn,
                            "continues_from_previous_page": bool(t.get("continues_from_previous_page")),
                            "continues_on_next_page": bool(t.get("continues_on_next_page")),
                            "flags": ";".join(flags),
                        }
                        writer.writerow(rec)
                        if flags:
                            review_writer.writerow(rec)
    print(f"  wrote {out_file}")


# ----------------------------------------------------------------------------- main
def process_wave(paths: list[Path], out_dir: Path, review_writer):
    docs = dict(enumerate(paths))
    print(f"Stage 1: locating table pages in {len(docs)} documents")
    table_pages = locate_table_pages(docs)
    print(f"Stage 2: extracting {sum(len(v) for v in table_pages.values())} table pages (x2 models)")
    requests, page_info = build_extract_requests(docs, table_pages)
    results = run_batches(requests)
    del requests
    print("Stage 3: verifying and writing CSV")
    for d, path in docs.items():
        write_document(path, d, table_pages[d], results, page_info, out_dir, review_writer)


def main(in_dir: str, out_dir: str):
    in_path, out_path = Path(in_dir), Path(out_dir)
    out_path.mkdir(parents=True, exist_ok=True)
    pdfs = sorted(p for p in in_path.rglob("*.pdf") if not (out_path / f"{p.stem}.csv").exists())
    review_file = out_path / "review_queue.csv"
    new_file = not review_file.exists()
    with review_file.open("a", newline="", encoding="utf-8") as fh:
        review_writer = csv.DictWriter(fh, fieldnames=CSV_FIELDS)
        if new_file:
            review_writer.writeheader()
        for i in range(0, len(pdfs), DOCS_PER_WAVE):
            print(f"=== Wave {i // DOCS_PER_WAVE + 1}: documents {i + 1}-{min(i + DOCS_PER_WAVE, len(pdfs))} of {len(pdfs)}")
            process_wave(pdfs[i:i + DOCS_PER_WAVE], out_path, review_writer)
            fh.flush()


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: python extract_tables.py <input_pdf_dir> <output_dir>")
    main(sys.argv[1], sys.argv[2])
```

Notes for integration:

- **Java side:** read each `<report>.csv` as long-format data.
  - `row_label_path` and `column_header_path` are JSON arrays, so multi-level headers and merged cells can be pivoted back exactly.
  - `value` is an exact decimal string. Parse it with `BigDecimal`. It is not scaled; apply `scale`/`unit` in Java.
  - Tables that span pages are marked with `continues_on_next_page`, so you can stitch them by page order.
- **Review workload:** analysts only open `review_queue.csv`. A cell lands there if the two models disagree, if a sum doesn't add up, if the parsed raw text conflicts with the model's value, or if a digit was illegible. Unflagged cells were read identically by two independent models and passed arithmetic checks.
- **Tuning:**
  - Raise `DOCS_PER_WAVE` if memory allows.
  - Set `CHECK_MODEL` to `PRIMARY_MODEL` if you prefer two reads by the same model. Cross-model checks usually catch more errors.
  - Run a pilot on ~50 reports and compare against hand-checked tables to calibrate how much to trust unflagged cells.

