def _resize_to_dimension_limit(image: Image.Image) -> Image.Image:
    max_dimension = max(image.width, image.height)
    if max_dimension <= 10_000:
        return image

    scale = 10_000 / max_dimension
    return image.resize(
        (max(1, int(image.width * scale)), max(1, int(image.height * scale))),
        Image.Resampling.LANCZOS,
    )


def _to_rgb(image: Image.Image) -> Image.Image:
    image = ImageOps.exif_transpose(image)

    if image.mode == "RGB":
        return image

    if image.mode in {"RGBA", "LA"} or "transparency" in image.info:
        rgba = image.convert("RGBA")
        background = Image.new("RGBA", rgba.size, "white")
        return Image.alpha_composite(background, rgba).convert("RGB")

    return image.convert("RGB")


def _encode_for_textract(image: Image.Image) -> bytes:
    image = _resize_to_dimension_limit(_to_rgb(image))

    # Try quality reduction before reducing image dimensions.
    while True:
        for quality in (92, 86, 78, 70, 62):
            output = io.BytesIO()
            image.save(
                output,
                format="JPEG",
                quality=quality,
                optimize=True,
                progressive=False,
            )
            encoded = output.getvalue()
            if len(encoded) <= MAX_TEXTRACT_BYTES:
                return encoded

        if image.width < 900 or image.height < 900:
            raise ValueError("The page cannot be encoded within Textract's size limit")

        image = image.resize(
            (int(image.width * 0.85), int(image.height * 0.85)),
            Image.Resampling.LANCZOS,
        )


def _render_pdf_page(document_bytes: bytes, page_number: int) -> bytes:
    with fitz.open(stream=document_bytes, filetype="pdf") as document:
        if document.needs_pass:
            raise ValueError("Password-protected PDFs are not supported")

        if page_number < 1 or page_number > document.page_count:
            raise ValueError(
                f"Page {page_number} is outside the PDF's 1-{document.page_count} range"
            )

        page = document.load_page(page_number - 1)
