                "titles": [value for value in titles if value],
                "footers": [value for value in footers if value],
                "headers": headers,
                "row_labels": row_labels,
                "rows": rows,
                "cells": cells,
                "merged_cells": merged_cells,
            }
        )

    return results


def _call_textract(page_bytes: bytes) -> dict[str, Any]:
    return textract.analyze_document(
