@app.post("/extract-page")
async def extract_page(
    file: UploadFile = File(...),
    page: int = Form(default=1, ge=1),
) -> dict[str, Any]:
    started = time.perf_counter()

    document_bytes = await file.read(MAX_UPLOAD_BYTES + 1)
    if not document_bytes:
        raise HTTPException(status_code=400, detail="The uploaded file is empty")

    if len(document_bytes) > MAX_UPLOAD_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"Upload exceeds the {MAX_UPLOAD_BYTES}-byte limit",
        )

    try:
        render_started = time.perf_counter()
        page_bytes = await asyncio.to_thread(
            _prepare_page,
            document_bytes,
            page,
        )
        render_ms = round((time.perf_counter() - render_started) * 1000)

        api_started = time.perf_counter()
        async with textract_slots:
            response = await asyncio.to_thread(_call_textract, page_bytes)
        provider_ms = round((time.perf_counter() - api_started) * 1000)

        tables = _parse_textract_response(response, page)

    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc

    except (ConnectTimeoutError, ReadTimeoutError) as exc:
        raise HTTPException(
            status_code=504,
            detail="Textract exceeded the interactive preview latency budget",
        ) from exc

    except ClientError as exc:
        error = exc.response.get("Error", {})
        code = error.get("Code", "TextractError")
        message = error.get("Message", "Textract request failed")

        if code in {
            "ProvisionedThroughputExceededException",
            "ThrottlingException",
        }:
            raise HTTPException(
                status_code=503,
                detail=f"{code}: {message}",
                headers={"Retry-After": "1"},
            ) from exc

        if code in {
            "UnsupportedDocumentException",
            "BadDocumentException",
            "DocumentTooLargeException",
        }:
            raise HTTPException(
                status_code=422,
                detail=f"{code}: {message}",
            ) from exc

        raise HTTPException(
            status_code=502,
            detail=f"{code}: {message}",
        ) from exc

    total_ms = round((time.perf_counter() - started) * 1000)
    request_id = response.get("ResponseMetadata", {}).get("RequestId")

    return {
        "provider": "AWS",
        "api": "Textract AnalyzeDocument",
        "page": page,
        "filename": file.filename,
        "table_count": len(tables),
        "tables": tables,
        "warnings": (
            [] if tables else ["No tables were detected on the requested page"]
        ),
        "timing_ms": {
            "render": render_ms,
            "provider": provider_ms,
            "total": total_ms,
        },
        "provider_request_id": request_id,
    }
