def _resize_to_dimension_limit(image: Image.Image) -> Image.Image:
    max_dimension = max(image.width, image.height)
    if max_dimension <= 10_000:
        return image

    scale = 10_000 / max_dimension
    return image.resize(
        (max(1, int(image.width * scale)), max(1, int(image.height * scale))),
        Image.Resampling.LANCZOS,
    )


