        "due_date": get("DueDate"),
        "purchase_order": get("PurchaseOrder"),
        "payment_terms": get("PaymentTerm"),
        "service_start_date": get("ServiceStartDate"),
        "service_end_date": get("ServiceEndDate"),
        "payment_details": get("PaymentDetails"),  # IBAN/SWIFT when present
    }

