    totals = {
        "subtotal": get("SubTotal"),
        "total_tax": get("TotalTax"),
        "total_discount": get("TotalDiscount"),
        "invoice_total": get("InvoiceTotal"),
        "amount_due": get("AmountDue"),
        "previous_unpaid_balance": get("PreviousUnpaidBalance"),
    }

