    if tax_field and tax_field.value_array:
        for i, item in enumerate(tax_field.value_array):
            obj = item.value_object or {}
            tax_details.append(
                {
                    "amount": _collect(obj, "Amount", review, f"TaxDetails[{i}].")[0],
                    "rate": _collect(obj, "Rate", review, f"TaxDetails[{i}].")[0],
                }
            )

