    line_items = []
    items_field = fields.get("Items")
    if items_field and items_field.value_array:
        for i, item in enumerate(items_field.value_array):
            obj = item.value_object or {}
            p = f"Items[{i}]."
            line_items.append(
                {
                    "line_number": i + 1,
                    "description": _collect(obj, "Description", review, p)[0],
                    "product_code": _collect(obj, "ProductCode", review, p)[0],
                    "quantity": _collect(obj, "Quantity", review, p)[0],
                    "unit": _collect(obj, "Unit", review, p)[0],
                    "unit_price": _collect(obj, "UnitPrice", review, p)[0],
                    "amount": _collect(obj, "Amount", review, p)[0],
                    "tax": _collect(obj, "Tax", review, p)[0],
                    "tax_rate": _collect(obj, "TaxRate", review, p)[0],
                    "date": _collect(obj, "Date", review, p)[0],
                    "confidence": item.confidence,
                }
            )

    # ---- Arithmetic cross-checks (catch wrong qty / decimal) -----------------
    checks: List[Dict[str, Any]] = []

    def check(name: str, expected: Optional[Decimal], actual: Optional[Decimal]):
        if expected is None or actual is None:
            checks.append({"check": name, "status": "skipped"})
            return
        ok = abs(expected - actual) <= AMOUNT_TOLERANCE
        checks.append(
