                "check": name,
                "status": "ok" if ok else "mismatch",
                "expected": str(expected),
                "actual": str(actual),
            }
        )
        if not ok:
            review.append(
                {
                    "field": name,
                    "reason": "arithmetic_mismatch",
                    "expected": str(expected),
                    "actual": str(actual),
                }
            )

