            obj = item.value_object or {}
            qty = _amount(obj.get("Quantity"))
            price = _amount(obj.get("UnitPrice"))
            amt = _amount(obj.get("Amount"))
            if qty is not None and price is not None and amt is not None:
                check(f"Items[{i}].quantity*unit_price==amount", qty * price, amt)

