    if line_amounts and all(a is not None for a in line_amounts):
        check("sum(Items.amount)==SubTotal", sum(line_amounts), _amount(fields.get("SubTotal")))

    # subtotal + tax - discount == total
    subtotal = _amount(fields.get("SubTotal"))
    tax = _amount(fields.get("TotalTax"))
    discount = _amount(fields.get("TotalDiscount")) or Decimal("0")
    total = _amount(fields.get("InvoiceTotal"))
    if subtotal is not None and tax is not None:
        check("SubTotal+TotalTax-TotalDiscount==InvoiceTotal", subtotal + tax - discount, total)

    # sum(TaxDetails.amount) == TotalTax
    if tax_field and tax_field.value_array:
        tax_amounts = [_amount((t.value_object or {}).get("Amount")) for t in tax_field.value_array]
        if tax_amounts and all(a is not None for a in tax_amounts):
            check("sum(TaxDetails.amount)==TotalTax", sum(tax_amounts), tax)

    needs_review = len(review) > 0

    return {
        "status": "needs_review" if needs_review else "ok",
        "document_confidence": doc.confidence,
        "pages": len(result.pages or []),
        "detected_languages": [
            {"locale": l.locale, "confidence": l.confidence} for l in (result.languages or [])
        ],
        "supplier": supplier,
        "customer": customer,
        "invoice": header,
        "totals": totals,
        "tax_details": tax_details,
        "line_items": line_items,
        "validation": {
            "confidence_threshold": CONFIDENCE_THRESHOLD,
            "checks": checks,
            "flags": review,
        },
    }


# --------------------------------------------------------------------------- #
# HTTP API
# --------------------------------------------------------------------------- #
@app.post("/extract")
async def extract(file: UploadFile = File(...)):
    if file.content_type not in ("application/pdf", "application/octet-stream"):
        raise HTTPException(status_code=400, detail="Only PDF files are accepted")
    data = await file.read()
    if not data:
        raise HTTPException(status_code=400, detail="Empty file")
    try:
        return extract_invoice(data)
    except HTTPException:
        raise
    except Exception as exc:  # surface Azure errors cleanly
        raise HTTPException(status_code=502, detail=f"Extraction failed: {exc}") from exc


@app.get("/health")
def health():
    return {"status": "ok"}


if __name__ == "__main__":
    import sys
    import json

    # Quick CLI test: python invoice_api.py invoice.pdf
    with open(sys.argv[1], "rb") as fh:
        print(json.dumps(extract_invoice(fh.read()), indent=2, ensure_ascii=False, default=str))
