    blocks = {
        block["Id"]: block
        for block in response.get("Blocks", [])
        if "Id" in block
    }

    tables = [
        block
        for block in response.get("Blocks", [])
        if block.get("BlockType") == "TABLE"
    ]
    tables.sort(key=_geometry_key)

    return [
        _parse_table(table, blocks, table_index=index)
        for index, table in enumerate(tables, start=1)
    ]


async def _analyze_page(data: bytes) -> dict[str, Any]:
