    page_number: int = Form(1),
) -> dict[str, Any]:
    if page_number < 1:
        raise HTTPException(status_code=422, detail="page_number must be positive")

    data = await page.read(MAX_IMAGE_BYTES + 1)
    await page.close()

    if len(data) > MAX_IMAGE_BYTES:
        raise HTTPException(status_code=413, detail="Page image exceeds 10 MB")

    if not _is_supported_image(data):
        raise HTTPException(
            status_code=415,
            detail="Render the PDF page as PNG or JPEG before submitting it",
        )

    started = time.perf_counter()

    try:
        response = await asyncio.wait_for(
            _analyze_page(data),
            timeout=PREVIEW_DEADLINE_SECONDS,
        )
    except TimeoutError as exc:
        raise HTTPException(
            status_code=504,
            detail="Table extraction exceeded the preview latency budget",
        ) from exc
    except ClientError as exc:
        error = exc.response.get("Error", {})
        code = error.get("Code", "TextractError")

        if code in {
            "UnsupportedDocumentException",
            "BadDocumentException",
            "InvalidParameterException",
        }:
            status = 422
        elif code in {
            "ThrottlingException",
            "ProvisionedThroughputExceededException",
            "LimitExceededException",
        }:
            status = 503
        else:
            status = 502

        raise HTTPException(
            status_code=status,
            detail={"provider": "aws-textract", "code": code},
        ) from exc
    except BotoCoreError as exc:
        raise HTTPException(
            status_code=502,
            detail="Unable to reach AWS Textract",
        ) from exc

    elapsed_ms = round((time.perf_counter() - started) * 1000)

    return {
        "provider": "aws-textract",
        "model": "AnalyzeDocument/TABLES",
        "page_number": page_number,
        "latency_ms": elapsed_ms,
        "request_id": response.get("ResponseMetadata", {}).get("RequestId"),
        "tables": _parse_response(response),
    }
