```python
#!/usr/bin/env python3
"""
Recommended API: Azure AI Document Intelligence, prebuilt-layout model with
ocrHighResolution enabled.

Why this API fits:
- Handles native and scanned PDFs.
- Automatically recognizes mixed English/French text.
- Returns explicit rows, columns, row/column spans, and cell types.
- High-resolution OCR improves small scanned text.
- Asynchronous processing is suitable for long annual reports.
- Available from both Python and Java.

This script:
1. Submits one PDF or HTTPS PDF URL.
2. Reconstructs every detected table as CSV.
3. Repeats merged-cell content across its span by default, since CSV has no
   native merged-cell representation.
4. Preserves raw text without parsing numbers, so parentheses, minus signs,
   currency symbols, units, and footnote references are not intentionally
   changed.
5. Writes exact span/header metadata to manifest.json.
6. Produces review_queue.csv containing only low-confidence or structurally
   suspicious cells.

Nearby table titles, units, and footnotes that are outside the detected table
are retained in the manifest as context rather than silently inserted into the
CSV.

Requirements:
    pip install requests

Environment:
    AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT=https://<resource>.cognitiveservices.azure.com
    AZURE_DOCUMENT_INTELLIGENCE_KEY=<key>

Example:
    python extract_financial_tables.py annual_report.pdf output/
    python extract_financial_tables.py "https://.../report.pdf?<sas>" output/
"""

from __future__ import annotations

import argparse
import bisect
import csv
import json
import os
import re
import sys
import time
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any
from urllib.parse import urljoin, urlparse

import requests


DEFAULT_API_VERSION = "2024-11-30"
MODEL_ID = "prebuilt-layout"
UNIT_PATTERN = re.compile(
    r"""
    (?:
        \b(?:in|en)\s+
    )?
    \b(?:
        thousand|thousands|
        million|millions|
        billion|billions|
        millier|milliers|
        milliard|milliards
    )\b
    |
    \b(?:USD|CAD|EUR|GBP|CHF)\b
    |
    [$€£]
    """,
    re.IGNORECASE | re.VERBOSE,
)


def is_http_url(value: str) -> bool:
    parsed = urlparse(value)
    return parsed.scheme in {"http", "https"} and bool(parsed.netloc)


def retry_delay(response: requests.Response | None, attempt: int) -> float:
    if response is not None:
        value = response.headers.get("Retry-After")
        if value:
            try:
                return min(float(value), 60.0)
            except ValueError:
                pass
    return min(2**attempt, 60)


def submit_document(
    endpoint: str,
    key: str,
    source: str,
    api_version: str,
    max_attempts: int = 6,
) -> str:
    analyze_url = (
        f"{endpoint.rstrip('/')}/documentintelligence/"
        f"documentModels/{MODEL_ID}:analyze"
    )
    params = {
        "api-version": api_version,
        "features": "ocrHighResolution",
    }
    request_id = str(uuid.uuid4())

    for attempt in range(max_attempts):
        response: requests.Response | None = None
        try:
            headers = {
                "Ocp-Apim-Subscription-Key": key,
                "x-ms-client-request-id": request_id,
            }

            if is_http_url(source):
                headers["Content-Type"] = "application/json"
                response = requests.post(
                    analyze_url,
                    params=params,
                    headers=headers,
                    json={"urlSource": source},
                    timeout=(30, 300),
                )
            else:
                pdf_path = Path(source)
                if not pdf_path.is_file():
                    raise FileNotFoundError(f"Input PDF does not exist: {pdf_path}")

                headers["Content-Type"] = "application/pdf"
                headers["Content-Length"] = str(pdf_path.stat().st_size)
                with pdf_path.open("rb") as pdf:
                    response = requests.post(
                        analyze_url,
                        params=params,
                        headers=headers,
                        data=pdf,
                        timeout=(30, 300),
                    )

            if response.status_code in {429, 500, 502, 503, 504}:
                if attempt + 1 == max_attempts:
                    response.raise_for_status()
                time.sleep(retry_delay(response, attempt))
                continue

            response.raise_for_status()
            operation_location = response.headers.get("Operation-Location")
            if not operation_location:
                raise RuntimeError(
                    "Azure accepted the request but returned no "
                    "Operation-Location header."
                )
            return urljoin(endpoint, operation_location)

        except requests.RequestException:
            if attempt + 1 == max_attempts:
                raise
            time.sleep(retry_delay(response, attempt))

    raise RuntimeError("Document submission failed unexpectedly.")


def wait_for_result(
    operation_url: str,
    key: str,
    timeout_seconds: int,
) -> dict[str, Any]:
    headers = {"Ocp-Apim-Subscription-Key": key}
    deadline = time.monotonic() + timeout_seconds
    attempt = 0

    while time.monotonic() < deadline:
        response = requests.get(
            operation_url,
            headers=headers,
            timeout=(30, 120),
        )

        if response.status_code in {429, 500, 502, 503, 504}:
            time.sleep(retry_delay(response, attempt))
            attempt += 1
            continue

        response.raise_for_status()
        payload = response.json()
        status = str(payload.get("status", "")).lower()

        if status == "succeeded":
            return payload
        if status in {"failed", "canceled", "cancelled"}:
            raise RuntimeError(
                "Document analysis failed:\n"
                + json.dumps(payload.get("error", payload), indent=2)
            )
        if status not in {"running", "notstarted"}:
            raise RuntimeError(f"Unexpected analysis status: {status!r}")

        time.sleep(retry_delay(response, attempt))
        attempt += 1

    raise TimeoutError(
        f"Analysis did not finish within {timeout_seconds} seconds. "
        f"Operation URL: {operation_url}"
    )


def build_word_index(
    analyze_result: dict[str, Any],
) -> tuple[list[int], list[dict[str, Any]]]:
    words: list[dict[str, Any]] = []

    for page in analyze_result.get("pages", []):
        page_number = page.get("pageNumber")
        for word in page.get("words", []):
            span = word.get("span") or {}
            start = span.get("offset")
            length = span.get("length")

            if start is None or length is None:
                continue

            words.append(
                {
                    "start": int(start),
                    "end": int(start) + int(length),
                    "confidence": word.get("confidence"),
                    "content": word.get("content", ""),
                    "page": page_number,
                }
            )

    words.sort(key=lambda item: (item["start"], item["end"]))
    starts = [word["start"] for word in words]
    return starts, words


def cell_word_confidence(
    cell: dict[str, Any],
    starts: list[int],
    words: list[dict[str, Any]],
) -> dict[str, Any]:
    matching_word_indexes: set[int] = set()

    for span in cell.get("spans", []):
        span_start = span.get("offset")
        span_length = span.get("length")
        if span_start is None or span_length is None:
            continue

        span_start = int(span_start)
        span_end = span_start + int(span_length)
        index = max(0, bisect.bisect_left(starts, span_start) - 1)

        while index < len(words) and words[index]["start"] < span_end:
            word = words[index]
            if word["end"] > span_start:
                matching_word_indexes.add(index)
            index += 1

    confidence_values: list[tuple[float, int]] = []
    for index in matching_word_indexes:
        word = words[index]
        confidence = word.get("confidence")
        if confidence is not None:
            weight = max(1, word["end"] - word["start"])
            confidence_values.append((float(confidence), weight))

    if not confidence_values:
        return {"average": None, "minimum": None, "wordCount": 0}

    total_weight = sum(weight for _, weight in confidence_values)
    weighted_average = sum(
        confidence * weight for confidence, weight in confidence_values
    ) / total_weight

    return {
        "average": round(weighted_average, 6),
        "minimum": round(min(value for value, _ in confidence_values), 6),
        "wordCount": len(confidence_values),
    }


def polygon_points(polygon: Any) -> list[tuple[float, float]]:
    if not polygon:
        return []

    if all(isinstance(value, (int, float)) for value in polygon):
        return [
            (float(polygon[index]), float(polygon[index + 1]))
            for index in range(0, len(polygon) - 1, 2)
        ]

    points: list[tuple[float, float]] = []
    for point in polygon:
        if isinstance(point, dict) and "x" in point and "y" in point:
            points.append((float(point["x"]), float(point["y"])))
    return points


def bounds(polygon: Any) -> tuple[float, float, float, float] | None:
    points = polygon_points(polygon)
    if not points:
        return None

    xs = [point[0] for point in points]
    ys = [point[1] for point in points]
    return min(xs), min(ys), max(xs), max(ys)


def horizontal_overlap_ratio(
    first: tuple[float, float, float, float],
    second: tuple[float, float, float, float],
) -> float:
    overlap = max(0.0, min(first[2], second[2]) - max(first[0], second[0]))
    denominator = min(first[2] - first[0], second[2] - second[0])
    return overlap / denominator if denominator > 0 else 0.0


def extract_table_context(
    table: dict[str, Any],
    pages_by_number: dict[int, dict[str, Any]],
    max_distance: float = 1.25,
) -> dict[str, list[dict[str, Any]]]:
    above: list[dict[str, Any]] = []
    below: list[dict[str, Any]] = []

    for region in table.get("boundingRegions", []):
        page_number = region.get("pageNumber")
        page = pages_by_number.get(page_number)
        table_bounds = bounds(region.get("polygon"))

        if not page or not table_bounds:
            continue

        for line in page.get("lines", []):
            line_bounds = bounds(line.get("polygon"))
            if not line_bounds:
                continue
            if horizontal_overlap_ratio(table_bounds, line_bounds) < 0.20:
                continue

            if line_bounds[3] <= table_bounds[1]:
                distance = table_bounds[1] - line_bounds[3]
                if distance <= max_distance:
                    above.append(
                        {
                            "page": page_number,
                            "distance": round(distance, 6),
                            "content": line.get("content", ""),
                            "polygon": line.get("polygon"),
                        }
                    )
            elif line_bounds[1] >= table_bounds[3]:
                distance = line_bounds[1] - table_bounds[3]
                if distance <= max_distance:
                    below.append(
                        {
                            "page": page_number,
                            "distance": round(distance, 6),
                            "content": line.get("content", ""),
                            "polygon": line.get("polygon"),
                        }
                    )

    # Keep nearest lines, but return them in page reading order.
    above = sorted(above, key=lambda item: item["distance"])[:6]
    below = sorted(below, key=lambda item: item["distance"])[:8]

    above.sort(key=lambda item: (item["page"], bounds(item["polygon"])[1]))
    below.sort(key=lambda item: (item["page"], bounds(item["polygon"])[1]))

    return {"above": above, "below": below}


def find_unit_candidates(
    table: dict[str, Any],
    context: dict[str, list[dict[str, Any]]],
) -> list[str]:
    candidates: list[str] = []
    seen: set[str] = set()

    texts = [item["content"] for item in context["above"]]
    texts.extend(cell.get("content", "") for cell in table.get("cells", []))

    for text in texts:
        for match in UNIT_PATTERN.finditer(text):
            candidate = match.group(0)
            normalized = candidate.casefold()
            if normalized not in seen:
                seen.add(normalized)
                candidates.append(candidate)

    return candidates


def page_numbers_for_table(table: dict[str, Any]) -> list[int]:
    return sorted(
        {
            int(region["pageNumber"])
            for region in table.get("boundingRegions", [])
            if region.get("pageNumber") is not None
        }
    )


def safe_page_suffix(page_numbers: list[int]) -> str:
    if not page_numbers:
        return "unknown"
    if len(page_numbers) == 1:
        return str(page_numbers[0])
    return f"{page_numbers[0]}-{page_numbers[-1]}"


def reconstruct_table(
    table: dict[str, Any],
    merged_mode: str,
) -> tuple[list[list[str]], list[str]]:
    row_count = int(table.get("rowCount", 0))
    column_count = int(table.get("columnCount", 0))
    grid = [["" for _ in range(column_count)] for _ in range(row_count)]
    owners: list[list[int | None]] = [
        [None for _ in range(column_count)] for _ in range(row_count)
    ]
    structural_issues: list[str] = []

    for cell_number, cell in enumerate(table.get("cells", [])):
        row_index = int(cell.get("rowIndex", 0))
        column_index = int(cell.get("columnIndex", 0))
        row_span = max(1, int(cell.get("rowSpan", 1)))
        column_span = max(1, int(cell.get("columnSpan", 1)))
        content = cell.get("content") or ""

        if (
            row_index < 0
            or column_index < 0
            or row_index + row_span > row_count
            or column_index + column_span > column_count
        ):
            structural_issues.append(
                f"Cell {cell_number} extends outside the declared table dimensions."
            )
            continue

        for row in range(row_index, row_index + row_span):
            for column in range(column_index, column_index + column_span):
                if owners[row][column] is not None:
                    structural_issues.append(
                        f"Cells {owners[row][column]} and {cell_number} overlap at "
                        f"row {row + 1}, column {column + 1}."
                    )
                    continue

                owners[row][column] = cell_number
                if merged_mode == "repeat" or (
                    row == row_index and column == column_index
                ):
                    grid[row][column] = content

    return grid, structural_issues


def write_csv(path: Path, rows: list[list[str]]) -> None:
    # UTF-8 BOM helps Excel open French characters correctly.
    with path.open("w", encoding="utf-8-sig", newline="") as output:
        writer = csv.writer(output, quoting=csv.QUOTE_MINIMAL, lineterminator="\n")
        writer.writerows(rows)


def extract_tables(
    payload: dict[str, Any],
    source: str,
    output_directory: Path,
    merged_mode: str,
    minimum_average_confidence: float,
    minimum_word_confidence: float,
    review_missing_confidence: bool,
) -> dict[str, Any]:
    analyze_result = payload.get("analyzeResult") or {}
    tables = analyze_result.get("tables", [])
    pages_by_number = {
        int(page["pageNumber"]): page
        for page in analyze_result.get("pages", [])
        if page.get("pageNumber") is not None
    }
    word_starts, words = build_word_index(analyze_result)

    output_directory.mkdir(parents=True, exist_ok=True)
    manifest_tables: list[dict[str, Any]] = []
    review_rows: list[dict[str, Any]] = []

    for table_number, table in enumerate(tables, start=1):
        page_numbers = page_numbers_for_table(table)
        filename = (
            f"table_{table_number:04d}_pages_"
            f"{safe_page_suffix(page_numbers)}.csv"
        )
        csv_path = output_directory / filename

        grid, structural_issues = reconstruct_table(table, merged_mode)
        write_csv(csv_path, grid)

        context = extract_table_context(table, pages_by_number)
        unit_candidates = find_unit_candidates(table, context)
        cell_metadata: list[dict[str, Any]] = []
        header_rows: set[int] = set()
        merged_cell_count = 0
        low_confidence_count = 0

        for cell_number, cell in enumerate(table.get("cells", [])):
            row_index = int(cell.get("rowIndex", 0))
            column_index = int(cell.get("columnIndex", 0))
            row_span = max(1, int(cell.get("rowSpan", 1)))
            column_span = max(1, int(cell.get("columnSpan", 1)))
            content = cell.get("content") or ""
            kind = cell.get("kind", "content")
            confidence = cell_word_confidence(cell, word_starts, words)
            issues: list[str] = []

            if kind in {"columnHeader", "stubHead"}:
                header_rows.add(row_index)

            if row_span > 1 or column_span > 1:
                merged_cell_count += 1

            if content:
                average = confidence["average"]
                minimum = confidence["minimum"]

                if average is None:
                    if review_missing_confidence:
                        issues.append("No word-level confidence was available.")
                else:
                    if average < minimum_average_confidence:
                        issues.append(
                            f"Average OCR confidence {average:.3f} is below "
                            f"{minimum_average_confidence:.3f}."
                        )
                    if minimum < minimum_word_confidence:
                        issues.append(
                            f"Minimum word confidence {minimum:.3f} is below "
                            f"{minimum_word_confidence:.3f}."
                        )

            if issues:
                low_confidence_count += 1
                review_rows.append(
                    {
                        "table": table_number,
                        "csv_file": filename,
                        "pages": ",".join(map(str, page_numbers)),
                        "row": row_index + 1,
                        "column": column_index + 1,
                        "row_span": row_span,
                        "column_span": column_span,
                        "kind": kind,
                        "average_confidence": confidence["average"],
                        "minimum_confidence": confidence["minimum"],
                        "content": content,
                        "reasons": " | ".join(issues),
                    }
                )

            cell_metadata.append(
                {
                    "cellNumber": cell_number,
                    "rowIndex": row_index,
                    "columnIndex": column_index,
                    "rowSpan": row_span,
                    "columnSpan": column_span,
                    "kind": kind,
                    "content": content,
                    "confidence": confidence,
                    "issues": issues,
                    "spans": cell.get("spans", []),
                    "boundingRegions": cell.get("boundingRegions", []),
                }
            )

        if structural_issues:
            review_rows.append(
                {
                    "table": table_number,
                    "csv_file": filename,
                    "pages": ",".join(map(str, page_numbers)),
                    "row": "",
                    "column": "",
                    "row_span": "",
                    "column_span": "",
                    "kind": "table",
                    "average_confidence": "",
                    "minimum_confidence": "",
                    "content": "",
                    "reasons": " | ".join(structural_issues),
                }
            )

        manifest_tables.append(
            {
                "tableNumber": table_number,
                "csvFile": filename,
                "pages": page_numbers,
                "rowCount": int(table.get("rowCount", 0)),
                "columnCount": int(table.get("columnCount", 0)),
                "headerRowsZeroBased": sorted(header_rows),
                "mergedCellCount": merged_cell_count,
                "mergedCellCsvMode": merged_mode,
                "lowConfidenceCellCount": low_confidence_count,
                "reviewRequired": bool(low_confidence_count or structural_issues),
                "structuralIssues": structural_issues,
                "unitCandidates": unit_candidates,
                "context": context,
                "boundingRegions": table.get("boundingRegions", []),
                "spans": table.get("spans", []),
                "cells": cell_metadata,
            }
        )

    review_path = output_directory / "review_queue.csv"
    review_fields = [
        "table",
        "csv_file",
        "pages",
        "row",
        "column",
        "row_span",
        "column_span",
        "kind",
        "average_confidence",
        "minimum_confidence",
        "content",
        "reasons",
    ]
    with review_path.open("w", encoding="utf-8-sig", newline="") as output:
        writer = csv.DictWriter(
            output,
            fieldnames=review_fields,
            quoting=csv.QUOTE_MINIMAL,
            lineterminator="\n",
        )
        writer.writeheader()
        writer.writerows(review_rows)

    return {
        "recommendedApi": "Azure AI Document Intelligence",
        "model": analyze_result.get("modelId", MODEL_ID),
        "apiVersion": analyze_result.get("apiVersion"),
        "feature": "ocrHighResolution",
        "source": source,
        "createdAt": datetime.now(timezone.utc).isoformat(),
        "tableCount": len(manifest_tables),
        "reviewItemCount": len(review_rows),
        "confidenceThresholds": {
            "minimumAverage": minimum_average_confidence,
            "minimumWord": minimum_word_confidence,
            "reviewMissingConfidence": review_missing_confidence,
        },
        "notes": [
            "CSV cannot represent merged cells natively; consult each cell's "
            "rowSpan and columnSpan in this manifest.",
            "Raw cell text is not converted to numeric values.",
            "Nearby titles, units, and possible footnotes are retained under context.",
            "No OCR service can guarantee zero transcription or placement errors; "
            "review_queue.csv provides a targeted fail-safe review list.",
        ],
        "tables": manifest_tables,
    }


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Extract financial tables from a PDF using Azure Document Intelligence."
    )
    parser.add_argument(
        "source",
        help="Local PDF path or an HTTPS URL accessible to Azure.",
    )
    parser.add_argument(
        "output_directory",
        type=Path,
        help="Directory for CSV tables, manifest.json, and review_queue.csv.",
    )
    parser.add_argument(
        "--endpoint",
        default=os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"),
        help="Azure endpoint; defaults to AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT.",
    )
    parser.add_argument(
        "--key",
        default=os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY"),
        help="Azure key; defaults to AZURE_DOCUMENT_INTELLIGENCE_KEY.",
    )
    parser.add_argument(
        "--api-version",
        default=DEFAULT_API_VERSION,
    )
    parser.add_argument(
        "--merged-mode",
        choices=("repeat", "anchor"),
        default="repeat",
        help=(
            "'repeat' copies merged content into all covered CSV cells; "
            "'anchor' writes it only in the top-left cell. Exact spans are "
            "always retained in manifest.json."
        ),
    )
    parser.add_argument(
        "--minimum-average-confidence",
        type=float,
        default=0.90,
    )
    parser.add_argument(
        "--minimum-word-confidence",
        type=float,
        default=0.80,
    )
    parser.add_argument(
        "--review-missing-confidence",
        action="store_true",
        help="Flag non-empty cells that have no word-level confidence.",
    )
    parser.add_argument(
        "--timeout-seconds",
        type=int,
        default=7200,
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    if not args.endpoint:
        print(
            "Missing Azure endpoint. Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT "
            "or pass --endpoint.",
            file=sys.stderr,
        )
        return 2
    if not args.key:
        print(
            "Missing Azure key. Set AZURE_DOCUMENT_INTELLIGENCE_KEY or pass --key.",
            file=sys.stderr,
        )
        return 2

    operation_url = submit_document(
        endpoint=args.endpoint,
        key=args.key,
        source=args.source,
        api_version=args.api_version,
    )
    payload = wait_for_result(
        operation_url=operation_url,
        key=args.key,
        timeout_seconds=args.timeout_seconds,
    )
    manifest = extract_tables(
        payload=payload,
        source=args.source,
        output_directory=args.output_directory,
        merged_mode=args.merged_mode,
        minimum_average_confidence=args.minimum_average_confidence,
        minimum_word_confidence=args.minimum_word_confidence,
        review_missing_confidence=args.review_missing_confidence,
    )

    manifest_path = args.output_directory / "manifest.json"
    with manifest_path.open("w", encoding="utf-8") as output:
        json.dump(manifest, output, ensure_ascii=False, indent=2)

    print(
        json.dumps(
            {
                "outputDirectory": str(args.output_directory.resolve()),
                "tablesExtracted": manifest["tableCount"],
                "reviewItems": manifest["reviewItemCount"],
                "manifest": str(manifest_path.resolve()),
            },
            indent=2,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
