"""
Per-page financial table extraction for a live preview UI.

API:    Anthropic Claude API, model "claude-haiku-4-5" (fastest Claude model)
Design: - Split uploads into single pages (small requests -> low latency)
        - Stream the response so the UI can render rows as they arrive
        - Constrain output with a JSON schema (structured outputs) so the
          TypeScript backend always receives parseable, typed JSON
        - Cell values are kept as the literal strings shown on the page;
          the backend can parse "(1,234)" -> -1234 for export.

pip install anthropic pypdf
export ANTHROPIC_API_KEY=...
"""

import base64
import io
import json
import sys
import time
from typing import Callable, Iterator, Optional

import anthropic
from pypdf import PdfReader, PdfWriter

MODEL = "claude-haiku-4-5"

client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY

# Compact schema: short output = faster generation = faster preview.
TABLE_SCHEMA = {
    "type": "object",
    "properties": {
        "tables": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "title": {"type": "string"},
                    "column_headers": {
                        "type": "array",
                        "items": {"type": "string"},
                    },
                    "rows": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "label": {"type": "string"},
                                "cells": {
                                    "type": "array",
                                    "items": {"type": "string"},
                                },
                            },
                            "required": ["label", "cells"],
                            "additionalProperties": False,
                        },
                    },
                },
                "required": ["title", "column_headers", "rows"],
                "additionalProperties": False,
            },
        }
    },
    "required": ["tables"],
    "additionalProperties": False,
}

SYSTEM_PROMPT = (
    "You extract financial tables from a single document page. "
    "Return every table on the page (usually 1-3). For each table:\n"
    "- title: the table caption/heading, or \"\" if none.\n"
    "- column_headers: header text for each value column, excluding the "
    "row-label column. Flatten multi-level headers with ' / ' "
    "(e.g. '2024 / Q3').\n"
    "- rows: one entry per row, in order. label = row label text "
    "(keep indentation meaning by including parent context only if the "
    "label is ambiguous). cells = values aligned 1:1 with column_headers.\n"
    "Copy values exactly as printed (keep parentheses, commas, %, currency "
    "symbols, dashes). Use \"\" for empty cells. Section header rows with "
    "no values get cells of empty strings. Do not compute or infer numbers. "
    "If the page has no tables, return {\"tables\": []}."
)


def split_pdf_pages(pdf_bytes: bytes) -> list[bytes]:
    """Split a PDF into single-page PDFs (one API call per page)."""
    reader = PdfReader(io.BytesIO(pdf_bytes))
    pages = []
    for page in reader.pages:
        writer = PdfWriter()
        writer.add_page(page)
        buf = io.BytesIO()
        writer.write(buf)
        pages.append(buf.getvalue())
    return pages


def _request_kwargs(page_pdf: bytes) -> dict:
    return dict(
        model=MODEL,
        max_tokens=4096,
        temperature=0,
        system=SYSTEM_PROMPT,
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": "document",
                        "source": {
                            "type": "base64",
                            "media_type": "application/pdf",
                            "data": base64.standard_b64encode(page_pdf).decode(),
                        },
                    },
                    {"type": "text", "text": "Extract the tables on this page."},
                ],
            }
        ],
        output_config={
            "format": {"type": "json_schema", "schema": TABLE_SCHEMA}
        },
    )


def extract_page_streaming(
    page_pdf: bytes,
    on_delta: Optional[Callable[[str], None]] = None,
) -> dict:
    """
    Extract tables from one page, streaming JSON text as it is generated.

    on_delta receives raw JSON text chunks; forward these to the browser
    (e.g. via Server-Sent Events) and render with a partial-JSON parser
    so rows appear progressively instead of after the full response.
    Returns the final parsed JSON.
    """
    with client.messages.stream(**_request_kwargs(page_pdf)) as stream:
        for text in stream.text_stream:
            if on_delta:
                on_delta(text)
        final = stream.get_final_message()

    if final.stop_reason == "max_tokens":
        raise RuntimeError("Output truncated; page has unusually large tables.")

    text = "".join(b.text for b in final.content if b.type == "text")
    return json.loads(text)


def extract_document(
    pdf_bytes: bytes,
    on_delta: Optional[Callable[[int, str], None]] = None,
) -> Iterator[dict]:
    """Yield per-page results so the UI can show page 1 while page 2 runs."""
    for i, page in enumerate(split_pdf_pages(pdf_bytes), start=1):
        t0 = time.perf_counter()
        try:
            result = extract_page_streaming(
                page,
                on_delta=(lambda d, i=i: on_delta(i, d)) if on_delta else None,
            )
            yield {
                "page": i,
                "ok": True,
                "seconds": round(time.perf_counter() - t0, 2),
                **result,
            }
        except (anthropic.APIError, json.JSONDecodeError, RuntimeError) as e:
            # Analysts verify anyway; surface the error and let them retry/edit.
            yield {"page": i, "ok": False, "error": str(e), "tables": []}


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: python extract_tables.py statement.pdf")
        sys.exit(1)

    with open(sys.argv[1], "rb") as f:
        data = f.read()

    first_token_at: dict[int, float] = {}
    start = time.perf_counter()

    def show_progress(page: int, delta: str) -> None:
        if page not in first_token_at:
            first_token_at[page] = time.perf_counter() - start
            print(f"[page {page}] first output after {first_token_at[page]:.2f}s",
                  file=sys.stderr)

    for page_result in extract_document(data, on_delta=show_progress):
        print(json.dumps(page_result, indent=2))
```

