"""
Recommendation: Azure AI Document Intelligence, prebuilt "invoice" model.

Why this one for your constraints:
- Built-in deskew / rotation handling, and the OCR layer is tuned for faded scans and
  stamp-overlapped text (it still returns the field and a lower confidence, instead of silently guessing).
- Native EN + DE invoice layouts (Rechnung/USt-ID/MwSt/Netto/Brutto are recognised as fields, not just text).
- Returns per-field confidence AND typed values (currency amounts are parsed into number + currency code),
  which is what lets you catch a wrong decimal automatically.
- Full line-item table extraction (description, qty, unit price, tax, amount).
- Async queue, so 25k/month is trivial and you can afford to pick the slow/accurate path.

The code below:
1. Submits the PDF (any page count) to the prebuilt-invoice model with high-res OCR enabled.
2. Builds a clean JSON document: supplier, invoice meta, taxes, totals, line items.
3. Runs arithmetic cross-checks (line items -> subtotal -> tax -> total) and confidence gates.
4. Marks the invoice "needs_review" with explicit reasons instead of letting a bad number through.

pip install azure-ai-documentintelligence
env: AZURE_DI_ENDPOINT, AZURE_DI_KEY
"""

import os
import json
import sys
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import (
    AnalyzeDocumentRequest,
    DocumentAnalysisFeature,
)

ENDPOINT = os.environ["AZURE_DI_ENDPOINT"]
KEY = os.environ["AZURE_DI_KEY"]

# Anything below this confidence on a money/quantity field goes to human review.
MONEY_CONFIDENCE_THRESHOLD = 0.90
TEXT_CONFIDENCE_THRESHOLD = 0.75
# Allowed rounding slack when cross-checking sums (per currency unit).
ARITHMETIC_TOLERANCE = Decimal("0.02")

client = DocumentIntelligenceClient(ENDPOINT, AzureKeyCredential(KEY))


# ---------------------------------------------------------------------------
# Helpers for pulling typed values + confidence out of the Azure result
# ---------------------------------------------------------------------------
def _dec(x: Any) -> Optional[Decimal]:
    if x is None:
        return None
    try:
        return Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except Exception:
        return None


def _field(fields: dict, name: str) -> dict:
    """Return {'value': ..., 'confidence': ..., 'text': ...} for a field, or empty."""
    f = fields.get(name)
    if f is None:
        return {"value": None, "confidence": None, "text": None}

    ftype = f.get("type")
    if ftype == "currency":
        cur = f.get("valueCurrency") or {}
        value = {"amount": _dec(cur.get("amount")), "currency": cur.get("currencyCode")}
    elif ftype == "number":
        value = f.get("valueNumber")
    elif ftype == "integer":
        value = f.get("valueInteger")
    elif ftype == "date":
        value = f.get("valueDate")
    elif ftype == "address":
        a = f.get("valueAddress") or {}
        value = {
            "street": a.get("streetAddress"),
            "house_number": a.get("houseNumber"),
            "postal_code": a.get("postalCode"),
            "city": a.get("city"),
            "state": a.get("state"),
            "country": a.get("countryRegion"),
            "raw": f.get("content"),
        }
    else:
        value = f.get("valueString") or f.get("content")

    return {"value": value, "confidence": f.get("confidence"), "text": f.get("content")}


def _money(fields: dict, name: str) -> dict:
    f = _field(fields, name)
    v = f["value"] or {}
    return {
        "amount": v.get("amount") if isinstance(v, dict) else None,
        "currency": v.get("currency") if isinstance(v, dict) else None,
        "confidence": f["confidence"],
        "text": f["text"],
    }


# ---------------------------------------------------------------------------
# Main extraction
# ---------------------------------------------------------------------------
def extract_invoice(pdf_path: str) -> dict:
    with open(pdf_path, "rb") as fh:
        pdf_bytes = fh.read()

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=AnalyzeDocumentRequest(bytes_source=pdf_bytes),
        # Slower, more expensive, noticeably better on faded/skewed scans.
        features=[DocumentAnalysisFeature.OCR_HIGH_RESOLUTION],
        # Not strictly needed, Azure autodetects; set if you want to force.
        # locale="de-DE",
    )
    result = poller.result()
    raw = result.as_dict()

    docs = raw.get("documents") or []
    if not docs:
        return {
            "source_file": os.path.basename(pdf_path),
            "status": "needs_review",
            "review_reasons": ["No invoice detected in document"],
            "data": None,
        }

    doc = docs[0]
    fields = doc.get("fields") or {}
    review_reasons: list[str] = []

    # ----- Supplier --------------------------------------------------------
    supplier = {
        "name": _field(fields, "VendorName"),
        "address": _field(fields, "VendorAddress"),
        "address_recipient": _field(fields, "VendorAddressRecipient"),
        "tax_id": _field(fields, "VendorTaxId"),  # USt-IdNr / VAT number
    }

    # ----- Customer (useful for matching to your entity) ------------------
    customer = {
        "name": _field(fields, "CustomerName"),
        "address": _field(fields, "CustomerAddress"),
        "customer_id": _field(fields, "CustomerId"),
        "tax_id": _field(fields, "CustomerTaxId"),
    }

    # ----- Invoice meta ----------------------------------------------------
    invoice = {
        "invoice_number": _field(fields, "InvoiceId"),
        "invoice_date": _field(fields, "InvoiceDate"),
        "due_date": _field(fields, "DueDate"),
        "purchase_order": _field(fields, "PurchaseOrder"),
        "payment_terms": _field(fields, "PaymentTerm"),
        "service_start": _field(fields, "ServiceStartDate"),
        "service_end": _field(fields, "ServiceEndDate"),
        "payment_details": [
            {
                "iban": _field(p.get("valueObject", {}), "IBAN")["value"],
                "swift": _field(p.get("valueObject", {}), "SWIFT")["value"],
                "bank_account": _field(p.get("valueObject", {}), "BankAccountNumber")["value"],
            }
            for p in (fields.get("PaymentDetails", {}).get("valueArray") or [])
        ],
    }

    # ----- Totals ----------------------------------------------------------
    totals = {
        "subtotal": _money(fields, "SubTotal"),
        "total_tax": _money(fields, "TotalTax"),
        "total_discount": _money(fields, "TotalDiscount"),
        "invoice_total": _money(fields, "InvoiceTotal"),
        "amount_due": _money(fields, "AmountDue"),
        "previous_unpaid_balance": _money(fields, "PreviousUnpaidBalance"),
    }

    # ----- Tax breakdown (per rate, e.g. 19% / 7% MwSt) ---------------------
    taxes = []
    for t in fields.get("TaxDetails", {}).get("valueArray") or []:
        tf = t.get("valueObject") or {}
        taxes.append(
            {
                "amount": _money(tf, "Amount"),
                "rate": _field(tf, "Rate"),
                "net_amount": _money(tf, "NetAmount"),
                "confidence": t.get("confidence"),
            }
        )

    # ----- Line items ------------------------------------------------------
    line_items = []
    for idx, item in enumerate(fields.get("Items", {}).get("valueArray") or []):
        lf = item.get("valueObject") or {}
        li = {
            "row": idx + 1,
            "description": _field(lf, "Description"),
            "product_code": _field(lf, "ProductCode"),
            "quantity": _field(lf, "Quantity"),
            "unit": _field(lf, "Unit"),
            "unit_price": _money(lf, "UnitPrice"),
            "tax": _money(lf, "Tax"),
            "tax_rate": _field(lf, "TaxRate"),
            "amount": _money(lf, "Amount"),
            "date": _field(lf, "Date"),
            "row_confidence": item.get("confidence"),
        }
        line_items.append(li)

    # ---------------------------------------------------------------------
    # Validation gates: this is what stops a wrong decimal from being paid
    # ---------------------------------------------------------------------

    # 1) Confidence gates on money fields
    for name, m in totals.items():
        if m["amount"] is not None and (m["confidence"] or 0) < MONEY_CONFIDENCE_THRESHOLD:
            review_reasons.append(f"Low confidence on {name}: {m['confidence']:.2f} ('{m['text']}')")

    for key in ("invoice_number", "invoice_date"):
        f = invoice[key]
        if f["value"] is None:
            review_reasons.append(f"Missing {key}")
        elif (f["confidence"] or 0) < TEXT_CONFIDENCE_THRESHOLD:
            review_reasons.append(f"Low confidence on {key}: {f['confidence']:.2f}")

    if supplier["name"]["value"] is None:
        review_reasons.append("Missing supplier name")

    # 2) Per-line arithmetic: qty * unit_price == amount
    for li in line_items:
        qty = li["quantity"]["value"]
        up = li["unit_price"]["amount"]
        amt = li["amount"]["amount"]
        if amt is None:
            review_reasons.append(f"Line {li['row']}: no amount extracted")
            continue
        if (li["amount"]["confidence"] or 0) < MONEY_CONFIDENCE_THRESHOLD:
            review_reasons.append(f"Line {li['row']}: low confidence on amount ({li['amount']['text']})")
        if qty is not None and up is not None:
            expected = _dec(Decimal(str(qty)) * up)
            if expected is not None and abs(expected - amt) > ARITHMETIC_TOLERANCE:
                review_reasons.append(
                    f"Line {li['row']}: qty*unit_price={expected} but amount={amt} (possible decimal/qty error)"
                )

    # 3) Sum of line items vs subtotal (or vs total if no subtotal/no tax)
    line_sum = _dec(sum((li["amount"]["amount"] for li in line_items if li["amount"]["amount"] is not None), Decimal(0)))
    subtotal = totals["subtotal"]["amount"]
    total_tax = totals["total_tax"]["amount"]
    grand = totals["invoice_total"]["amount"] or totals["amount_due"]["amount"]

    if line_items:
        if subtotal is not None:
            if abs(line_sum - subtotal) > ARITHMETIC_TOLERANCE:
                review_reasons.append(f"Line items sum {line_sum} != subtotal {subtotal}")
        elif grand is not None and (total_tax is None or total_tax == 0):
            if abs(line_sum - grand) > ARITHMETIC_TOLERANCE:
                review_reasons.append(f"Line items sum {line_sum} != invoice total {grand}")
    else:
        review_reasons.append("No line items extracted")

    # 4) subtotal + tax == total
    if subtotal is not None and total_tax is not None and grand is not None:
        if abs((subtotal + total_tax) - grand) > ARITHMETIC_TOLERANCE:
            review_reasons.append(f"subtotal {subtotal} + tax {total_tax} != total {grand}")

    # 5) Tax breakdown rows should add up to total tax
    if taxes and total_tax is not None:
        tax_sum = _dec(sum((t["amount"]["amount"] for t in taxes if t["amount"]["amount"] is not None), Decimal(0)))
        if abs(tax_sum - total_tax) > ARITHMETIC_TOLERANCE:
            review_reasons.append(f"Tax breakdown sum {tax_sum} != total tax {total_tax}")

    # 6) Nothing to pay at all -> definitely review
    if grand is None:
        review_reasons.append("No invoice total / amount due extracted")

    # 7) Currency consistency
    currencies = {
        m["currency"] for m in totals.values() if m["currency"]
    } | {li["amount"]["currency"] for li in line_items if li["amount"]["currency"]}
    if len(currencies) > 1:
        review_reasons.append(f"Mixed currencies detected: {sorted(currencies)}")

    status = "needs_review" if review_reasons else "ok"

    return {
        "source_file": os.path.basename(pdf_path),
        "status": status,
        "review_reasons": review_reasons,
        "document_confidence": doc.get("confidence"),
        "pages": len(raw.get("pages") or []),
