        "data": {
            "supplier": supplier,
            "customer": customer,
            "invoice": invoice,
            "totals": totals,
            "taxes": taxes,
            "line_items": line_items,
            "line_items_sum": line_sum,
            "currency": next(iter(currencies), None),
