**Recommendation:** Claude Haiku via the Message Batches API. Cheapest capable model, batch gives 50% off, and the "run overnight, retries OK" constraint fits batch exactly. Two cost tricks: (1) for the ~95% digital PDFs, pull text locally with `pypdf` and send text only (≈1–2k tokens/page); (2) only send the actual PDF bytes for scans that yield no text layer. Rough math: 1.2M pages × ~1.5k tokens × $0.40/M (batch input) ≈ $700–900/month plus negligible output — well inside $4,800 even if every page went as native PDF. No OCR product, no Document AI tiers, no large model needed since amounts are validated downstream.

```python
"""
Invoice archive extraction pipeline.
- Digital PDFs: local text extraction (pypdf) -> text-only prompt
- Scans (no text layer): send PDF natively as a document block
- Submits in Message Batches (50% off), polls, writes JSONL results
- Retries failed/expired items in a follow-up batch

pip install anthropic pypdf
export ANTHROPIC_API_KEY=...
"""

import base64
import json
import os
import sys
import time
from pathlib import Path

import anthropic
from pypdf import PdfReader

MODEL = "claude-haiku-4-5"
BATCH_SIZE = 10_000            # requests per batch (API limit 100k / 256MB)
MIN_CHARS_PER_PAGE = 200       # below this we treat the PDF as a scan
POLL_SECONDS = 120
MAX_ATTEMPTS = 3

SYSTEM = (
    "You extract fields from supplier invoices (English or Italian). "
    "Return ONLY via the record_invoice tool. If a field is not present, use null."
)

TOOL = {
    "name": "record_invoice",
    "description": "Record the extracted invoice header fields.",
    "input_schema": {
        "type": "object",
        "properties": {
            "supplier_id": {
                "type": ["string", "null"],
                "description": "Supplier identifier: VAT number / Partita IVA / Codice Fiscale "
                               "/ supplier code as printed. Prefer the VAT number.",
            },
            "invoice_date": {
                "type": ["string", "null"],
                "description": "Invoice date (data fattura) in ISO 8601 YYYY-MM-DD.",
            },
            "currency": {
                "type": ["string", "null"],
                "description": "ISO 4217 code, e.g. EUR, USD, GBP.",
            },
            "total": {
                "type": ["number", "null"],
                "description": "Grand total including tax (Totale fattura / Totale da pagare). "
                               "Plain decimal, no thousands separators.",
            },
        },
        "required": ["supplier_id", "invoice_date", "currency", "total"],
    },
}

client = anthropic.Anthropic()


def build_request(pdf_path: Path) -> dict:
    """Build one batch request; text-only for digital PDFs, document block for scans."""
    reader = PdfReader(str(pdf_path))
    pages_text = [(p.extract_text() or "").strip() for p in reader.pages]
    text = "\n\n".join(pages_text)
    is_scan = len(text) < MIN_CHARS_PER_PAGE * len(reader.pages)

    if is_scan:
        content = [
            {
                "type": "document",
                "source": {
                    "type": "base64",
                    "media_type": "application/pdf",
                    "data": base64.b64encode(pdf_path.read_bytes()).decode(),
                },
            },
            {"type": "text", "text": "Extract the invoice fields."},
        ]
    else:
        content = [{"type": "text", "text": f"Invoice text:\n\n{text}\n\nExtract the invoice fields."}]

    return {
        "custom_id": pdf_path.stem[:64],
        "params": {
            "model": MODEL,
            "max_tokens": 200,
            "system": SYSTEM,
            "tools": [TOOL],
            "tool_choice": {"type": "tool", "name": "record_invoice"},
            "messages": [{"role": "user", "content": content}],
        },
    }


def submit_batch(requests: list[dict]) -> str:
    batch = client.messages.batches.create(requests=requests)
    print(f"submitted batch {batch.id} with {len(requests)} requests")
    return batch.id


def wait_for_batch(batch_id: str):
    while True:
        b = client.messages.batches.retrieve(batch_id)
        c = b.request_counts
        print(f"{batch_id}: {b.processing_status} "
              f"(ok={c.succeeded} err={c.errored} exp={c.expired} proc={c.processing})")
        if b.processing_status == "ended":
            return
        time.sleep(POLL_SECONDS)


def collect_results(batch_id: str, out_file, failed: set[str]):
    for r in client.messages.batches.results(batch_id):
        cid = r.custom_id
        if r.result.type == "succeeded":
            msg = r.result.message
            tool_use = next((blk for blk in msg.content if blk.type == "tool_use"), None)
            if tool_use is None:
                failed.add(cid)
                continue
            record = {"id": cid, **tool_use.input}
            out_file.write(json.dumps(record, ensure_ascii=False) + "\n")
        else:
            # errored / expired / canceled -> retry later
            failed.add(cid)


def run(input_dir: str, output_path: str):
    pdfs = {p.stem[:64]: p for p in sorted(Path(input_dir).glob("*.pdf"))}
    pending = set(pdfs)
    done_ids = set()

    if os.path.exists(output_path):  # resume support
        with open(output_path) as f:
            done_ids = {json.loads(line)["id"] for line in f if line.strip()}
        pending -= done_ids

    with open(output_path, "a", encoding="utf-8") as out:
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if not pending:
                break
            print(f"attempt {attempt}: {len(pending)} invoices")
            ids = sorted(pending)
            failed: set[str] = set()

            for i in range(0, len(ids), BATCH_SIZE):
                chunk = ids[i:i + BATCH_SIZE]
                reqs = []
                for cid in chunk:
                    try:
                        reqs.append(build_request(pdfs[cid]))
                    except Exception as e:
                        print(f"skip {cid}: unreadable PDF ({e})", file=sys.stderr)
                        out.write(json.dumps({"id": cid, "error": str(e)}) + "\n")
                if not reqs:
                    continue
                bid = submit_batch(reqs)
                wait_for_batch(bid)
                collect_results(bid, out, failed)
                out.flush()

            pending = failed
            if pending:
                time.sleep(60)

    if pending:
        print(f"gave up on {len(pending)} invoices after {MAX_ATTEMPTS} attempts:", sorted(pending))


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("usage: python extract_invoices.py <pdf_dir> <output.jsonl>")
        sys.exit(1)
    run(sys.argv[1], sys.argv[2])
```

Notes:
- Output is one JSON line per invoice: `{"id", "supplier_id", "invoice_date", "currency", "total"}`; `null` where the model couldn't find a field, so your accounting validation can flag them.
- `custom_id` is the PDF filename stem — tie it to your document key before running.
- Resumable: rerunning skips IDs already in the output file.
- If you later see scans dominating cost, lower `MIN_CHARS_PER_PAGE` or pre-rasterise scans at ~150 dpi JPEG and send images instead of full PDFs.

