            },
        },
        "required": ["invoice_number", "supplier", "date", "total", "currency"],
        "additionalProperties": False,
    },
}

PROMPT = (
    "Extract the invoice number, supplier (the issuer/seller), invoice date and "
    "grand total from this invoice. Use null for any field that is not present; "
    "do not guess. Record the result with the record_invoice tool."
)

MEDIA_TYPES = {
    ".pdf": ("document", "application/pdf"),
    ".png": ("image", "image/png"),
    ".jpg": ("image", "image/jpeg"),
    ".jpeg": ("image", "image/jpeg"),
}

client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY


def extract_invoice(path: str) -> dict:
    file_path = Path(path)
    suffix = file_path.suffix.lower()
    if suffix not in MEDIA_TYPES:
