    block_type, media_type = MEDIA_TYPES[suffix]
    data = base64.standard_b64encode(file_path.read_bytes()).decode("utf-8")

    response = client.messages.create(
        model=MODEL,
        max_tokens=1024,
        tools=[INVOICE_TOOL],
        tool_choice={"type": "tool", "name": "record_invoice"},
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": block_type,
                        "source": {"type": "base64", "media_type": media_type, "data": data},
                    },
                    {"type": "text", "text": PROMPT},
                ],
            }
        ],
    )

    for block in response.content:
        if block.type == "tool_use" and block.name == "record_invoice":
            return block.input

    raise RuntimeError(f"No structured result returned for {path}")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python extract_invoice.py <invoice.pdf> [...]", file=sys.stderr)
        sys.exit(1)

    for invoice_path in sys.argv[1:]:
        try:
            result = extract_invoice(invoice_path)
            print(json.dumps({"file": invoice_path, **result}, indent=2))
        except (anthropic.APIError, ValueError, RuntimeError, OSError) as exc:
            print(json.dumps({"file": invoice_path, "error": str(exc)}), file=sys.stderr)
