#!/usr/bin/env python3
"""
Recommended API: Google Vertex AI Gemini Batch with gemini-2.5-flash-lite.

Why:
- Asynchronous batch processing fits a multi-day workload.
- Directly accepts JPEGs and scanned PDFs from Google Cloud Storage.
- Structured JSON output avoids a separate OCR/parsing API.
- Flash-Lite batch pricing is generally much cheaper than specialized
  per-page receipt APIs. Confirm current regional pricing and benchmark
  accuracy on a labeled sample before processing the full monthly volume.

Install:
    pip install google-genai google-cloud-storage

Authenticate:
    gcloud auth application-default login

Enable the Vertex AI API and ensure the Vertex AI service agent can read the
receipt objects and write to the working bucket.

Manifest format, one JSON object per line:
    {"id":"receipt-0001","uri":"gs://input-bucket/receipts/0001.jpg"}
    {"id":"receipt-0002","uri":"gs://input-bucket/receipts/0002.pdf",
     "mime_type":"application/pdf"}

Run:
    python receipt_batch.py \
        --project my-project \
        --location us-central1 \
        --manifest receipts.jsonl \
        --work-uri gs://my-bucket/receipt-jobs/2025-01 \
        --output extracted-receipts.jsonl
"""

import argparse
import json
import mimetypes
import os
import re
import tempfile
import time
from collections import deque
from pathlib import Path
from typing import Any, Dict, Iterable, Iterator, List, Tuple

from google import genai
from google.genai import types
from google.cloud import storage


PROMPT = """
Extract every receipt represented by this document.

The document may be an English or Spanish JPEG or scanned PDF. Return one
object per receipt. For each receipt:

- merchant: the printed merchant or trading name.
- date: transaction date in YYYY-MM-DD format.
- currency: ISO 4217 code such as USD, EUR, MXN, or GBP.
- total: the final amount charged, including tax and tip when applicable.
  Do not use subtotal, tax, balance due after payment, or change.
- Use null when a field cannot be determined reliably.
- Infer currency from symbols, address, and receipt context only when
  unambiguous.
- Do not invent obscured values.
- Return JSON only.
""".strip()

RESPONSE_SCHEMA = {
    "type": "ARRAY",
    "items": {
        "type": "OBJECT",
        "properties": {
            "merchant": {
                "type": "STRING",
                "nullable": True,
                "description": "Printed merchant or trading name.",
            },
            "date": {
                "type": "STRING",
                "nullable": True,
                "description": "Transaction date formatted as YYYY-MM-DD.",
            },
            "currency": {
                "type": "STRING",
                "nullable": True,
                "description": "Three-letter ISO 4217 currency code.",
            },
            "total": {
                "type": "NUMBER",
                "nullable": True,
                "description": "Final amount charged.",
            },
        },
        "required": ["merchant", "date", "currency", "total"],
        "additionalProperties": False,
    },
}

TERMINAL_SUCCESS = {"JOB_STATE_SUCCEEDED", "SUCCEEDED"}
TERMINAL_FAILURE = {
    "JOB_STATE_FAILED",
    "JOB_STATE_CANCELLED",
    "JOB_STATE_EXPIRED",
    "FAILED",
    "CANCELLED",
    "EXPIRED",
}


def split_gcs_uri(uri: str) -> Tuple[str, str]:
    if not uri.startswith("gs://"):
        raise ValueError(f"Expected a gs:// URI, received: {uri}")
    remainder = uri[5:]
    bucket, separator, object_name = remainder.partition("/")
