import base64
import json
from decimal import Decimal, InvalidOperation
from pathlib import Path

import anthropic

MODEL = "claude-opus-4-7"   # use the most capable model available to you; accuracy > cost
MAX_TOKENS = 16000          # long invoices can have many line items
LINE_TOL = Decimal("0.02")  # rounding tolerance per line
TOTAL_TOL = Decimal("0.05") # rounding tolerance on aggregates

client = anthropic.Anthropic()

AMOUNT = {"type": ["string", "null"], "pattern": r"^-?\d+(\.\d+)?$"}

INVOICE_TOOL = {
    "name": "record_invoice",
    "description": "Record the data extracted from a supplier invoice.",
    "input_schema": {
        "type": "object",
        "properties": {
            "supplier": {
                "type": "object",
                "properties": {
                    "name": {"type": ["string", "null"]},
                    "address": {"type": ["string", "null"]},
                    "vat_id": {"type": ["string", "null"], "description": "USt-IdNr. / VAT number"},
                    "tax_number": {"type": ["string", "null"], "description": "Steuernummer or other tax ID"},
                    "iban": {"type": ["string", "null"]},
                    "bic": {"type": ["string", "null"]},
                    "email": {"type": ["string", "null"]},
                    "phone": {"type": ["string", "null"]},
                },
                "required": ["name", "address", "vat_id", "tax_number", "iban", "bic", "email", "phone"],
            },
            "invoice_number": {"type": ["string", "null"]},
            "invoice_date": {"type": ["string", "null"], "description": "YYYY-MM-DD"},
            "due_date": {"type": ["string", "null"], "description": "YYYY-MM-DD"},
            "purchase_order": {"type": ["string", "null"]},
            "currency": {"type": ["string", "null"], "description": "ISO 4217, e.g. EUR"},
            "document_language": {"type": "string"},
            "line_items": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "position": {"type": ["string", "null"]},
                        "description": {"type": "string"},
                        "quantity": AMOUNT,
                        "unit": {"type": ["string", "null"]},
                        "unit_price": AMOUNT,
                        "discount": AMOUNT,
                        "net_amount": AMOUNT,
                        "tax_rate_percent": AMOUNT,
                    },
                    "required": ["position", "description", "quantity", "unit",
                                 "unit_price", "discount", "net_amount", "tax_rate_percent"],
                },
            },
            "tax_breakdown": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "rate_percent": AMOUNT,
                        "taxable_amount": AMOUNT,
                        "tax_amount": AMOUNT,
                    },
                    "required": ["rate_percent", "taxable_amount", "tax_amount"],
                },
            },
            "subtotal_net": AMOUNT,
            "total_tax": AMOUNT,
            "total_gross": AMOUNT,
            "amount_due": AMOUNT,
            "legibility_issues": {
                "type": "array",
                "description": "Every field you could not read with full certainty.",
                "items": {
                    "type": "object",
                    "properties": {
                        "field": {"type": "string"},
                        "issue": {"type": "string"},
                    },
                    "required": ["field", "issue"],
                },
            },
        },
        "required": ["supplier", "invoice_number", "invoice_date", "due_date", "purchase_order",
                     "currency", "document_language", "line_items", "tax_breakdown",
                     "subtotal_net", "total_tax", "total_gross", "amount_due", "legibility_issues"],
    },
}

EXTRACTION_INSTRUCTIONS = """You are extracting data from a supplier invoice for accounts payable. \
Errors cause wrong payments, so precision matters more than completeness.

Rules:
- Copy values exactly as printed. Never compute, infer, or "fix" a value the document doesn't show; use null instead.
- Normalize numbers to plain decimal strings with a dot separator and no thousands separators.
  German "1.234,56" -> "1234.56"; English "1,234.56" -> "1234.56". Decide the format from the document's \
conventions, not from a single number in isolation.
- Quantities: copy exactly (e.g. "2.5", "1000"). Do not round.
- Negative amounts (credits, discounts) get a leading minus.
- Extract every line item on every page, including continuation pages. Do not merge or skip lines.
- Dates as YYYY-MM-DD.
- The scan may be skewed, faded, or have stamps/handwriting over values. If any digit of a field is \
obscured, ambiguous (e.g. 1/7, 3/8, 5/6, comma vs dot), or partly guessed, still give your best reading \
but ALSO add an entry to legibility_issues naming the field (e.g. "line_items[3].quantity", "total_gross") \
and describing the problem. Report liberally: an unnecessary flag costs a quick human check; \
a silent misreading costs a wrong payment.

