        model=MODEL,
        max_tokens=MAX_TOKENS,
        tools=[INVOICE_TOOL],
        tool_choice={"type": "tool", "name": "record_invoice"},
        messages=[{
            "role": "user",
            "content": [_pdf_block(pdf_bytes), {"type": "text", "text": instructions}],
        }],
    )
    if resp.stop_reason == "max_tokens":
        raise RuntimeError("Output truncated; raise MAX_TOKENS or split the PDF.")
