    """Arithmetic and completeness checks. Returns a list of problems."""
    errors = []

    for field in ("invoice_number", "total_gross", "currency"):
        if not inv.get(field):
            errors.append(f"missing {field}")
    if not (inv.get("supplier") or {}).get("name"):
        errors.append("missing supplier.name")
    if not inv.get("line_items"):
        errors.append("no line items extracted")

    line_sum = Decimal("0")
    for i, li in enumerate(inv.get("line_items", [])):
        qty, price, net = _d(li.get("quantity")), _d(li.get("unit_price")), _d(li.get("net_amount"))
        disc = _d(li.get("discount")) or Decimal("0")
        if net is None:
            errors.append(f"line_items[{i}].net_amount missing")
            continue
