        va, vb = a.get(f), b.get(f)
        if f in ("invoice_number", "currency"):
            same = (va or "").strip().upper() == (vb or "").strip().upper()
        else:
            same = _norm_num(va) == _norm_num(vb)
        if not same:
            diffs.append(f"{f}: {va!r} vs {vb!r}")

    for f in ("vat_id", "iban"):
        va = ((a.get("supplier") or {}).get(f) or "").replace(" ", "").upper()
        vb = ((b.get("supplier") or {}).get(f) or "").replace(" ", "").upper()
        if va != vb:
            diffs.append(f"supplier.{f}: {va!r} vs {vb!r}")

    la, lb = a.get("line_items", []), b.get("line_items", [])
    if len(la) != len(lb):
        diffs.append(f"line item count: {len(la)} vs {len(lb)}")
    for i, (x, y) in enumerate(zip(la, lb)):
        for f in ("quantity", "unit_price", "net_amount", "tax_rate_percent"):
            if _norm_num(x.get(f)) != _norm_num(y.get(f)):
                diffs.append(f"line_items[{i}].{f}: {x.get(f)!r} vs {y.get(f)!r}")
    return diffs


def _reconcile(pdf_bytes: bytes, a: dict, b: dict, problems: list[str]) -> dict:
    instructions = (
        EXTRACTION_INSTRUCTIONS
        + "\n\nTwo earlier independent readings of this invoice disagreed or failed arithmetic checks.\n"
        + "Problems:\n- " + "\n- ".join(problems)
        + "\n\nReading A:\n" + json.dumps(a, ensure_ascii=False)
        + "\n\nReading B:\n" + json.dumps(b, ensure_ascii=False)
        + "\n\nRe-read the document itself, paying close attention to the fields listed above. "
          "Do not choose a value because it makes the arithmetic work; report what is printed. "
          "If a value is genuinely unreadable, keep your best reading and flag it in legibility_issues. "
          "Return the complete corrected invoice."
    )
    return _call(pdf_bytes, instructions)


# ---------- main entry point ----------

def extract_invoice(pdf_path: str | Path) -> dict:
    """
    Returns:
      {
        "status": "auto_approved" | "needs_review",
        "invoice": {...},
        "review_reasons": [...],
      }
    """
    pdf_bytes = Path(pdf_path).read_bytes()
    if len(pdf_bytes) > 32 * 1024 * 1024:
        return {"status": "needs_review", "invoice": None,
                "review_reasons": ["PDF exceeds 32 MB API limit"]}

    first = _call(pdf_bytes, EXTRACTION_INSTRUCTIONS)
    second = _call(pdf_bytes, EXTRACTION_INSTRUCTIONS)

    diffs = compare(first, second)
    errors = validate(first)

    if diffs or errors:
        final = _reconcile(pdf_bytes, first, second, diffs + errors)
        final_errors = validate(final)
        # The reconciled result must agree with at least one independent reading on
        # every payment-critical field; otherwise a human decides.
        unresolved = [d for d in compare(final, first) if d in compare(final, second)]
    else:
        final, final_errors, unresolved = first, [], []

    reasons = []
    reasons += [f"arithmetic: {e}" for e in final_errors]
    reasons += [f"readings disagree: {d}" for d in unresolved]
    reasons += [f"illegible: {x['field']} - {x['issue']}" for x in final.get("legibility_issues", [])]

    return {
        "status": "needs_review" if reasons else "auto_approved",
        "invoice": final,
        "review_reasons": reasons,
    }


if __name__ == "__main__":
    import sys
    result = extract_invoice(sys.argv[1])
    print(json.dumps(result, indent=2, ensure_ascii=False))
```

**Before production:**

- **Measure it on your own invoices.** Have finance label 200–300 invoices, weighted toward the bad scans, and compare field by field. Pay closest attention to how often `auto_approved` invoices contain any error. That number decides whether you can trust the auto-approval path. The review rate only tells you how much manual work is left.
- **Cross-check against your data.** Check supplier VAT ID and IBAN against your vendor master, and amounts against the PO. A changed IBAN should always go to a person, both because of extraction errors and because of fraud.
- **Tune the routing rules, not the prompt.** If too much goes to review, look at which checks fire and fix those. Avoid relaxing tolerances on amounts.
- **Watch for duplicate invoice numbers** per supplier. Re-sent scans of the same invoice are common.

