Below is the extraction service in Python. The TypeScript SDK (`@anthropic-ai/sdk`) has the same parameters if you want it inline in your backend.

```python
"""
Fast financial-table extraction for a live preview.
Model: Claude Haiku 4.5 (fastest Claude model), with structured outputs + streaming.

pip install anthropic pypdf
export ANTHROPIC_API_KEY=...
"""

import asyncio
import base64
import io
import json
import sys
import time

import anthropic
from pypdf import PdfReader, PdfWriter

MODEL = "claude-haiku-4-5"

client = anthropic.AsyncAnthropic()  # reads ANTHROPIC_API_KEY

# JSON schema returned to the TypeScript backend.
# Cell values are kept as the exact printed text, e.g. "(1,234)", "—", "12.5%",
# so analysts see what's on the page. Parse numbers downstream.
TABLE_SCHEMA = {
    "type": "object",
    "properties": {
        "tables": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "title": {
                        "anyOf": [{"type": "string"}, {"type": "null"}],
                        "description": "Table title/caption as printed, or null.",
                    },
                    "units": {
                        "anyOf": [{"type": "string"}, {"type": "null"}],
                        "description": "Unit/scale note, e.g. 'USD in thousands', or null.",
                    },
                    "header_rows": {
                        "type": "array",
                        "description": (
                            "Column header rows, top to bottom. Each row lists header "
                            "text per data column (excluding the row-label column). "
                            "Repeat spanning headers across the columns they cover."
                        ),
                        "items": {"type": "array", "items": {"type": "string"}},
                    },
                    "rows": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "label": {"type": "string"},
                                "is_section_header": {"type": "boolean"},
                                "is_total": {"type": "boolean"},
                                "cells": {
                                    "type": "array",
                                    "description": "One entry per data column; empty string if blank.",
                                    "items": {"type": "string"},
                                },
                            },
                            "required": ["label", "is_section_header", "is_total", "cells"],
                            "additionalProperties": False,
                        },
                    },
                },
                "required": ["title", "units", "header_rows", "rows"],
                "additionalProperties": False,
            },
        }
    },
    "required": ["tables"],
    "additionalProperties": False,
}

INSTRUCTIONS = """Extract every financial table on this page into the JSON schema.

- Copy values exactly as printed (keep parentheses for negatives, commas, %, currency symbols, dashes).
- Use the leftmost descriptive column as each row's label; indentation-only subheadings are rows with is_section_header=true and empty cells.
- Every row's cells array must have the same length as the number of data columns.
- Mark subtotal/total lines with is_total=true.
- Ignore running text, footnote paragraphs, and page headers/footers.
- If the page has no financial tables, return {"tables": []}."""


def split_pdf_pages(pdf_bytes: bytes) -> list[bytes]:
    """Split an uploaded PDF into single-page PDFs so pages can be extracted in parallel."""
    reader = PdfReader(io.BytesIO(pdf_bytes))
    pages = []
    for page in reader.pages:
        writer = PdfWriter()
        writer.add_page(page)
        buf = io.BytesIO()
        writer.write(buf)
        pages.append(buf.getvalue())
    return pages


async def extract_page(page_pdf: bytes, page_number: int, on_partial=None) -> dict:
    """
    Extract tables from a single-page PDF.
    `on_partial(page_number, text_so_far)` is called as JSON streams in, so the UI can
    render a progressive preview (e.g. with a partial-JSON parser on the frontend).
    """
    started = time.perf_counter()
    text_so_far = ""

    async with client.messages.stream(
        model=MODEL,
        max_tokens=8000,
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": "document",
                        "source": {
                            "type": "base64",
                            "media_type": "application/pdf",
                            "data": base64.standard_b64encode(page_pdf).decode("utf-8"),
                        },
                    },
                    {"type": "text", "text": INSTRUCTIONS},
                ],
            }
        ],
        output_config={"format": {"type": "json_schema", "schema": TABLE_SCHEMA}},
    ) as stream:
        async for chunk in stream.text_stream:
            text_so_far += chunk
            if on_partial:
                on_partial(page_number, text_so_far)
        final = await stream.get_final_message()

    elapsed = time.perf_counter() - started

    if final.stop_reason == "refusal":
        return {"page": page_number, "error": "refused", "tables": [], "seconds": elapsed}
    if final.stop_reason == "max_tokens":
        return {"page": page_number, "error": "truncated", "tables": [], "seconds": elapsed}

    raw = next(b.text for b in final.content if b.type == "text")
    data = json.loads(raw)  # schema-conformant thanks to structured outputs
    return {
        "page": page_number,
        "tables": data["tables"],
        "seconds": round(elapsed, 2),
        "usage": {
            "input_tokens": final.usage.input_tokens,
            "output_tokens": final.usage.output_tokens,
        },
    }


async def extract_document(pdf_bytes: bytes, max_concurrency: int = 10, on_partial=None) -> list[dict]:
    """Extract all pages concurrently; each page's preview latency is independent of doc length."""
    pages = split_pdf_pages(pdf_bytes)
    sem = asyncio.Semaphore(max_concurrency)

    async def run(i: int, page: bytes) -> dict:
        async with sem:
            try:
                return await extract_page(page, i + 1, on_partial)
            except anthropic.APIStatusError as e:
                # SDK already retries 429/5xx with backoff; surface anything left to the UI.
                return {"page": i + 1, "error": f"api_error_{e.status_code}", "tables": []}
            except anthropic.APIConnectionError:
                return {"page": i + 1, "error": "connection_error", "tables": []}

    return await asyncio.gather(*(run(i, p) for i, p in enumerate(pages)))


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "statement.pdf"
    with open(path, "rb") as f:
        pdf = f.read()

    def show_progress(page: int, text: str) -> None:
        print(f"\rpage {page}: {len(text)} chars streamed", end="", file=sys.stderr)

    results = asyncio.run(extract_document(pdf, on_partial=show_progress))
    print(file=sys.stderr)
    print(json.dumps(results, indent=2))
```

**Notes for production:**

- **Progressive preview.** Forward the streamed text to the browser over SSE or WebSocket and parse it with a partial-JSON parser (for example, the `partial-json` npm package). Rows then appear as they're generated, and analysts rarely wait on a blank screen.
- **Timing.** Track the `seconds` field. If tables with many rows push past five seconds, the output length is the cause. You can cap it by dropping the `is_section_header`/`is_total` flags or emitting one table per request.
- **First request with a new schema.** It compiles the grammar and is a bit slower; the compiled schema is then cached for 24 hours. Send one warm-up call at deploy time so analysts never hit that delay.
- **Throughput.** At your volume, ask Anthropic for rate-limit headroom based on peak (not average) concurrency. Uploads tend to cluster during business hours.

