Use Claude Haiku 4.5. It is fast enough to process one page within your 5-second budget. It reads both digital PDFs and scans, and a forced tool call makes it return structured JSON.

Send each page as its own request, all in parallel. The service below streams results back as NDJSON, so the preview fills in as pages finish instead of waiting for the whole document. Your TypeScript backend calls it over HTTP.

```python
"""
Financial-table extraction preview service.

Run:   pip install anthropic pypdf fastapi uvicorn python-multipart
       export ANTHROPIC_API_KEY=...
       uvicorn table_preview:app --host 0.0.0.0 --port 8000

TypeScript backend:
    POST /extract  (multipart, field "file" = PDF)
    -> application/x-ndjson, one JSON line per page as soon as it finishes:
       {"page": 3, "status": "ok", "elapsed_s": 2.1, "tables": [...]}
       {"page": 7, "status": "timeout", "elapsed_s": 5.0, "tables": []}
"""

import asyncio
import base64
import io
import json
import time

from anthropic import AsyncAnthropic
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.responses import StreamingResponse
from pypdf import PdfReader, PdfWriter

MODEL = "claude-haiku-4-5"     # fast model; swap to "claude-sonnet-4-5" for a slower, more careful re-run
PAGE_DEADLINE_S = 5.0          # UI budget per page
MAX_CONCURRENCY = 16           # parallel page requests per process; tune to your rate limits

client = AsyncAnthropic(max_retries=0)  # no retries inside the 5-second budget
semaphore = asyncio.Semaphore(MAX_CONCURRENCY)
app = FastAPI()

# A forced tool call guarantees the reply matches this schema.
TABLE_TOOL = {
    "name": "record_tables",
    "description": "Record every financial table found on the page.",
    "input_schema": {
        "type": "object",
        "properties": {
            "tables": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "title": {"type": "string", "description": "Table caption or heading, '' if none."},
                        "units": {"type": "string", "description": "e.g. 'USD thousands', '' if not stated."},
                        "header_rows": {
                            "type": "array",
                            "description": "Column header rows, top to bottom. Each row has one string per data column (repeat spanning headers).",
                            "items": {"type": "array", "items": {"type": "string"}},
                        },
                        "rows": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "label": {"type": "string", "description": "Row label exactly as printed."},
                                    "indent_level": {"type": "integer", "description": "0 = top level, 1 = sub-item, etc."},
                                    "is_total": {"type": "boolean"},
                                    "cells": {
                                        "type": "array",
                                        "description": "One entry per data column, aligned with header_rows.",
                                        "items": {
                                            "type": "object",
                                            "properties": {
                                                "raw": {"type": "string", "description": "Exactly as printed, e.g. '(1,234)', '—', '12.5%'."},
                                                "value": {"type": ["number", "null"], "description": "Parsed number; parentheses = negative; null if blank/dash/non-numeric."},
                                            },
                                            "required": ["raw", "value"],
                                        },
                                    },
                                },
                                "required": ["label", "indent_level", "is_total", "cells"],
                            },
                        },
                    },
                    "required": ["title", "units", "header_rows", "rows"],
                },
            }
        },
        "required": ["tables"],
    },
}

PROMPT = (
    "Extract every financial table on this page. "
    "Copy numbers exactly; do not compute, round, or fill in missing values. "
    "Keep row order and column order as printed. "
    "If there are no tables, return an empty list."
)


def split_pages(pdf_bytes: bytes) -> list[bytes]:
    """Split the PDF into single-page PDFs (keeps the text layer for digital docs)."""
    reader = PdfReader(io.BytesIO(pdf_bytes))
    pages = []
    for page in reader.pages:
        writer = PdfWriter()
        writer.add_page(page)
        buf = io.BytesIO()
        writer.write(buf)
        pages.append(buf.getvalue())
    return pages


async def extract_page(page_no: int, page_pdf: bytes) -> dict:
    start = time.monotonic()
    result = {"page": page_no, "status": "ok", "tables": []}
    try:
        async with semaphore:
            resp = await asyncio.wait_for(
                client.messages.create(
                    model=MODEL,
                    max_tokens=4096,
                    temperature=0,
                    tools=[TABLE_TOOL],
                    tool_choice={"type": "tool", "name": "record_tables"},
                    messages=[{
                        "role": "user",
                        "content": [
                            {
                                "type": "document",
                                "source": {
                                    "type": "base64",
                                    "media_type": "application/pdf",
                                    "data": base64.standard_b64encode(page_pdf).decode(),
                                },
                            },
                            {"type": "text", "text": PROMPT},
                        ],
                    }],
                ),
                timeout=PAGE_DEADLINE_S,
            )
        tool_use = next(b for b in resp.content if b.type == "tool_use")
        result["tables"] = tool_use.input.get("tables", [])
        if resp.stop_reason == "max_tokens":
            result["status"] = "truncated"   # very dense page; flag it for the analyst
    except asyncio.TimeoutError:
        result["status"] = "timeout"         # UI can show "still processing" and retry in the background
    except Exception as e:
        result["status"] = "error"
        result["error"] = str(e)
    result["elapsed_s"] = round(time.monotonic() - start, 2)
    return result


@app.post("/extract")
async def extract(file: UploadFile = File(...)):
    data = await file.read()
    try:
        pages = split_pages(data)
    except Exception:
        raise HTTPException(status_code=400, detail="Could not read PDF")

    async def stream():
        tasks = [asyncio.create_task(extract_page(i + 1, p)) for i, p in enumerate(pages)]
        for done in asyncio.as_completed(tasks):
            yield json.dumps(await done) + "\n"

    return StreamingResponse(stream(), media_type="application/x-ndjson")


@app.post("/extract-page")
async def extract_single(page: int, file: UploadFile = File(...)):
    """Re-run one page (e.g. after a timeout) without the 5s cap."""
    pages = split_pages(await file.read())
    if not 1 <= page <= len(pages):
        raise HTTPException(status_code=400, detail="Page out of range")
    global PAGE_DEADLINE_S
    saved, PAGE_DEADLINE_S = PAGE_DEADLINE_S, 60.0
    try:
        return await extract_page(page, pages[page - 1])
    finally:
        PAGE_DEADLINE_S = saved
```

