```python
"""
Recommended hosted API:
Azure AI Document Intelligence — prebuilt-invoice model with high-resolution OCR.

Why this configuration:
- Supports English and German invoices.
- Extracts invoice fields and nested line items.
- Handles scanned, rotated, and degraded PDFs.
- Returns confidence scores and source text for audit/review.
- Uses decimal strings to avoid binary floating-point errors.

Install:
    pip install requests

Environment:
    export AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT="https://<resource>.cognitiveservices.azure.com"
    export AZURE_DOCUMENT_INTELLIGENCE_KEY="<api-key>"

Usage:
    python extract_invoice.py invoice.pdf -o invoice.json

For production, run this from queue workers and send any invoice with
review.required == true to manual validation before payment.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import time
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any
from urllib.parse import quote

import requests


API_VERSION = "2024-11-30"
MODEL_ID = "prebuilt-invoice"
DEFAULT_CONFIDENCE_THRESHOLD = Decimal("0.95")


class DocumentIntelligenceError(RuntimeError):
    pass


def parse_json_response(response: requests.Response) -> dict[str, Any]:
    try:
        return json.loads(response.text, parse_float=Decimal)
    except json.JSONDecodeError as exc:
        raise DocumentIntelligenceError(
            f"API returned invalid JSON ({response.status_code}): "
            f"{response.text[:1000]}"
        ) from exc


def decimal_string(value: Any) -> str | None:
    if value is None:
        return None
    try:
        return format(Decimal(str(value)), "f")
    except (InvalidOperation, ValueError, TypeError):
        return None


def json_compatible(value: Any) -> Any:
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, dict):
        return {key: json_compatible(item) for key, item in value.items()}
    if isinstance(value, list):
        return [json_compatible(item) for item in value]
    if isinstance(value, tuple):
        return [json_compatible(item) for item in value]
    return value


def field_pages(field: dict[str, Any] | None) -> list[int]:
    if not field:
        return []

    pages = {
        int(region["pageNumber"])
        for region in field.get("boundingRegions", [])
        if region.get("pageNumber") is not None
    }
    return sorted(pages)


def field_value(field: dict[str, Any] | None) -> Any:
    if not field:
        return None

    if "valueCurrency" in field:
        currency = dict(field["valueCurrency"] or {})
        amount = currency.get("amount")
        if amount is not None:
            currency["amount"] = decimal_string(amount)
        if "currencyCode" in currency:
            currency["currency"] = currency.pop("currencyCode")
        return currency

    if "valueNumber" in field:
        return decimal_string(field["valueNumber"])

    if "valueInteger" in field:
        return decimal_string(field["valueInteger"])

    for key in (
        "valueString",
        "valueDate",
        "valueTime",
        "valuePhoneNumber",
        "valueCountryRegion",
        "valueSelectionMark",
        "valueBoolean",
    ):
        if key in field:
            return field[key]

    if "valueAddress" in field:
        return json_compatible(field["valueAddress"])

    if "valueObject" in field:
        return {
            name: field_payload(child)
            for name, child in (field["valueObject"] or {}).items()
        }

    if "valueArray" in field:
        return [field_payload(item) for item in field["valueArray"] or []]

    return field.get("content")


def field_payload(field: dict[str, Any] | None) -> dict[str, Any] | None:
    if not field:
        return None

    confidence = field.get("confidence")
    return {
        "value": field_value(field),
        "raw_text": field.get("content"),
        "confidence": decimal_string(confidence),
        "pages": field_pages(field),
    }


def pick_field(
    fields: dict[str, Any], *candidate_names: str
) -> dict[str, Any] | None:
    for name in candidate_names:
        if fields.get(name) is not None:
            return fields[name]
    return None


def object_fields(field: dict[str, Any] | None) -> dict[str, Any]:
    if not field:
        return {}
    return field.get("valueObject") or {}


def array_items(field: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not field:
        return []
    return field.get("valueArray") or []


def numeric_field_value(field: dict[str, Any] | None) -> Decimal | None:
    if not field:
        return None

    value: Any = None

    if "valueCurrency" in field:
        value = (field.get("valueCurrency") or {}).get("amount")
    elif "valueNumber" in field:
        value = field.get("valueNumber")
    elif "valueInteger" in field:
        value = field.get("valueInteger")

    if value is None:
        return None

    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None


def currency_code(field: dict[str, Any] | None) -> str | None:
    if not field:
        return None
    value = field.get("valueCurrency") or {}
    return value.get("currencyCode") or value.get("currency")


def confidence_value(field: dict[str, Any] | None) -> Decimal | None:
    if not field or field.get("confidence") is None:
        return None
    try:
        return Decimal(str(field["confidence"]))
    except (InvalidOperation, ValueError, TypeError):
        return None


def mapped_fields(
    fields: dict[str, Any],
    mapping: dict[str, tuple[str, ...]],
) -> dict[str, Any]:
    return {
        output_name: field_payload(pick_field(fields, *source_names))
        for output_name, source_names in mapping.items()
    }


def normalize_line_item(item: dict[str, Any], index: int) -> dict[str, Any]:
    fields = object_fields(item)

    normalized = mapped_fields(
        fields,
        {
            "description": ("Description",),
            "product_code": ("ProductCode", "ItemCode"),
            "quantity": ("Quantity",),
            "unit": ("Unit",),
            "unit_price": ("UnitPrice",),
            "discount": ("Discount",),
            "discount_rate": ("DiscountRate",),
            "tax": ("Tax",),
            "tax_rate": ("TaxRate",),
            "amount": ("Amount",),
            "date": ("Date",),
        },
    )

    normalized.update(
        {
            "line_number": index,
            "raw_text": item.get("content"),
            "confidence": decimal_string(item.get("confidence")),
            "pages": field_pages(item),
            "all_extracted_fields": {
                name: field_payload(field) for name, field in fields.items()
            },
        }
    )
    return normalized


def normalize_object_array(field: dict[str, Any] | None) -> list[dict[str, Any]]:
    output = []
    for item in array_items(field):
        fields = object_fields(item)
        output.append(
            {
                "raw_text": item.get("content"),
                "confidence": decimal_string(item.get("confidence")),
                "pages": field_pages(item),
                "fields": {
                    name: field_payload(child) for name, child in fields.items()
                },
            }
        )
    return output


def tolerance(expected: Decimal) -> Decimal:
    return max(Decimal("0.02"), abs(expected) * Decimal("0.001"))


def build_review_result(
    fields: dict[str, Any],
    threshold: Decimal,
) -> dict[str, Any]:
    reasons: list[dict[str, Any]] = []

    def require(
        label: str,
        field: dict[str, Any] | None,
        *,
        required: bool = True,
    ) -> None:
        if field is None:
            if required:
                reasons.append(
                    {
                        "code": "missing_critical_field",
                        "field": label,
                    }
                )
            return

        confidence = confidence_value(field)
        if confidence is None:
            reasons.append(
                {
                    "code": "missing_confidence",
                    "field": label,
                }
            )
        elif confidence < threshold:
            reasons.append(
                {
                    "code": "low_confidence",
                    "field": label,
                    "confidence": decimal_string(confidence),
                    "required_confidence": decimal_string(threshold),
                }
            )

    require("supplier.name", pick_field(fields, "VendorName"))
    require("invoice.number", pick_field(fields, "InvoiceId"))
    require("totals.invoice_total", pick_field(fields, "InvoiceTotal"))

    for optional_label, names in (
        ("invoice.date", ("InvoiceDate",)),
        ("invoice.due_date", ("DueDate",)),
        ("supplier.tax_id", ("VendorTaxId",)),
        ("totals.subtotal", ("SubTotal",)),
        ("taxes.total", ("TotalTax",)),
        ("totals.amount_due", ("AmountDue",)),
    ):
        optional_field = pick_field(fields, *names)
        if optional_field is not None:
            require(optional_label, optional_field, required=False)

    items_field = pick_field(fields, "Items")
    items = array_items(items_field)

    if not items:
        reasons.append(
            {
                "code": "missing_line_items",
                "field": "line_items",
            }
        )

    item_amounts: list[Decimal] = []
    item_currencies: set[str] = set()
    all_items_have_amount = True

    for index, item in enumerate(items, start=1):
        item_fields = object_fields(item)
        prefix = f"line_items[{index}]"

        description = pick_field(item_fields, "Description")
        product_code = pick_field(item_fields, "ProductCode", "ItemCode")
        quantity = pick_field(item_fields, "Quantity")
        unit_price = pick_field(item_fields, "UnitPrice")
        amount = pick_field(item_fields, "Amount")
        tax = pick_field(item_fields, "Tax")
        discount = pick_field(item_fields, "Discount")

        require(f"{prefix}.description", description)
        require(f"{prefix}.amount", amount)

        if quantity is not None:
            require(f"{prefix}.quantity", quantity)
        if unit_price is not None:
            require(f"{prefix}.unit_price", unit_price)
        if tax is not None:
            require(f"{prefix}.tax", tax, required=False)
        if discount is not None:
            require(f"{prefix}.discount", discount, required=False)

        if (product_code is not None or unit_price is not None) and quantity is None:
            reasons.append(
                {
                    "code": "missing_quantity",
                    "field": f"{prefix}.quantity",
                }
            )

        if quantity is not None and unit_price is None:
            reasons.append(
                {
                    "code": "missing_unit_price",
                    "field": f"{prefix}.unit_price",
                }
            )

        quantity_value = numeric_field_value(quantity)
        unit_price_value = numeric_field_value(unit_price)
        amount_value = numeric_field_value(amount)
        tax_value = numeric_field_value(tax)

        if amount_value is None:
            all_items_have_amount = False
        else:
            item_amounts.append(amount_value)

        code = currency_code(amount)
        if code:
            item_currencies.add(code)

        # Accept either a net line amount or a tax-inclusive line amount.
        # Discounts are excluded from this check because invoice schemas vary.
        if (
            quantity_value is not None
            and unit_price_value is not None
            and amount_value is not None
            and discount is None
        ):
            base_expected = quantity_value * unit_price_value
            accepted_values = [base_expected]
            if tax_value is not None:
                accepted_values.append(base_expected + tax_value)

            if all(
                abs(amount_value - expected) > tolerance(expected)
                for expected in accepted_values
            ):
                reasons.append(
                    {
                        "code": "line_arithmetic_mismatch",
                        "field": prefix,
                        "quantity": decimal_string(quantity_value),
                        "unit_price": decimal_string(unit_price_value),
                        "extracted_amount": decimal_string(amount_value),
                        "expected_before_tax": decimal_string(base_expected),
                        "extracted_tax": decimal_string(tax_value),
                    }
                )

    subtotal_field = pick_field(fields, "SubTotal")
    subtotal = numeric_field_value(subtotal_field)

    if (
        subtotal is not None
        and items
        and all_items_have_amount
        and len(item_amounts) == len(items)
    ):
        item_sum = sum(item_amounts, Decimal("0"))
        if abs(item_sum - subtotal) > tolerance(subtotal):
            reasons.append(
                {
                    "code": "line_sum_subtotal_mismatch",
                    "field": "totals.subtotal",
                    "line_item_sum": decimal_string(item_sum),
                    "extracted_subtotal": decimal_string(subtotal),
                }
            )

    tax_details_field = pick_field(fields, "TaxDetails", "TaxItems")
    tax_amounts: list[Decimal] = []

    for detail in array_items(tax_details_field):
        detail_fields = object_fields(detail)
        amount = numeric_field_value(
            pick_field(detail_fields, "Amount", "TaxAmount")
        )
        if amount is not None:
            tax_amounts.append(amount)

    total_tax = numeric_field_value(pick_field(fields, "TotalTax"))
    if total_tax is not None and tax_amounts:
        details_sum = sum(tax_amounts, Decimal("0"))
        if abs(details_sum - total_tax) > tolerance(total_tax):
            reasons.append(
                {
                    "code": "tax_sum_mismatch",
                    "field": "taxes.total",
                    "tax_detail_sum": decimal_string(details_sum),
                    "extracted_total_tax": decimal_string(total_tax),
                }
            )

    invoice_total_code = currency_code(pick_field(fields, "InvoiceTotal"))
    if invoice_total_code:
        item_currencies.add(invoice_total_code)

    if len(item_currencies) > 1:
        reasons.append(
            {
                "code": "currency_mismatch",
                "currencies": sorted(item_currencies),
            }
        )

    return {
        "required": bool(reasons),
        "decision": (
            "manual_review"
            if reasons
            else "candidate_for_automated_business_validation"
        ),
        "critical_confidence_threshold": decimal_string(threshold),
        "reasons": reasons,
    }


def normalize_document(
    document: dict[str, Any],
    index: int,
    threshold: Decimal,
) -> dict[str, Any]:
    fields = document.get("fields") or {}
    items = array_items(pick_field(fields, "Items"))

    return {
        "document_number": index,
        "document_type": document.get("docType"),
        "model_confidence": decimal_string(document.get("confidence")),
        "supplier": mapped_fields(
            fields,
            {
                "name": ("VendorName",),
                "address": ("VendorAddress",),
                "address_recipient": ("VendorAddressRecipient",),
                "tax_id": ("VendorTaxId",),
                "registration_id": ("VendorRegistrationId",),
            },
        ),
        "customer": mapped_fields(
            fields,
            {
                "name": ("CustomerName",),
                "id": ("CustomerId",),
                "address": ("CustomerAddress",),
                "address_recipient": ("CustomerAddressRecipient",),
                "tax_id": ("CustomerTaxId",),
                "billing_address": ("BillingAddress",),
                "billing_address_recipient": ("BillingAddressRecipient",),
                "shipping_address": ("ShippingAddress",),
                "shipping_address_recipient": ("ShippingAddressRecipient",),
            },
        ),
        "invoice": mapped_fields(
            fields,
            {
                "number": ("InvoiceId",),
                "date": ("InvoiceDate",),
                "due_date": ("DueDate",),
                "purchase_order": ("PurchaseOrder",),
                "service_start_date": ("ServiceStartDate",),
                "service_end_date": ("ServiceEndDate",),
            },
        ),
        "taxes": {
            "total": field_payload(pick_field(fields, "TotalTax")),
            "details": normalize_object_array(
                pick_field(fields, "TaxDetails", "TaxItems")
            ),
        },
        "totals": mapped_fields(
            fields,
            {
                "subtotal": ("SubTotal",),
                "total_discount": ("TotalDiscount",),
                "total_tax": ("TotalTax",),
                "invoice_total": ("InvoiceTotal",),
                "amount_due": ("AmountDue",),
                "previous_unpaid_balance": ("PreviousUnpaidBalance",),
            },
        ),
        "remittance": mapped_fields(
            fields,
            {
                "address": ("RemittanceAddress",),
                "address_recipient": ("RemittanceAddressRecipient",),
            },
        ),
        "payment_details": normalize_object_array(
            pick_field(fields, "PaymentDetails")
        ),
        "line_items": [
            normalize_line_item(item, item_index)
            for item_index, item in enumerate(items, start=1)
        ],
        "review": build_review_result(fields, threshold),
        # Retains newly introduced or provider-specific fields without
        # silently dropping them.
        "all_extracted_fields": {
            name: field_payload(field) for name, field in fields.items()
        },
    }


class AzureInvoiceExtractor:
    def __init__(
        self,
        endpoint: str,
        api_key: str,
        *,
        confidence_threshold: Decimal = DEFAULT_CONFIDENCE_THRESHOLD,
        poll_timeout_seconds: int = 900,
    ) -> None:
        self.endpoint = endpoint.rstrip("/")
        self.api_key = api_key
        self.confidence_threshold = confidence_threshold
        self.poll_timeout_seconds = poll_timeout_seconds
        self.session = requests.Session()
        self.session.headers.update(
            {"Ocp-Apim-Subscription-Key": self.api_key}
        )

    def _request_with_retry(
        self,
        method: str,
        url: str,
        *,
        attempts: int = 5,
        **kwargs: Any,
    ) -> requests.Response:
        last_error: Exception | None = None

        for attempt in range(attempts):
            try:
                response = self.session.request(method, url, **kwargs)
            except requests.RequestException as exc:
                last_error = exc
                if attempt == attempts - 1:
                    raise DocumentIntelligenceError(
                        f"Document Intelligence request failed: {exc}"
                    ) from exc
                time.sleep(min(2**attempt, 20))
                continue

            if response.status_code not in {429, 500, 502, 503, 504}:
                return response

            if attempt == attempts - 1:
                return response

            retry_after = response.headers.get("Retry-After")
            try:
                delay = float(retry_after) if retry_after else min(2**attempt, 20)
            except ValueError:
                delay = min(2**attempt, 20)
            time.sleep(delay)

        raise DocumentIntelligenceError(str(last_error or "Request failed"))

    def analyze_pdf(
        self,
        pdf_path: str | Path,
        *,
        include_raw_result: bool = False,
    ) -> dict[str, Any]:
        path = Path(pdf_path)
        pdf_bytes = path.read_bytes()

        if not pdf_bytes.startswith(b"%PDF"):
            raise ValueError(f"{path} is not a PDF file")

        digest = hashlib.sha256(pdf_bytes).hexdigest()

        analyze_url = (
            f"{self.endpoint}/documentintelligence/documentModels/"
            f"{quote(MODEL_ID, safe='')}:analyze"
        )

        response = self._request_with_retry(
            "POST",
            analyze_url,
            params={
                "api-version": API_VERSION,
                "features": "ocrHighResolution",
            },
            headers={"Content-Type": "application/pdf"},
            data=pdf_bytes,
            timeout=(30, 300),
        )

        if response.status_code not in {200, 202}:
            raise DocumentIntelligenceError(
                f"Analyze request failed ({response.status_code}): "
                f"{response.text[:2000]}"
            )

        operation_url = response.headers.get("Operation-Location")

        if response.status_code == 200:
            operation_result = parse_json_response(response)
        else:
            if not operation_url:
                raise DocumentIntelligenceError(
                    "Analyze response did not contain Operation-Location"
                )
            operation_result = self._poll(operation_url)

        analyze_result = operation_result.get("analyzeResult") or {}
        documents = analyze_result.get("documents") or []

        if not documents:
            raise DocumentIntelligenceError(
                "The API succeeded but returned no invoice documents"
            )

        output: dict[str, Any] = {
            "provider": "Azure AI Document Intelligence",
            "model": MODEL_ID,
            "api_version": API_VERSION,
            "features": ["ocrHighResolution"],
            "source": {
                "filename": path.name,
                "sha256": digest,
                "page_count": len(analyze_result.get("pages") or []),
            },
            "invoices": [
                normalize_document(
                    document,
                    index,
                    self.confidence_threshold,
                )
                for index, document in enumerate(documents, start=1)
            ],
        }

        output["manual_review_required"] = any(
            invoice["review"]["required"] for invoice in output["invoices"]
        )

        if include_raw_result:
            output["raw_analyze_result"] = analyze_result

        return json_compatible(output)

    def _poll(self, operation_url: str) -> dict[str, Any]:
        deadline = time.monotonic() + self.poll_timeout_seconds

        while time.monotonic() < deadline:
            response = self._request_with_retry(
                "GET",
                operation_url,
                timeout=(30, 120),
            )

            if response.status_code != 200:
                raise DocumentIntelligenceError(
                    f"Polling failed ({response.status_code}): "
                    f"{response.text[:2000]}"
                )

            result = parse_json_response(response)
            status = str(result.get("status", "")).lower()

            if status == "succeeded":
                return result

            if status in {"failed", "canceled", "cancelled"}:
                raise DocumentIntelligenceError(
                    f"Invoice analysis {status}: "
                    f"{json.dumps(json_compatible(result.get('error')), ensure_ascii=False)}"
                )

            retry_after = response.headers.get("Retry-After")
            try:
                delay = float(retry_after) if retry_after else 2.0
            except ValueError:
                delay = 2.0
            time.sleep(max(0.5, min(delay, 10.0)))

        raise TimeoutError(
            f"Invoice analysis exceeded {self.poll_timeout_seconds} seconds"
        )


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Extract and validate supplier invoice data."
    )
    parser.add_argument("pdf", type=Path)
    parser.add_argument("-o", "--output", type=Path)
    parser.add_argument(
        "--confidence-threshold",
        default=os.getenv("MIN_CRITICAL_CONFIDENCE", "0.95"),
    )
    parser.add_argument(
        "--include-raw-result",
        action="store_true",
        help="Include the complete Azure analyzeResult in the output.",
    )
    args = parser.parse_args()

    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    extractor = AzureInvoiceExtractor(
        endpoint,
        api_key,
        confidence_threshold=Decimal(args.confidence_threshold),
    )
    result = extractor.analyze_pdf(
        args.pdf,
        include_raw_result=args.include_raw_result,
    )

    rendered = json.dumps(
        result,
        ensure_ascii=False,
        indent=2,
        allow_nan=False,
    )

    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(rendered + "\n", encoding="utf-8")
    else:
        print(rendered)


if __name__ == "__main__":
    main()
