                delay = polling_delay(response)

    except (TimeoutError, httpx.TimeoutException):
        if operation_id is None:
            # Submission might have reached Azure. Do not blindly retry and
            # risk duplicate billable extraction.
            raise HTTPException(
                504, "The provider did not acknowledge submission within the budget."
            )
    except httpx.RequestError as exc:
        if operation_id is None:
            raise HTTPException(502, "Could not reach the extraction provider.") from exc

    # Azure retains the operation; no in-process background job is required.
    return pending(operation_id, page, delay)


@app.get("/previews/{operation_id}")
async def preview_status(
    request: Request,
