        "source_sha256": digest.hexdigest(),
        "api": "Azure AI Document Intelligence / prebuilt-layout",
        "api_version": API_VERSION,
        "high_resolution_ocr": True,
        "document_issues": [] if tables else ["No tables detected; inspect document."],
        "tables": tables,
        "publication_policy": (
