            "accounting reconciliation and document-level completeness checks "
            "before publication. Cross-page tables remain separate API table "
            "objects; do not join them solely because their widths match."
        ),
    }
    write_json(destination / "manifest.json", manifest)
    return manifest


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("pdfs", nargs="+", type=Path)
    parser.add_argument("--out", type=Path, default=Path("exports"))
    parser.add_argument("--workers", type=int, default=4)
    args = parser.parse_args()

    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    args.out.mkdir(parents=True, exist_ok=True)
    summaries = []

    # For a larger deployment, place this worker behind a durable queue and
    # rate-limit submissions/polling to your resource's provisioned quotas.
    with ThreadPoolExecutor(max_workers=max(1, args.workers)) as executor:
        futures = {
            executor.submit(process_pdf, pdf, args.out, endpoint, key): pdf
            for pdf in dict.fromkeys(args.pdfs)
        }
        for future in as_completed(futures):
            pdf = futures[future]
            try:
                manifest = future.result()
                summary = {
                    "source": str(pdf),
                    "tables": len(manifest["tables"]),
                    "tables_flagged": sum(
                        table["state"] == "review_required"
                        for table in manifest["tables"]
                    ),
                    "document_issues": manifest["document_issues"],
                }
            except Exception as error:
                summary = {"source": str(pdf), "error": str(error)}
            summaries.append(summary)
            print(json.dumps(summary, ensure_ascii=False))

    write_json(args.out / "batch_summary.json", summaries)


