    }

    parsed_tables: list[dict[str, Any]] = []

    for table_number, table_block in enumerate(
        (b for b in blocks if b.get("BlockType") == "TABLE"),
        start=1,
    ):
        raw_cells: list[dict[str, Any]] = []

        for relationship in table_block.get("Relationships", []):
            if relationship.get("Type") != "CHILD":
                continue

            for child_id in relationship.get("Ids", []):
                child = blocks_by_id.get(child_id)
                if not child or child.get("BlockType") != "CELL":
                    continue

                raw_cells.append(
                    {
                        "row": child.get("RowIndex", 1),
                        "column": child.get("ColumnIndex", 1),
                        "row_span": child.get("RowSpan", 1),
                        "column_span": child.get("ColumnSpan", 1),
                        "value": text_for_block(child, blocks_by_id),
                        "entity_types": child.get("EntityTypes", []),
                        "confidence": round(child.get("Confidence", 0.0), 2),
                        "bounding_box": normalized_bbox(child),
