def render_pdf_page(data: bytes, page_number: int) -> Image.Image:
    try:
        document = fitz.open(stream=data, filetype="pdf")
    except Exception as exc:
        raise ValueError("The uploaded PDF could not be opened") from exc

    try:
        if page_number < 1 or page_number > document.page_count:
            raise ValueError(
                f"Page must be between 1 and {document.page_count}"
            )

        page = document.load_page(page_number - 1)
        scale = PDF_RENDER_DPI / 72.0
        pixmap = page.get_pixmap(
            matrix=fitz.Matrix(scale, scale),
            colorspace=fitz.csRGB,
            alpha=False,
        )
        return Image.frombytes(
            "RGB",
            (pixmap.width, pixmap.height),
            pixmap.samples,
        )
    finally:
        document.close()


def open_image_page(data: bytes, page_number: int) -> Image.Image:
    try:
        image = Image.open(io.BytesIO(data))
        frame_count = getattr(image, "n_frames", 1)

        if page_number < 1 or page_number > frame_count:
            raise ValueError(
                f"Page/frame must be between 1 and {frame_count}"
            )

        image.seek(page_number - 1)
        return ImageOps.exif_transpose(image.copy()).convert("RGB")
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("Unsupported or invalid image") from exc


def encode_for_textract(image: Image.Image) -> bytes:
    image = image.convert("RGB")
    resampling = getattr(Image, "Resampling", Image).LANCZOS

    if max(image.size) > MAX_IMAGE_SIDE:
        scale = MAX_IMAGE_SIDE / max(image.size)
        image = image.resize(
            (
                max(1, int(image.width * scale)),
                max(1, int(image.height * scale)),
            ),
            resampling,
        )

    png_buffer = io.BytesIO()
    image.save(png_buffer, format="PNG", compress_level=3)

    if png_buffer.tell() <= MAX_TEXTRACT_BYTES:
        return png_buffer.getvalue()

    working_image = image

    while True:
        for quality in (92, 85, 75, 65):
            jpeg_buffer = io.BytesIO()
            working_image.save(
                jpeg_buffer,
                format="JPEG",
                quality=quality,
                subsampling=0,
            )
            if jpeg_buffer.tell() <= MAX_TEXTRACT_BYTES:
                return jpeg_buffer.getvalue()

        scale = math.sqrt(
            MAX_TEXTRACT_BYTES / max(jpeg_buffer.tell(), 1)
        ) * 0.9

        if scale >= 1:
            scale = 0.85

        new_size = (
            max(800, int(working_image.width * scale)),
            max(800, int(working_image.height * scale)),
        )

        if new_size == working_image.size:
            raise ValueError(
                "The page cannot be reduced below Textract's 5 MB limit"
            )

        working_image = working_image.resize(new_size, resampling)


def extract_page(
    data: bytes,
    content_type: str | None,
    page_number: int,
) -> dict[str, Any]:
    total_started = time.perf_counter()

    is_pdf = (
        content_type == "application/pdf"
        or data[:5].upper() == b"%PDF-"
    )

    if is_pdf:
        image = render_pdf_page(data, page_number)
    else:
        image = open_image_page(data, page_number)

    source_width, source_height = image.size
    document_bytes = encode_for_textract(image)

    api_started = time.perf_counter()
    response = textract.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES"],
    )
    api_latency_ms = round(
        (time.perf_counter() - api_started) * 1000, 1
    )

    return {
        "provider": "aws_textract",
        "operation": "AnalyzeDocument",
        "features": ["TABLES"],
        "page": page_number,
        "rendered_image": {
            "width": source_width,
            "height": source_height,
            "encoded_bytes": len(document_bytes),
        },
        "latency_ms": {
            "textract": api_latency_ms,
            "total": round(
                (time.perf_counter() - total_started) * 1000, 1
            ),
        },
        "tables": parse_textract_tables(response),
    }


@app.post("/extract-table")
async def extract_table(
    file: UploadFile = File(...),
    page: int = Query(default=1, ge=1),
) -> dict[str, Any]:
    data = await file.read(MAX_UPLOAD_BYTES + 1)

    if not data:
        raise HTTPException(status_code=400, detail="The file is empty")

    if len(data) > MAX_UPLOAD_BYTES:
        raise HTTPException(
            status_code=413,
            detail="The uploaded file exceeds 50 MB",
        )

    try:
        return await asyncio.to_thread(
            extract_page,
            data,
            file.content_type,
            page,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except (ReadTimeoutError, ConnectTimeoutError) as exc:
        raise HTTPException(
            status_code=504,
            detail="Textract did not finish within the preview latency budget",
        ) from exc
    except ClientError as exc:
        error = exc.response.get("Error", {})
        raise HTTPException(
            status_code=502,
            detail={
                "provider": "aws_textract",
                "code": error.get("Code", "Unknown"),
                "message": error.get("Message", str(exc)),
            },
        ) from exc


