```python
#!/usr/bin/env python3
"""
Receipt extraction with OpenAI's Batch API.

Recommended default:
  gpt-4.1-mini-2025-04-14 + Batch API

It provides better mixed-quality OCR than nano while remaining comfortably suited
to a $15k/month budget for ~3M mostly single-page receipts. Benchmark nano on a
representative sample before switching:

  export RECEIPT_MODEL=gpt-4.1-nano-2025-04-14

Install:
  pip install openai

Input manifest, one receipt per line:
  {"id":"receipt-001","url":"https://.../receipt-001.jpg","mime_type":"image/jpeg"}
  {"id":"receipt-002","url":"https://.../receipt-002.pdf","mime_type":"application/pdf"}

URLs should remain accessible for at least 48 hours. Long-lived signed object-store
URLs keep Batch JSONL files small; local files are supported for testing but are
embedded as base64 and are not recommended at this volume.

Typical asynchronous workflow:
  export OPENAI_API_KEY=...
  python receipts.py build receipts.jsonl ./receipt-job
  python receipts.py submit ./receipt-job --limit 10
  python receipts.py status ./receipt-job
  python receipts.py collect ./receipt-job ./receipt-output
  python receipts.py merge ./receipt-output results.jsonl errors.jsonl
  python receipts.py cleanup ./receipt-job
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import json
import mimetypes
import os
import shutil
import sqlite3
import sys
from collections import Counter
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

from openai import OpenAI


MODEL = os.getenv("RECEIPT_MODEL", "gpt-4.1-mini-2025-04-14")
BATCH_ENDPOINT = "/v1/responses"

# API limits are currently 50,000 requests and 200 MB per batch input file.
# Leave headroom for final newlines and API-side accounting.
MAX_REQUESTS_PER_SHARD = 45_000
MAX_BYTES_PER_SHARD = 190 * 1024 * 1024

SYSTEM_PROMPT = """
You extract accounting fields from English and Spanish receipts.

Use all provided pages as one receipt and return only the requested JSON object.

Rules:
- merchant: the business that sold the goods or services, not the card network,
  bank, payment processor, tax authority, or delivery intermediary unless that
  intermediary is actually the merchant.
- date: the transaction date in YYYY-MM-DD. Do not use print, upload, statement,
  due, or processing dates. Resolve day/month order from labels, language,
  address, and other receipt context. Return null if it cannot be resolved.
- currency: uppercase ISO 4217 code such as USD, EUR, MXN, GBP, CAD, or COP.
  Normalize printed currency names and unambiguous symbols. A bare "$" is not
  sufficient unless the merchant/address/receipt context makes the country clear.
- total: the final transaction amount actually charged or payable. Prefer a
  clearly labeled grand total or final charged amount. Do not return subtotal,
  tax, tip by itself, cash tendered, change, savings, or a post-payment balance
  of zero.
- Preserve the decimal value; do not convert currencies.
- Return null for unreadable or genuinely absent fields. Never invent text or
  numbers.
""".strip()

RECEIPT_SCHEMA = {
    "type": "object",
    "properties": {
        "merchant": {
            "type": ["string", "null"],
            "description": "Printed merchant/business name.",
        },
        "date": {
            "type": ["string", "null"],
            "description": "Transaction date normalized to YYYY-MM-DD.",
        },
        "currency": {
            "type": ["string", "null"],
            "description": "Uppercase ISO 4217 currency code.",
        },
        "total": {
            "type": ["number", "null"],
            "description": "Final transaction amount without currency symbols.",
        },
    },
    "required": ["merchant", "date", "currency", "total"],
    "additionalProperties": False,
}


def openai_client() -> OpenAI:
    return OpenAI(timeout=600.0, max_retries=5)


def is_http_url(value: str) -> bool:
    return value.startswith("https://") or value.startswith("http://")


def guess_mime(source: str) -> str | None:
    path = urlparse(source).path if is_http_url(source) else source
    mime, _ = mimetypes.guess_type(path)
    return mime


def file_data_url(path: Path, mime_type: str) -> str:
    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:{mime_type};base64,{encoded}"


def resolve_source(record: dict[str, Any], manifest_dir: Path) -> tuple[str, str]:
    source = record.get("url") or record.get("path") or record.get("source")
    if not isinstance(source, str) or not source:
        raise ValueError("Each manifest record needs url, path, or source")

    mime_type = record.get("mime_type") or guess_mime(source)
    if not isinstance(mime_type, str):
        raise ValueError(f"Cannot determine MIME type for {source!r}")

    mime_type = mime_type.lower().split(";", 1)[0].strip()

    if is_http_url(source):
        return source, mime_type

    path = Path(source)
    if not path.is_absolute():
        path = manifest_dir / path
    path = path.resolve()

    if not path.is_file():
        raise FileNotFoundError(path)

    return file_data_url(path, mime_type), mime_type


def make_input_content(source: str, mime_type: str) -> dict[str, Any]:
    if mime_type == "application/pdf":
        if is_http_url(source):
            return {
                "type": "input_file",
                "file_url": source,
            }
        return {
            "type": "input_file",
            "filename": "receipt.pdf",
            "file_data": source,
        }

    supported_images = {
        "image/jpeg",
        "image/jpg",
        "image/png",
        "image/webp",
        "image/gif",
    }
    if mime_type not in supported_images:
        raise ValueError(
            f"Unsupported MIME type {mime_type!r}; convert it to JPEG, PNG, "
            "WEBP, GIF, or PDF first"
        )

    return {
        "type": "input_image",
        "image_url": source,
        "detail": "high",
    }


def custom_id_for(receipt_id: str) -> str:
    digest = hashlib.sha256(receipt_id.encode("utf-8")).hexdigest()
    return f"receipt_{digest[:40]}"


def make_batch_request(
    custom_id: str,
    source: str,
    mime_type: str,
    model: str,
) -> dict[str, Any]:
    document_content = make_input_content(source, mime_type)

    return {
        "custom_id": custom_id,
        "method": "POST",
        "url": BATCH_ENDPOINT,
        "body": {
            "model": model,
            "store": False,
            "temperature": 0,
            "max_output_tokens": 160,
            "input": [
                {
                    "role": "system",
                    "content": [
                        {
                            "type": "input_text",
                            "text": SYSTEM_PROMPT,
                        }
                    ],
                },
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": "Extract the receipt fields from this document.",
                        },
                        document_content,
                    ],
                },
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": "receipt",
                    "strict": True,
                    "schema": RECEIPT_SCHEMA,
                }
            },
        },
    }


def init_index(path: Path) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute(
        """
        CREATE TABLE receipts (
            custom_id TEXT PRIMARY KEY,
            receipt_id TEXT NOT NULL UNIQUE
        )
        """
    )
    conn.commit()
    return conn


def cmd_build(args: argparse.Namespace) -> None:
    manifest = Path(args.manifest).resolve()
    workdir = Path(args.workdir).resolve()

    if not manifest.is_file():
        raise FileNotFoundError(manifest)

    if workdir.exists():
        if not args.force:
            raise FileExistsError(
                f"{workdir} already exists; use --force to replace it"
            )
        shutil.rmtree(workdir)

    shards_dir = workdir / "shards"
    shards_dir.mkdir(parents=True)

    conn = init_index(workdir / "index.sqlite")
    cursor = conn.cursor()

    shard_number = -1
    shard_file = None
    shard_size = 0
    shard_requests = 0
    total_requests = 0
    shard_stats: list[dict[str, Any]] = []

    def open_shard() -> None:
        nonlocal shard_number, shard_file, shard_size, shard_requests
        shard_number += 1
        shard_size = 0
        shard_requests = 0
        path = shards_dir / f"shard-{shard_number:05d}.jsonl"
        shard_file = path.open("wb")

    def close_shard() -> None:
        nonlocal shard_file
        if shard_file is None:
            return
        path = Path(shard_file.name)
        shard_file.close()
        shard_stats.append(
            {
                "name": path.name,
                "requests": shard_requests,
                "bytes": shard_size,
            }
        )
        conn.commit()
        shard_file = None

    model = args.model or MODEL
    manifest_dir = manifest.parent

    try:
        with manifest.open("r", encoding="utf-8") as source_file:
            for line_number, raw_line in enumerate(source_file, start=1):
                raw_line = raw_line.strip()
                if not raw_line:
                    continue

                try:
                    record = json.loads(raw_line)
                    receipt_id = str(record["id"])
                    if not receipt_id:
                        raise ValueError("id cannot be empty")

                    source, mime_type = resolve_source(record, manifest_dir)
                    custom_id = custom_id_for(receipt_id)
                    request = make_batch_request(
                        custom_id=custom_id,
                        source=source,
                        mime_type=mime_type,
                        model=model,
                    )
                    encoded = (
                        json.dumps(
                            request,
                            ensure_ascii=False,
                            separators=(",", ":"),
                        ).encode("utf-8")
                        + b"\n"
                    )
                except Exception as exc:
                    raise ValueError(
                        f"Invalid manifest line {line_number}: {exc}"
                    ) from exc

                if len(encoded) > MAX_BYTES_PER_SHARD:
                    raise ValueError(
                        f"Receipt {receipt_id!r} creates a request larger than "
                        f"{MAX_BYTES_PER_SHARD} bytes. Use an HTTPS URL rather "
                        "than embedding the local file."
                    )

                if shard_file is None:
                    open_shard()
                elif (
                    shard_requests >= MAX_REQUESTS_PER_SHARD
                    or shard_size + len(encoded) > MAX_BYTES_PER_SHARD
                ):
                    close_shard()
                    open_shard()

                try:
                    cursor.execute(
                        "INSERT INTO receipts(custom_id, receipt_id) VALUES (?, ?)",
                        (custom_id, receipt_id),
                    )
                except sqlite3.IntegrityError as exc:
                    raise ValueError(
                        f"Duplicate receipt id at manifest line {line_number}: "
                        f"{receipt_id!r}"
                    ) from exc

                shard_file.write(encoded)
                shard_size += len(encoded)
                shard_requests += 1
                total_requests += 1
    finally:
        close_shard()
        conn.close()

    build_info = {
        "model": model,
        "endpoint": BATCH_ENDPOINT,
        "receipts": total_requests,
        "shards": shard_stats,
    }
    (workdir / "build.json").write_text(
        json.dumps(build_info, indent=2),
        encoding="utf-8",
    )
    save_state(workdir, {})

    print(
        json.dumps(
            {
                "workdir": str(workdir),
                "model": model,
                "receipts": total_requests,
                "shards": len(shard_stats),
            },
            indent=2,
        )
    )


def state_path(workdir: Path) -> Path:
    return workdir / "batches.json"


def load_state(workdir: Path) -> dict[str, dict[str, Any]]:
    path = state_path(workdir)
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def save_state(workdir: Path, state: dict[str, dict[str, Any]]) -> None:
    path = state_path(workdir)
    temporary = path.with_suffix(".tmp")
    temporary.write_text(
        json.dumps(state, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    temporary.replace(path)


def cmd_submit(args: argparse.Namespace) -> None:
    workdir = Path(args.workdir).resolve()
    shards_dir = workdir / "shards"

    if not shards_dir.is_dir():
        raise FileNotFoundError(shards_dir)

    state = load_state(workdir)
    client = openai_client()
    submitted = 0

    for shard in sorted(shards_dir.glob("*.jsonl")):
        if submitted >= args.limit:
            break

        record = state.setdefault(shard.name, {})

        if record.get("batch_id"):
            continue

        if not record.get("input_file_id"):
            with shard.open("rb") as file_handle:
                uploaded = client.files.create(
                    file=file_handle,
                    purpose="batch",
                )
            record["input_file_id"] = uploaded.id
            save_state(workdir, state)

        batch = client.batches.create(
            input_file_id=record["input_file_id"],
            endpoint=BATCH_ENDPOINT,
            completion_window="24h",
            metadata={
                "job": "receipt-extraction",
                "shard": shard.stem,
            },
        )

        record.update(
            {
                "batch_id": batch.id,
                "status": batch.status,
                "output_file_id": getattr(batch, "output_file_id", None),
                "error_file_id": getattr(batch, "error_file_id", None),
                "collected": False,
                "cleaned": False,
            }
        )
        save_state(workdir, state)
        submitted += 1

        print(
            json.dumps(
                {
                    "shard": shard.name,
                    "batch_id": batch.id,
                    "status": batch.status,
                }
            )
        )

    print(json.dumps({"submitted": submitted}))


def refresh_state(
    workdir: Path,
    client: OpenAI,
) -> dict[str, dict[str, Any]]:
    state = load_state(workdir)

    for record in state.values():
        batch_id = record.get("batch_id")
        if not batch_id:
            continue

        batch = client.batches.retrieve(batch_id)
        counts = getattr(batch, "request_counts", None)

        record.update(
            {
                "status": batch.status,
                "output_file_id": getattr(batch, "output_file_id", None),
                "error_file_id": getattr(batch, "error_file_id", None),
                "request_counts": (
                    counts.model_dump()
                    if counts is not None and hasattr(counts, "model_dump")
                    else None
                ),
            }
        )

    save_state(workdir, state)
    return state


def cmd_status(args: argparse.Namespace) -> None:
    workdir = Path(args.workdir).resolve()
    client = openai_client()
    state = refresh_state(workdir, client)

    statuses = Counter(
        record.get("status", "not_submitted") for record in state.values()
    )
    print(json.dumps(dict(sorted(statuses.items())), indent=2))


def download_api_file(client: OpenAI, file_id: str, destination: Path) -> None:
    response = client.files.content(file_id)

    if hasattr(response, "write_to_file"):
        response.write_to_file(destination)
        return

    content = getattr(response, "content", None)
    if content is None and hasattr(response, "read"):
        content = response.read()
    if content is None:
        raise RuntimeError(f"Could not read API file {file_id}")

    destination.write_bytes(content)


def response_output_text(body: dict[str, Any]) -> str:
    for output_item in body.get("output", []):
        if output_item.get("type") != "message":
            continue
        for content in output_item.get("content", []):
            if content.get("type") == "output_text":
                return content["text"]
    raise ValueError("Response contained no output_text")


def receipt_id_for(
    cursor: sqlite3.Cursor,
    custom_id: str | None,
) -> str | None:
    if not custom_id:
        return None
    row = cursor.execute(
        "SELECT receipt_id FROM receipts WHERE custom_id = ?",
        (custom_id,),
    ).fetchone()
    return row[0] if row else None


def normalize_result(data: dict[str, Any]) -> dict[str, Any]:
    merchant = data.get("merchant")
    date = data.get("date")
    currency = data.get("currency")
    total = data.get("total")

    if merchant is not None and not isinstance(merchant, str):
        raise ValueError("merchant is not a string or null")
    if date is not None and not isinstance(date, str):
        raise ValueError("date is not a string or null")
    if currency is not None and not isinstance(currency, str):
        raise ValueError("currency is not a string or null")
    if total is not None and (
        isinstance(total, bool) or not isinstance(total, (int, float))
    ):
        raise ValueError("total is not a number or null")

    if isinstance(merchant, str):
        merchant = merchant.strip() or None
    if isinstance(date, str):
        date = date.strip() or None
    if isinstance(currency, str):
        currency = currency.strip().upper() or None

    return {
        "merchant": merchant,
        "date": date,
        "currency": currency,
        "total": total,
    }


def cmd_collect(args: argparse.Namespace) -> None:
    workdir = Path(args.workdir).resolve()
    output_dir = Path(args.output_dir).resolve()
    output_dir.mkdir(parents=True, exist_ok=True)

    client = openai_client()
    state = refresh_state(workdir, client)
    conn = sqlite3.connect(workdir / "index.sqlite")
    cursor = conn.cursor()
    collected = 0

    try:
        for shard_name, record in sorted(state.items()):
            if record.get("status") != "completed":
                continue

            result_path = output_dir / f"{Path(shard_name).stem}.results.jsonl"
            error_path = output_dir / f"{Path(shard_name).stem}.errors.jsonl"

            if record.get("collected") and result_path.exists():
                continue

            result_tmp = result_path.with_suffix(".results.tmp")
            error_tmp = error_path.with_suffix(".errors.tmp")
            raw_output = output_dir / f".{Path(shard_name).stem}.raw-output.tmp"
            raw_errors = output_dir / f".{Path(shard_name).stem}.raw-errors.tmp"

            with result_tmp.open("w", encoding="utf-8") as results, error_tmp.open(
                "w", encoding="utf-8"
            ) as errors:
                output_file_id = record.get("output_file_id")

                if output_file_id:
                    download_api_file(client, output_file_id, raw_output)

                    with raw_output.open("r", encoding="utf-8") as raw:
                        for line in raw:
                            if not line.strip():
                                continue

                            batch_line = json.loads(line)
                            custom_id = batch_line.get("custom_id")
                            receipt_id = receipt_id_for(cursor, custom_id)
                            response = batch_line.get("response") or {}
                            status_code = response.get("status_code")

                            if status_code != 200:
                                errors.write(
                                    json.dumps(
                                        {
                                            "receipt_id": receipt_id,
                                            "custom_id": custom_id,
                                            "error": batch_line.get("error")
                                            or response,
                                        },
                                        ensure_ascii=False,
                                    )
                                    + "\n"
                                )
                                continue

                            try:
                                text = response_output_text(response["body"])
                                extracted = normalize_result(json.loads(text))
                                results.write(
                                    json.dumps(
                                        {
                                            "receipt_id": receipt_id,
                                            **extracted,
                                        },
                                        ensure_ascii=False,
                                        separators=(",", ":"),
                                    )
                                    + "\n"
                                )
                            except Exception as exc:
                                errors.write(
                                    json.dumps(
                                        {
                                            "receipt_id": receipt_id,
                                            "custom_id": custom_id,
                                            "error": str(exc),
                                            "response": response.get("body"),
                                        },
                                        ensure_ascii=False,
                                    )
                                    + "\n"
                                )

                error_file_id = record.get("error_file_id")
                if error_file_id:
                    download_api_file(client, error_file_id, raw_errors)

                    with raw_errors.open("r", encoding="utf-8") as raw:
                        for line in raw:
                            if not line.strip():
                                continue
                            item = json.loads(line)
                            custom_id = item.get("custom_id")
                            errors.write(
                                json.dumps(
                                    {
                                        "receipt_id": receipt_id_for(
                                            cursor, custom_id
                                        ),
                                        "custom_id": custom_id,
                                        "error": item.get("error") or item,
                                    },
                                    ensure_ascii=False,
                                )
                                + "\n"
                            )

            result_tmp.replace(result_path)
            error_tmp.replace(error_path)
            raw_output.unlink(missing_ok=True)
            raw_errors.unlink(missing_ok=True)

            record["collected"] = True
            save_state(workdir, state)
            collected += 1
    finally:
        conn.close()

    print(json.dumps({"collected_batches": collected}))


def cmd_merge(args: argparse.Namespace) -> None:
    output_dir = Path(args.output_dir).resolve()
    results_destination = Path(args.results).resolve()
    errors_destination = Path(args.errors).resolve()

    with results_destination.open("wb") as destination:
        for part in sorted(output_dir.glob("*.results.jsonl")):
            with part.open("rb") as source:
                shutil.copyfileobj(source, destination)

    with errors_destination.open("wb") as destination:
        for part in sorted(output_dir.glob("*.errors.jsonl")):
            with part.open("rb") as source:
                shutil.copyfileobj(source, destination)

    print(
        json.dumps(
            {
                "results": str(results_destination),
                "errors": str(errors_destination),
            },
            indent=2,
        )
    )


def cmd_cleanup(args: argparse.Namespace) -> None:
    workdir = Path(args.workdir).resolve()
    state = load_state(workdir)
    client = openai_client()
    cleaned = 0

    terminal_statuses = {"completed", "failed", "expired", "cancelled"}

    for record in state.values():
        if record.get("cleaned"):
            continue
        if record.get("status") not in terminal_statuses:
            continue
        if record.get("status") == "completed" and not record.get("collected"):
            continue

        for key in ("input_file_id", "output_file_id", "error_file_id"):
            file_id = record.get(key)
            if not file_id:
                continue
            try:
                client.files.delete(file_id)
            except Exception as exc:
                print(
                    f"Warning: could not delete {file_id}: {exc}",
                    file=sys.stderr,
                )

        record["cleaned"] = True
        cleaned += 1
        save_state(workdir, state)

    print(json.dumps({"cleaned_batches": cleaned}))


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Asynchronous receipt extraction with OpenAI Batch API"
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    build = subparsers.add_parser("build")
    build.add_argument("manifest")
    build.add_argument("workdir")
    build.add_argument("--model", default=MODEL)
    build.add_argument("--force", action="store_true")
    build.set_defaults(func=cmd_build)

    submit = subparsers.add_parser("submit")
    submit.add_argument("workdir")
    submit.add_argument(
        "--limit",
        type=int,
        default=10,
        help="Maximum number of new shards to submit in this invocation",
    )
    submit.set_defaults(func=cmd_submit)

    status = subparsers.add_parser("status")
    status.add_argument("workdir")
    status.set_defaults(func=cmd_status)

    collect = subparsers.add_parser("collect")
    collect.add_argument("workdir")
    collect.add_argument("output_dir")
    collect.set_defaults(func=cmd_collect)

    merge = subparsers.add_parser("merge")
    merge.add_argument("output_dir")
    merge.add_argument("results")
    merge.add_argument("errors")
    merge.set_defaults(func=cmd_merge)

    cleanup = subparsers.add_parser("cleanup")
    cleanup.add_argument("workdir")
    cleanup.set_defaults(func=cmd_cleanup)

    return parser


def main() -> None:
    parser = build_parser()
    args = parser.parse_args()
    args.func(args)


