from __future__ import annotations

import argparse
import asyncio
import json
import os
import random
import re
import sys
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Iterator

import httpx
from pypdf import PdfReader


API_BASE = os.getenv("MISTRAL_API_BASE", "https://api.mistral.ai/v1")
API_KEY = os.getenv("MISTRAL_API_KEY")
OCR_MODEL = os.getenv("MISTRAL_OCR_MODEL", "mistral-ocr-latest")

RETRYABLE_STATUS = {408, 409, 425, 429, 500, 502, 503, 504}
MAX_HTTP_ATTEMPTS = 8
DOCUMENT_ANNOTATION_ATTEMPTS = 2

ANNOTATION_SCHEMA = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "supplier_id": {
            "anyOf": [{"type": "string"}, {"type": "null"}],
            "description": (
                "The supplier/vendor identifier printed on the invoice. Prefer "
                "fields explicitly labeled Supplier ID, Vendor ID, Supplier Code, "
                "Codice fornitore, or Codice cliente. If none exists, use the "
                "supplier VAT/tax identifier such as Partita IVA. Return only the "
                "identifier, not the supplier name."
            ),
        },
        "invoice_date": {
            "anyOf": [
                {
                    "type": "string",
                    "pattern": r"^\d{4}-\d{2}-\d{2}$",
                },
                {"type": "null"},
            ],
            "description": (
                "The invoice issue date, not the due date, normalized to ISO "
                "YYYY-MM-DD."
            ),
        },
        "currency": {
            "anyOf": [
                {
                    "type": "string",
                    "pattern": r"^[A-Z]{3}$",
                },
                {"type": "null"},
            ],
            "description": (
                "The invoice currency as an uppercase ISO 4217 code, for example "
                "EUR, USD, or GBP. Infer it from an unambiguous currency symbol "
                "when necessary."
            ),
        },
        "total": {
            "anyOf": [
                {
                    "type": "string",
                    "pattern": r"^-?[0-9]+(?:\.[0-9]+)?$",
                },
                {"type": "null"},
            ],
            "description": (
                "The final invoice total including taxes, or the credit-note total. "
                "Return a plain decimal string with a period as decimal separator, "
                "no currency symbol, and no thousands separators."
            ),
        },
    },
    "required": ["supplier_id", "invoice_date", "currency", "total"],
}


class APIError(RuntimeError):
    pass


def iter_pdfs(root: Path) -> Iterator[Path]:
    for current_root, directories, filenames in os.walk(root):
        directories.sort()
        for filename in sorted(filenames):
            if filename.lower().endswith(".pdf"):
                yield Path(current_root) / filename


def output_path_for(source: Path, input_root: Path, output_root: Path) -> Path:
    return output_root / source.relative_to(input_root).with_suffix(".json")


def count_pdf_pages(path: Path) -> int:
    reader = PdfReader(str(path), strict=False)
    if reader.is_encrypted:
        try:
            reader.decrypt("")
        except Exception as exc:
            raise RuntimeError(f"Cannot count pages in encrypted PDF: {path}") from exc

    count = len(reader.pages)
    if count < 1:
        raise RuntimeError(f"PDF has no pages: {path}")
    return count


def count_all_pages(input_root: Path) -> tuple[int, int]:
    documents = 0
    pages = 0

    for path in iter_pdfs(input_root):
        documents += 1
        pages += count_pdf_pages(path)
        if documents % 10_000 == 0:
            print(
                f"Preflight: {documents:,} PDFs, {pages:,} pages",
                file=sys.stderr,
            )

    return documents, pages


def normalize_annotation(annotation: Any) -> dict[str, Any]:
    if isinstance(annotation, str):
        text = annotation.strip()
        if text.startswith("```"):
            text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
            text = re.sub(r"\s*```$", "", text)
        annotation = json.loads(text)

    if not isinstance(annotation, dict):
        raise ValueError("Document annotation is not a JSON object")

    unexpected = set(annotation) - {
        "supplier_id",
        "invoice_date",
        "currency",
        "total",
    }
    if unexpected:
        raise ValueError(f"Unexpected annotation fields: {sorted(unexpected)}")

    supplier_id = annotation.get("supplier_id")
    if supplier_id is not None:
        supplier_id = str(supplier_id).strip() or None

    invoice_date = annotation.get("invoice_date")
    if invoice_date is not None:
        invoice_date = str(invoice_date).strip()
        parsed_date = date.fromisoformat(invoice_date)
        invoice_date = parsed_date.isoformat()

    currency = annotation.get("currency")
    if currency is not None:
        currency = str(currency).strip().upper()
        if not re.fullmatch(r"[A-Z]{3}", currency):
            raise ValueError(f"Invalid ISO currency code: {currency!r}")

    total = annotation.get("total")
    if total is not None:
        total_text = str(total).strip()

        if not re.fullmatch(r"-?[0-9]+(?:\.[0-9]+)?", total_text):
            raise ValueError(f"Invalid normalized invoice total: {total_text!r}")

        try:
            amount = Decimal(total_text)
        except InvalidOperation as exc:
            raise ValueError(f"Invalid invoice total: {total_text!r}") from exc

        if not amount.is_finite():
            raise ValueError("Invoice total is not finite")

        total = format(amount, "f")

    return {
        "supplier_id": supplier_id,
        "invoice_date": invoice_date,
        "currency": currency,
        # Stored as a decimal string to avoid binary floating-point corruption.
        "total": total,
    }


def atomic_write_json(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{random.randrange(1_000_000_000)}.tmp"
    )
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, path)


def retry_delay(attempt: int, response: httpx.Response | None = None) -> float:
    if response is not None:
        retry_after = response.headers.get("Retry-After")
        if retry_after:
            try:
                return min(120.0, max(0.0, float(retry_after)))
            except ValueError:
                pass

    return min(60.0, (2**attempt) + random.random())


class MistralOCR:
    def __init__(self, api_key: str):
        self.client = httpx.AsyncClient(
            base_url=API_BASE,
            headers={
                "Authorization": f"Bearer {api_key}",
                "Accept": "application/json",
                "User-Agent": "invoice-field-extractor/1.0",
            },
            timeout=httpx.Timeout(
                connect=30.0,
                read=600.0,
                write=600.0,
                pool=60.0,
            ),
            limits=httpx.Limits(
                max_connections=256,
                max_keepalive_connections=128,
            ),
        )

    async def close(self) -> None:
        await self.client.aclose()

    async def json_request(
        self,
        method: str,
        endpoint: str,
        *,
        allow_404: bool = False,
        **kwargs: Any,
    ) -> dict[str, Any]:
        last_error: Exception | None = None

        for attempt in range(MAX_HTTP_ATTEMPTS):
            response: httpx.Response | None = None
            try:
                response = await self.client.request(method, endpoint, **kwargs)

                if allow_404 and response.status_code == 404:
                    return {}

                if 200 <= response.status_code < 300:
                    if not response.content:
                        return {}
                    result = response.json()
                    if not isinstance(result, dict):
                        raise APIError(
                            f"{method} {endpoint} returned a non-object response"
                        )
                    return result

                if response.status_code not in RETRYABLE_STATUS:
                    body = response.text[:1000]
                    raise APIError(
                        f"{method} {endpoint} failed with "
                        f"HTTP {response.status_code}: {body}"
                    )

                last_error = APIError(
                    f"{method} {endpoint} temporarily failed with "
                    f"HTTP {response.status_code}"
                )

            except (httpx.TimeoutException, httpx.TransportError) as exc:
                last_error = exc

            if attempt + 1 < MAX_HTTP_ATTEMPTS:
                await asyncio.sleep(retry_delay(attempt, response))

        raise APIError(
            f"{method} {endpoint} failed after {MAX_HTTP_ATTEMPTS} attempts"
        ) from last_error

    async def upload_pdf(self, path: Path) -> str:
        last_error: Exception | None = None

        for attempt in range(MAX_HTTP_ATTEMPTS):
            response: httpx.Response | None = None
            try:
                with path.open("rb") as pdf:
                    response = await self.client.post(
                        "/files",
                        data={"purpose": "ocr"},
                        files={
                            "file": (
                                path.name,
                                pdf,
                                "application/pdf",
                            )
                        },
                    )

                if 200 <= response.status_code < 300:
                    data = response.json()
                    file_id = data.get("id")
                    if not file_id:
                        raise APIError("File upload response did not contain an ID")
                    return str(file_id)

                if response.status_code not in RETRYABLE_STATUS:
                    raise APIError(
                        f"Upload failed with HTTP {response.status_code}: "
                        f"{response.text[:1000]}"
                    )

                last_error = APIError(
                    f"Upload temporarily failed with HTTP {response.status_code}"
                )

            except (httpx.TimeoutException, httpx.TransportError) as exc:
                last_error = exc

            if attempt + 1 < MAX_HTTP_ATTEMPTS:
                await asyncio.sleep(retry_delay(attempt, response))

        raise APIError(
            f"Upload failed after {MAX_HTTP_ATTEMPTS} attempts: {path}"
        ) from last_error

    async def signed_url(self, file_id: str) -> str:
        data = await self.json_request(
            "GET",
            f"/files/{file_id}/url",
            params={"expiry": 24},
        )
        url = data.get("url")
        if not url:
            raise APIError("Signed URL response did not contain a URL")
        return str(url)

    async def delete_file(self, file_id: str) -> None:
        await self.json_request(
            "DELETE",
            f"/files/{file_id}",
            allow_404=True,
        )

    async def extract(self, document_url: str) -> dict[str, Any]:
        payload = {
            "model": OCR_MODEL,
            "document": {
                "type": "document_url",
                "document_url": document_url,
            },
            "include_image_base64": False,
            "document_annotation_format": {
                "type": "json_schema",
                "json_schema": {
                    "name": "invoice_fields",
                    "description": (
                        "Extract only the requested accounting fields from an "
                        "English or Italian invoice."
                    ),
                    "strict": True,
                    "schema": ANNOTATION_SCHEMA,
                },
            },
        }

        last_error: Exception | None = None

        for attempt in range(DOCUMENT_ANNOTATION_ATTEMPTS):
            try:
                response = await self.json_request(
                    "POST",
                    "/ocr",
                    json=payload,
                )

                annotation = response.get("document_annotation")
                if annotation is None:
                    raise ValueError(
                        "OCR response did not contain document_annotation"
                    )

                return normalize_annotation(annotation)

            except (ValueError, json.JSONDecodeError) as exc:
                last_error = exc
                if attempt + 1 < DOCUMENT_ANNOTATION_ATTEMPTS:
                    await asyncio.sleep(1.0 + random.random())

        raise ValueError("Could not obtain a valid invoice annotation") from last_error


async def process_pdf(
    api: MistralOCR,
    source: Path,
    destination: Path,
) -> None:
    file_id: str | None = None

    try:
        file_id = await api.upload_pdf(source)
        url = await api.signed_url(file_id)
        fields = await api.extract(url)
        await asyncio.to_thread(atomic_write_json, destination, fields)
    finally:
        if file_id is not None:
            try:
                await api.delete_file(file_id)
            except Exception as exc:
                print(
                    f"Warning: could not delete hosted file {file_id}: {exc}",
                    file=sys.stderr,
                )


async def run_pipeline(args: argparse.Namespace) -> int:
    input_root = args.input.resolve()
    output_root = args.output.resolve()

    if not input_root.is_dir():
        raise SystemExit(f"Input directory does not exist: {input_root}")

    output_root.mkdir(parents=True, exist_ok=True)

    if args.known_pages is None:
        document_count, page_count = await asyncio.to_thread(
            count_all_pages,
            input_root,
        )
    else:
        document_count = sum(1 for _ in iter_pdfs(input_root))
        page_count = args.known_pages

    if document_count == 0:
        print("No PDF files found.", file=sys.stderr)
        return 0

    estimated_cost = (
        Decimal(page_count)
        / Decimal(1000)
        * args.effective_price
        * args.retry_reserve
    )

    print(
        f"Documents: {document_count:,}\n"
        f"Pages: {page_count:,}\n"
        f"Budgeted all-in rate: ${args.effective_price}/1,000 pages\n"
        f"Retry reserve: {args.retry_reserve}x\n"
        f"Estimated extraction cost: ${estimated_cost:,.2f}\n"
        f"Monthly budget: ${args.budget:,.2f}",
        file=sys.stderr,
    )

    if estimated_cost > args.budget:
        raise SystemExit(
            f"Refusing to start: estimated cost ${estimated_cost:,.2f} "
            f"exceeds the ${args.budget:,.2f} monthly budget."
        )

    api = MistralOCR(API_KEY)
    queue: asyncio.Queue[tuple[Path, Path] | None] = asyncio.Queue(
        maxsize=args.concurrency * 2
    )
    failure_lock = asyncio.Lock()
    progress_lock = asyncio.Lock()
    failures_path = output_root / "_failures.jsonl"

    completed = 0
    failed = 0
    skipped = 0

    async def record_failure(source: Path, exc: Exception) -> None:
        entry = {
            "source": str(source.relative_to(input_root)),
            "error": f"{type(exc).__name__}: {exc}",
        }
        line = json.dumps(entry, ensure_ascii=False) + "\n"

        async with failure_lock:
            await asyncio.to_thread(
                append_text,
                failures_path,
                line,
            )

    async def worker() -> None:
        nonlocal completed, failed

        while True:
            item = await queue.get()
            try:
                if item is None:
                    return

                source, destination = item
                try:
                    await process_pdf(api, source, destination)
                    async with progress_lock:
                        completed += 1
                        processed = completed + failed
                        if processed % args.progress_every == 0:
                            print(
                                f"Processed {processed:,}: "
                                f"{completed:,} completed, {failed:,} failed",
                                file=sys.stderr,
                            )
                except Exception as exc:
                    await record_failure(source, exc)
                    async with progress_lock:
                        failed += 1
                        print(
                            f"Failed: {source}: {exc}",
                            file=sys.stderr,
                        )
            finally:
                queue.task_done()

    workers = [
        asyncio.create_task(worker())
        for _ in range(args.concurrency)
    ]

    try:
        for source in iter_pdfs(input_root):
            destination = output_path_for(source, input_root, output_root)

            if destination.exists() and not args.overwrite:
                skipped += 1
                continue

            await queue.put((source, destination))

        for _ in workers:
            await queue.put(None)

