Usage:
    python invoice_extract.py invoice.pdf
    python invoice_extract.py invoices/ --output-dir extracted/ --workers 4

Amounts and quantities are emitted as strings to avoid JSON floating-point
rounding. Documents with low-confidence critical fields or failed arithmetic
checks are marked review_required and should not be sent directly for payment.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import mimetypes
import os
import re
import statistics
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Iterable

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import DocumentAnalysisFeature
from azure.core.credentials import AzureKeyCredential


CRITICAL_CONFIDENCE = Decimal("0.99")
TEXT_CONFIDENCE = Decimal("0.97")
MONEY_TOLERANCE = Decimal("0.02")
SUPPORTED_EXTENSIONS = {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp"}


def decimal_text(value: Any) -> str | None:
    if value is None:
        return None
    try:
        return format(Decimal(str(value)), "f")
    except (InvalidOperation, ValueError, TypeError):
        return str(value)


def snake_case(name: str) -> str:
    name = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", name)
    return re.sub(r"[^a-zA-Z0-9]+", "_", name).strip("_").lower()


def address_value(address: Any) -> dict[str, Any]:
    attributes = (
        "house_number",
        "po_box",
        "road",
        "city",
        "city_district",
        "state",
        "state_district",
        "postal_code",
        "country_region",
        "street_address",
        "unit",
        "level",
        "suburb",
    )
    return {
        key: value
        for key in attributes
        if (value := getattr(address, key, None)) not in (None, "")
    }


def field_value(field: Any) -> Any:
    if field is None:
        return None

    currency = getattr(field, "value_currency", None)
    if currency is not None:
        return {
            "amount": decimal_text(getattr(currency, "amount", None)),
            "currency_code": getattr(currency, "currency_code", None),
            "currency_symbol": getattr(currency, "currency_symbol", None),
        }

    address = getattr(field, "value_address", None)
    if address is not None:
        result = address_value(address)
        return result or getattr(field, "content", None)

    array = getattr(field, "value_array", None)
    if array is not None:
        return [field_value(item) for item in array]

    obj = getattr(field, "value_object", None)
    if obj is not None:
        return {snake_case(key): field_value(value) for key, value in obj.items()}

    for attribute in ("value_number", "value_integer"):
        value = getattr(field, attribute, None)
        if value is not None:
            return decimal_text(value)

    for attribute in ("value_date", "value_time"):
        value = getattr(field, attribute, None)
        if value is not None:
            return value.isoformat()

    for attribute in (
        "value_string",
        "value_phone_number",
        "value_country_region",
        "value_selection_mark",
        "value_signature",
    ):
        value = getattr(field, attribute, None)
        if value is not None:
            return value

    return getattr(field, "content", None)


def get_value(fields: dict[str, Any], name: str) -> Any:
    return field_value(fields.get(name))


def numeric_field(field: Any) -> Decimal | None:
    if field is None:
        return None

    currency = getattr(field, "value_currency", None)
    raw = getattr(currency, "amount", None) if currency is not None else None

    if raw is None:
        raw = getattr(field, "value_number", None)
    if raw is None:
        raw = getattr(field, "value_integer", None)

    try:
        return Decimal(str(raw)) if raw is not None else None
    except (InvalidOperation, ValueError, TypeError):
        return None


def field_confidence(field: Any) -> Decimal | None:
    confidence = getattr(field, "confidence", None) if field is not None else None
    return Decimal(str(confidence)) if confidence is not None else None


def page_numbers(field: Any) -> list[int]:
    return sorted(
        {
            region.page_number
            for region in (getattr(field, "bounding_regions", None) or [])
            if getattr(region, "page_number", None) is not None
        }
    )


def collect_evidence(
    fields: dict[str, Any],
    prefix: str = "",
    output: dict[str, Any] | None = None,
) -> dict[str, Any]:
    output = output if output is not None else {}

    for name, field in fields.items():
        path = f"{prefix}.{name}" if prefix else name
        confidence = getattr(field, "confidence", None)
        content = getattr(field, "content", None)
        pages = page_numbers(field)

        if confidence is not None or content or pages:
            output[path] = {
                "raw_text": content,
                "confidence": confidence,
                "pages": pages,
            }

        obj = getattr(field, "value_object", None)
        if obj:
            collect_evidence(obj, path, output)

        array = getattr(field, "value_array", None)
        if array:
            for index, item in enumerate(array):
                item_path = f"{path}[{index}]"
                item_obj = getattr(item, "value_object", None)
                if item_obj:
                    collect_evidence(item_obj, item_path, output)
                else:
                    output[item_path] = {
                        "raw_text": getattr(item, "content", None),
                        "confidence": getattr(item, "confidence", None),
                        "pages": page_numbers(item),
                    }

    return output


def extract_line_items(fields: dict[str, Any]) -> list[dict[str, Any]]:
    items_field = fields.get("Items")
    items = getattr(items_field, "value_array", None) or []
    extracted = []

    for item in items:
        item_fields = getattr(item, "value_object", None)
        if item_fields is None:
            extracted.append({"raw_value": field_value(item)})
            continue

        # Generic extraction preserves every column returned by the API.
        extracted.append(
            {snake_case(name): field_value(value) for name, value in item_fields.items()}
        )

    return extracted


def require_confidence(
    field: Any,
    label: str,
    threshold: Decimal,
    reasons: list[str],
    required: bool = True,
) -> None:
    if field is None:
        if required:
            reasons.append(f"Missing required field: {label}")
        return

    confidence = field_confidence(field)
    if confidence is None:
        reasons.append(f"No confidence score for critical field: {label}")
    elif confidence < threshold:
        reasons.append(
            f"Low confidence for {label}: {confidence} < {threshold}"
        )


def close_enough(left: Decimal, right: Decimal) -> bool:
    return abs(left - right) <= MONEY_TOLERANCE


def validate_invoice(fields: dict[str, Any]) -> list[str]:
    reasons: list[str] = []

    require_confidence(fields.get("VendorName"), "supplier name", TEXT_CONFIDENCE, reasons)
    require_confidence(fields.get("InvoiceId"), "invoice number", CRITICAL_CONFIDENCE, reasons)
    require_confidence(fields.get("InvoiceTotal"), "invoice total", CRITICAL_CONFIDENCE, reasons)

    for name, label in (
        ("SubTotal", "subtotal"),
        ("TotalTax", "total tax"),
        ("TotalDiscount", "total discount"),
        ("TotalShipping", "total shipping"),
        ("AmountDue", "amount due"),
    ):
        if fields.get(name) is not None:
            require_confidence(fields[name], label, CRITICAL_CONFIDENCE, reasons)

    items_field = fields.get("Items")
    items = getattr(items_field, "value_array", None) or []
    if not items:
        reasons.append("No line items detected")

    line_amounts: list[Decimal] = []

    for index, item in enumerate(items, start=1):
        item_fields = getattr(item, "value_object", None) or {}
        description = item_fields.get("Description")
        amount = item_fields.get("Amount")
        quantity = item_fields.get("Quantity")
        unit_price = item_fields.get("UnitPrice")
        tax = item_fields.get("Tax")
        tax_rate = item_fields.get("TaxRate")

        require_confidence(
            description,
            f"line {index} description",
            TEXT_CONFIDENCE,
            reasons,
        )
        require_confidence(
            amount,
            f"line {index} amount",
            CRITICAL_CONFIDENCE,
            reasons,
        )

        for field, label in (
            (quantity, "quantity"),
            (unit_price, "unit price"),
            (tax, "tax"),
            (tax_rate, "tax rate"),
        ):
            if field is not None:
                require_confidence(
                    field,
                    f"line {index} {label}",
                    CRITICAL_CONFIDENCE,
                    reasons,
                )

        amount_number = numeric_field(amount)
        quantity_number = numeric_field(quantity)
        unit_price_number = numeric_field(unit_price)

        if amount_number is not None:
            line_amounts.append(amount_number)

        if unit_price is not None and quantity is None:
            reasons.append(f"Line {index} has unit price but no detected quantity")

        if (
            amount_number is not None
            and quantity_number is not None
            and unit_price_number is not None
        ):
            expected = quantity_number * unit_price_number
            if not close_enough(amount_number, expected):
                reasons.append(
                    f"Line {index} arithmetic mismatch: "
                    f"amount {amount_number} != quantity {quantity_number} "
                    f"* unit price {unit_price_number}"
                )

    subtotal = numeric_field(fields.get("SubTotal"))
    total_tax = numeric_field(fields.get("TotalTax"))
    total_discount = numeric_field(fields.get("TotalDiscount")) or Decimal("0")
    total_shipping = numeric_field(fields.get("TotalShipping")) or Decimal("0")
