    }


def find_documents(inputs: Iterable[str]) -> list[Path]:
    documents: list[Path] = []

    for raw_path in inputs:
        path = Path(raw_path)
        if path.is_file() and path.suffix.lower() in SUPPORTED_EXTENSIONS:
            documents.append(path)
        elif path.is_dir():
            documents.extend(
                child
                for child in path.rglob("*")
                if child.is_file() and child.suffix.lower() in SUPPORTED_EXTENSIONS
            )
        else:
            raise FileNotFoundError(f"Unsupported or missing input: {path}")

    return sorted(set(document.resolve() for document in documents))


def safe_output_name(path: Path) -> str:
    path_hash = hashlib.sha256(str(path).encode("utf-8")).hexdigest()[:10]
    return f"{path.stem}-{path_hash}.json"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("inputs", nargs="+", help="Invoice PDFs/images or directories")
    parser.add_argument("--output-dir", type=Path)
    parser.add_argument("--workers", type=int, default=4)
    args = parser.parse_args()

    documents = find_documents(args.inputs)
    if not documents:
        parser.error("No supported documents found")

    if args.output_dir:
        args.output_dir.mkdir(parents=True, exist_ok=True)

    client = create_client()
    results: list[dict[str, Any]] = []

    def process(path: Path) -> dict[str, Any]:
        try:
            return analyze_file(client, path)
        except Exception as exc:
            return {
                "source": str(path),
                "provider": "azure_ai_document_intelligence",
                "model": "prebuilt-invoice",
                "invoices": [],
                "error": f"{type(exc).__name__}: {exc}",
            }

    with ThreadPoolExecutor(max_workers=max(1, args.workers)) as executor:
        futures = {executor.submit(process, path): path for path in documents}

        for future in as_completed(futures):
            path = futures[future]
            result = future.result()

            if args.output_dir:
                output_path = args.output_dir / safe_output_name(path)
                output_path.write_text(
                    json.dumps(result, ensure_ascii=False, indent=2),
                    encoding="utf-8",
                )
            else:
                results.append(result)

    if not args.output_dir:
        payload: Any = results[0] if len(results) == 1 else results
        json.dump(payload, sys.stdout, ensure_ascii=False, indent=2)
        sys.stdout.write("\n")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
