    if not field:
        return None

    if "valueCurrency" in field:
        currency = field["valueCurrency"] or {}
        return _compact(
            {
                "amount": _decimal_string(currency.get("amount")),
                "currency_code": currency.get("currencyCode"),
                "currency_symbol": currency.get("currencySymbol"),
            }
        )

    if "valueAddress" in field:
        address = {
            _snake(key): value
            for key, value in (field["valueAddress"] or {}).items()
            if value is not None
        }
        if field.get("content"):
            address["raw"] = field["content"]
        return address

    if "valueArray" in field:
        return [_field_value(item) for item in field.get("valueArray", [])]

    if "valueObject" in field:
        return {
            _snake(key): _field_value(value)
            for key, value in (field.get("valueObject") or {}).items()
        }

    if "valueNumber" in field:
        return _decimal_string(field["valueNumber"])

    if "valueInteger" in field:
        return str(field["valueInteger"])

    for key in (
        "valueString",
        "valueDate",
        "valueTime",
        "valuePhoneNumber",
        "valueCountryRegion",
        "valueSelectionMark",
        "valueSignature",
        "valueBoolean",
    ):
