def _normalize_line_items(
    field: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    if not field:
        return []

    items: list[dict[str, Any]] = []

    for index, entry in enumerate(field.get("valueArray", []), start=1):
        obj = entry.get("valueObject") or {}
