def _page_quality(analyze_result: dict[str, Any]) -> list[dict[str, Any]]:
    quality: list[dict[str, Any]] = []

    for page in analyze_result.get("pages", []):
        word_confidences = [
            float(word["confidence"])
            for word in page.get("words", [])
            if word.get("confidence") is not None
        ]
        average = (
            sum(word_confidences) / len(word_confidences)
            if word_confidences
            else None
        )
        low_fraction = (
            sum(value < MIN_PAGE_WORD_CONFIDENCE for value in word_confidences)
            / len(word_confidences)
            if word_confidences
            else None
        )

        quality.append(
            {
                "page_number": page.get("pageNumber"),
                "detected_rotation_degrees": page.get("angle"),
                "width": page.get("width"),
                "height": page.get("height"),
                "unit": page.get("unit"),
                "average_word_confidence": (
                    round(average, 4) if average is not None else None
                ),
                "low_confidence_word_fraction": (
                    round(low_fraction, 4)
                    if low_fraction is not None
                    else None
                ),
            }
