def _validate_invoice(
    invoice: dict[str, Any],
    fields: dict[str, dict[str, Any]],
    page_quality: list[dict[str, Any]],
) -> list[dict[str, str]]:
    reasons: list[dict[str, str]] = []

    critical_fields = [
        ("VendorName", "supplier.name"),
        ("InvoiceId", "invoice_number"),
        ("InvoiceDate", "invoice_date"),
        ("InvoiceTotal", "totals.invoice_total"),
    ]

    for azure_name, path in critical_fields:
        field = fields.get(azure_name)
        value = _field_value(field)
        confidence = _confidence(field)

        if value in (None, "", {}):
            reasons.append(
                _reason(
                    "missing_critical_field",
                    f"Critical field {azure_name} was not extracted.",
                    path,
                )
            )
        elif confidence is None or confidence < MIN_CRITICAL_CONFIDENCE:
            reasons.append(
                _reason(
                    "low_critical_confidence",
                    f"{azure_name} confidence is {confidence}; "
                    f"minimum is {MIN_CRITICAL_CONFIDENCE}.",
                    path,
                )
            )

    line_items = invoice["line_items"]
    if not line_items:
        reasons.append(
            _reason(
                "missing_line_items",
                "No line items were extracted.",
                "line_items",
            )
        )

    for index, item in enumerate(line_items):
        path = f"line_items[{index}]"
        confidence = item["confidence"]

        if item.get("amount") is None:
            reasons.append(
                _reason(
                    "missing_line_amount",
                    "Line item amount was not extracted.",
                    f"{path}.amount",
                )
            )

        for field_name in ("description", "quantity", "unit_price", "amount"):
            value = item.get(field_name)
            field_confidence = confidence.get(field_name)

            if value is not None and (
                field_confidence is None
                or field_confidence < MIN_CRITICAL_CONFIDENCE
            ):
                reasons.append(
                    _reason(
                        "low_line_item_confidence",
                        f"{field_name} confidence is {field_confidence}; "
                        f"minimum is {MIN_CRITICAL_CONFIDENCE}.",
                        f"{path}.{field_name}",
                    )
                )

        quantity = _decimal(item.get("quantity"))
        unit_price = _decimal(item.get("unit_price"))
        amount = _decimal(item.get("amount"))
        discount = _decimal(item.get("discount")) or Decimal("0")

        if quantity is not None and unit_price is not None and amount is not None:
            expected = quantity * unit_price - discount
            if abs(expected - amount) > ARITHMETIC_TOLERANCE:
                reasons.append(
                    _reason(
                        "line_arithmetic_mismatch",
                        f"Extracted amount {amount} does not equal "
                        f"quantity {quantity} × unit price {unit_price} "
                        f"minus discount {discount}.",
                        path,
                    )
                )

    subtotal = _decimal(invoice["totals"].get("subtotal"))
    line_amounts = [_decimal(item.get("amount")) for item in line_items]

    if (
        subtotal is not None
        and line_amounts
        and all(value is not None for value in line_amounts)
    ):
        line_sum = sum(
            (value for value in line_amounts if value is not None),
            Decimal("0"),
        )
        if abs(line_sum - subtotal) > ARITHMETIC_TOLERANCE:
            reasons.append(
                _reason(
                    "subtotal_mismatch",
                    f"Line item sum {line_sum} does not equal "
                    f"subtotal {subtotal}.",
                    "totals.subtotal",
                )
            )

    total = _decimal(invoice["totals"].get("invoice_total"))
    total_tax = _decimal(invoice["taxes"].get("total"))
    total_discount = (
        _decimal(invoice["totals"].get("total_discount")) or Decimal("0")
    )
    shipping = _decimal(invoice["totals"].get("shipping")) or Decimal("0")

    if subtotal is not None and total_tax is not None and total is not None:
        expected_total = subtotal + total_tax - total_discount + shipping
        if abs(expected_total - total) > ARITHMETIC_TOLERANCE:
            reasons.append(
                _reason(
                    "invoice_total_mismatch",
                    f"Calculated total {expected_total} does not equal "
                    f"extracted invoice total {total}.",
                    "totals.invoice_total",
                )
            )

    currencies: set[str] = set()
    money_values = [
        *invoice["totals"].values(),
        invoice["taxes"].get("total"),
    ]
    for item in line_items:
        money_values.extend(
            [
                item.get("unit_price"),
                item.get("amount"),
                item.get("tax"),
                item.get("discount"),
            ]
        )

    for value in money_values:
        code = _money_currency(value)
        if code:
            currencies.add(code)

    if len(currencies) > 1:
        reasons.append(
            _reason(
                "mixed_currencies",
                f"Multiple currencies were extracted: {sorted(currencies)}.",
            )
        )

    for page in page_quality:
        average = page.get("average_word_confidence")
        if average is not None and average < MIN_PAGE_WORD_CONFIDENCE:
            reasons.append(
                _reason(
                    "low_page_ocr_confidence",
                    f"Page {page['page_number']} average word confidence "
                    f"is {average}.",
                    f"pages[{page['page_number']}]",
                )
            )

    unique: list[dict[str, str]] = []
    seen: set[tuple[str, str | None]] = set()
    for reason in reasons:
        identity = (reason["code"], reason.get("path"))
        if identity not in seen:
            seen.add(identity)
            unique.append(reason)

    return unique


