def _normalize_invoice(
    document: dict[str, Any],
    page_quality: list[dict[str, Any]],
) -> dict[str, Any]:
    fields = document.get("fields") or {}

    supplier = {
        "name": _field_value(fields.get("VendorName")),
        "tax_id": _field_value(fields.get("VendorTaxId")),
        "registration_id": _field_value(fields.get("VendorRegistrationId")),
        "address": _field_value(fields.get("VendorAddress")),
        "address_recipient": _field_value(
            fields.get("VendorAddressRecipient")
        ),
    }

    totals = {
        "subtotal": _field_value(fields.get("SubTotal")),
        "total_discount": _field_value(fields.get("TotalDiscount")),
        "shipping": _field_value(
            _first_field(fields, "ShippingCost", "TotalShipping")
        ),
        "invoice_total": _field_value(fields.get("InvoiceTotal")),
        "amount_due": _field_value(fields.get("AmountDue")),
        "previous_unpaid_balance": _field_value(
            fields.get("PreviousUnpaidBalance")
        ),
    }

    invoice: dict[str, Any] = {
        "document_type": document.get("docType"),
        "document_confidence": document.get("confidence"),
        "supplier": supplier,
        "invoice_number": _field_value(fields.get("InvoiceId")),
        "invoice_date": _field_value(fields.get("InvoiceDate")),
        "due_date": _field_value(fields.get("DueDate")),
        "purchase_order": _field_value(fields.get("PurchaseOrder")),
        "payment_terms": _field_value(fields.get("PaymentTerm")),
        "taxes": {
            "total": _field_value(fields.get("TotalTax")),
            "details": _normalize_object_array(fields.get("TaxDetails")),
        },
        "totals": totals,
        "line_items": _normalize_line_items(fields.get("Items")),
        "additional_fields": {
            _snake(name): _field_value(field)
            for name, field in fields.items()
            if name not in KNOWN_TOP_LEVEL_FIELDS
        },
        "confidence": {
            _snake(name): _confidence(field)
            for name, field in fields.items()
        },
    }

    reasons = _validate_invoice(invoice, fields, page_quality)
    invoice["review"] = {
        "required": bool(reasons),
        "reasons": reasons,
    }
    invoice["automation_eligible"] = not reasons
    return invoice


async def _request_with_retry(
    client: httpx.AsyncClient,
    method: str,
    url: str,
    **kwargs: Any,
) -> httpx.Response:
    attempts = 5 if method == "GET" else 3

    for attempt in range(attempts):
        try:
            response = await client.request(method, url, **kwargs)
        except httpx.TransportError:
            if method != "GET" or attempt == attempts - 1:
                raise
            await asyncio.sleep(min(2**attempt, 10))
            continue

        retryable = response.status_code == 429 or (
            method == "GET" and response.status_code >= 500
        )
        if not retryable or attempt == attempts - 1:
            return response

        retry_after = response.headers.get("Retry-After")
        try:
            delay = float(retry_after) if retry_after else 2**attempt
        except ValueError:
            delay = 2**attempt
        await asyncio.sleep(min(delay, 30))

    raise RuntimeError("Retry loop exited unexpectedly")


def _azure_error(response: httpx.Response) -> HTTPException:
    code = "azure_document_intelligence_error"
    message = "Azure Document Intelligence request failed."

    try:
        payload = response.json()
        error = payload.get("error") or {}
        code = error.get("code") or code
        message = error.get("message") or message
    except ValueError:
        pass

    return HTTPException(
        status_code=502,
        detail={
            "code": code,
            "message": message,
            "upstream_status": response.status_code,
            "azure_request_id": response.headers.get("x-ms-request-id"),
        },
    )


async def _analyze_pdf(request: Request, pdf: bytes) -> dict[str, Any]:
    request_id = str(uuid.uuid4())
    endpoint = request.app.state.azure_endpoint
    key = request.app.state.azure_key
    client: httpx.AsyncClient = request.app.state.http

    model_path = quote(MODEL_ID, safe="")
    analyze_url = (
        f"{endpoint}/documentintelligence/documentModels/"
        f"{model_path}:analyze"
    )

    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/pdf",
        "Accept": "application/json",
        "x-ms-client-request-id": request_id,
    }
    params = {
        "api-version": API_VERSION,
        "features": "ocrHighResolution",
    }

    response = await _request_with_retry(
        client,
        "POST",
        analyze_url,
        headers=headers,
        params=params,
        content=pdf,
    )

    if response.status_code == 200:
        payload = response.json()
        return payload.get("analyzeResult", payload)

    if response.status_code != 202:
        raise _azure_error(response)

    operation_location = response.headers.get("operation-location")
    if not operation_location:
        raise HTTPException(
            status_code=502,
            detail="Azure did not return an operation-location header.",
        )

    operation_location = urljoin(endpoint + "/", operation_location)
    poll_headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Accept": "application/json",
        "x-ms-client-request-id": request_id,
    }

    deadline = time.monotonic() + ANALYSIS_TIMEOUT_SECONDS
    poll_delay = 1.0

    while time.monotonic() < deadline:
        await asyncio.sleep(poll_delay)

        poll_response = await _request_with_retry(
            client,
            "GET",
            operation_location,
            headers=poll_headers,
        )
        if poll_response.status_code != 200:
            raise _azure_error(poll_response)

        payload = poll_response.json()
        status = str(payload.get("status", "")).lower()

        if status == "succeeded":
            return payload["analyzeResult"]

        if status in {"failed", "canceled", "cancelled"}:
            error = payload.get("error") or {}
            raise HTTPException(
                status_code=422,
                detail={
                    "code": error.get("code", "invoice_analysis_failed"),
                    "message": error.get(
                        "message", "Invoice analysis failed."
                    ),
                },
            )

        retry_after = poll_response.headers.get("Retry-After")
        try:
            poll_delay = (
                min(max(float(retry_after), 0.5), 10.0)
                if retry_after
                else min(poll_delay * 1.5, 5.0)
            )
        except ValueError:
            poll_delay = min(poll_delay * 1.5, 5.0)

    raise HTTPException(
        status_code=504,
        detail="Invoice analysis exceeded the configured timeout.",
    )


