            detail=f"PDF exceeds the {MAX_FILE_BYTES}-byte limit.",
        )

    if not pdf.lstrip().startswith(b"%PDF-"):
        raise HTTPException(
            status_code=415,
            detail="The uploaded file is not a valid PDF.",
        )

    document_hash = hashlib.sha256(pdf).hexdigest()

    try:
        async with request.app.state.analysis_slots:
            analyze_result = await _analyze_pdf(request, pdf)
    except httpx.TransportError:
        raise HTTPException(
            status_code=502,
            detail="Could not connect to Azure Document Intelligence.",
        )

    pages = _page_quality(analyze_result)
    documents = analyze_result.get("documents") or []
    invoices = [
        _normalize_invoice(document, pages) for document in documents
    ]

    global_reasons: list[dict[str, str]] = []
    if not invoices:
        global_reasons.append(
            _reason(
                "no_invoice_detected",
                "The service did not detect an invoice document.",
            )
        )

    requires_review = bool(global_reasons) or any(
        invoice["review"]["required"] for invoice in invoices
    )

    return {
        "document_id": document_hash,
        "provider": "azure_document_intelligence",
        "model_id": MODEL_ID,
        "api_version": API_VERSION,
        "page_count": len(pages),
        "pages": pages,
        "invoices": invoices,
        "requires_review": requires_review,
        "automation_eligible": bool(invoices) and not requires_review,
        "review_reasons": global_reasons,
    }
