```python
"""
Hosted API recommendation: Azure AI Document Intelligence.

Uses the prebuilt-invoice model with paid high-resolution OCR, automatic
English/German recognition, exact decimal strings, confidence gating, and
arithmetic validation. Set AZURE_DOCUMENT_MODEL_ID to a trained custom or
composed invoice model later for even higher supplier-specific accuracy.

Install:
    pip install fastapi uvicorn httpx python-multipart

Environment:
    AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT=https://<resource>.cognitiveservices.azure.com
    AZURE_DOCUMENT_INTELLIGENCE_KEY=<key>

Run:
    uvicorn invoice_api:app --host 0.0.0.0 --port 8000
"""

from __future__ import annotations

import asyncio
import hashlib
import os
import re
import time
import uuid
from contextlib import asynccontextmanager
from decimal import Decimal, InvalidOperation
from typing import Any
from urllib.parse import quote, urljoin

import httpx
from fastapi import FastAPI, File, HTTPException, Request, UploadFile

API_VERSION = os.getenv("AZURE_DOCUMENT_API_VERSION", "2024-11-30")
MODEL_ID = os.getenv("AZURE_DOCUMENT_MODEL_ID", "prebuilt-invoice")
MAX_FILE_BYTES = int(os.getenv("MAX_INVOICE_BYTES", str(50 * 1024 * 1024)))
MAX_CONCURRENT_ANALYSES = int(os.getenv("MAX_CONCURRENT_ANALYSES", "32"))
ANALYSIS_TIMEOUT_SECONDS = float(os.getenv("ANALYSIS_TIMEOUT_SECONDS", "600"))
MIN_CRITICAL_CONFIDENCE = float(os.getenv("MIN_CRITICAL_CONFIDENCE", "0.90"))
MIN_PAGE_WORD_CONFIDENCE = float(
    os.getenv("MIN_PAGE_WORD_CONFIDENCE", "0.78")
)
ARITHMETIC_TOLERANCE = Decimal(os.getenv("ARITHMETIC_TOLERANCE", "0.02"))


def _required_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.azure_endpoint = _required_env(
        "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"
    ).rstrip("/")
    app.state.azure_key = _required_env("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    app.state.http = httpx.AsyncClient(
        timeout=httpx.Timeout(120.0, connect=15.0),
        limits=httpx.Limits(
            max_connections=MAX_CONCURRENT_ANALYSES * 2,
            max_keepalive_connections=MAX_CONCURRENT_ANALYSES,
        ),
    )
    app.state.analysis_slots = asyncio.Semaphore(MAX_CONCURRENT_ANALYSES)
    yield
    await app.state.http.aclose()


app = FastAPI(
    title="High-Accuracy Supplier Invoice Extraction API",
    version="1.0.0",
    lifespan=lifespan,
)


def _snake(name: str) -> str:
    name = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", name)
    name = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", name)
    return name.replace("-", "_").lower()


def _decimal_string(value: Any) -> str | None:
    if value is None:
        return None
    try:
        number = Decimal(str(value))
        if not number.is_finite():
            return None
        return format(number, "f")
    except (InvalidOperation, ValueError, TypeError):
        return None


def _decimal(value: Any) -> Decimal | None:
    if isinstance(value, dict):
        value = value.get("amount")
    text = _decimal_string(value)
    return Decimal(text) if text is not None else None


def _confidence(field: dict[str, Any] | None) -> float | None:
    if not field or field.get("confidence") is None:
        return None
    return float(field["confidence"])


def _compact(data: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in data.items() if value is not None}


def _field_value(field: dict[str, Any] | None) -> Any:
    if not field:
        return None

    if "valueCurrency" in field:
        currency = field["valueCurrency"] or {}
        return _compact(
            {
                "amount": _decimal_string(currency.get("amount")),
                "currency_code": currency.get("currencyCode"),
                "currency_symbol": currency.get("currencySymbol"),
            }
        )

    if "valueAddress" in field:
        address = {
            _snake(key): value
            for key, value in (field["valueAddress"] or {}).items()
            if value is not None
        }
        if field.get("content"):
            address["raw"] = field["content"]
        return address

    if "valueArray" in field:
        return [_field_value(item) for item in field.get("valueArray", [])]

    if "valueObject" in field:
        return {
            _snake(key): _field_value(value)
            for key, value in (field.get("valueObject") or {}).items()
        }

    if "valueNumber" in field:
        return _decimal_string(field["valueNumber"])

    if "valueInteger" in field:
        return str(field["valueInteger"])

    for key in (
        "valueString",
        "valueDate",
        "valueTime",
        "valuePhoneNumber",
        "valueCountryRegion",
        "valueSelectionMark",
        "valueSignature",
        "valueBoolean",
    ):
        if key in field:
            return field[key]

    return field.get("content")


def _first_field(
    fields: dict[str, dict[str, Any]], *names: str
) -> dict[str, Any] | None:
    for name in names:
        if fields.get(name):
            return fields[name]
    return None


def _normalize_object_array(
    field: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    if not field:
        return []

    output: list[dict[str, Any]] = []
    for entry in field.get("valueArray", []):
        obj = entry.get("valueObject") or {}
        output.append(
            {
                **{
                    _snake(name): _field_value(value)
                    for name, value in obj.items()
                },
                "confidence": {
                    _snake(name): _confidence(value)
                    for name, value in obj.items()
                },
            }
        )
    return output


LINE_ITEM_FIELDS = {
    "Description": "description",
    "Quantity": "quantity",
    "UnitPrice": "unit_price",
    "Amount": "amount",
    "ProductCode": "product_code",
    "Unit": "unit",
    "Tax": "tax",
    "TaxRate": "tax_rate",
    "Date": "date",
    "Discount": "discount",
    "NetAmount": "net_amount",
}


def _normalize_line_items(
    field: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    if not field:
        return []

    items: list[dict[str, Any]] = []

    for index, entry in enumerate(field.get("valueArray", []), start=1):
        obj = entry.get("valueObject") or {}
        item: dict[str, Any] = {"line_number": index}
        confidences: dict[str, float | None] = {}

        for azure_name, output_name in LINE_ITEM_FIELDS.items():
            source = obj.get(azure_name)
            item[output_name] = _field_value(source)
            confidences[output_name] = _confidence(source)

        additional = {
            _snake(name): _field_value(source)
            for name, source in obj.items()
            if name not in LINE_ITEM_FIELDS
        }
        additional_confidence = {
            _snake(name): _confidence(source)
            for name, source in obj.items()
            if name not in LINE_ITEM_FIELDS
        }

        item["additional_fields"] = additional
        item["confidence"] = {
            **confidences,
            **additional_confidence,
        }
        items.append(item)

    return items


def _page_quality(analyze_result: dict[str, Any]) -> list[dict[str, Any]]:
    quality: list[dict[str, Any]] = []

    for page in analyze_result.get("pages", []):
        word_confidences = [
            float(word["confidence"])
            for word in page.get("words", [])
            if word.get("confidence") is not None
        ]
        average = (
            sum(word_confidences) / len(word_confidences)
            if word_confidences
            else None
        )
        low_fraction = (
            sum(value < MIN_PAGE_WORD_CONFIDENCE for value in word_confidences)
            / len(word_confidences)
            if word_confidences
            else None
        )

        quality.append(
            {
                "page_number": page.get("pageNumber"),
                "detected_rotation_degrees": page.get("angle"),
                "width": page.get("width"),
                "height": page.get("height"),
                "unit": page.get("unit"),
                "average_word_confidence": (
                    round(average, 4) if average is not None else None
                ),
                "low_confidence_word_fraction": (
                    round(low_fraction, 4)
                    if low_fraction is not None
                    else None
                ),
            }
        )

    return quality


def _reason(
    code: str,
    message: str,
    path: str | None = None,
) -> dict[str, str]:
    result = {"code": code, "message": message}
    if path:
        result["path"] = path
    return result


def _money_currency(value: Any) -> str | None:
    return value.get("currency_code") if isinstance(value, dict) else None


def _validate_invoice(
    invoice: dict[str, Any],
    fields: dict[str, dict[str, Any]],
    page_quality: list[dict[str, Any]],
) -> list[dict[str, str]]:
    reasons: list[dict[str, str]] = []

    critical_fields = [
        ("VendorName", "supplier.name"),
        ("InvoiceId", "invoice_number"),
        ("InvoiceDate", "invoice_date"),
        ("InvoiceTotal", "totals.invoice_total"),
    ]

    for azure_name, path in critical_fields:
        field = fields.get(azure_name)
        value = _field_value(field)
        confidence = _confidence(field)

        if value in (None, "", {}):
            reasons.append(
                _reason(
                    "missing_critical_field",
                    f"Critical field {azure_name} was not extracted.",
                    path,
                )
            )
        elif confidence is None or confidence < MIN_CRITICAL_CONFIDENCE:
            reasons.append(
                _reason(
                    "low_critical_confidence",
                    f"{azure_name} confidence is {confidence}; "
                    f"minimum is {MIN_CRITICAL_CONFIDENCE}.",
                    path,
                )
            )

    line_items = invoice["line_items"]
    if not line_items:
        reasons.append(
            _reason(
                "missing_line_items",
                "No line items were extracted.",
                "line_items",
            )
        )

    for index, item in enumerate(line_items):
        path = f"line_items[{index}]"
        confidence = item["confidence"]

        if item.get("amount") is None:
            reasons.append(
                _reason(
                    "missing_line_amount",
                    "Line item amount was not extracted.",
                    f"{path}.amount",
                )
            )

        for field_name in ("description", "quantity", "unit_price", "amount"):
            value = item.get(field_name)
            field_confidence = confidence.get(field_name)

            if value is not None and (
                field_confidence is None
                or field_confidence < MIN_CRITICAL_CONFIDENCE
            ):
                reasons.append(
                    _reason(
                        "low_line_item_confidence",
                        f"{field_name} confidence is {field_confidence}; "
                        f"minimum is {MIN_CRITICAL_CONFIDENCE}.",
                        f"{path}.{field_name}",
                    )
                )

        quantity = _decimal(item.get("quantity"))
        unit_price = _decimal(item.get("unit_price"))
        amount = _decimal(item.get("amount"))
        discount = _decimal(item.get("discount")) or Decimal("0")

        if quantity is not None and unit_price is not None and amount is not None:
            expected = quantity * unit_price - discount
            if abs(expected - amount) > ARITHMETIC_TOLERANCE:
                reasons.append(
                    _reason(
                        "line_arithmetic_mismatch",
                        f"Extracted amount {amount} does not equal "
                        f"quantity {quantity} × unit price {unit_price} "
                        f"minus discount {discount}.",
                        path,
                    )
                )

    subtotal = _decimal(invoice["totals"].get("subtotal"))
    line_amounts = [_decimal(item.get("amount")) for item in line_items]

    if (
        subtotal is not None
        and line_amounts
        and all(value is not None for value in line_amounts)
    ):
        line_sum = sum(
            (value for value in line_amounts if value is not None),
            Decimal("0"),
        )
        if abs(line_sum - subtotal) > ARITHMETIC_TOLERANCE:
            reasons.append(
                _reason(
                    "subtotal_mismatch",
                    f"Line item sum {line_sum} does not equal "
                    f"subtotal {subtotal}.",
                    "totals.subtotal",
                )
            )

    total = _decimal(invoice["totals"].get("invoice_total"))
    total_tax = _decimal(invoice["taxes"].get("total"))
    total_discount = (
        _decimal(invoice["totals"].get("total_discount")) or Decimal("0")
    )
    shipping = _decimal(invoice["totals"].get("shipping")) or Decimal("0")

    if subtotal is not None and total_tax is not None and total is not None:
        expected_total = subtotal + total_tax - total_discount + shipping
        if abs(expected_total - total) > ARITHMETIC_TOLERANCE:
            reasons.append(
                _reason(
                    "invoice_total_mismatch",
                    f"Calculated total {expected_total} does not equal "
                    f"extracted invoice total {total}.",
                    "totals.invoice_total",
                )
            )

    currencies: set[str] = set()
    money_values = [
        *invoice["totals"].values(),
        invoice["taxes"].get("total"),
    ]
    for item in line_items:
        money_values.extend(
            [
                item.get("unit_price"),
                item.get("amount"),
                item.get("tax"),
                item.get("discount"),
            ]
        )

    for value in money_values:
        code = _money_currency(value)
        if code:
            currencies.add(code)

    if len(currencies) > 1:
        reasons.append(
            _reason(
                "mixed_currencies",
                f"Multiple currencies were extracted: {sorted(currencies)}.",
            )
        )

    for page in page_quality:
        average = page.get("average_word_confidence")
        if average is not None and average < MIN_PAGE_WORD_CONFIDENCE:
            reasons.append(
                _reason(
                    "low_page_ocr_confidence",
                    f"Page {page['page_number']} average word confidence "
                    f"is {average}.",
                    f"pages[{page['page_number']}]",
                )
            )

    unique: list[dict[str, str]] = []
    seen: set[tuple[str, str | None]] = set()
    for reason in reasons:
        identity = (reason["code"], reason.get("path"))
        if identity not in seen:
            seen.add(identity)
            unique.append(reason)

    return unique


KNOWN_TOP_LEVEL_FIELDS = {
    "VendorName",
    "VendorTaxId",
    "VendorRegistrationId",
    "VendorAddress",
    "VendorAddressRecipient",
    "InvoiceId",
    "InvoiceDate",
    "DueDate",
    "PurchaseOrder",
    "PaymentTerm",
    "SubTotal",
    "TotalTax",
    "TotalDiscount",
    "ShippingCost",
    "TotalShipping",
    "InvoiceTotal",
    "AmountDue",
    "PreviousUnpaidBalance",
    "TaxDetails",
    "Items",
}


def _normalize_invoice(
    document: dict[str, Any],
    page_quality: list[dict[str, Any]],
) -> dict[str, Any]:
    fields = document.get("fields") or {}

    supplier = {
        "name": _field_value(fields.get("VendorName")),
        "tax_id": _field_value(fields.get("VendorTaxId")),
        "registration_id": _field_value(fields.get("VendorRegistrationId")),
        "address": _field_value(fields.get("VendorAddress")),
        "address_recipient": _field_value(
            fields.get("VendorAddressRecipient")
        ),
    }

    totals = {
        "subtotal": _field_value(fields.get("SubTotal")),
        "total_discount": _field_value(fields.get("TotalDiscount")),
        "shipping": _field_value(
            _first_field(fields, "ShippingCost", "TotalShipping")
        ),
        "invoice_total": _field_value(fields.get("InvoiceTotal")),
        "amount_due": _field_value(fields.get("AmountDue")),
        "previous_unpaid_balance": _field_value(
            fields.get("PreviousUnpaidBalance")
        ),
    }

    invoice: dict[str, Any] = {
        "document_type": document.get("docType"),
        "document_confidence": document.get("confidence"),
        "supplier": supplier,
        "invoice_number": _field_value(fields.get("InvoiceId")),
        "invoice_date": _field_value(fields.get("InvoiceDate")),
        "due_date": _field_value(fields.get("DueDate")),
        "purchase_order": _field_value(fields.get("PurchaseOrder")),
        "payment_terms": _field_value(fields.get("PaymentTerm")),
        "taxes": {
            "total": _field_value(fields.get("TotalTax")),
            "details": _normalize_object_array(fields.get("TaxDetails")),
        },
        "totals": totals,
        "line_items": _normalize_line_items(fields.get("Items")),
        "additional_fields": {
            _snake(name): _field_value(field)
            for name, field in fields.items()
            if name not in KNOWN_TOP_LEVEL_FIELDS
        },
        "confidence": {
            _snake(name): _confidence(field)
            for name, field in fields.items()
        },
    }

    reasons = _validate_invoice(invoice, fields, page_quality)
    invoice["review"] = {
        "required": bool(reasons),
        "reasons": reasons,
    }
    invoice["automation_eligible"] = not reasons
    return invoice


async def _request_with_retry(
    client: httpx.AsyncClient,
    method: str,
    url: str,
    **kwargs: Any,
) -> httpx.Response:
    attempts = 5 if method == "GET" else 3

    for attempt in range(attempts):
        try:
            response = await client.request(method, url, **kwargs)
        except httpx.TransportError:
            if method != "GET" or attempt == attempts - 1:
                raise
            await asyncio.sleep(min(2**attempt, 10))
            continue

        retryable = response.status_code == 429 or (
            method == "GET" and response.status_code >= 500
        )
        if not retryable or attempt == attempts - 1:
            return response

        retry_after = response.headers.get("Retry-After")
        try:
            delay = float(retry_after) if retry_after else 2**attempt
        except ValueError:
            delay = 2**attempt
        await asyncio.sleep(min(delay, 30))

    raise RuntimeError("Retry loop exited unexpectedly")


def _azure_error(response: httpx.Response) -> HTTPException:
    code = "azure_document_intelligence_error"
    message = "Azure Document Intelligence request failed."

    try:
        payload = response.json()
        error = payload.get("error") or {}
        code = error.get("code") or code
        message = error.get("message") or message
    except ValueError:
        pass

    return HTTPException(
        status_code=502,
        detail={
            "code": code,
            "message": message,
            "upstream_status": response.status_code,
            "azure_request_id": response.headers.get("x-ms-request-id"),
        },
    )


async def _analyze_pdf(request: Request, pdf: bytes) -> dict[str, Any]:
    request_id = str(uuid.uuid4())
    endpoint = request.app.state.azure_endpoint
    key = request.app.state.azure_key
    client: httpx.AsyncClient = request.app.state.http

    model_path = quote(MODEL_ID, safe="")
    analyze_url = (
        f"{endpoint}/documentintelligence/documentModels/"
        f"{model_path}:analyze"
    )

    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/pdf",
        "Accept": "application/json",
        "x-ms-client-request-id": request_id,
    }
    params = {
        "api-version": API_VERSION,
        "features": "ocrHighResolution",
    }

    response = await _request_with_retry(
        client,
        "POST",
        analyze_url,
        headers=headers,
        params=params,
        content=pdf,
    )

    if response.status_code == 200:
        payload = response.json()
        return payload.get("analyzeResult", payload)

    if response.status_code != 202:
        raise _azure_error(response)

    operation_location = response.headers.get("operation-location")
    if not operation_location:
        raise HTTPException(
            status_code=502,
            detail="Azure did not return an operation-location header.",
        )

    operation_location = urljoin(endpoint + "/", operation_location)
    poll_headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Accept": "application/json",
        "x-ms-client-request-id": request_id,
    }

    deadline = time.monotonic() + ANALYSIS_TIMEOUT_SECONDS
    poll_delay = 1.0

    while time.monotonic() < deadline:
        await asyncio.sleep(poll_delay)

        poll_response = await _request_with_retry(
            client,
            "GET",
            operation_location,
            headers=poll_headers,
        )
        if poll_response.status_code != 200:
            raise _azure_error(poll_response)

        payload = poll_response.json()
        status = str(payload.get("status", "")).lower()

        if status == "succeeded":
            return payload["analyzeResult"]

        if status in {"failed", "canceled", "cancelled"}:
            error = payload.get("error") or {}
            raise HTTPException(
                status_code=422,
                detail={
                    "code": error.get("code", "invoice_analysis_failed"),
                    "message": error.get(
                        "message", "Invoice analysis failed."
                    ),
                },
            )

        retry_after = poll_response.headers.get("Retry-After")
        try:
            poll_delay = (
                min(max(float(retry_after), 0.5), 10.0)
                if retry_after
                else min(poll_delay * 1.5, 5.0)
            )
        except ValueError:
            poll_delay = min(poll_delay * 1.5, 5.0)

    raise HTTPException(
        status_code=504,
        detail="Invoice analysis exceeded the configured timeout.",
    )


@app.get("/health")
async def health() -> dict[str, str]:
    return {"status": "ok", "provider": "azure-document-intelligence"}


@app.post("/v1/invoices/extract")
async def extract_invoice(
    request: Request,
    file: UploadFile = File(...),
) -> dict[str, Any]:
    if not (file.filename or "").lower().endswith(".pdf"):
        raise HTTPException(status_code=415, detail="Only PDF files are accepted.")

    pdf = await file.read(MAX_FILE_BYTES + 1)

    if not pdf:
        raise HTTPException(status_code=400, detail="The uploaded PDF is empty.")

    if len(pdf) > MAX_FILE_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"PDF exceeds the {MAX_FILE_BYTES}-byte limit.",
        )

    if not pdf.lstrip().startswith(b"%PDF-"):
        raise HTTPException(
            status_code=415,
            detail="The uploaded file is not a valid PDF.",
        )

    document_hash = hashlib.sha256(pdf).hexdigest()

    try:
        async with request.app.state.analysis_slots:
            analyze_result = await _analyze_pdf(request, pdf)
    except httpx.TransportError:
        raise HTTPException(
            status_code=502,
            detail="Could not connect to Azure Document Intelligence.",
        )

    pages = _page_quality(analyze_result)
    documents = analyze_result.get("documents") or []
    invoices = [
        _normalize_invoice(document, pages) for document in documents
    ]

    global_reasons: list[dict[str, str]] = []
    if not invoices:
        global_reasons.append(
            _reason(
                "no_invoice_detected",
                "The service did not detect an invoice document.",
            )
