        values: list[str] = []
        for cell in sorted(
            header_cells,
            key=lambda item: (item["row_index"], item["column_index"]),
        ):
            start = cell["column_index"]
            end = start + cell["column_span"]
            value = cell["value"].strip()
            if start <= column_index < end and value and value not in values:
