            detail=f"Unsupported content type: {content_type}",
        )

    document = await file.read(MAX_UPLOAD_BYTES + 1)
    if not document:
        raise HTTPException(status_code=400, detail="The uploaded file is empty.")
    if len(document) > MAX_UPLOAD_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"Upload exceeds the {MAX_UPLOAD_BYTES}-byte preview limit.",
        )

    deadline = time.monotonic() + PREVIEW_TIMEOUT_SECONDS
    client: httpx.AsyncClient = app.state.http

    try:
        operation_url = await start_analysis(
            client=client,
            document=document,
            content_type=content_type,
            page_number=page_number,
            deadline=deadline,
        )
        result = await wait_for_analysis(client, operation_url, deadline)
    except httpx.TimeoutException as exc:
        raise HTTPException(
            status_code=504,
            detail="Document extraction exceeded the preview latency budget.",
        ) from exc
    except httpx.RequestError as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Could not reach Azure Document Intelligence: {exc}",
        ) from exc

    pages = [
        {
            "page_number": page.get("pageNumber"),
            "width": page.get("width"),
            "height": page.get("height"),
            "unit": page.get("unit"),
        }
        for page in result.get("pages", [])
    ]

    tables = [
        normalize_table(table, index)
        for index, table in enumerate(result.get("tables", []))
    ]

    return {
        "provider": "azure_ai_document_intelligence",
        "model": MODEL_ID,
        "requested_page": page_number,
        "pages": pages,
        "table_count": len(tables),
        "tables": tables,
    }
