import hashlib
import json
import os
import sys
import time
from decimal import Decimal

import requests


API_VERSION = "2024-11-30"
MODEL_ID = "prebuilt-invoice"
MIN_FIELD_CONFIDENCE = Decimal("0.98")  # Calibrate on your labeled pilot.


def analyze_pdf(pdf_bytes: bytes, timeout_seconds: int = 900) -> dict:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"].rstrip("/")
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    deadline = time.monotonic() + timeout_seconds

    with requests.Session() as session:
        session.headers["Ocp-Apim-Subscription-Key"] = key

        # Do not automatically retry this POST after an ambiguous network
        # failure: a second submission could create another billable operation.
        response = session.post(
            f"{endpoint}/documentintelligence/documentModels/{MODEL_ID}:analyze",
            params={
                "api-version": API_VERSION,
                "features": "ocrHighResolution",  # Additional cost may apply.
            },
            headers={"Content-Type": "application/pdf"},
            data=pdf_bytes,
            timeout=(15, 180),
        )
        response.raise_for_status()
        operation_url = response.headers["Operation-Location"]

        # Persist operation_url in your job store to resume polling after restarts.
        delay = 2.0
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError(
                    "Analysis polling timed out; resume the existing operation "
                    "rather than submitting the PDF again."
                )

            time.sleep(min(delay, remaining))
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                continue

            response = session.get(
                operation_url,
                timeout=(min(15, remaining), min(60, remaining)),
