        ]
    else:
        value = next(
            (value for key, value in field.items() if key.startswith("value")),
            None,
        )

    confidence = field.get("confidence")
    return {
        "type": kind,
        "value": value,
        "confidence": float(confidence) if confidence is not None else None,
        "source": {
            "text": field.get("content"),
            "bounding_regions": field.get("boundingRegions", []),
            "spans": field.get("spans", []),
        },
    }


def confidence_issues(field: dict, path: str) -> list[str]:
