        issues.append(f"{path}: low extraction confidence ({confidence})")
    elif confidence is None and kind not in {"object", "array"}:
        issues.append(f"{path}: no extraction confidence")

    for name, child in field.get("valueObject", {}).items():
        issues.extend(confidence_issues(child, f"{path}.{name}"))
    for index, child in enumerate(field.get("valueArray", [])):
        issues.extend(confidence_issues(child, f"{path}[{index}]"))
    return issues


def number(field: dict | None) -> Decimal | None:
    if not field:
        return None
    if field.get("type") == "currency":
        value = field.get("valueCurrency", {}).get("amount")
