        return None
    return value if isinstance(value, Decimal) else Decimal(str(value))


def validate_document(fields: dict, tolerance: Decimal) -> list[str]:
    issues = []
    for name, field in fields.items():
        issues.extend(confidence_issues(field, name))

    for name in ("VendorName", "InvoiceId", "InvoiceDate", "InvoiceTotal"):
        field = fields.get(name)
        if not field or normalize_field(field)["value"] in (None, ""):
