        unit_price = number(row.get("UnitPrice"))
        amount = number(row.get("Amount"))

        # Missing values remain missing. Never guess quantity=1 or tax=0.
        for name, value in (
            ("Quantity", quantity),
            ("UnitPrice", unit_price),
            ("Amount", amount),
        ):
            if value is None:
                issues.append(f"Items[{index}]: missing {name}")

        if amount is not None:
            line_amounts.append(amount)

        if all(value is not None for value in (quantity, unit_price, amount)):
            if abs(quantity * unit_price - amount) > tolerance:
                issues.append(
                    f"Items[{index}]: quantity × unit price differs from amount; "
                    "check OCR, discounts, price basis, and rounding"
                )

    subtotal = number(fields.get("SubTotal"))
    tax = number(fields.get("TotalTax"))
    total = number(fields.get("InvoiceTotal"))

    if items and subtotal is not None and len(line_amounts) == len(items):
        if abs(sum(line_amounts, Decimal("0")) - subtotal) > tolerance:
            issues.append(
                "Line amounts do not reconcile to subtotal; check omitted rows, "
                "discounts, charges, and tax-inclusive pricing"
            )
    else:
        issues.append("Line-item/subtotal reconciliation could not be completed")

    if all(value is not None for value in (subtotal, tax, total)):
        if abs(subtotal + tax - total) > tolerance:
            issues.append(
                "Subtotal + tax differs from invoice total; check adjustments "
                "and extraction errors"
            )
    else:
        issues.append("Subtotal/tax/total reconciliation could not be completed")

    return issues


def extract_invoice(
    pdf_bytes: bytes,
    rounding_tolerance: Decimal = Decimal("0.02"),
) -> dict:
    # Set tolerance according to currency and your accounting rules.
    analyzed = analyze_pdf(pdf_bytes)
    documents = analyzed.get("documents", [])
    global_issues = []

    if len(documents) != 1:
        global_issues.append(
            f"Expected one invoice per PDF; service returned {len(documents)}. "
            "Review document boundaries."
        )
    if analyzed.get("warnings"):
        global_issues.append("Service returned warnings; inspect service_warnings")

    invoices = []
    for document in documents:
        raw_fields = document.get("fields", {})
        fields = {
            name: normalize_field(field) for name, field in raw_fields.items()
        }
        issues = validate_document(raw_fields, rounding_tolerance)
        issues = list(dict.fromkeys(global_issues + issues))

        invoices.append({
            "supplier": {
                "name": fields.get("VendorName"),
                "address": fields.get("VendorAddress"),
                "address_recipient": fields.get("VendorAddressRecipient"),
                "tax_id": fields.get("VendorTaxId"),
            },
            "invoice_number": fields.get("InvoiceId"),
            "invoice_date": fields.get("InvoiceDate"),
            "due_date": fields.get("DueDate"),
            "purchase_order": fields.get("PurchaseOrder"),
            "taxes": {
                "total": fields.get("TotalTax"),
                "breakdown": fields.get("TaxDetails"),
            },
            "totals": {
                "subtotal": fields.get("SubTotal"),
                "invoice_total": fields.get("InvoiceTotal"),
                "amount_due": fields.get("AmountDue"),
            },
            "line_items": [
                item["value"]
                for item in fields.get("Items", {}).get("value", [])
            ],
            "all_extracted_fields": fields,
            "review_required": bool(issues),
            "review_reasons": issues,
            # Passing checks does not prove that all printed rows were found.
            "line_item_completeness_verified": False,
            "payment_authorized": False,
        })

    return {
        "provider": "Azure AI Document Intelligence",
        "model": MODEL_ID,
        "api_version": API_VERSION,
        "document_sha256": hashlib.sha256(pdf_bytes).hexdigest(),
        "page_count": len(analyzed.get("pages", [])),
        "service_warnings": analyzed.get("warnings", []),
        "invoices": invoices,
        "review_required": bool(global_issues) or any(
            invoice["review_required"] for invoice in invoices
        ),
        "review_reasons": global_issues,
        "payment_authorized": False,
    }


def json_default(value):
    if isinstance(value, Decimal):
        # Financial values are JSON strings, avoiding binary-float rounding
        # in downstream systems. Consumers should parse them as Decimal.
        return format(value, "f")
    raise TypeError(f"Cannot serialize {type(value).__name__}")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python extract_invoice.py invoice.pdf")

    with open(sys.argv[1], "rb") as source:
        output = extract_invoice(source.read())

    print(json.dumps(
        output,
        ensure_ascii=False,
        indent=2,
        default=json_default,
    ))
