def cell_covers(
    cell: dict[str, Any],
    row: int,
    column: int | None = None,
) -> bool:
    row_start = int(cell.get("rowIndex", 0))
    row_end = row_start + int(cell.get("rowSpan", 1))

    if not row_start <= row < row_end:
        return False

    if column is None:
        return True

    column_start = int(cell.get("columnIndex", 0))
    column_end = column_start + int(cell.get("columnSpan", 1))
    return column_start <= column < column_end


def public_cell(
    cell: dict[str, Any],
    semantic_kind: str | None = None,
) -> dict[str, Any]:
    return {
        "row_index": int(cell.get("rowIndex", 0)),
        "column_index": int(cell.get("columnIndex", 0)),
        "row_span": int(cell.get("rowSpan", 1)),
        "column_span": int(cell.get("columnSpan", 1)),
        "value": cell.get("content", ""),
        "kind": cell.get("kind", "content"),
        "semantic_kind": semantic_kind or cell.get("kind", "content"),
        "confidence": cell.get("confidence"),
        "bounding_regions": cell.get("boundingRegions", []),
    }


def infer_header_cells(
    cells: list[dict[str, Any]],
    row_count: int,
    column_count: int,
) -> tuple[list[dict[str, Any]], bool]:
    explicit = [
        cell
        for cell in cells
        if cell.get("kind") in {"columnHeader", "stubHead"}
    ]
    if explicit:
        return explicit, False

    # If Azure did not assign semantic kinds, skip merged title rows and use
    # the first row containing multiple independently positioned cells.
    for row in range(row_count):
        row_cells = [
            cell
            for cell in cells
            if int(cell.get("rowIndex", 0)) == row
            and str(cell.get("content", "")).strip()
            and cell.get("kind") != "description"
        ]
        occupied_columns = {
            int(cell.get("columnIndex", 0)) for cell in row_cells
        }
        if len(occupied_columns) >= 2 or (column_count == 1 and row_cells):
            return row_cells, True

    nonempty = [
        cell for cell in cells if str(cell.get("content", "")).strip()
    ]
    if not nonempty:
        return [], True

    first_row = min(int(cell.get("rowIndex", 0)) for cell in nonempty)
    return [
        cell
        for cell in nonempty
        if int(cell.get("rowIndex", 0)) == first_row
    ], True


def normalize_table(
    table: dict[str, Any],
    table_index: int,
) -> dict[str, Any]:
    row_count = int(table.get("rowCount", 0))
    column_count = int(table.get("columnCount", 0))
    cells = table.get("cells", [])

    header_cells, headers_inferred = infer_header_cells(
        cells, row_count, column_count
    )

    header_rows: set[int] = set()
    for cell in header_cells:
        start = int(cell.get("rowIndex", 0))
        span = int(cell.get("rowSpan", 1))
        header_rows.update(range(start, start + span))

    data_start_row = max(header_rows, default=-1) + 1

    # Produce one combined header for each physical column, supporting
    # multi-row and column-spanning headers.
    column_headers: list[dict[str, Any]] = []
    for column in range(column_count):
        matching = sorted(
            (
                cell
                for cell in header_cells
                if cell_covers(
                    cell,
                    int(cell.get("rowIndex", 0)),
                    column,
                )
            ),
            key=lambda cell: (
                int(cell.get("rowIndex", 0)),
                int(cell.get("columnIndex", 0)),
            ),
        )

        parts: list[str] = []
        for cell in matching:
            value = str(cell.get("content", "")).strip()
            if value and value not in parts:
                parts.append(value)

        column_headers.append(
            {
                "column_index": column,
                "value": " / ".join(parts) if parts else f"column_{column + 1}",
