#!/usr/bin/env python3
"""
Recommendation: Google Cloud Document AI's pretrained Form Parser.

Why it fits:
- No training data or custom model maintenance.
- Extracts key/value fields, tables, and checkboxes from scanned PDFs.
- Returns confidence scores and structured results.
- Has Java and Python SDKs.
- A Form Parser processor only needs to be created once in Google Cloud.

Install:
    pip install google-cloud-documentai

Configure Application Default Credentials, then set:
    export GOOGLE_CLOUD_PROJECT="your-project-id"
    export DOCUMENT_AI_LOCATION="us"
    export DOCUMENT_AI_PROCESSOR_ID="your-form-parser-processor-id"

Usage:
    python extract_forms.py form.pdf
    python extract_forms.py ./incoming-pdfs --output ./extracted-json --workers 4
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
import unicodedata
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from typing import Any

from google.api_core.client_options import ClientOptions
from google.cloud import documentai


MAX_ONLINE_FILE_SIZE = 40 * 1024 * 1024  # Document AI online-processing limit.


def clean_text(value: str) -> str:
    return " ".join((value or "").replace("\x00", "").split())


def canonical_key(label: str) -> str:
    """Convert a printed field label to a backend-friendly key."""
    value = unicodedata.normalize("NFKD", label)
    value = value.encode("ascii", "ignore").decode("ascii").lower()
    value = re.sub(r"[^a-z0-9]+", "_", value).strip("_")
    return value or "unnamed_field"


def anchored_text(document_text: str, layout: Any) -> str:
    if not layout or not layout.text_anchor:
        return ""

    parts: list[str] = []
    for segment in layout.text_anchor.text_segments:
        start = int(segment.start_index or 0)
        end = int(segment.end_index or 0)
        parts.append(document_text[start:end])

    return clean_text("".join(parts))


def checkbox_state(value_type: str, value_text: str) -> bool | None:
    combined = f"{value_type} {value_text}".lower()

    if any(
        token in combined
        for token in (
            "unfilled_checkbox",
            "unchecked",
            "unselected",
            "not selected",
            "☐",
            "□",
        )
    ):
        return False

    if any(
        token in combined
        for token in (
            "filled_checkbox",
            "checked",
            "selected",
            "☒",
            "☑",
            "✓",
            "✔",
        )
    ):
        return True

    return None


def load_field_aliases(path: Path | None) -> dict[str, str]:
    """
    Optional mapping file format:

    {
      "full_name": ["name", "applicant name", "participant name"],
      "registration_date": ["date", "registration date"],
      "street_address": ["address", "street address"]
    }
    """
    if path is None:
        return {}

    definitions = json.loads(path.read_text(encoding="utf-8"))
    aliases: dict[str, str] = {}

    for canonical_name, labels in definitions.items():
        aliases[canonical_key(canonical_name)] = canonical_key(canonical_name)
        for label in labels:
            aliases[canonical_key(str(label))] = canonical_key(canonical_name)

    return aliases


def extract_table(document_text: str, table: Any) -> dict[str, Any]:
    def extract_rows(rows: Any) -> list[list[dict[str, Any]]]:
        result: list[list[dict[str, Any]]] = []
        for row in rows:
            cells = []
            for cell in row.cells:
                cells.append(
                    {
                        "text": anchored_text(document_text, cell.layout),
                        "confidence": round(float(cell.layout.confidence), 4),
                        "row_span": int(cell.row_span or 1),
                        "column_span": int(cell.col_span or 1),
                    }
                )
            result.append(cells)
        return result

    return {
        "header_rows": extract_rows(table.header_rows),
        "body_rows": extract_rows(table.body_rows),
        "confidence": round(float(table.layout.confidence), 4),
    }


