                element_type = clean_text(
                    getattr(element, "type_", "") or getattr(element, "type", "")
                )
                if "checkbox" not in element_type.lower():
                    continue

                text = anchored_text(document.text, element.layout)
                page_result["checkboxes"].append(
                    {
                        "label": text,
                        "checked": checkbox_state(element_type, text),
                        "type": element_type,
                        "confidence": round(
                            float(element.layout.confidence), 4
                        ),
                    }
                )

            for table in page.tables:
                page_result["tables"].append(
                    extract_table(document.text, table)
                )

