def write_result(
    parser: FormParser,
    source: Path,
    destination: Path,
) -> tuple[Path, str | None]:
    try:
        result = parser.process(source)
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(
            json.dumps(result, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
        return source, None
    except Exception as exc:
        return source, str(exc)


def required_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise SystemExit(f"Missing required environment variable: {name}")
    return value


def main() -> int:
    argument_parser = argparse.ArgumentParser()
    argument_parser.add_argument(
        "input",
        type=Path,
        help="A PDF file or a directory containing PDFs",
    )
    argument_parser.add_argument(
        "--output",
        type=Path,
        help="Output directory; required when input is a directory",
    )
    argument_parser.add_argument(
        "--field-map",
        type=Path,
        help="Optional JSON file mapping printed labels to canonical keys",
    )
    argument_parser.add_argument(
        "--workers",
        type=int,
        default=4,
        help="Number of concurrent API requests",
    )
    args = argument_parser.parse_args()

    source = args.input.resolve()
    if not source.exists():
        raise SystemExit(f"Input does not exist: {source}")

    form_parser = FormParser(
        project_id=required_env("GOOGLE_CLOUD_PROJECT"),
        location=os.getenv("DOCUMENT_AI_LOCATION", "us"),
        processor_id=required_env("DOCUMENT_AI_PROCESSOR_ID"),
        field_aliases=load_field_aliases(args.field_map),
    )

    if source.is_file():
        if source.suffix.lower() != ".pdf":
            raise SystemExit("Input file must be a PDF")

        result = form_parser.process(source)

        if args.output:
            destination = args.output
            if destination.exists() and destination.is_dir():
                destination = destination / f"{source.stem}.json"
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(
                json.dumps(result, indent=2, ensure_ascii=False),
                encoding="utf-8",
            )
        else:
            json.dump(result, sys.stdout, indent=2, ensure_ascii=False)
            sys.stdout.write("\n")

        return 0

    if args.output is None:
        raise SystemExit("--output is required when processing a directory")

    pdfs = sorted(
        path for path in source.rglob("*") if path.suffix.lower() == ".pdf"
    )
    if not pdfs:
        raise SystemExit(f"No PDFs found under {source}")

    failures = 0
    workers = max(1, args.workers)

    with ThreadPoolExecutor(max_workers=workers) as executor:
        futures = {}
        for pdf in pdfs:
            relative = pdf.relative_to(source)
            destination = args.output / relative.with_suffix(".json")
            future = executor.submit(
                write_result,
                form_parser,
                pdf,
                destination,
            )
            futures[future] = pdf

        for future in as_completed(futures):
            pdf, error = future.result()
            if error:
                failures += 1
                print(f"FAILED {pdf}: {error}", file=sys.stderr)
            else:
                print(f"OK {pdf}", file=sys.stderr)

    print(
        f"Processed {len(pdfs) - failures}/{len(pdfs)} PDFs successfully.",
        file=sys.stderr,
    )
    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(main())
