"""
Recommendation: Amazon Textract's synchronous AnalyzeDocument API, using
FeatureTypes=["TABLES"]. Submit one PDF page per request so analysts can preview
the visible page without waiting for the entire document.

Textract provides cells, column-header tags, merged-cell spans, and confidence
scores. Row labels below are explicitly marked as first-column heuristics.
Financial values remain strings: do not silently normalize accounting notation.

IMPORTANT: Sub-five-second latency is not guaranteed. Benchmark end-to-end p95
latency on representative statements in your deployment region before committing.
Disable automatic retries on the interactive path, and size concurrency and
Textract quotas for peak traffic—not just the ~0.23 pages/second daily average.

Install:
    pip install boto3 fastapi uvicorn python-multipart pymupdf

Configure AWS credentials through the normal AWS credential chain; grant
textract:AnalyzeDocument. Set AWS_REGION to a region near your backend.

Run:
    uvicorn app:app --host 0.0.0.0 --port 8000

Call from your TypeScript backend:
    POST /preview?page=1
    Content-Type: multipart/form-data
    file: statement.pdf

For production, store each uploaded document once and cache previews by document
hash + page + extraction version. This example accepts the PDF with each call.
"""

import os
import threading
import time

import boto3
import pymupdf
from botocore.config import Config
from botocore.exceptions import (
    BotoCoreError,
    ClientError,
    ConnectTimeoutError,
    EndpointConnectionError,
    ReadTimeoutError,
)
from fastapi import FastAPI, File, HTTPException, Query, UploadFile

app = FastAPI(title="Financial table previews")

MAX_CONCURRENCY = int(os.getenv("MAX_CONCURRENCY", "16"))
MAX_UPLOAD_BYTES = 50 * 1024 * 1024
MAX_API_BYTES = 10 * 1024 * 1024
slots = threading.BoundedSemaphore(MAX_CONCURRENCY)

textract = boto3.client(
    "textract",
    region_name=os.getenv("AWS_REGION", "us-east-1"),
    config=Config(
        connect_timeout=0.5,
        read_timeout=4.0,
        retries={"total_max_attempts": 1},
        max_pool_connections=MAX_CONCURRENCY,
    ),
)
# Socket timeouts are best-effort bounds, not an end-to-end five-second SLA.


def related(block, relationship_type, blocks):
    return [
        blocks[block_id]
        for relationship in block.get("Relationships", [])
        if relationship["Type"] == relationship_type
        for block_id in relationship.get("Ids", [])
        if block_id in blocks
    ]


def text_of(block, blocks):
    if block["BlockType"] == "WORD":
        return block.get("Text", "")
    if block["BlockType"] == "SELECTION_ELEMENT":
        return "[x]" if block["SelectionStatus"] == "SELECTED" else "[ ]"
    return " ".join(
        text
        for child in related(block, "CHILD", blocks)
        if (text := text_of(child, blocks))
    )


def cell_json(block, blocks):
    entity_types = set(block.get("EntityTypes", []))
    if block["BlockType"] == "MERGED_CELL":
        for child in related(block, "CHILD", blocks):
            entity_types.update(child.get("EntityTypes", []))

    return {
        "row": block["RowIndex"],             # One-based.
        "column": block["ColumnIndex"],       # One-based.
        "row_span": block.get("RowSpan", 1),
        "column_span": block.get("ColumnSpan", 1),
        "value": text_of(block, blocks),
        "entity_types": sorted(entity_types),
        "confidence": block.get("Confidence", 0) / 100,
        "bounding_box": block.get("Geometry", {}).get("BoundingBox"),
    }


def table_json(table, blocks):
    raw_cells = [
        block
        for block in related(table, "CHILD", blocks)
        if block["BlockType"] == "CELL"
    ]
    merged_cells = [
        block
        for block in related(table, "MERGED_CELL", blocks)
        if block["BlockType"] == "MERGED_CELL"
    ]

    # Replace constituent cells with a single cell carrying the merged span.
    covered = {
        (row, column)
        for merged in merged_cells
        for row in range(
            merged["RowIndex"],
            merged["RowIndex"] + merged.get("RowSpan", 1),
        )
        for column in range(
            merged["ColumnIndex"],
            merged["ColumnIndex"] + merged.get("ColumnSpan", 1),
        )
    }
    effective_cells = [
        cell
        for cell in raw_cells
        if (cell["RowIndex"], cell["ColumnIndex"]) not in covered
    ] + merged_cells

    cells = sorted(
        (cell_json(cell, blocks) for cell in effective_cells),
        key=lambda cell: (cell["row"], cell["column"]),
    )
    row_count = max(
        (cell["row"] + cell["row_span"] - 1 for cell in cells), default=0
    )
    column_count = max(
        (cell["column"] + cell["column_span"] - 1 for cell in cells), default=0
    )

    # Only the anchor of a merged cell contains its value.
    grid = [[""] * column_count for _ in range(row_count)]
    for cell in cells:
        grid[cell["row"] - 1][cell["column"] - 1] = cell["value"]

    headers = [
        cell for cell in cells if "COLUMN_HEADER" in cell["entity_types"]
    ]
    row_labels = [
        {
            "row": cell["row"],
            "row_span": cell["row_span"],
            "column": cell["column"],
            "value": cell["value"],
            "inferred": True,
            "method": "first_column_non_header",
        }
        for cell in cells
        if cell["column"] == 1
        and cell["column_span"] == 1
        and cell["value"]
        and not set(cell["entity_types"]).intersection(
            {"COLUMN_HEADER", "TABLE_TITLE", "TABLE_FOOTER", "TABLE_SECTION_TITLE"}
        )
    ]

    return {
        "id": table["Id"],
        "row_count": row_count,
        "column_count": column_count,
        "cells": cells,
        "grid": grid,
        "headers": headers,  # Empty if Textract did not identify headers.
        "row_labels": row_labels,
        "titles": [
            text_of(block, blocks)
            for block in related(table, "TABLE_TITLE", blocks)
        ],
        "footers": [
            text_of(block, blocks)
            for block in related(table, "TABLE_FOOTER", blocks)
        ],
        "confidence": table.get("Confidence", 0) / 100,
        "bounding_box": table.get("Geometry", {}).get("BoundingBox"),
    }


def extract_page_bytes(pdf_bytes, page_number):
    try:
        with pymupdf.open(stream=pdf_bytes, filetype="pdf") as document:
            if document.needs_pass:
                raise HTTPException(422, "Password-protected PDFs are unsupported.")
            page_count = document.page_count
            if page_number > page_count:
                raise HTTPException(422, f"PDF contains only {page_count} pages.")

            # Keep the PDF intact rather than rasterizing digital text.
            # Embedded scanned pages are also supported by Textract.
            with pymupdf.open() as single_page:
                single_page.insert_pdf(
                    document,
                    from_page=page_number - 1,
                    to_page=page_number - 1,
                )
                data = single_page.tobytes(garbage=3, deflate=True)
    except HTTPException:
        raise
    except (RuntimeError, ValueError) as exc:
        raise HTTPException(422, "Invalid or unreadable PDF.") from exc

    if len(data) > MAX_API_BYTES:
        raise HTTPException(422, "Selected page exceeds the synchronous API limit.")
    return data, page_count


@app.post("/preview")
def preview(
    file: UploadFile = File(...),
    page: int = Query(1, ge=1),
):
    # Avoid an invisible queue that consumes the preview latency budget.
    if not slots.acquire(blocking=False):
        raise HTTPException(
            503, "Preview capacity is busy.", headers={"Retry-After": "1"}
        )

    started = time.perf_counter()
    try:
        pdf_bytes = file.file.read(MAX_UPLOAD_BYTES + 1)
        if len(pdf_bytes) > MAX_UPLOAD_BYTES:
            raise HTTPException(413, "PDF exceeds the upload limit.")

        page_bytes, page_count = extract_page_bytes(pdf_bytes, page)

        response = textract.analyze_document(
            Document={"Bytes": page_bytes},
            FeatureTypes=["TABLES"],  # Do not request unnecessary analysis features.
        )
        blocks = {block["Id"]: block for block in response.get("Blocks", [])}
        tables = [
            table_json(block, blocks)
            for block in blocks.values()
            if block["BlockType"] == "TABLE"
        ]
        tables.sort(
            key=lambda table: (
                (table["bounding_box"] or {}).get("Top", 0),
                (table["bounding_box"] or {}).get("Left", 0),
            )
        )

        return {
            "provider": "amazon_textract",
            "page": page,
            "page_count": page_count,
            "tables": tables,
            "model_version": response.get("AnalyzeDocumentModelVersion"),
            "processing_ms": round((time.perf_counter() - started) * 1000),
            "requires_analyst_verification": True,
        }

    except (ConnectTimeoutError, ReadTimeoutError, EndpointConnectionError) as exc:
        raise HTTPException(504, "Extraction service timed out.") from exc
    except ClientError as exc:
        code = exc.response.get("Error", {}).get("Code", "")
        if code in {"ThrottlingException", "ProvisionedThroughputExceededException"}:
            raise HTTPException(
                503, "Extraction capacity is busy.", headers={"Retry-After": "1"}
            ) from exc
        if code in {
            "InvalidParameterException",
            "UnsupportedDocumentException",
            "BadDocumentException",
            "DocumentTooLargeException",
        }:
            raise HTTPException(422, "Textract could not process this page.") from exc
        raise HTTPException(502, "Extraction service failed.") from exc
    except BotoCoreError as exc:
        raise HTTPException(502, "Extraction service is unavailable.") from exc
    finally:
        slots.release()
