            text_of(block, blocks)
            for block in related(table, "TABLE_TITLE", blocks)
        ],
        "footers": [
            text_of(block, blocks)
            for block in related(table, "TABLE_FOOTER", blocks)
        ],
        "confidence": table.get("Confidence", 0) / 100,
        "bounding_box": table.get("Geometry", {}).get("BoundingBox"),
    }


def extract_page_bytes(pdf_bytes, page_number):
    try:
        with pymupdf.open(stream=pdf_bytes, filetype="pdf") as document:
            if document.needs_pass:
                raise HTTPException(422, "Password-protected PDFs are unsupported.")
            page_count = document.page_count
            if page_number > page_count:
                raise HTTPException(422, f"PDF contains only {page_count} pages.")

            # Keep the PDF intact rather than rasterizing digital text.
            # Embedded scanned pages are also supported by Textract.
            with pymupdf.open() as single_page:
                single_page.insert_pdf(
                    document,
                    from_page=page_number - 1,
                    to_page=page_number - 1,
                )
                data = single_page.tobytes(garbage=3, deflate=True)
    except HTTPException:
        raise
    except (RuntimeError, ValueError) as exc:
        raise HTTPException(422, "Invalid or unreadable PDF.") from exc

    if len(data) > MAX_API_BYTES:
        raise HTTPException(422, "Selected page exceeds the synchronous API limit.")
    return data, page_count


@app.post("/preview")
def preview(
    file: UploadFile = File(...),
    page: int = Query(1, ge=1),
):
    # Avoid an invisible queue that consumes the preview latency budget.
    if not slots.acquire(blocking=False):
        raise HTTPException(
            503, "Preview capacity is busy.", headers={"Retry-After": "1"}
        )

    started = time.perf_counter()
    try:
        pdf_bytes = file.file.read(MAX_UPLOAD_BYTES + 1)
        if len(pdf_bytes) > MAX_UPLOAD_BYTES:
            raise HTTPException(413, "PDF exceeds the upload limit.")

        page_bytes, page_count = extract_page_bytes(pdf_bytes, page)

        response = textract.analyze_document(
            Document={"Bytes": page_bytes},
            FeatureTypes=["TABLES"],  # Do not request unnecessary analysis features.
        )
        blocks = {block["Id"]: block for block in response.get("Blocks", [])}
        tables = [
            table_json(block, blocks)
            for block in blocks.values()
            if block["BlockType"] == "TABLE"
        ]
        tables.sort(
            key=lambda table: (
                (table["bounding_box"] or {}).get("Top", 0),
                (table["bounding_box"] or {}).get("Left", 0),
            )
        )

        return {
            "provider": "amazon_textract",
            "page": page,
            "page_count": page_count,
            "tables": tables,
            "model_version": response.get("AnalyzeDocumentModelVersion"),
            "processing_ms": round((time.perf_counter() - started) * 1000),
            "requires_analyst_verification": True,
        }

    except (ConnectTimeoutError, ReadTimeoutError, EndpointConnectionError) as exc:
        raise HTTPException(504, "Extraction service timed out.") from exc
    except ClientError as exc:
        code = exc.response.get("Error", {}).get("Code", "")
        if code in {"ThrottlingException", "ProvisionedThroughputExceededException"}:
            raise HTTPException(
                503, "Extraction capacity is busy.", headers={"Retry-After": "1"}
            ) from exc
        if code in {
            "InvalidParameterException",
            "UnsupportedDocumentException",
            "BadDocumentException",
            "DocumentTooLargeException",
        }:
            raise HTTPException(422, "Textract could not process this page.") from exc
        raise HTTPException(502, "Extraction service failed.") from exc
    except BotoCoreError as exc:
        raise HTTPException(502, "Extraction service is unavailable.") from exc
    finally:
        slots.release()
