                    "id": str(path.relative_to(source)),
                    "path": str(path),
                }
        return

    base_dir = source.parent
    with source.open("r", encoding="utf-8") as handle:
        for line_number, raw_line in enumerate(handle, 1):
            raw_line = raw_line.strip()
            if not raw_line:
                continue

            if raw_line.startswith("{"):
                record = json.loads(raw_line)
                path_value = record["path"]
                source_id = str(record.get("id", path_value))
            else:
                path_value = raw_line
                source_id = raw_line

            path = Path(path_value)
            if not path.is_absolute():
                path = base_dir / path
            path = path.resolve()

            if path.suffix.lower() not in SUPPORTED_EXTENSIONS:
                raise ValueError(
                    f"Unsupported file on line {line_number}: {path}"
                )
            if not path.is_file():
                raise FileNotFoundError(path)

            yield {"id": source_id, "path": str(path)}


def make_custom_id(index: int, source_id: str) -> str:
    digest = hashlib.sha256(source_id.encode("utf-8")).hexdigest()[:20]
    return f"receipt-{index:05d}-{digest}"


def upload_receipt(
    client: OpenAI,
    index: int,
    record: dict[str, str],
) -> dict[str, Any]:
    path = Path(record["path"])
    suffix = path.suffix.lower()

    if suffix in {".jpg", ".jpeg"}:
        purpose = "vision"
        mime_type = "image/jpeg"
        content_type = "input_image"
    elif suffix == ".pdf":
        purpose = "user_data"
        mime_type = "application/pdf"
        content_type = "input_file"
    else:
        raise ValueError(f"Unsupported file type: {path}")

    # OpenAI image inputs are limited to 20 MB; PDF inputs are limited to 50 MB.
    size = path.stat().st_size
    limit = 20 * 1024 * 1024 if content_type == "input_image" else 50 * 1024 * 1024
    if size > limit:
        raise ValueError(
            f"{path} is {size / 1024 / 1024:.1f} MB; "
            f"the input limit is {limit / 1024 / 1024:.0f} MB"
        )

    with path.open("rb") as file_handle:
        uploaded = client.files.create(
            file=(path.name, file_handle, mime_type),
            purpose=purpose,
        )

    return {
        "index": index,
        "id": record["id"],
        "path": str(path),
        "custom_id": make_custom_id(index, record["id"]),
        "openai_file_id": uploaded.id,
        "content_type": content_type,
    }


def build_batch_request(upload: dict[str, Any]) -> dict[str, Any]:
    if upload["content_type"] == "input_image":
        document_content = {
            "type": "input_image",
            "file_id": upload["openai_file_id"],
            "detail": "high",
        }
    else:
        document_content = {
            "type": "input_file",
            "file_id": upload["openai_file_id"],
        }

    return {
        "custom_id": upload["custom_id"],
        "method": "POST",
        "url": "/v1/responses",
        "body": {
            "model": MODEL,
            "input": [
                {
                    "role": "system",
                    "content": [
                        {
                            "type": "input_text",
                            "text": SYSTEM_PROMPT,
                        }
                    ],
                },
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": "Extract the receipt fields from this document.",
                        },
                        document_content,
                    ],
                },
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": "receipt_extraction",
                    "strict": True,
                    "schema": RECEIPT_SCHEMA,
                }
            },
            "max_output_tokens": 160,
        },
    }


def write_json_atomic(path: Path, value: Any) -> None:
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    temporary.replace(path)


def submit(source: Path, job_path: Path, workers: int) -> None:
    client = get_client()
    records = list(iter_source_records(source))

    if not records:
        raise ValueError("No JPEG or PDF receipts were found")
    if len(records) > MAX_REQUESTS_PER_BATCH:
        raise ValueError(
            f"Found {len(records):,} receipts. Split the source into shards of "
            f"at most {MAX_REQUESTS_PER_BATCH:,} receipts."
        )

    uploads: list[dict[str, Any]] = []
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            futures = {
                pool.submit(upload_receipt, client, index, record): record
                for index, record in enumerate(records)
            }

            completed = 0
            for future in concurrent.futures.as_completed(futures):
                uploads.append(future.result())
                completed += 1
                if completed % 100 == 0 or completed == len(records):
                    print(
                        f"Uploaded {completed:,}/{len(records):,}",
                        file=sys.stderr,
                    )
    except Exception:
        for upload in uploads:
            try:
                client.files.delete(upload["openai_file_id"])
            except Exception:
                pass
        raise

    uploads.sort(key=lambda item: item["index"])
    request_path = job_path.with_suffix(".requests.jsonl")
    request_path.parent.mkdir(parents=True, exist_ok=True)

    with request_path.open("w", encoding="utf-8") as handle:
        for upload in uploads:
            handle.write(
                json.dumps(build_batch_request(upload), ensure_ascii=False) + "\n"
            )

    try:
        with request_path.open("rb") as handle:
            batch_input_file = client.files.create(
                file=(request_path.name, handle, "application/jsonl"),
                purpose="batch",
            )

        batch = client.batches.create(
            input_file_id=batch_input_file.id,
            endpoint="/v1/responses",
            completion_window="24h",
            metadata={
                "workload": "receipt-extraction",
                "model": MODEL,
            },
        )
    except Exception:
        for upload in uploads:
            try:
                client.files.delete(upload["openai_file_id"])
            except Exception:
                pass
        raise

    job = {
        "batch_id": batch.id,
        "batch_input_file_id": batch_input_file.id,
        "model": MODEL,
        "created_at": int(time.time()),
        "status": batch.status,
        "receipts": uploads,
    }
    write_json_atomic(job_path, job)

    print(
        json.dumps(
            {
                "job": str(job_path),
                "batch_id": batch.id,
                "status": batch.status,
                "receipt_count": len(uploads),
            },
            indent=2,
        )
    )


def download_file(client: OpenAI, file_id: str) -> bytes:
    response = client.files.content(file_id)
    if hasattr(response, "read"):
        return response.read()
    return response.content


def extract_output_text(response_body: dict[str, Any]) -> str:
    for output_item in response_body.get("output", []):
        if output_item.get("type") != "message":
            continue
        for content_item in output_item.get("content", []):
            if content_item.get("type") == "output_text":
                return content_item["text"]
    raise ValueError("Response did not contain output_text")


def safe_delete(client: OpenAI, file_id: str | None) -> None:
    if not file_id:
        return
    try:
        client.files.delete(file_id)
    except Exception as exc:
        print(f"Warning: could not delete {file_id}: {exc}", file=sys.stderr)


def collect(
    job_path: Path,
    output_path: Path,
    wait: bool,
    poll_seconds: int,
    cleanup: bool,
) -> None:
    client = get_client()
    job = json.loads(job_path.read_text(encoding="utf-8"))
    receipt_by_custom_id = {
        item["custom_id"]: item for item in job["receipts"]
    }

    terminal_states = {"completed", "failed", "expired", "cancelled"}

    while True:
        batch = client.batches.retrieve(job["batch_id"])
        job["status"] = batch.status
        write_json_atomic(job_path, job)

        print(f"Batch {batch.id}: {batch.status}", file=sys.stderr)

        if batch.status in terminal_states:
            break
        if not wait:
            raise SystemExit(2)

        time.sleep(poll_seconds)

    error_path = output_path.with_suffix(".errors.jsonl")
    output_path.parent.mkdir(parents=True, exist_ok=True)

    if batch.error_file_id:
        error_path.with_suffix(".batch-errors.jsonl").write_bytes(
            download_file(client, batch.error_file_id)
        )

    completed_count = 0
    failed_count = 0
    input_tokens = 0
    output_tokens = 0

    with (
        output_path.open("w", encoding="utf-8") as output_handle,
        error_path.open("w", encoding="utf-8") as error_handle,
    ):
        if batch.output_file_id:
            raw_output = download_file(client, batch.output_file_id)

            for raw_line in raw_output.decode("utf-8").splitlines():
                if not raw_line.strip():
                    continue

                row = json.loads(raw_line)
                custom_id = row.get("custom_id")
                source = receipt_by_custom_id.get(custom_id, {})
                response = row.get("response") or {}
                status_code = response.get("status_code")
                body = response.get("body") or {}

                usage = body.get("usage") or {}
                input_tokens += int(usage.get("input_tokens", 0))
                output_tokens += int(usage.get("output_tokens", 0))

                if status_code != 200:
                    failed_count += 1
                    error_handle.write(
                        json.dumps(
                            {
                                "id": source.get("id"),
                                "path": source.get("path"),
                                "custom_id": custom_id,
                                "status_code": status_code,
                                "error": row.get("error") or body,
                            },
                            ensure_ascii=False,
                        )
                        + "\n"
                    )
                    continue

                try:
                    extracted = json.loads(extract_output_text(body))
                    result = {
                        "id": source.get("id"),
                        "merchant": extracted["merchant"],
                        "date": extracted["date"],
                        "currency": extracted["currency"],
                        "total": extracted["total"],
                    }
                    output_handle.write(
                        json.dumps(result, ensure_ascii=False) + "\n"
                    )
                    completed_count += 1
                except Exception as exc:
                    failed_count += 1
                    error_handle.write(
                        json.dumps(
                            {
                                "id": source.get("id"),
                                "path": source.get("path"),
                                "custom_id": custom_id,
                                "error": str(exc),
                                "response_body": body,
                            },
                            ensure_ascii=False,
                        )
                        + "\n"
                    )
        else:
            for source in job["receipts"]:
                failed_count += 1
                error_handle.write(
                    json.dumps(
                        {
                            "id": source["id"],
                            "path": source["path"],
                            "custom_id": source["custom_id"],
                            "error": f"Batch ended with status {batch.status}",
                        },
                        ensure_ascii=False,
                    )
                    + "\n"
                )

    estimated_cost = (
        input_tokens * BATCH_INPUT_USD_PER_MILLION
        + output_tokens * BATCH_OUTPUT_USD_PER_MILLION
    ) / 1_000_000

    processed = completed_count + failed_count
    projected_three_million = (
        estimated_cost / processed * 3_000_000 if processed else None
    )

    summary = {
        "batch_id": batch.id,
        "status": batch.status,
        "completed": completed_count,
        "failed": failed_count,
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "estimated_batch_cost_usd": round(estimated_cost, 4),
        "projected_cost_for_3m_receipts_usd": (
            round(projected_three_million, 2)
            if projected_three_million is not None
            else None
        ),
        "within_15000_budget_projection": (
            projected_three_million <= 15_000
            if projected_three_million is not None
            else None
        ),
        "output": str(output_path),
        "errors": str(error_path),
    }
    print(json.dumps(summary, indent=2))

    if cleanup:
        for receipt in job["receipts"]:
            safe_delete(client, receipt["openai_file_id"])
        safe_delete(client, job.get("batch_input_file_id"))
        safe_delete(client, batch.output_file_id)
        safe_delete(client, batch.error_file_id)

        job["cleaned_up"] = True
        write_json_atomic(job_path, job)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Asynchronous receipt extraction with the OpenAI Batch API"
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    submit_parser = subparsers.add_parser("submit")
    submit_parser.add_argument(
        "source",
        type=Path,
        help="Directory, text path list, or JSONL manifest",
    )
    submit_parser.add_argument("job", type=Path)
    submit_parser.add_argument(
        "--workers",
        type=int,
        default=12,
        help="Concurrent file uploads",
    )

    collect_parser = subparsers.add_parser("collect")
    collect_parser.add_argument("job", type=Path)
    collect_parser.add_argument(
        "--output",
        type=Path,
        default=Path("receipts.jsonl"),
    )
    collect_parser.add_argument(
        "--wait",
        action="store_true",
        help="Poll until the batch reaches a terminal state",
    )
    collect_parser.add_argument("--poll-seconds", type=int, default=60)
    collect_parser.add_argument(
        "--no-cleanup",
        action="store_true",
        help="Retain uploaded OpenAI files after collection",
    )

    args = parser.parse_args()

    if args.command == "submit":
        submit(args.source, args.job, args.workers)
    else:
        collect(
            job_path=args.job,
            output_path=args.output,
            wait=args.wait,
            poll_seconds=args.poll_seconds,
            cleanup=not args.no_cleanup,
        )


if __name__ == "__main__":
    main()
