"""
Recommendation: Azure AI Document Intelligence's hosted `prebuilt-invoice` API.

It supports English/German invoices, scanned PDFs, structured invoice fields,
line items, and field-level confidence. Enable high-resolution OCR for this
scan-heavy workload; benchmark it on your hardest invoices before committing.

No API can guarantee correct quantities/decimals or recover obscured text.
Confidence is not a calibrated probability of correctness. Tune review rules
on labeled invoices, measuring exact numeric accuracy and missed line items.
The checks below NEVER authorize payment or invent missing values.

Confirm regional availability, data-handling requirements, add-on pricing,
and page/throughput quotas for your peak workload—not just monthly volume.

Install:
    pip install azure-ai-documentintelligence azure-core

Configure:
    export AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT="https://YOUR-RESOURCE.cognitiveservices.azure.com"
    export AZURE_DOCUMENT_INTELLIGENCE_KEY="YOUR-KEY"

Run:
    python extract_invoice.py invoice.pdf > invoice.json

Protect the output: it contains sensitive supplier and financial information.
"""

import argparse
import hashlib
import json
import os
from decimal import Decimal, InvalidOperation
from pathlib import Path

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import (
    AnalyzeDocumentRequest,
    DocumentAnalysisFeature,
)
from azure.core.credentials import AzureKeyCredential


API_VERSION = "2024-11-30"
MODEL_ID = "prebuilt-invoice"

# Conservative starting policy, NOT an empirically validated accuracy guarantee.
MIN_CONFIDENCE = float(os.getenv("INVOICE_MIN_CONFIDENCE", "0.98"))

# Configure this policy for the currencies your organization actually accepts.
ROUNDING_TOLERANCE = {
    "EUR": Decimal("0.01"),
    "USD": Decimal("0.01"),
    "GBP": Decimal("0.01"),
    "CHF": Decimal("0.01"),
    "JPY": Decimal("1"),
    "KWD": Decimal("0.001"),
}


def number_string(value):
    """Represent API-normalized numbers as strings, using no float arithmetic."""
    return None if value is None else format(Decimal(str(value)), "f")


def unpack_field(field, path, evidence):
    """Preserve normalized values plus original text and review coordinates."""
    kind = getattr(field.type, "value", field.type)
    evidence[path] = {
        "type": kind,
        "confidence": field.confidence,
        "source_text": field.content,
        "regions": [
            region.as_dict() for region in (field.bounding_regions or [])
        ],
    }

    if kind == "object":
        return {
            name: unpack_field(child, f"{path}.{name}", evidence)
            for name, child in (field.value_object or {}).items()
        }

    if kind == "array":
        return [
            unpack_field(child, f"{path}[{index}]", evidence)
            for index, child in enumerate(field.value_array or [])
        ]

    if kind == "currency":
        currency = field.value_currency
        if currency is None:
            return None
        return {
            "amount": number_string(currency.amount),
            "currency_code": currency.currency_code,
            "currency_symbol": currency.currency_symbol,
        }

    if kind == "number":
        return number_string(field.value_number)

    if kind == "integer":
        return number_string(field.value_integer)

    if kind == "address":
        return field.value_address.as_dict() if field.value_address else None

    if kind in {"date", "time"}:
        value = getattr(field, f"value_{kind}", None)
        return value.isoformat() if value is not None else None

    if kind == "string":
        return field.value_string

    # Keep unusual fields rather than silently discarding them.
    return field.content


def decimal_value(value):
    """Use normalized API values, never heuristically parse German/English text."""
    if isinstance(value, dict):
        value = value.get("amount")
    if value is None:
        return None
    try:
        result = Decimal(str(value))
        return result if result.is_finite() else None
    except InvalidOperation:
        return None


def currency_codes(value):
    codes = set()
    if isinstance(value, dict):
        if "amount" in value and value.get("currency_code"):
            codes.add(value["currency_code"].upper())
        for child in value.values():
            codes.update(currency_codes(child))
    elif isinstance(value, list):
        for child in value:
            codes.update(currency_codes(child))
    return codes


def normalize_invoice(document):
    evidence = {}
    fields = {
        name: unpack_field(field, name, evidence)
        for name, field in (document.fields or {}).items()
    }
    issues = []

    def require(value, path):
        if value is None or value == "" or value == [] or value == {}:
            issues.append(f"Missing required field: {path}")

    def check_confidence(path):
        confidence = evidence.get(path, {}).get("confidence")
        if confidence is None or confidence < MIN_CONFIDENCE:
            issues.append(f"Low or unavailable confidence: {path}")

    required = (
        "VendorName",
        "InvoiceId",
        "SubTotal",
        "TotalTax",
        "InvoiceTotal",
    )
    for name in required:
        require(fields.get(name), name)
        check_confidence(name)

    # Optional identifiers still matter when present.
    for name in ("VendorTaxId", "InvoiceDate", "PurchaseOrder"):
        if name in fields:
            check_confidence(name)

    # Gate every extracted numeric field, including quantities, taxes, and prices.
    for path, info in evidence.items():
        if info["type"] in {"currency", "number", "integer"}:
            check_confidence(path)

    items = fields.get("Items")
    if not isinstance(items, list):
        items = []
    require(items, "Items")

    codes = currency_codes(fields)
    currency = next(iter(codes)) if len(codes) == 1 else None
    tolerance = ROUNDING_TOLERANCE.get(currency)

    if not codes:
        issues.append("Currency is unknown; do not infer it from a symbol alone")
    elif len(codes) > 1:
        issues.append(f"Multiple currencies require review: {sorted(codes)}")
    elif tolerance is None:
        issues.append(f"No reconciliation policy configured for {currency}")

    def compare(actual, expected, label):
        if (
            tolerance is not None
            and actual is not None
            and expected is not None
            and abs(actual - expected) > tolerance
        ):
            issues.append(f"Reconciliation failed: {label}")

    for name in ("SubTotal", "TotalTax", "InvoiceTotal", "AmountDue"):
        if name in fields and decimal_value(fields[name]) is None:
            issues.append(f"Unusable normalized amount: {name}")

    line_items = []
    line_amounts = []

    for index, item in enumerate(items):
        path = f"Items[{index}]"
        if not isinstance(item, dict):
            issues.append(f"Malformed line item: {path}")
            line_amounts.append(None)
            line_items.append({"unparsed": item})
            continue

        for name in ("Description", "Quantity", "UnitPrice", "Amount"):
            require(item.get(name), f"{path}.{name}")
            check_confidence(f"{path}.{name}")

        quantity = decimal_value(item.get("Quantity"))
        unit_price = decimal_value(item.get("UnitPrice"))
        amount = decimal_value(item.get("Amount"))
        line_amounts.append(amount)

        for name, value in (
            ("Quantity", quantity),
            ("UnitPrice", unit_price),
            ("Amount", amount),
        ):
            if value is None:
                issues.append(f"Unusable normalized number: {path}.{name}")

        if quantity is not None and unit_price is not None:
            compare(
                amount,
                quantity * unit_price,
                f"{path}: quantity × unit price versus amount",
            )

        line_items.append({
            "description": item.get("Description"),
            "product_code": item.get("ProductCode"),
            "quantity": item.get("Quantity"),
            "unit": item.get("Unit"),
            "unit_price": item.get("UnitPrice"),
            "amount": item.get("Amount"),
            "tax": item.get("Tax"),
            "tax_rate": item.get("TaxRate"),
        })

    subtotal = decimal_value(fields.get("SubTotal"))
    tax = decimal_value(fields.get("TotalTax"))
    total = decimal_value(fields.get("InvoiceTotal"))

    # These are conservative checks for ordinary invoices. Discounts, shipping,
    # withholding, tax-inclusive pricing, etc. can legitimately trigger review.
    # Never "fix" an extracted value merely to make the arithmetic reconcile.
    if line_amounts and all(value is not None for value in line_amounts):
        compare(
            subtotal,
            sum(line_amounts, Decimal("0")),
            "sum of line amounts versus subtotal",
        )
    if subtotal is not None and tax is not None:
        compare(total, subtotal + tax, "subtotal + tax versus invoice total")

    issues = list(dict.fromkeys(issues))
    return {
        "supplier": {
            "name": fields.get("VendorName"),
            "address": fields.get("VendorAddress"),
            "tax_id": fields.get("VendorTaxId"),
        },
        "invoice_number": fields.get("InvoiceId"),
        "invoice_date": fields.get("InvoiceDate"),
        "due_date": fields.get("DueDate"),
        "purchase_order": fields.get("PurchaseOrder"),
        "currency": currency,
        "taxes": {
            "total": fields.get("TotalTax"),
            "breakdown": fields.get("TaxDetails", []),
        },
        "totals": {
            "subtotal": fields.get("SubTotal"),
            "invoice_total": fields.get("InvoiceTotal"),
            "amount_due": fields.get("AmountDue"),
            "previous_unpaid_balance": fields.get("PreviousUnpaidBalance"),
        },
        "line_items": line_items,
        "review_required": bool(issues),
        "review_reasons": issues,
        "payment_authorized": False,
        # Preserve every recognized field, including fields outside our mapping.
        "provider_fields": fields,
        "evidence": evidence,
    }


def extract_invoice(pdf_path):
    pdf = Path(pdf_path).read_bytes()
    if b"%PDF-" not in pdf[:1024]:
        raise ValueError("Input does not appear to be a PDF")

    if not 0 <= MIN_CONFIDENCE <= 1:
        raise ValueError("INVOICE_MIN_CONFIDENCE must be between 0 and 1")

    with DocumentIntelligenceClient(
        endpoint=os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"],
        credential=AzureKeyCredential(
            os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
        ),
        api_version=API_VERSION,
    ) as client:
        poller = client.begin_analyze_document(
            MODEL_ID,
            AnalyzeDocumentRequest(bytes_source=pdf),
            features=[DocumentAnalysisFeature.OCR_HIGH_RESOLUTION],
            # Leave locale unset for mixed English/German input.
        )
        result = poller.result()

    invoices = [
        normalize_invoice(document) for document in (result.documents or [])
    ]
    packet_issues = []
    if len(invoices) != 1:
        packet_issues.append(
            f"Expected one invoice per PDF; extracted {len(invoices)}. "
            "Review document boundaries before processing."
        )

    return {
        "source_sha256": hashlib.sha256(pdf).hexdigest(),
        "provider": "azure-ai-document-intelligence",
        "model": result.model_id,
        "api_version": API_VERSION,
        "confidence_threshold": MIN_CONFIDENCE,
        "review_required": bool(packet_issues) or any(
            invoice["review_required"] for invoice in invoices
