"""
Recommendation: Amazon Textract, using synchronous AnalyzeDocument(TABLES).

It provides structured cells, merged cells, column-header classifications, and
confidence scores without custom training. Preserve financial values as strings;
infer row labels from the first column and let analysts correct them.

Important: sub-five-second latency is NOT guaranteed. Benchmark regional p95/p99
on your statements before committing. Process only the requested preview page,
reuse connections, and provision quotas for peak traffic—not just the average
of ~0.23 pages/second. A timeout is not a successful preview.

Your TypeScript backend can call this service, or implement the same flow using
@aws-sdk/client-textract.

Install:
    pip install boto3 pymupdf fastapi uvicorn python-multipart

Configure AWS credentials through an IAM role or the standard credential chain.
Required permission: textract:AnalyzeDocument

Run behind your application's authentication:
    AWS_DEFAULT_REGION=us-east-1 uvicorn app:app --port 8000

Request (zero-based page):
    curl -F "document=@statement.pdf" -F "page=0" localhost:8000/preview
"""

import asyncio
import os
import time

import boto3
import pymupdf
from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError
from fastapi import FastAPI, File, Form, HTTPException, UploadFile


app = FastAPI()
MAX_UPLOAD_BYTES = 32 * 1024 * 1024
MAX_IMAGE_BYTES = 10 * 1024 * 1024
PROCESSING_BUDGET_SECONDS = 4.5  # Excludes upload transfer and response transit.

# Reuse a regional client; automatic retries can consume the preview budget.
textract = boto3.client(
    "textract",
    region_name=os.getenv("AWS_DEFAULT_REGION", "us-east-1"),
    config=Config(
        connect_timeout=0.5,
        read_timeout=4.0,
        retries={"total_max_attempts": 1},
        max_pool_connections=32,
    ),
)


def page_image(data: bytes, page_index: int) -> bytes:
    """Render only the requested PDF page, or accept an existing PNG/JPEG."""
    if page_index < 0:
        raise ValueError("page must be zero or greater")

    if data.startswith((b"\x89PNG\r\n\x1a\n", b"\xff\xd8\xff")):
        if page_index != 0:
            raise ValueError("PNG/JPEG inputs contain only page 0")
        image = data
    else:
        try:
            document = pymupdf.open(stream=data, filetype="pdf")
        except Exception as exc:
            raise ValueError("Provide a valid PDF, PNG, or JPEG") from exc

        with document:
            if document.needs_pass:
                raise ValueError("Password-protected PDFs are not supported")
            if page_index >= document.page_count:
                raise ValueError("Requested page does not exist")

            page = document.load_page(page_index)
            # Typically adequate for clean statements; validate on your scans.
            scale = min(150 / 72, 5000 / max(page.rect.width, page.rect.height))
            image = page.get_pixmap(
                matrix=pymupdf.Matrix(scale, scale),
                colorspace=pymupdf.csRGB,
                alpha=False,
            ).tobytes("png")

    if len(image) > MAX_IMAGE_BYTES:
        raise ValueError("Page image exceeds Textract's 10 MB synchronous limit")
    return image


def structured_tables(response: dict) -> list[dict]:
    blocks = {block["Id"]: block for block in response.get("Blocks", [])}

    def related(block: dict, relationship_type: str) -> list[dict]:
        return [
            blocks[block_id]
            for relationship in block.get("Relationships", [])
            if relationship["Type"] == relationship_type
            for block_id in relationship.get("Ids", [])
            if block_id in blocks
        ]

    def text(block: dict) -> str:
        if block["BlockType"] == "WORD":
            return block.get("Text", "")
        if block["BlockType"] == "SELECTION_ELEMENT":
            return "[x]" if block.get("SelectionStatus") == "SELECTED" else "[ ]"
        return " ".join(
            value
            for child in related(block, "CHILD")
            if (value := text(child))
        )

    def cell(block: dict) -> dict:
        return {
            "row_index": block["RowIndex"] - 1,
            "column_index": block["ColumnIndex"] - 1,
            "row_span": block.get("RowSpan", 1),
            "column_span": block.get("ColumnSpan", 1),
            "value": text(block),  # Never silently convert financial numbers.
            "roles": block.get("EntityTypes", []),
            "confidence": block.get("Confidence"),  # Textract scale: 0–100.
            "bounding_box": block.get("Geometry", {}).get("BoundingBox"),
        }

    tables = []
    for table in response.get("Blocks", []):
        if table["BlockType"] != "TABLE":
            continue

        cells = sorted(
            [
                cell(block)
                for block in related(table, "CHILD")
                if block["BlockType"] == "CELL"
            ],
            key=lambda item: (item["row_index"], item["column_index"]),
        )
        merged_cells = [
            cell(block) for block in related(table, "MERGED_CELL")
        ]

        headers = [
            item
            for item in cells + merged_cells
            if "COLUMN_HEADER" in item["roles"]
        ]
        row_labels = [
            {
                "row_index": item["row_index"],
                "value": item["value"],
                "inferred": True,
                "inference": "first_column",
            }
            for item in cells
            if item["column_index"] == 0
            and item["value"]
            and not set(item["roles"]).intersection(
                {"COLUMN_HEADER", "TABLE_TITLE", "TABLE_FOOTER"}
            )
        ]

        tables.append(
            {
                "table_index": len(tables),
                "cells": cells,
                # Separate from constituent cells; do not concatenate both.
                "merged_cells": merged_cells,
                "headers": headers,
                "row_labels": row_labels,
                "confidence": table.get("Confidence"),
                "bounding_box": table.get("Geometry", {}).get("BoundingBox"),
            }
        )
    return tables


def extract_page(data: bytes, page_index: int) -> dict:
    started = time.perf_counter()
    image = page_image(data, page_index)
    response = textract.analyze_document(
        Document={"Bytes": image},
        FeatureTypes=["TABLES"],  # Avoid unnecessary FORMS/QUERIES work.
    )
    return {
        "provider": "amazon-textract",
        "page_index": page_index,
        "tables": structured_tables(response),
        "processing_ms": round((time.perf_counter() - started) * 1000),
        "requires_analyst_review": True,
    }


@app.post("/preview")
async def preview(
    document: UploadFile = File(...),
    page: int = Form(0),
) -> dict:
    try:
        data = await document.read(MAX_UPLOAD_BYTES + 1)
    finally:
        await document.close()

    if len(data) > MAX_UPLOAD_BYTES:
        raise HTTPException(413, "Upload exceeds this service's 32 MB limit")
    if not data:
        raise HTTPException(400, "Empty upload")

    try:
        # The blocking SDK call runs off the event loop.
        # Timing out does not cancel the underlying AWS request.
        return await asyncio.wait_for(
            asyncio.to_thread(extract_page, data, page),
            timeout=PROCESSING_BUDGET_SECONDS,
        )
    except asyncio.TimeoutError:
        raise HTTPException(
            504,
            "Extraction exceeded the preview budget. Offer background processing "
            "rather than silently retrying on the interactive path.",
        )
    except ValueError as exc:
        raise HTTPException(422, str(exc))
    except (ClientError, BotoCoreError):
        # Avoid exposing or logging financial documents and provider payloads.
        raise HTTPException(502, "Document extraction service unavailable")
