"""
Use Amazon Textract: hosted, pretrained form extraction with checkbox detection.
Add Queries to return names, dates, and addresses under fixed JSON keys.
No labeling, custom models, or workflow platform needed.

Your Java backend can use the same APIs through AWS SDK for Java v2.
This Python reference handles one registration per PDF, including multipage PDFs.

Install:
    pip install boto3

Run:
    python extract_registration.py form.pdf --bucket YOUR_PRIVATE_BUCKET \
        --region us-east-1 > registration.json

Use AWS workload credentials or an AWS profile—not hard-coded keys.
The private S3 bucket must be in the same region as Textract.
Configure short retention, including noncurrent versions if versioning is enabled.
Required permissions: s3:PutObject/GetObject/DeleteObject and
textract:StartDocumentAnalysis/GetDocumentAnalysis.
"""

import argparse
import json
import sys
import time
import uuid
from pathlib import Path

import boto3
from botocore.exceptions import ClientError


# Adjust questions to match your registration form's terminology.
# Output keys remain fixed even when an answer cannot be found.
QUESTIONS = {
    "full_name": "What is the registrant's full name?",
    "date_of_birth": "What is the registrant's date of birth?",
    "address": "What is the registrant's complete mailing address?",
    "registration_date": "What is the registration date?",
}

REQUIRED_FIELDS = {"full_name", "address"}  # Change to your business requirements.
REVIEW_THRESHOLD = 90.0  # Textract scores are 0–100; validate on real scans.


def extract_blocks(textract, bucket, key, timeout_seconds=600):
    started = textract.start_document_analysis(
        DocumentLocation={"S3Object": {"Bucket": bucket, "Name": key}},
        FeatureTypes=["FORMS", "QUERIES"],
        QueriesConfig={
            "Queries": [
                {"Text": question, "Alias": alias, "Pages": ["*"]}
                for alias, question in QUESTIONS.items()
            ]
        },
        ClientRequestToken=uuid.uuid4().hex,
    )

    job_id = started["JobId"]
    deadline = time.monotonic() + timeout_seconds

    while True:
        response = textract.get_document_analysis(JobId=job_id, MaxResults=1000)
        status = response["JobStatus"]

        if status == "FAILED":
            raise RuntimeError(
                response.get("StatusMessage", "Textract analysis failed")
            )
        if status in {"SUCCEEDED", "PARTIAL_SUCCESS"}:
            break
        if time.monotonic() >= deadline:
            raise TimeoutError(f"Textract job timed out: {job_id}")
        time.sleep(2)

    blocks = list(response.get("Blocks", []))
    warnings = list(response.get("Warnings", []))
    token = response.get("NextToken")

    while token:
        response = textract.get_document_analysis(
            JobId=job_id, NextToken=token, MaxResults=1000
        )
        blocks.extend(response.get("Blocks", []))
        warnings.extend(response.get("Warnings", []))
        token = response.get("NextToken")

    return blocks, status, warnings


def registration_json(blocks, status, warnings):
    by_id = {block["Id"]: block for block in blocks}

    def related(block, relationship_type):
        return [
            by_id[block_id]
            for relation in block.get("Relationships", [])
            if relation["Type"] == relationship_type
            for block_id in relation["Ids"]
            if block_id in by_id
        ]

    def words(block):
        return " ".join(
            child["Text"]
            for child in related(block, "CHILD")
            if child["BlockType"] == "WORD"
        ).strip()

    candidates = {alias: [] for alias in QUESTIONS}

    for block in blocks:
        if block["BlockType"] != "QUERY":
            continue
        alias = block.get("Query", {}).get("Alias")
        if alias not in candidates:
            continue

        for answer in related(block, "ANSWER"):
            text = answer.get("Text", "").strip()
            if text:
                candidates[alias].append({
                    "value": text,
                    "confidence": answer.get("Confidence"),
                    "page": answer.get("Page", block.get("Page")),
                })

    fields = {}
    review_reasons = []

    for alias, answers in candidates.items():
        fields[alias] = max(
            answers,
            key=lambda answer: answer["confidence"] or 0,
            default={"value": None, "confidence": None, "page": None},
        )

        field = fields[alias]
        if field["value"] is None and alias in REQUIRED_FIELDS:
            review_reasons.append(f"missing_required_field:{alias}")
        elif field["value"] is not None:
            if (field["confidence"] or 0) < REVIEW_THRESHOLD:
                review_reasons.append(f"low_confidence:{alias}")

        if len({answer["value"].casefold() for answer in answers}) > 1:
            review_reasons.append(f"conflicting_answers:{alias}")

    # Associate checkbox marks with the form keys Textract detected.
    # Preserve labels instead of inventing application-specific checkbox names.
    checkbox_context = {}

    for block in blocks:
        if (
            block["BlockType"] == "KEY_VALUE_SET"
            and "KEY" in block.get("EntityTypes", [])
        ):
            label = words(block) or None
            for value in related(block, "VALUE"):
                option_text = words(value) or None
                for child in related(value, "CHILD"):
                    if child["BlockType"] == "SELECTION_ELEMENT":
                        checkbox_context[child["Id"]] = {
                            "label": label,
                            "option_text": option_text,
                            "association_confidence": min(
                                block.get("Confidence", 0),
                                value.get("Confidence", 0),
                            ),
                        }

    checkboxes = []

    for block in blocks:
        if block["BlockType"] != "SELECTION_ELEMENT":
            continue

        context = checkbox_context.get(block["Id"], {})
        selection = block.get("SelectionStatus")
        selected = {
            "SELECTED": True,
            "NOT_SELECTED": False,
        }.get(selection)

        checkbox = {
            "label": context.get("label"),
            "option_text": context.get("option_text"),
            "selected": selected,
            "confidence": block.get("Confidence"),
            "association_confidence": context.get("association_confidence"),
            "page": block.get("Page"),
            "bounding_box": block.get("Geometry", {}).get("BoundingBox"),
        }
        checkboxes.append(checkbox)

        index = len(checkboxes) - 1
        if (
            not checkbox["label"]
            or selected is None
            or (checkbox["confidence"] or 0) < REVIEW_THRESHOLD
            or (checkbox["association_confidence"] or 0) < REVIEW_THRESHOLD
        ):
            review_reasons.append(f"check_checkbox:{index}")

    if status != "SUCCEEDED" or warnings:
        review_reasons.append("incomplete_document_analysis")

    # Dates stay as printed: do not silently guess ambiguous date formats.
    # Confidence cannot detect every error; test representative scans before launch.
    return {
        "schema_version": "1.0",
        "fields": fields,
        "checkboxes": checkboxes,
        "needs_review": bool(review_reasons),
        "review_reasons": review_reasons,
        "service_warnings": warnings,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("pdf", type=Path)
    parser.add_argument("--bucket", required=True)
    parser.add_argument("--region", required=True)
    args = parser.parse_args()

    if not args.pdf.is_file() or args.pdf.suffix.lower() != ".pdf":
        parser.error("Provide an existing PDF file.")

    session = boto3.Session(region_name=args.region)
    s3 = session.client("s3")
    textract = session.client("textract")

    # Avoid putting names or other personal information into object keys.
    key = f"registration-ocr/{uuid.uuid4().hex}.pdf"
    s3.upload_file(
        str(args.pdf),
        args.bucket,
        key,
        ExtraArgs={"ContentType": "application/pdf"},
    )

    try:
        blocks, status, warnings = extract_blocks(textract, args.bucket, key)
        result = registration_json(blocks, status, warnings)
        # Send this JSON to your application; avoid logging personal information.
        print(json.dumps(result, ensure_ascii=False, indent=2))
    finally:
        try:
            s3.delete_object(Bucket=args.bucket, Key=key)
        except ClientError:
            print(
                "Warning: temporary PDF cleanup failed; enforce bucket retention.",
                file=sys.stderr,
            )


if __name__ == "__main__":
    main()
