        try:
            s3.delete_object(Bucket=args.bucket, Key=key)
        except ClientError:
            print(
                "Warning: temporary PDF cleanup failed; enforce bucket retention.",
                file=sys.stderr,
            )


if __name__ == "__main__":
    main()
