- Independent extraction checks table inventory, cell positions, text, and spans.
- Financial values remain strings: no floating-point conversion, translation,
  sign normalization, inferred units, or silent correction.
- CSV cannot represent merges by itself. cells.csv is the lossless structural
  export; individual table CSVs are convenient views with merged cells populated
  only at their upper-left anchor.
- Units, captions, footnotes, raw page text, and source geometry are retained.

IMPORTANT: agreement between engines is not proof of correctness. Benchmark on
representative labeled reports before production, and retain stratified audits.
Disagreements become targeted exceptions, not guessed values. This worker does
not silently stitch tables across pages.

For ~8,000 reports/month, invoke workers from a durable Java-side job queue,
negotiate API quotas, and keep documents/checkpoints in encrypted storage.
The Python CLI emits a JSON manifest for Java to consume.

Install:
    pip install requests openai pydantic pymupdf pillow

Environment:
    AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT=https://YOUR-RESOURCE.cognitiveservices.azure.com
    AZURE_DOCUMENT_INTELLIGENCE_KEY=...
    OPENAI_API_KEY=...
    OPENAI_VISION_MODEL=gpt-5   # Pin a benchmark-approved snapshot in production.

Usage:
    python extract_financial_tables.py annual_report.pdf --out ./output

Only status="machine_checked" releases CSVs into the machine_checked directory.
Otherwise, candidate CSVs and exceptions.json remain available for review.
Use suitable vendor data-residency/retention agreements for confidential PDFs;
store=False alone is not a zero-retention guarantee.
"""

from __future__ import annotations

import argparse
import base64
import csv
import hashlib
import io
import json
import os
import re
import shutil
import time
import unicodedata
from pathlib import Path
from typing import Literal

import fitz  # PyMuPDF
import requests
from openai import OpenAI
from PIL import Image
from pydantic import BaseModel, ConfigDict, Field
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry


API_VERSION = "2024-11-30"
MODEL = os.getenv("OPENAI_VISION_MODEL", "gpt-5")
DPI = 300
TILE_SIZE = 1536
TILE_OVERLAP = 256
PIPELINE_VERSION = "financial-tables-v1"

PROMPT = """
Independently transcribe every table on this ONE PDF page.
The overview and overlapping detail tiles show the SAME page. Do not duplicate
tables because they appear in multiple images. Order tables top-to-bottom, then
left-to-right. Extract all tables, not only those you consider financial.

Preserve the original English or French. Never translate, calculate, repair,
round, or infer values. Preserve decimal/grouping separators, currency symbols,
percent signs, minus signs, parentheses, dashes, and footnote markers.
Do not add Markdown or HTML markup to cell text.

Use zero-based row/column indices. row_count includes all header rows.
Represent each merged cell ONCE at its upper-left anchor with its full spans.
Preserve multi-level headers structurally; do not flatten or repeat them.
Include every nonempty cell. Empty cells may be included but must not overlap.
Keep blank cells distinct from printed dashes and zeros.

Record footnote_refs as literal substrings of the corresponding cell text.
Include visible table-associated captions, unit statements, and footnote text
verbatim in context. Do not invent unit scope or inherit units from unseen pages.
Do not join tables across pages.

If table boundaries, cell placement, small text, signs, references, or associated
context cannot be read confidently, describe the precise problem in uncertainties.
Do not silently resolve ambiguity. Ignore unreadable decorative/non-table text.
"""


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class Cell(StrictModel):
    row: int = Field(ge=0)
    column: int = Field(ge=0)
    row_span: int = Field(ge=1)
    column_span: int = Field(ge=1)
    kind: Literal[
        "content", "columnHeader", "rowHeader", "stubHead", "description"
    ]
    text: str
    footnote_refs: list[str]


class Context(StrictModel):
    kind: Literal["caption", "unit", "footnote"]
    text: str


class Table(StrictModel):
    row_count: int = Field(ge=1)
    column_count: int = Field(ge=1)
    cells: list[Cell]
    context: list[Context]


class PageRead(StrictModel):
    tables: list[Table]
    uncertainties: list[str]


def write_json(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    temporary.replace(path)


def read_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def comparison_text(text: str) -> str:
    # Comparison only. Export the original text, not this normalized version.
    # Deliberately do NOT normalize minus signs, digits, punctuation, or units.
    return re.sub(r"\s+", " ", unicodedata.normalize("NFC", text)).strip()


def compact_text(text: str) -> str:
    return re.sub(r"\s+", "", unicodedata.normalize("NFC", text))


def write_csv(path: Path, header: list[str] | None, rows) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.writer(stream, quoting=csv.QUOTE_ALL, lineterminator="\n")
        if header is not None:
            writer.writerow(header)
        writer.writerows(rows)
    # Consume as data. Quoting does not prevent spreadsheet formula evaluation;
    # altering formula-like source text would violate lossless transcription.


def azure_layout(pdf: Path, cache: Path) -> dict:
    """Submit once, persist the operation URL, and resume polling after restarts."""
    result_path = cache / "azure-layout.json"
    if result_path.exists():
        return read_json(result_path)

    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"].rstrip("/")
    session = requests.Session()
    session.headers["Ocp-Apim-Subscription-Key"] = os.environ[
        "AZURE_DOCUMENT_INTELLIGENCE_KEY"
    ]
    session.mount(
        "https://",
        HTTPAdapter(
            max_retries=Retry(
                total=6,
                backoff_factor=2,
                status_forcelist=[429, 500, 502, 503, 504],
                allowed_methods=["GET"],  # Do not blindly repeat paid submissions.
                respect_retry_after_header=True,
            )
        ),
    )

    operation_path = cache / "azure-operation.json"
    if operation_path.exists():
        operation_url = read_json(operation_path)["url"]
    else:
        with pdf.open("rb") as stream:
            response = session.post(
                f"{endpoint}/documentintelligence/documentModels/"
                "prebuilt-layout:analyze",
                params={
                    "api-version": API_VERSION,
                    "features": "ocrHighResolution",
                },
                headers={"Content-Type": "application/pdf"},
                data=stream,
                timeout=(30, 300),
            )
        response.raise_for_status()
        operation_url = response.headers["Operation-Location"]
        write_json(operation_path, {"url": operation_url})

    deadline = time.monotonic() + 7200
    while time.monotonic() < deadline:
        response = session.get(operation_url, timeout=(30, 120))
        response.raise_for_status()
        body = response.json()
        status = body.get("status", "").lower()

        if status == "succeeded":
            result = body["analyzeResult"]
            write_json(result_path, result)
            return result
        if status in {"failed", "canceled", "cancelled"}:
            raise RuntimeError(f"Document Intelligence failed: {body.get('error')}")

        retry_after = response.headers.get("Retry-After", "3")
        time.sleep(min(60, max(1, float(retry_after))) if retry_after.isdigit() else 3)

    raise TimeoutError("Azure polling timed out; rerun to resume the saved operation.")


def png_url(image: Image.Image) -> str:
    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return "data:image/png;base64," + base64.b64encode(buffer.getvalue()).decode()


def page_images(page: fitz.Page) -> list[dict]:
    """Use an overview plus overlapping crops so small type is not lost."""
    pixmap = page.get_pixmap(dpi=DPI, colorspace=fitz.csRGB, alpha=False)
    image = Image.frombytes("RGB", (pixmap.width, pixmap.height), pixmap.samples)
    overview = image.copy()
    overview.thumbnail((1800, 1800))

    content = [
        {
            "type": "input_text",
            "text": (
                f"Page {page.number + 1}; full raster size "
                f"{image.width} x {image.height} pixels. Overview follows."
            ),
        },
        {"type": "input_image", "image_url": png_url(overview), "detail": "high"},
    ]

    step = TILE_SIZE - TILE_OVERLAP
    positions = [
        (x, y)
        for y in range(0, image.height, step)
        for x in range(0, image.width, step)
    ]
    if len(positions) > 64:
        raise ValueError("Oversized page: needs a specialized tiling workflow.")

    for x, y in positions:
        box = (
            x,
            y,
            min(x + TILE_SIZE, image.width),
            min(y + TILE_SIZE, image.height),
        )
        content.extend(
            [
                {
                    "type": "input_text",
                    "text": f"Detail crop, full-page pixel coordinates: {box}.",
                },
                {
                    "type": "input_image",
                    "image_url": png_url(image.crop(box)),
                    "detail": "high",
                },
            ]
        )
    return content


def independent_read(
    client: OpenAI, page: fitz.Page, cache: Path
) -> PageRead:
    path = cache / f"vision-page-{page.number + 1:04d}.json"
    if path.exists():
        return PageRead.model_validate(read_json(path)["extraction"])

    options = {}
    if MODEL.startswith(("gpt-5", "o1", "o3", "o4")):
        options["reasoning"] = {"effort": "high"}

    response = client.responses.parse(
        model=MODEL,
        store=False,
        max_output_tokens=32768,
        input=[
            {"role": "system", "content": PROMPT},
            # Deliberately do not supply Azure's transcription: avoid anchoring.
            {"role": "user", "content": page_images(page)},
        ],
        text_format=PageRead,
        **options,
    )
    parsed = response.output_parsed
    if response.status != "completed" or parsed is None:
        raise RuntimeError("Vision extraction refused, was incomplete, or did not parse.")

    write_json(
        path,
        {
            "model": response.model,
            "response_id": response.id,
            "extraction": parsed.model_dump(),
        },
    )
    return parsed


def table_pages(raw: dict) -> list[int]:
    regions = raw.get("boundingRegions", [])
    if not regions:
        regions = [
            region
            for cell in raw.get("cells", [])
            for region in cell.get("boundingRegions", [])
        ]
    return sorted({region["pageNumber"] for region in regions})


def table_position(raw: dict) -> tuple[float, float]:
    polygons = [
        region.get("polygon", []) for region in raw.get("boundingRegions", [])
    ]
    points = [polygon for polygon in polygons if polygon]
    if not points:
        return float("inf"), float("inf")
    return (
        min(min(polygon[1::2]) for polygon in points),
        min(min(polygon[0::2]) for polygon in points),
    )


def azure_table(raw: dict) -> Table:
    return Table(
        row_count=raw["rowCount"],
        column_count=raw["columnCount"],
        context=[],
        cells=[
            Cell(
                row=cell["rowIndex"],
                column=cell["columnIndex"],
                row_span=cell.get("rowSpan", 1),
                column_span=cell.get("columnSpan", 1),
                kind=cell.get("kind", "content"),
                text=cell.get("content", ""),
                footnote_refs=[],
            )
            for cell in raw.get("cells", [])
        ],
    )


def structural_errors(table: Table) -> list[dict]:
    errors = []
    occupied = set()
    for cell in table.cells:
        if (
            cell.row + cell.row_span > table.row_count
            or cell.column + cell.column_span > table.column_count
        ):
            errors.append({"reason": "cell_out_of_bounds", "cell": cell.model_dump()})
            continue

        for row in range(cell.row, cell.row + cell.row_span):
            for column in range(cell.column, cell.column + cell.column_span):
                if (row, column) in occupied:
                    errors.append(
                        {"reason": "overlapping_cells", "row": row, "column": column}
                    )
                occupied.add((row, column))
    return errors


def cell_signature(table: Table) -> dict:
    # Omitted single blank cells and explicit single blank cells are equivalent.
    # Blank merged cells remain structurally significant.
    return {
        (cell.row, cell.column): (
            cell.row_span,
            cell.column_span,
            comparison_text(cell.text),
        )
        for cell in table.cells
        if comparison_text(cell.text) or cell.row_span > 1 or cell.column_span > 1
    }


def compare_tables(layout: Table, vision: Table, page_text: str) -> list[dict]:
    errors = []
    for source, table in [("layout", layout), ("vision", vision)]:
        errors.extend({"source": source, **error} for error in structural_errors(table))

    if (layout.row_count, layout.column_count) != (
        vision.row_count,
        vision.column_count,
    ):
        errors.append(
            {
                "reason": "dimensions_disagree",
                "layout": [layout.row_count, layout.column_count],
                "vision": [vision.row_count, vision.column_count],
            }
        )

    left, right = cell_signature(layout), cell_signature(vision)
    for row, column in sorted(left.keys() | right.keys()):
        if left.get((row, column)) != right.get((row, column)):
            errors.append(
                {
                    "reason": "cell_text_position_or_span_disagrees",
                    "row": row,
                    "column": column,
                    "layout": left.get((row, column)),
                    "vision": right.get((row, column)),
                }
            )

    for cell in vision.cells:
        for reference in cell.footnote_refs:
            if not reference or comparison_text(reference) not in comparison_text(cell.text):
                errors.append(
                    {
                        "reason": "footnote_marker_not_literal_in_cell",
                        "row": cell.row,
                        "column": cell.column,
                        "reference": reference,
                    }
                )

    for context in vision.context:
        if not compact_text(context.text) or (
            compact_text(context.text) not in compact_text(page_text)
        ):
            errors.append(
                {
                    "reason": "context_not_confirmed_by_layout_text",
                    "kind": context.kind,
                    "text": context.text,
                }
            )

    # Semantic role classifications are retained from BOTH engines, not silently
    # reconciled. Position + content + spans preserve the actual header hierarchy.
    return errors


def minimum_word_confidence(raw_cell: dict, words: list[dict]):
    spans = [
        (span["offset"], span["offset"] + span["length"])
        for span in raw_cell.get("spans", [])
    ]
    confidences = []
    for word in words:
        span = word.get("span")
        if span is None or "confidence" not in word:
            continue
        start, end = span["offset"], span["offset"] + span["length"]
        if any(start < stop and end > begin for begin, stop in spans):
            confidences.append(word["confidence"])
    return min(confidences) if confidences else ""


def export_csvs(
    destination: Path,
    source_hash: str,
    layout: dict,
    matched: dict[int, Table],
    readings: dict[int, PageRead],
    errors: list[dict],
) -> None:
    bad_pages = {error["page"] for error in errors if "page" in error}
    global_error = any("page" not in error for error in errors)
    pages = {page["pageNumber"]: page for page in layout.get("pages", [])}

    def status(page_numbers: list[int]) -> str:
        return (
            "review"
            if global_error or not page_numbers or bad_pages.intersection(page_numbers)
            else "machine_checked"
        )

    rows = []
    for table_id, raw in enumerate(layout.get("tables", [])):
        table = azure_table(raw)
        page_numbers = table_pages(raw)
        vision_cells = {
            (cell.row, cell.column): cell
            for cell in matched[table_id].cells
        } if table_id in matched else {}
        words = [
            word
            for number in page_numbers
            for word in pages.get(number, {}).get("words", [])
        ]
        grid = [[""] * table.column_count for _ in range(table.row_count)]

        for original, cell in zip(raw.get("cells", []), table.cells):
            peer = vision_cells.get((cell.row, cell.column))
            if cell.row < table.row_count and cell.column < table.column_count:
                grid[cell.row][cell.column] = cell.text
            rows.append(
                [
                    source_hash,
                    json.dumps(page_numbers),
                    table_id,
                    table.row_count,
                    table.column_count,
                    cell.row,
                    cell.column,
                    cell.row_span,
                    cell.column_span,
                    cell.kind,
                    peer.kind if peer else "",
                    cell.text,
                    json.dumps(peer.footnote_refs if peer else [], ensure_ascii=False),
                    minimum_word_confidence(original, words),
                    json.dumps(original.get("boundingRegions", []), ensure_ascii=False),
                    status(page_numbers),
                ]
            )

        write_csv(destination / f"table-{table_id:04d}.csv", None, grid)

    write_csv(
        destination / "cells.csv",
        [
            "pdf_sha256", "pages_json", "table_id", "row_count", "column_count",
            "row", "column", "row_span", "column_span",
            "layout_kind", "vision_kind", "raw_text", "footnote_refs_json",
            "min_ocr_word_confidence", "bounding_regions_json", "status",
        ],
        rows,
    )

    write_csv(
        destination / "page_text.csv",
        ["page", "line", "raw_text", "polygon_json"],
        (
            [
                number,
                index,
                line.get("content", ""),
                json.dumps(line.get("polygon", [])),
            ]
            for number, page in sorted(pages.items())
            for index, line in enumerate(page.get("lines", []))
        ),
    )

    write_csv(
        destination / "table_context.csv",
        ["page", "vision_table_on_page", "kind", "raw_text", "status"],
        (
            [number, index, item.kind, item.text, status([number])]
            for number, reading in sorted(readings.items())
            for index, table in enumerate(reading.tables)
            for item in table.context
        ),
    )


def process(pdf: Path, output: Path) -> dict:
    source_hash = sha256(pdf)
    configuration = {
        "pipeline": PIPELINE_VERSION,
        "azure_api": API_VERSION,
        "azure_features": ["ocrHighResolution"],
        "vision_model": MODEL,
        "dpi": DPI,
        "tile_size": TILE_SIZE,
        "tile_overlap": TILE_OVERLAP,
        "prompt": PROMPT,
    }
    configuration_hash = hashlib.sha256(
        json.dumps(configuration, sort_keys=True).encode()
    ).hexdigest()[:12]

    job = output / f"{source_hash}-{configuration_hash}"
    cache = job / "cache"
    cache.mkdir(parents=True, exist_ok=True)
    manifest_path = job / "manifest.json"
    if manifest_path.exists():
        return read_json(manifest_path)

    # Archive immutable source bytes for reproducibility and targeted review.
    archived_pdf = job / "source.pdf"
    if not archived_pdf.exists():
        shutil.copyfile(pdf, archived_pdf)
    if sha256(archived_pdf) != source_hash:
        raise RuntimeError("Source changed during ingestion or archived source is corrupt.")

    layout = azure_layout(archived_pdf, cache)
    errors: list[dict] = []
    readings: dict[int, PageRead] = {}
    matched: dict[int, Table] = {}
    tables_by_page: dict[int, list[tuple[int, dict]]] = {}

    for table_id, table in enumerate(layout.get("tables", [])):
        numbers = table_pages(table)
        if len(numbers) != 1:
            errors.append(
                {
                    "reason": "table_has_missing_or_cross_page_geometry",
                    "table_id": table_id,
                    "pages": numbers,
                }
            )
        if numbers:
            tables_by_page.setdefault(numbers[0], []).append((table_id, table))

    azure_pages = {page["pageNumber"]: page for page in layout.get("pages", [])}
    client = OpenAI(max_retries=5, timeout=600.0)

    with fitz.open(archived_pdf) as document:
        expected_pages = set(range(1, len(document) + 1))
        if set(azure_pages) != expected_pages:
            errors.append(
                {
                    "reason": "layout_page_coverage_incomplete",
                    "expected_pages": len(document),
                    "received_pages": sorted(azure_pages),
                }
            )

        # Check EVERY page, including pages where Azure found no tables.
        # Otherwise, two-engine agreement would miss undetected tables entirely.
        for page in document:
            number = page.number + 1
            page_errors = []
            try:
                reading = independent_read(client, page, cache)
                readings[number] = reading
                page_errors.extend(
                    {"reason": "vision_uncertainty", "detail": uncertainty}
                    for uncertainty in reading.uncertainties
                )

                primary = sorted(
                    tables_by_page.get(number, []),
                    key=lambda pair: table_position(pair[1]),
                )

                if len(primary) != len(reading.tables):
                    page_errors.append(
                        {
                            "reason": "table_inventory_disagrees",
                            "layout_count": len(primary),
                            "vision_count": len(reading.tables),
                        }
                    )
                else:
                    page_text = "\n".join(
                        line.get("content", "")
                        for line in azure_pages.get(number, {}).get("lines", [])
                    )
                    for (table_id, raw), independently_read in zip(
                        primary, reading.tables
                    ):
                        matched[table_id] = independently_read
                        page_errors.extend(
                            {"table_id": table_id, **error}
                            for error in compare_tables(
                                azure_table(raw), independently_read, page_text
                            )
                        )

            except Exception as exc:
                # A failed, truncated, or refused read cannot become an approval.
                page_errors.append(
                    {"reason": "verification_failed", "detail": str(exc)}
                )

            errors.extend({"page": number, **error} for error in page_errors)

    if not layout.get("tables"):
        errors.append({"reason": "no_tables_found_in_annual_report"})

    candidate = job / "candidate"
    export_csvs(candidate, source_hash, layout, matched, readings, errors)
    write_json(job / "exceptions.json", errors)

    state = "review" if errors else "machine_checked"
    csv_directory = candidate
    if not errors:
        csv_directory = job / "machine_checked"
        candidate.replace(csv_directory)

    manifest = {
        "status": state,
        "source_name": pdf.name,
        "pdf_sha256": source_hash,
        "source_pdf": str(archived_pdf.resolve()),
        "csv_directory": str(csv_directory.resolve()),
        "exceptions_file": str((job / "exceptions.json").resolve()),
        "raw_evidence_directory": str(cache.resolve()),
        "table_count": len(layout.get("tables", [])),
        "exception_count": len(errors),
        "configuration": configuration,
        "assurance": (
            "Independent machine agreement, not a correctness guarantee. "
            "Keep representative benchmarks and ongoing audits."
        ),
    }
    write_json(manifest_path, manifest)
    return manifest


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("pdf", type=Path)
    parser.add_argument("--out", type=Path, default=Path("financial-table-output"))
    args = parser.parse_args()

    for variable in (
        "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT",
        "AZURE_DOCUMENT_INTELLIGENCE_KEY",
        "OPENAI_API_KEY",
    ):
        if not os.getenv(variable):
            parser.error(f"Missing environment variable: {variable}")

    if not args.pdf.is_file():
        parser.error(f"PDF does not exist: {args.pdf}")

    try:
        manifest = process(args.pdf, args.out)
        print(json.dumps(manifest, ensure_ascii=False))
        return 0 if manifest["status"] == "machine_checked" else 2
    except Exception as exc:
        print(json.dumps({"status": "error", "detail": str(exc)}, ensure_ascii=False))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
